INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_immigration_rules_2051:5.99', 'doc_immigration_rules_2051', 'doc_immigration_rules_2051:5', 2, 'rule', '1', 'नन योग वा प्रवेिस्थल शस्थत कायाथलयले पयथटक निसा जार ी गद ाथ लाग्न े द स्तुर ः', 'नन योग वा प्रवेिस्थल शस्थत कायाथलयले पयथटक निसा जार ी गद ाथ लाग्न े द स्तुर ः', '(क) पन्र दद न को बिुप्रवेिी सुहवधा सहितको निसाका लानग तीस अमेरर की िलर वा सो
बराबरको अन्य परर वत्र्य हवद ेिी मुद्रा ।
(ि) तीस दद न को बिुप्रवेिी सुहवधा सहितको निसाका लानग पचास अमेरर की िलर वा सो
बर ाबर को अन्य परर वत्र्य हवद ेिी मुद्रा ।
(ग) न ब् बे दद न को बिुप्रवेिी सुहवधा सहितको निसाका लानग एक सय पच् चीस अमेरर की िलर
वा सो बर ाबर को परर वत्र्य हवद ेिी मुद्रा ।
(घ) ि ण्ि (क) र (ि ) मा जुन सुकै कुर ा लेशि एको िए तापनन द शि ि एशियाली िेत्रीय
सियोग सङ्गठन (साक थ ) का सदस्य राष्‍ट रका रािदानी बािकलाई तीस ददनसभमको
