  ('doc_national_criminal_procedure_code_2074_2017:19.11', 'doc_national_criminal_procedure_code_2074_2017', 'doc_national_criminal_procedure_code_2074_2017:19', 2, 'rule', '13', 'Offence under the Prison Act, 2019', 'Offence under the Prison Act, 2019', NULL, 11, 'The National Criminal Procedure (Code) Act, 2017, Chapter-26 (Offence under the Prison Act, 2019)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_criminal_procedure_code_2074_2017:19.12', 'doc_national_criminal_procedure_code_2074_2017', 'doc_national_criminal_procedure_code_2074_2017:19', 2, 'rule', '14', 'Offence under the Donation Act, 2025', 'Offence under the Donation Act, 2025', NULL, 12, 'The National Criminal Procedure (Code) Act, 2017, Chapter-26 (Offence under the Donation Act, 2025)', '2026-01-15T09:00:00.000Z'),
