INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_national_penal_code_2074_2017:5', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-5', '', NULL, 'Provisions Relating to Punishment and Interim Relief', 5, 'The National Penal (Code) Act, 2017, Chapter-5', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5', 2, 'rule', '40', 'Types of punishment', 'Types of punishment', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-5 (Types of punishment)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.0', 3, 'clause', '(1)', '', NULL, 'The punishments for the offences set
forth in this Act shall be as follows:
(a) Imprisonment for life,
(b) Imprisonment,
(c) Fine,
(d) Imprisonment and fine,
(e) Compensation,
(f) Imprisonment for the failure to pay a fine or
compensation,
(g) Community service in lieu of imprisonment.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.0', 3, 'clause', '(2)', '', NULL, 'Where any law provides for the sentence of confiscation
of property for any offence, such sentence of confiscation shall not
be imposed for that offence, after the commencement of this Act.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.0', 3, 'clause', '(3)', '', NULL, 'Notwithstanding anything contained in this Section, no
sentence of fine of less than one rupee and of impri sonment for a
term of less than one day shall be imposed.', 2, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5', 2, 'rule', '41', 'Imprisonment for life', 'Imprisonment for life', 'Notwithstanding anything contained
elsewhere in this Act, in imposing a sentence of imprisonment on an
offender for the following offence, the offender shall be subjected to
imprisonment for the whole of his or her natural life:', 1, 'The National Penal (Code) Act, 2017, Chapter-5 (Imprisonment for life)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.1', 3, 'clause', '(a)', '', NULL, 'Murder with cruelty, torture or inhumane conduct,', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (a)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.1', 3, 'clause', '(b)', '', NULL, 'Murder by hijacking or exploding an aircraft,', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (b)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.1.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.1', 3, 'clause', '(c)', '', NULL, 'Murder by kidnapping or taking hostage,', 2, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (c)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.1.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.1', 3, 'clause', '(d)', '', NULL, 'Murder by poisoning publicly consumable bevera ges
or food,', 3, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (d)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.1.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.1', 3, 'clause', '(e)', '', NULL, 'Genocide (destroying the identity of any caste, race or
group) or offence committed with the objective of
committing genocide,', 4, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (e)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.1.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.1', 3, 'clause', '(f)', '', NULL, 'Murder with rape.', 5, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (f)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5', 2, 'rule', '42', 'Computation of imprisonment for life', 'Computation of imprisonment for life', 'Except in the circumstance
referred to in Se ction 41, the sentence of imprisonment for life shall
be so computed that its term is twenty-five years.', 2, 'The National Penal (Code) Act, 2017, Chapter-5 (Computation of imprisonment for life)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5', 2, 'rule', '43', 'One and half punishment for consolidated/integrated offence', 'One and half punishment for consolidated/integrated offence', NULL, 3, 'The National Penal (Code) Act, 2017, Chapter-5 (One and half punishment for consolidated/integrated offence)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.3', 3, 'clause', '(1)', '', NULL, 'Where a person, at the time of judgment by a court, is convicted of
more than one offence on a single occasion or different offences on
different occasions, such person shall be deemed to have committed
a consolidated offence.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.3.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.3', 3, 'clause', '(2)', '', NULL, 'The offender who commits a consolidated offence
referred to in sub-section (1) shall be sentenced for the o ffence
punishable by the maximum punishment and to additional
punishment of one half of that punishment specified for such
offence.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5', 2, 'rule', '44', 'Additional punishment for offender of heinous crime and', 'Additional punishment for offender of heinous crime and', 'recidivist: (1) If a person who was sentenced for an y offence
commits another heinous or grave offence before the expiry of a
period of five years after the date on which he or she completed the
service of that sentence or was granted pardon, he or she shall be
considered to be a recidivist.', 4, 'The National Penal (Code) Act, 2017, Chapter-5 (Additional punishment for offender of heinous crime and)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.4', 3, 'clause', '(2)', '', NULL, 'A recidivist shall be liable to a punishment that is up to
double the punishment imposable for the last offence committed by
him or her.
Provided that this Section shall not apply to an offender who
has been sentenced to imprisonment for life pursuant to Section 41.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5', 2, 'rule', '45', 'Punishment imposable on children', 'Punishment imposable on children', NULL, 5, 'The National Penal (Code) Act, 2017, Chapter-5 (Punishment imposable on children)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.5.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.5', 3, 'clause', '(1)', '', NULL, 'A person who commits an
act constituting an offence under the law shall not be liable to any
punishment if that person has not attained ten years of age at the time
of the commission of such act.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.5.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.5', 3, 'clause', '(2)', '', NULL, 'In imposing the punishm ent of imprisonment on a
person who is ten years of age or above ten but below fourteen years
of age, such person may be sentenced to imprisonment for a
maximum of six months or sent to a reform home for a maximum of
one year in lieu of such imprisonment.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.5.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.5', 3, 'clause', '(3)', '', NULL, 'Where a person who is fourteen years of age or above
fourteen but below sixteen years of age commits any offence
punishable by imprisonment, such person shall be liable to half the
punishment imposable by law on a person who has attained majority.', 2, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.5.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.5', 3, 'clause', '(4)', '', NULL, 'Where a person who is sixteen years of age or above
sixteen but below eighteen years of age commits any offence
punishable by imprisonment, such person shall be liable to two -
thirds of the punishment imposable by law on a person who has
attained majority.', 3, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5', 2, 'rule', '46', 'Imprisonment for fine', 'Imprisonment for fine', NULL, 6, 'The National Penal (Code) Act, 2017, Chapter-5 (Imprisonment for fine)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.6.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.6', 3, 'clause', '(1)', '', NULL, 'Any offender who is unable to pay a
fine imposed on him or her may be subjected to imprisonment.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.6.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.6', 3, 'clause', '(2)', '', NULL, 'The term of imprisonment under sub-section (1) shall be
determined as follows:
(a) In determining the sentence of impriso nment in
default of payment of a fine for an offence
punishable by both imprisonment and fine, the
term of imprisonment shall be so determined as
not to exceed ten years.
(b) Where an offence is punishable by either
imprisonment or fine or with both, in wh ich the
offender is sentenced to a fine only, in
determining the sentence of imprisonment in
default of payment of such fine, the term of
imprisonment shall be so determined as not to
exceed one half of the maximum term of
imprisonment that can be imposed for such
offence,
(c) Where an offence is punishable by fine only, in
which the offender is sentenced to a fine, in
determining the sentence of imprisonment in
default of payment of such fine, the term of
imprisonment shall be so determined as not to
exceed two years.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.6.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.6', 3, 'clause', '(3)', '', NULL, 'Notwithstanding anything contained in sub -section (2),
the following provisions shall apply to the imposition of a sentence
of imprisonment for non-payment of a fine on a child below eighteen
years of age:
(a) In the event of non -payment of a fine for an
offence punishable by fine only or by either fine
or imprisonment, the child shall not be subjected
to imprisonment and the fine shall be remitted.
(b) Where an offence is punishable by imprisonment
or fine or both, in which the offender is sentenced
to a fine only, in determining the sentence of
imprisonment in default of payment of such fine,
the term of imprisonment shall be so determined
as not to exceed three months.
(c) In determining the sentence of imprisonment
pursuant to sub -section (2) to be imposed on a
person who is above fourteen but below eighteen
years of age, the term of imprisonment shall be so
determined as not to exceed half the sentence of
imprisonment imposable on a person above
eighteen years of age.', 2, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5', 2, 'rule', '47', 'Remission of sentence', 'Remission of sentence', NULL, 7, 'The National Penal (Code) Act, 2017, Chapter-5 (Remission of sentence)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.7.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.7', 3, 'clause', '(1)', '', NULL, 'Where any offender, upon having
confessed the offence committed by him or her, has assisted in the
collection of evidence, apprehension of other accused person or gang
or accomplice thereof, in relation to such offence or assisted the
investigating or prosecuting authority or the court, a maximum of
fifty percent of the sentence imposable under law for such offence
may be remitted.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.7.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.7', 3, 'clause', '(2)', '', NULL, 'Notwithstanding anything contained in sub -section (1),
the following offender shall not be entitled to the r emission of
sentence:
(a) One who has once obtained remission under sub -
section (1),
(b) One who has been convicted of any offence
punishable by imprisonment, and a period of
three years has not lapsed since the completion of
service of the sentence of imprisonment,
(c) One who has once been sentenced for any offence
of the same nature as in which the remission of
sentence is sought.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.7.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.7', 3, 'clause', '(3)', '', NULL, 'In granting a remission of punishment pursuant to sub -
section (1), regard shall be had to, inter alia , at which stage o f
investigation or trial the accused has confessed the offence and in
what circumstances he or she has made such confession.', 2, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.8', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5', 2, 'rule', '48', 'Power of court to order interim compensation', 'Power of court to order interim compensation', NULL, 8, 'The National Penal (Code) Act, 2017, Chapter-5 (Power of court to order interim compensation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.8.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.8', 3, 'clause', '(1)', '', NULL, 'Notwithstanding anything contained elsewhere in thi s Act, where it
is necessa ry to immediately provide medical treatment or
compensation or any type of relief amount to a person who has
become victim of an offence in consequence of its commission or a
person who is dependent on him or her, the court may order the
person accused of such offence to provide medical treatment or pay
an interim compensation or relief amount to such person.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.8.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.8', 3, 'clause', '(2)', '', NULL, 'Where an order is made pursuant to sub -section (1), the
person so accused shall immediately provide such compensation or
amount to the victim or person dependent on him or her.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.8.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.8', 3, 'clause', '(3)', '', NULL, 'Where the accused is unable to provide the
compensation or amount pursuant to sub -section (2) in accordance
with the order referred to in sub-section (1), the court shall order that
the compensation or amount be provided to the victim or person
dependent on him or her from the victim relief fund established
pursuant to the laws in force related to the determination and
execution of sentences for criminal offence s, and the amount so
provided shall be recovered from such acc used person and
reimbursed into such fund.', 2, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.8.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.8', 3, 'clause', '(4)', '', NULL, 'Where a person who has paid compensation or relief
amount pursuant to this Section is acquitted of the charge by the
judgment of the court, the person who has received such
compensation or relief amount shall , within thirty-five days of such
acquittal, return such amount to such person or to the victim relief
fund referred to in sub-section (3).', 3, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:5.8.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:5.8', 3, 'clause', '(5)', '', NULL, 'Where such person does not return such amount within
the period referred to in sub-section (4), the court shall cause such
amount to be recovered from any assets of such person within thirty-
five days of such acquittal.
Part-2
Criminal Offences', 4, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-1', '', NULL, 'Offences against the State', 6, 'The National Penal (Code) Act, 2017, Chapter-1', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6', 2, 'rule', '49', 'Prohibition of undermining sovereignty, integrity or national', 'Prohibition of undermining sovereignty, integrity or national', 'unity: (1) N o person shall, with the intention of undermining the
independence, sovereignty, geographical or territorial integrity or
national unity of Nepal, collect persons, arm s and ammunitions,
build any armed military or paramilitary organization or attempt to
commit such act.', 0, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition of undermining sovereignty, integrity or national)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.0', 3, 'clause', '(2)', '', NULL, 'No person shall make, or cause to be made, any kind of
conspiracy, in association with any foreign state, government or
organized force, to undermine the independence, sovereignty,
geographical or territorial integrity or national unity of Nepal.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.0', 3, 'clause', '(3)', '', NULL, 'No person shall abet the commission of the offence
under sub-section (1) or (2).', 1, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.0', 3, 'clause', '(4)', '', NULL, 'No person shall commit, or cause to be committed, any
act that gives rise to hatred, enmity or contempt on grounds of class,
race, religion, region, commun ity or similar other ground, which is
likely to jeopardize the sovereignty , geographical or territorial
integrity, nationality , national unity, independence, dignity, or
harmonious relations between federal units, of Nepal or attempt to
commit, or abet the commission of, or make conspiracy to commit,
such act, or undermine or cause to be undermined the cordial
relations subsisting between different castes, races or communities.', 2, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.0.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.0', 3, 'clause', '(5)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in this Section shall be sentenced to the following
punishment:
(a) Imprisonment for life in the case of the offence referred
to in sub-section (1) or (2),
(b) Imprisonment for a term not exceeding ten years and a
fine not exceeding one hundred thousand rupees in th e
case of the offence referred to in sub-section (3),
(c) Imprisonment for a term not exceeding five years and a
fine not exceeding fifty thousand rupees in the case of
the offence referred to in sub-section (4).', 3, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6', 2, 'rule', '50', 'Sedition', 'Sedition', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-1 (Sedition)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.1', 3, 'clause', '(1)', '', NULL, 'No person shall, with the int ention of overthrowing the
Government of Nepal or the constitutional structure, create any kind
of disorder by demonstrating or using military, paramilitary or
criminal force or form an armed military or paramilitary organization
or make conspiracy, attempt or incitement to commit such act.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.1', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to punishment with imprisonment for a
term not exceeding twenty-five years.', 1, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.1.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.1', 3, 'clause', '(3)', '', NULL, 'No person shall, by words, either spoken or written or
by figure or signs or otherwise, showing any baseless or
unsubstantiated matter in relation to the Government of Nepal or any
action of the Government of Nepal, bring or attempt to bring into
hatred, enmity or contempt towards the Government of Nepal or
cause the commission of such act.
Provided that nothing contained in this sub -section shall be
considered to render any healthy or decent criticism of the
Government of Nepal to be the offence.', 2, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.1.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.1', 3, 'clause', '(4)', '', NULL, 'A person who commits the offence referred to in sub-
section (3) shall be liable to the sentence of imprisonment for a term
not exceeding three years or a fine not exceeding thirty thousand
rupees.', 3, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6', 2, 'rule', '51', 'Prohibition of act against national interest', 'Prohibition of act against national interest', NULL, 2, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition of act against national interest)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.2', 3, 'clause', '(1)', '', NULL, 'No one shall do, or
cause to be done, any act against national interest.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.2.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.2', 3, 'clause', '(2)', '', NULL, 'For the purpose s of sub -section (1), where any person
does, or causes to be done, any of the following acts, he or she shall
be considered to have done an act against national interest:
(a) To dishonor or degrade or spread hatred or
enmity against the freedom, sovereignty,
geographical or territorial integrity, nationality,
independence, self -esteem of, or international
image of, Nepal,
(b) To encroach the international boundary of Nepal,
or remove or dislocate any boundary pillar,
except in accordance with agreement with a
neighbouring country, or to so change any
boundary pillar as to be prejudicial to the
geographical or territorial integrity of Nepal.', 1, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.2.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.2', 3, 'clause', '(3)', '', NULL, 'Any Nepali player or a group of Nepali players, who
representing Nepal, plays any match in competition with any player
or players in Nepal or a foreign country shall not play, or cause to be
played, such match in connivance with or under the influence of any
one in a manner to manipulate a natural result of such match or to
make a bet w in or lose , and where any match has been so played,
the offence against national interest shall be considered to have been
committed.', 2, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.2.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.2', 3, 'clause', '(4)', '', NULL, 'Any person who commits the offence referred to in sub-
section (2) or (3) shall be liable to the following punishment:
(a) A sentence of imprisonment for a term not
exceeding five years and fine not exceeding fifty
thousand rupees, in the case of the offence
referred to in sub-section (2),
(b) A sentence of imprisonment for a term not
exceeding three years and fine not e xceeding
thirty thousand rupees, in the case of the offence
referred to in sub-section (3).', 3, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.2.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.2', 3, 'clause', '(5)', '', NULL, 'Where any person has transacted money in the course of
the commission of the offence referred to in sub-section (2) or (3),
the amount of money so transacted sh all be forfeited, in addition to
the punishment pursuant to sub-section (4).', 4, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.2.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.2', 3, 'clause', '(6)', '', NULL, 'Any person who orders, directs, abets, incites or
facilitates the commission of the offence referred to in sub-section', 5, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (6)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.2.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.2', 3, 'clause', '(3)', '', NULL, 'shall be liable to punishment as if that person were the principal
offender.', 6, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.2.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.2', 3, 'clause', '(7)', '', NULL, 'Where the offence referred to in sub-section (2) or (3) is
committed by a public office holder or a person representing Nepal,
while in a foreign country, he or she shall be liable to additional
sentence of imprisonment for a term not exceeding three years.', 7, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (7)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6', 2, 'rule', '52', 'Prohibition of genocide', 'Prohibition of genocide', NULL, 3, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition of genocide)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.3', 3, 'clause', '(1)', '', NULL, 'No person shall commit, or cause to be
committed, genocide.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.3.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.3', 3, 'clause', '(2)', '', NULL, 'For the purpose of sub -section (1), any of the following
acts committed with intent to destroy, in whole or in part, an
ethnical, racial, national or religious group, or any attempt or
conspiracy to commit such act, shall be considered to be the offence
of genocide:
(a) Mass killing of members of such group, in a
planned way, at one or several times,
(b) Causing grievous hurt t o the body of, or causing
serious bodily or mental harm to, members of
such group, in a planned way, at one or several
times,
(c) Deliberately inflicting on the group conditions of
life, inter alia , the depriving its members of
access to essential goods such as water, food, fuel
and medicine, by hindering the supply or
movement of such goods, thereby deliberately
making painful the life of members of such
group, calculated to bring about its physical
destruction in whole or in part,
(d) Forcibly imposing measures on members of such
group intended to prevent births within the group,
except in cases of voluntary use by such members
of family planning means,
(e) Forcibly transferring children of such group to
another group.', 1, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.3.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.3', 3, 'clause', '(3)', '', NULL, 'Any person who commits the offence referred to in sub-
section (1) shall be liable to the following punishment:
(a) Imprisonment for life, in the case of the offence
referred to in clause (a),
(b) Imprisonment for a term not exceeding five years
and fine not exceeding fifty thousand rupees , in
addition to the sentence imposable under this Act
for grievous hurt or hurt to human body, in the
case of the offence referred to in clause (b),
(c) Imprisonment for a term not exceeding ten years,
in the case of the offence referred to in clause (c),
(d) or (e).', 2, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.3.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.3', 3, 'clause', '(4)', '', NULL, 'Where the offence referred to in this Section is
committed in pursuance of order or direction given by a person or
group, whether organized or unorganized, the person, or the
responsible person or persons of such group giving such order o r
direction shall be liable as the principal offender.', 3, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.3.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.3', 3, 'clause', '(5)', '', NULL, 'Where the offence referred to in this Section has been
committed by a group or with the involvement of several persons,
every person involved in such offence shall be equally liable as the
offender.', 4, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.3.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.3', 3, 'clause', '(6)', '', NULL, 'Where any person who commits the offence referred to
in this Section is a public office holder, he or she shall not be
allowed to make a plea that such offence has been committed in the
course of executing a superior order or maintaining law and orde r or
enforcing law, and that person shall not enjoy any remission or
waiver from sentence on the ground that he or she has made such
plea.', 5, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (6)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6', 2, 'rule', '53', 'Prohibition of waging war against Nepal or assist the army of a', 'Prohibition of waging war against Nepal or assist the army of a', 'State at war with Nepal: (1) No person shall wag e or declare to
wage war against Nepal, by raising arms, or attempt or threat to
wage such war, or collect arms, ammunition or form a military or
paramilitary organization with intent to wage war against Nepal.', 4, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition of waging war against Nepal or assist the army of a)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.4', 3, 'clause', '(2)', '', NULL, 'No person shall, in any situation whether a state of war
is declared or not, supply any kind of strategic or military
information or otherwise render assistance to any foreign army
engaged in war with Nepal or attempt to do so.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.4.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.4', 3, 'clause', '(3)', '', NULL, 'Where a declaration is made by the Government of
Nepal prohibiting the making of relation or transaction with a State
engaged in war with Nepal, any citizen or corporate body of such
State or the importing or obtaining of any goods or services of such
State, no person shall make such relation or transaction with such
State, citizen or body or import or obtain such goods or services.', 1, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.4.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.4', 3, 'clause', '(4)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) or (2) shall be liable to a
sentence of imprisonment for life, and a person who commits the
offence referred to in sub-section (3) shall be liable to a sentence of
imprisonment for a term not exceeding twenty-five years and a fine
not exceeding one hundred thousand rupees.', 2, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6', 2, 'rule', '54', 'Prohibition of waging war or insurrection against friendly State', 'Prohibition of waging war or insurrection against friendly State', NULL, 5, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition of waging war or insurrection against friendly State)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.5.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.5', 3, 'clause', '(1)', '', NULL, 'No person shall, using the territory of Nepal, wage or threaten to
wage war, by raising arms, or attempt to wage such war or insurrect
or attempt to insurrect against a State having diplomatic relations
with Nepal.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.5.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.5', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding seven years and a fine not
exceeding seventy thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6', 2, 'rule', '55', 'Prohibition of giving provocation to army or p olice', 'Prohibition of giving provocation to army or p olice', NULL, 6, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition of giving provocation to army or p olice)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.6.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.6', 3, 'clause', '(1)', '', NULL, 'No
person shall abet or give provocation to the desertion of a soldier,
police or armed police personnel or officer in the Nepal Army, Nepal
Police or Armed Police Force, Nepal from the Nepal Army, Nepal
Police or Armed Police Force, Nepal or abet the breach of di scipline
by such soldier, police or armed police personnel or attempt to
seduce such soldier, police or armed police personnel from his or her
duty, or, knowing or having reason to believe that a soldier, police or
armed police personnel has so deserted th e Army or Police or Force,
harbor such deserter.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.6.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.6', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be
committed the offence referred to in sub-section (1) shall be liable to
a sentence of imprisonment for a term not exceeding ten years and a
fine not exceeding one hundred thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6', 2, 'rule', '56', 'Prohibition of espionage', 'Prohibition of espionage', NULL, 7, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition of espionage)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.7.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.7', 3, 'clause', '(1)', '', NULL, 'No person shall, with intent to
undermine the sovereignty, security or geographical or territorial
integrity of Nepal or to prejudice the interests of Nepal or with the
knowledge that such consequ ence is likely, or being induced by any
foreign country or international organization, supply to any one any
information relating to the military situation, strategic arrangement
or internal security of Nepal or relating to any matter that must be
kept con fidential by the Government of Nepal from the political,
economic or diplomatic viewpoint or confidential document, or any
matter that is confidential or must be kept confidential under law or
conspire or attempt to commit, or abet the commission of, such act or
do any other act with intent to supply such informati on, and a person
who commits such act shall be considered to have committed
espionage.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.7.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.7', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed,
espionage referred to in sub-section (1) shall be liable to punishment
as follows:
(a) In the case of a person who commits, or causes to be
committed, espionage in relation to any matter of
military situation, strategic arrangement or internal
security of Nepal, a sentence of imprisonment for a term
not exceeding twenty-five years,
(a) In the case of a person who commits, or causes to be
committed, espionage in relation to any matter that must
be kept confidential by the Government of Nepal from
the political, economic or diplomatic viewpoint or any
other confiden tial document, that must be kept
confidential by the Government of Nepal from the
political, economic or diplomatic viewpoint or any other
confidential document, a sentence of imprisonment for a
term ranging from five to ten years,
(c) In the case of a per son who commits, or causes to be
committed, espionage in relation to any matter other
than that set forth in clauses (a) and (b), a sentence of
imprisonment for a term not exceeding five years and a
fine of fifty thousand rupees,
(d) In the case of a perso n who, despite the knowledge that
any one is going to commit espionage, does not give
information thereof to the Government of Nepal, a
sentence of imprisonment for a term not exceeding one
year and a fine of one hundred thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.8', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6', 2, 'rule', '57', 'Prohibition of assault on President', 'Prohibition of assault on President', NULL, 8, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition of assault on President)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.8.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.8', 3, 'clause', '(1)', '', NULL, 'No person shall assassinate
or attempt to assassinate the President of Nepal.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.8.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.8', 3, 'clause', '(2)', '', NULL, 'No person shall, in any manner, abduct, or cause to be
abducted, the President of Nepal or take, or cause to be taken, him or
her hostage.', 1, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.8.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.8', 3, 'clause', '(3)', '', NULL, 'No person shall, in any manner, assault, or cause to be
assaulted, the President of Nepal.', 2, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.8.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.8', 3, 'clause', '(4)', '', NULL, 'A person who commits any offence referred to in this
Section shall be liable to punishment as follows:
(a) In the case of the offence referred to in sub-
section (1), a sentence of imprisonment for life,
(b) In the case of the offence referred to in sub-
section (2), a sentence of imprisonment for a term
ranging from ten to fifteen years,
(c) In the case of the offence referred to in sub-
section (3), a sentence of imprisonment for a term
ranging from five to ten years.', 3, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.9', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6', 2, 'rule', '58', 'Prohibition of intimidation of President or Parliament', 'Prohibition of intimidation of President or Parliament', NULL, 9, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition of intimidation of President or Parliament)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.9.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.9', 3, 'clause', '(1)', '', NULL, 'No
person shall intimidate, whether by using any kind of force or not,
show fear or terror to, or otherwise overawe the President or
Parliament of Nepal with intent to prevent or restrain the President or
Parliament of Nepal from performing any of the functions required
to be performed pursuant to the Constitution or law or compel the
President or Parliament of Nepal to perform the functions in any
specific manner.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.9.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.9', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding seven years or a fine not
exceeding seventy thousand rupees or with both.
Explanation: For the purposes of this Section, the term
"Parliament" means the Federal Parliament and the State Assembly
under the Constitution of Nepal, and this term also includes the
Legislature-Parliament.', 1, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.10', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6', 2, 'rule', '59', 'Statute of limitation', 'Statute of limitation', NULL, 10, 'The National Penal (Code) Act, 2017, Chapter-1 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.10.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.10', 3, 'clause', '(1)', '', NULL, 'No s tatute of limitation shall apply to a
complaint with regard to any of the offences under Sections 49, 50,
51 52, 53 and 57.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:6.10.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:6.10', 3, 'clause', '(2)', '', NULL, 'In the case of the offences under the Sections of this
Chapter, except those Sections set forth in sub -section (1), no
complaint shall be entertained after the expiry of two years of the
date of knowledge of the commission of the offence.', 1, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-2', '', NULL, 'Offences against Public Tranquility', 7, 'The National Penal (Code) Act, 2017, Chapter-2', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7', 2, 'rule', '60', 'Prohibition of unlawful assembly', 'Prohibition of unlawful assembly', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-2 (Prohibition of unlawful assembly)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.0', 3, 'clause', '(1)', '', NULL, 'No person shall be engaged
in an unlawful assembly.', 0, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.0', 3, 'clause', '(2)', '', NULL, 'An assembly of five or more persons with the objective
of doing any of the following acts shall be considered to be an
unlawful assembly:
(a) By means of force or show of force or show of a
deadly weapon:', 1, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.0', 3, 'clause', '(1)', '', NULL, 'to prevent any public servant from
exercising the lawful functions or duties,', 2, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.0.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.0', 3, 'clause', '(2)', '', NULL, 'to take or obtain possession of anyone’s
property,', 3, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.0.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.0', 3, 'clause', '(3)', '', NULL, 'to deprive any person of the enjoyment of
the right of way, use of water, public
transport or communication or similar
other utilities,', 4, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.0.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.0', 3, 'clause', '(4)', '', NULL, 'to compel any person to do what he or she
is not legally bound to do or to omit to do
what he or she is legally entitled to do.
(b) To hinder, resist the execution of any law, or of any
legal process,
(c) To commit any offence punishable by a sentence of
imprisonment.', 5, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.0.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.0', 3, 'clause', '(3)', '', NULL, 'Any pe rson who, with the knowledge that it is an
unlawful assembly, joins the assembly shall be liable to a sentence of
imprisonment for a term not exceeding six months and a fine not
exceeding five thousand rupees where he or she has joined it without
arms, and imprisonment for a term not exceeding one year and a fine
not exceeding ten thousand rupees where he or she has joined it with
arms.', 6, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.0.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.0', 3, 'clause', '(4)', '', NULL, 'Any person who himself or herself does not join an
unlawful assembly but hires or otherwise induces or overawes
another to join such assembly shall be liable to the sentence referred
to in sub-section (3) as if he or she himself or herself had joined such
unlawful assembly.', 7, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7', 2, 'rule', '61', 'Prohibition of breach of order issued to prevent or disperse', 'Prohibition of breach of order issued to prevent or disperse', 'unlawful assembly: (1) Where a com petent authority makes an
order to prevent or disperse an unlawful assembly, no person shall
participate or continue in such assembly.', 1, 'The National Penal (Code) Act, 2017, Chapter-2 (Prohibition of breach of order issued to prevent or disperse)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.1', 3, 'clause', '(2)', '', NULL, 'A person who continues in, participates in, or joins an
unlawful assembly under sub-section (1) shall be liable to a sentence
of imprisonment for a term not exceeding one year or a fine not
exceeding ten thousand rupees or with both.', 0, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7', 2, 'rule', '62', 'Every member to be considered to have committed offence', 'Every member to be considered to have committed offence', 'Where any member of an unlawful assembly commits any offence in
the achievemen t of the object of such assembly, every member of
such assembly who aids and assists knowingly at the time of the
commission of offence shall be considered to have committed the
offence.', 2, 'The National Penal (Code) Act, 2017, Chapter-2 (Every member to be considered to have committed offence)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7', 2, 'rule', '63', 'Prohibition of rioting', 'Prohibition of rioting', NULL, 3, 'The National Penal (Code) Act, 2017, Chapter-2 (Prohibition of rioting)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.3', 3, 'clause', '(1)', '', NULL, 'No person shall commit, or cause to b e
committed, the offence of rioting.', 0, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.3.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.3', 3, 'clause', '(2)', '', NULL, 'Where an unlawful assembly or a member thereof uses
force or destroys, damages or causes loss to any public or private
property in the course of achievement of the object of such assembly,
every member of such assem bly shall be considered to have
committed the offence of rioting.', 1, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.3.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.3', 3, 'clause', '(3)', '', NULL, 'Every person who commits the offense referred to in
sub-section (1) shall be liable to a sentence of imprisonment for a
term not exceeding two years and a fine not exceeding twenty
thousand rupees if he or she is armed with a deadly weapon, and to a
sentence of imprisonment for a term not exceeding one year and a
fine not exceeding ten thousand rupees if he or she is not armed with
a deadly weapon.', 2, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7', 2, 'rule', '64', 'Prohibition of abetting rioting', 'Prohibition of abetting rioting', NULL, 4, 'The National Penal (Code) Act, 2017, Chapter-2 (Prohibition of abetting rioting)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.4', 3, 'clause', '(1)', '', NULL, 'No person shall, with intent to
cause the commission of rioting or with the knowledge that rioting is
likely to be committed, abet the commission of rioting by another
person.', 0, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.4.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.4', 3, 'clause', '(2)', '', NULL, 'A person who abets under sub-section (1) shall be liable
to a sentence of imprisonment for a term not exceeding one year, if
the offence of rioting is committed, and to a sentence of
imprisonment for a term not exceeding six months, if the offence of
rioting is not committed, or to a fine not exceeding five thousand
rupees or the both sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7', 2, 'rule', '65', 'Prohibition of acts prejudicial to public tranquility', 'Prohibition of acts prejudicial to public tranquility', NULL, 5, 'The National Penal (Code) Act, 2017, Chapter-2 (Prohibition of acts prejudicial to public tranquility)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.5.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.5', 3, 'clause', '(1)', '', NULL, 'No
person, by words, either spoken or written or by signs or otherwise
shall do any act which, on the ground of religion, color, caste, race,
community or language, is prej udicial to harmonious relationship
between people s of different classes, regions or communities of
Nepal.', 0, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.5.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.5', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a te rm not exceeding one year and a fine not
exceeding ten thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.5.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.5', 3, 'clause', '(3)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) in any shrine , deity place, place of worship or pray or in
any assembly engaged in the performance of a religious or cultural
festival or ceremony shall be liable to an additional sentence of
imprisonment for a term not exceeding one year, in addition to the
sentence referred to in sub-section (2).', 2, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7', 2, 'rule', '66', 'Prohibition of obstructing public servant', 'Prohibition of obstructing public servant', NULL, 6, 'The National Penal (Code) Act, 2017, Chapter-2 (Prohibition of obstructing public servant)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.6.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.6', 3, 'clause', '(1)', '', NULL, 'No person shall
obstruct or attempt to obstruct any public official in the discharg e of
his or her duty in endeavo ring to prevent or disperse an unlawful
assembly or to suppress a riot.', 0, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.6.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.6', 3, 'clause', '(2)', '', NULL, 'A person who commits, or cause s to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding one year or a fine not
exceeding ten thousand rupees or both sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7', 2, 'rule', '67', 'Prohibition of obstructing movement in public place', 'Prohibition of obstructing movement in public place', NULL, 7, 'The National Penal (Code) Act, 2017, Chapter-2 (Prohibition of obstructing movement in public place)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.7.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.7', 3, 'clause', '(1)', '', NULL, 'No
person, by show of any kind of fear or terr or, shall close the
operation of a public road, way, rope -way, cable -car, airport,
railway, water transportation route, post al and other public service,
or obstruct, in any way, the movement of pedestrians, motor vehicles
or animals by obstructing, in any way, a public road, way, rope-way,
cable-car way, airport, railway or water transportation route or
impede or obstruct, in any way, any person in entering into any
public place except in accordance with the order of a competent
authority under a law.', 0, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.7.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.7', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence under sub -section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three years or a fine not
exceeding thirty thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.8', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7', 2, 'rule', '68', 'Prohibition of obstructing public services', 'Prohibition of obstructing public services', NULL, 8, 'The National Penal (Code) Act, 2017, Chapter-2 (Prohibition of obstructing public services)', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_national_penal_code_2074_2017:7.8.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.8', 3, 'clause', '(1)', '', NULL, 'No person shall, by
show of any kind of fear or threat, close, or obstruct, in any way, the
operation of public electricity, telecommunication or other public
services of similar nature or public service specified in law.', 0, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.8.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.8', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three years or a fine not
exceeding thirty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.9', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7', 2, 'rule', '69', 'Prohibition of violating curfew', 'Prohibition of violating curfew', NULL, 9, 'The National Penal (Code) Act, 2017, Chapter-2 (Prohibition of violating curfew)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.9.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.9', 3, 'clause', '(1)', '', NULL, 'No person shall knowingly
violate a curfew order imposed by a competent authority under law
to prevent an unlawful assembly, riot or any other act that breaches
tranquility.', 0, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.9.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.9', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) sh all be liable to a sentence of imprisonment for a term
not exceeding one year or a fine not exceed ing ten thousand rupees
or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.10', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7', 2, 'rule', '70', 'Not to spread rumor', 'Not to spread rumor', NULL, 10, 'The National Penal (Code) Act, 2017, Chapter-2 (Not to spread rumor)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.10.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.10', 3, 'clause', '(1)', '', NULL, 'No person shall, with intent to breach
public tranquility , commit rioting or unde rmine or jeopardize the
sovereignty, geographical or territorial integrity of Nepal or
harmonious relation between different races, castes or communities,
spread or propagate rumors or hold a procession with slogans, in a
manner to provoke any one.', 0, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.10.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.10', 3, 'clause', '(2)', '', NULL, 'Any person who commits, or causes to be committed,
the offence referred to in sub-section (1) shall be liable to a sentence
of imprisonment for a term not exceeding one year or a fine not
exceeding ten thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.11', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7', 2, 'rule', '71', 'Prohibition of providing house, land or vehicle for breaching', 'Prohibition of providing house, land or vehicle for breaching', 'peace: No person, knowingly or having a reasonable reason to know
that another person is going to breach public peace or commit
rioting, shall provide his or her house, land, vehicle or arm to that
other person.', 11, 'The National Penal (Code) Act, 2017, Chapter-2 (Prohibition of providing house, land or vehicle for breaching)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.11.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.11', 3, 'clause', '(2)', '', NULL, 'Any person who commits, or causes to be committed,
the offence referred to in sub-section (1) shall be liable to a sentence
of imprisonment for a term not exceeding six months or a fine not
exceeding five thousand rupees or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.12', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7', 2, 'rule', '72', 'Prohibition of holding tourch procession in sensitive public area', 'Prohibition of holding tourch procession in sensitive public area', NULL, 12, 'The National Penal (Code) Act, 2017, Chapter-2 (Prohibition of holding tourch procession in sensitive public area)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.12.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.12', 3, 'clause', '(1)', '', NULL, 'No person shall, with intent to breach public peace, hold any
tourch procession or assembly or procession carrying a fire or
inflammable substance in any place specified as the sensi tive public
area by order of the competent authority in view of the sovereignty,
geographical or territorial integrity, security of Nepal or pubic
tranquility or decency.', 0, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.12.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.12', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable t o a sentence of imprisonment for a term
not exceeding six months or a fine not exceed ing five thousand
rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.13', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7', 2, 'rule', '73', 'Prohibition of destroying or damaging essential commodities', 'Prohibition of destroying or damaging essential commodities', NULL, 13, 'The National Penal (Code) Act, 2017, Chapter-2 (Prohibition of destroying or damaging essential commodities)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.13.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.13', 3, 'clause', '(1)', '', NULL, 'No person shall, having committed any offence under t his Chapter,
destroy, damage or set on fire, or cause to be done so, any
commodity which is regarded as an essential commodity under the
law or public or private property or disorder such commodity or
property by himself or herself or cause it to be disord ered by another
person, steal such commodity or property or knowingly buy or sell,
or cause to be bought or sold, any commodity obtained by theft.', 0, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.13.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.13', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to an additional sentence of imprisonment
for a term not exceeding one year or a fine not exceeding ten
thousand rupees or both the sentences, in addition to the sentence
imposable for any offence referred to in this Chapter.', 1, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.13.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.13', 3, 'clause', '(3)', '', NULL, 'Where such commodity or property has already been
destroyed or damaged from the offence referred to in sub-section (1),
a compensation equal to the claimed amount shall also be recovered
from such person.', 2, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.13.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7.13', 3, 'clause', '(4)', '', NULL, 'Where the person who has committed the offence
referred to in sub-section (1) is identified, such person, and where
such person is not so identified, the person who induces or orders the
commission of such act shall be considered to have committed the
offence.', 3, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:7.14', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:7', 2, 'rule', '74', 'Statute of limitation', 'Statute of limitation', 'No complaint on an offence under this
Chapter shall lie after th e lapse of three months from the date of
commission of such offence.', 14, 'The National Penal (Code) Act, 2017, Chapter-2 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-3', '', NULL, 'Offences Relating to Contempt of Authority of Public Servants', 8, 'The National Penal (Code) Act, 2017, Chapter-3', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '75', 'Prohibition of obstructing the service of summons, process etc', 'Prohibition of obstructing the service of summons, process etc', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of obstructing the service of summons, process etc)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.0', 3, 'clause', '(1)', '', NULL, 'No person shall obstru ct in or object to, or cause to be done so,
the service of a summons, process, arrest warrant, notice or order
issued under a law or the making of search, seizure , survey,
measurement or public inquiry or arresting any person in pursuance
of a warrant.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.0', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding six months or a fine not exceed ing five thousand
rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.0', 3, 'clause', '(3)', '', NULL, 'Where a public servant commits the of fence referred to
in sub-section (1), he or she shall be liable to an additional sentence
of imprisonment for a term not exceeding three months.', 2, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '76', 'Prohibition of refusing to receive and returning summons,', 'Prohibition of refusing to receive and returning summons,', 'process, notice or order: (1) Where a person in w hose name a
summons, process, notice, arrest warrant or order has been issued
under law is tendered for the service thereof on him or her, such
person shall, with mala fide intention, not refuse to receive, and
return, such summons, process, notice or arrest warrant.', 1, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of refusing to receive and returning summons,)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.1', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding three months or a fine not exceed ing five thousand
rupees or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '77', 'Prohibition of absc onding to avoid service of summons, process,', 'Prohibition of absc onding to avoid service of summons, process,', 'notice or order: (1) No person, being legally bound to receive a
summons, process, notice, arrest warrant or order issued by the
competent authority, shall abscond, with mala fide intention to avoid
being served with such summons, process, notice, arrest warrant or
order.', 2, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of absc onding to avoid service of summons, process,)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.2', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding three months or a fine not exceed ing five thousand
rupees or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '78', 'Prohibition of tearing out or removing summons, process etc', 'Prohibition of tearing out or removing summons, process etc', NULL, 3, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of tearing out or removing summons, process etc)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.3', 3, 'clause', '(1)', '', NULL, 'No person shall, with mala fide intention, tear out or remove a
summons, process, arrest warrant, notice or order affixed to a place
in accordance with law, until its purpose is served.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.3.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.3', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding six months or a fine not
exceeding five thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '79', 'Prohibition of serving process in a false manner', 'Prohibition of serving process in a false manner', NULL, 4, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of serving process in a false manner)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.4', 3, 'clause', '(1)', '', NULL, 'No person
who is legally bound to serve, or cause to be served, a process shall
serve the process in a false manner.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.4.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.4', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding one year or a fine not exceeding ten thousand rupees
or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '80', 'Prohibition of omission to produce document', 'Prohibition of omission to produce document', NULL, 5, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of omission to produce document)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.5.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.5', 3, 'clause', '(1)', '', NULL, 'No person who
is legally bound to produce or deliver up any document to any office,
court or public servant under law shall omit so to produce or deliver
up such document.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.5.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.5', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not excee ding six months or a fine not exceeding five thousand
rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '81', 'Prohibition of making false statement by person under oath', 'Prohibition of making false statement by person under oath', NULL, 6, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of making false statement by person under oath)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.6.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.6', 3, 'clause', '(1)', '', NULL, 'A person who is bound by law or by an oath to state the truth on any
subject to any competent authority or is a public office holder upon
taking oath under law shall not, in that capacity, state any false
statement.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.6.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.6', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding two years or a fine not exceeding twenty thousand
rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '82', 'Prohibition of refusing oath', 'Prohibition of refusing oath', NULL, 7, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of refusing oath)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.7.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.7', 3, 'clause', '(1)', '', NULL, 'No person who is present before
the competent authority to state the truth on any subject shall refuse
to take an oath to state the truth on s uch subject when so required to
take such oath.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.7.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.7', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding three months or a fine not exceeding five thousand
rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.8', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '83', 'Prohibition of refusing to answer', 'Prohibition of refusing to answer', NULL, 8, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of refusing to answer)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.8.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.8', 3, 'clause', '(1)', '', NULL, 'No person who is under a
legal duty to state the truth on any subject to a competent authority
shall refuse to answer any question demanded of him or her on such
subject by such authority.
Provided that no person shall be compelled to testify against
himself or herself.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.8.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.8', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding six months or a fine not exceeding five thous and
rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.9', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '84', 'Prohibition of giving false information', 'Prohibition of giving false information', NULL, 9, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of giving false information)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.9.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.9', 3, 'clause', '(1)', '', NULL, 'No person shall give
any false information to any one, with intent to prevent any public
servant from doing any act which he or she is bound by law to do or
to cause such public servant to do anything which he or she need not
or ought not to do.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.9.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.9', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding one year or a fine not exceeding ten thousand rupees
or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.10', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '85', 'Prohibition of obstructing', 'Prohibition of obstructing', NULL, 10, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of obstructing)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.10.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.10', 3, 'clause', '(1)', '', NULL, 'No person shall , by way of
intimidation or force or in any other way , obstruct or hinder any
public servant, who is discharging his or her public duties, in the
discharge of such duties.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.10.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.10', 3, 'clause', '(2)', '', NULL, 'No person shall knowingly obstruct or hinder the
process of forfeiture, collection of records, withholding, auction or
sale of any property being carried out in accordance with law.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.10.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.10', 3, 'clause', '(3)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) or (2) shall be liable to a sentence of imprisonment for a
term not exceeding one year or a fine not exceeding ten thousand
rupees or both the sentences.', 2, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.11', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '86', 'Prohibition of refusing to render assistance to public servant', 'Prohibition of refusing to render assistance to public servant', NULL, 11, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of refusing to render assistance to public servant)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.11.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.11', 3, 'clause', '(1)', '', NULL, 'No person under a legal duty t o render assistance to a public servant
in the execution of his or her public duty shall refuse to so render
such assistance.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.11.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.11', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not e xceeding six months or a fine not exceeding five thousand
rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.12', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '87', 'Prohibition of disobedience to order', 'Prohibition of disobedience to order', NULL, 12, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of disobedience to order)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.12.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.12', 3, 'clause', '(1)', '', NULL, 'No person shall disobey
an order made by a competent authority in accordance with law, by
omitting to do anything ought to be done under law or doing
anything prohibited by law.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.12.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.12', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding six months or a fine not exceeding five thousand
rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.13', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '88', 'Statute of limitation', 'Statute of limitation', 'No complaint shall lie after the lapse of three
months from the date of knowledge of the commission of any
offence under Section 78, 80 or 83 and from the date of the
commission of any offence under the other Sections of this Chapter.
Chpater-4
Offences against Public Justice', 13, 'The National Penal (Code) Act, 2017, Chapter-3 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.14', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '89', 'Prohibition of fabricating evidence', 'Prohibition of fabricating evidence', NULL, 14, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of fabricating evidence)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.14.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.14', 3, 'clause', '(1)', '', NULL, 'Except as otherwise
provided in this Act, no person shall fabricate evidence, cause any
circumstance to exist, forge any document or electroni c record or
make any false entry in any document or electronic record, with
intent to use it in a judicial or other legal proceeding.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.14.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.14', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a se ntence of
imprisonment for a term not exceeding five years and a fine not
exceeding fifty thousand rupees.
Provided that where a sentence of imprisonment for life has
been imposed on any person on the basis of such false evidence, the
offender shall be liable to a sentence of imprisonment for a term not
exceeding seven years and a fine not exceeding seventy thousand
rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.14.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.14', 3, 'clause', '(3)', '', NULL, 'Notwithstanding anything contained elsewhere in this
Section, no sentence shall be so imposed under this Section that the
sentence is in excess of the maximum sentence that can be imposed
on the offence in relation to which the evidence has been fabricated.', 2, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.15', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '90', 'Prohibition of making or issuing false certificate', 'Prohibition of making or issuing false certificate', NULL, 15, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of making or issuing false certificate)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.15.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.15', 3, 'clause', '(1)', '', NULL, 'No person
with authority or duty under law to submit, certify, a uthenticate or
issue a certificate or submit an affidavit in relation to any matter
shall submit, certify, authenticate or issue such certificate or submit
such affidavit, knowingly setting down a false statement in such
certificate or affidavit.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.15.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.15', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding two years and a fine not
exceeding twenty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.16', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '91', 'Prohibition of using false evidence or certificate', 'Prohibition of using false evidence or certificate', NULL, 16, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of using false evidence or certificate)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.16.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.16', 3, 'clause', '(1)', '', NULL, 'No person
shall, knowing that any evidence or certificate is false, use, or cause
to be used, as true such false evidence or certificate.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.16.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.16', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three years and a fine not
exceeding thirty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.17', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '92', 'Prohibition of destroying document', 'Prohibition of destroying document', NULL, 17, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of destroying document)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.17.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.17', 3, 'clause', '(1)', '', NULL, 'No person who is under a
legal duty to produce any document or electronic record as evidence
in a judicial or other legal proceeding shall knowingly destroy,
obliterate, render illegible such document or record, or otherwise
make it incapable of being used as evidence.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.17.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.17', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding two years and a fine not
exceeding twenty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.17.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.17', 3, 'clause', '(3)', '', NULL, 'No person shall, in contravention of law, knowingly
destroy, obliterate, render illegible any document or electronic record
produced in any judicial or other legal proceeding or otherwise
making such document or record incapable of being used as evidence
or cause it to disappear illegally or give it to another person in an
unauthorized manner.', 2, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.17.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.17', 3, 'clause', '(4)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (3) shall be liable to a sentence of
imprisonment for a term not exceeding four years and a fine not
exceeding forty thousand rupees.', 3, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.17.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.17', 3, 'clause', '(5)', '', NULL, 'If a public servant commi ts the offence referred to in
sub-section (1) or (3), he or she shall be liable to double the sentence
referred to in that sub-section.', 4, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.18', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '93', 'Prohibition of concealing evidence of offence', 'Prohibition of concealing evidence of offence', NULL, 18, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of concealing evidence of offence)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.18.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.18', 3, 'clause', '(1)', '', NULL, 'No person shall,
with intent to protect any offender, conceal or destroy any evidence
relating to the offense committed by the offender or render it
ineligible to be used as evidence.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.18.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.18', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three years and a fine not
exceeding thirty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.19', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '94', 'Prohibition of obstructing the giving of information', 'Prohibition of obstructing the giving of information', NULL, 19, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of obstructing the giving of information)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.19.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.19', 3, 'clause', '(1)', '', NULL, 'No
person shall restraint or otherwise obstruct or hinder a person who,
upon knowing that an offence ha s been committed or is about to be
committed, intends to give information or notice about such offence
to the police or competent authority.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.19.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.19', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding two years or a fine not
exceeding twenty thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.20', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '95', 'Prohibition of harboring offender', 'Prohibition of harboring offender', NULL, 20, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of harboring offender)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.20.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.20', 3, 'clause', '(1)', '', NULL, 'No person shall knowingly
harbor an offender with intent to prevent him or her fr om being
apprehended or save him or her from a lawful sentence.
Explanation: For the purposes of this Section, the term
“offender” means a person who is suspected or accused of an offence
or convicted by a court of such offence.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.20.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.20', 3, 'clause', '(2)', '', NULL, 'A person who commits, or cause s to be committed, the
offence referred to in sub-section (1) shall be liable to the sentence as
follows:
(a) Sentence of imprisonment for a term not exceeding five
years and a fine not exceeding fifty thousand rupees
where that person has harb ored the offender of an
offence punishable by imprisonment for life or
imprisonment for a term not exceeding twenty years,
(b) Sentence of imprisonment for a term not exceeding
three years and a fine not exceeding thirty thousand
rupees where that person h as harbored the offender of
an offence punishable by imprisonment for a term not
exceeding ten years,
(c) Sentence of imprisonment or fine not exceeding one
fourth of the maximum term of imprisonment or amount
of fine or both the sentences imposable for th e offence
where that person has harbored the offender of the
offence other than that mentioned in clause (a) or (b).', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.20.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.20', 3, 'clause', '(3)', '', NULL, 'Notwithstanding anything contained in sub -section (1),
no offence referred to in this Section shall be considered to have
been commit ted where the offender''s husband or wife or father,
mother, son, daughter, elder brother, younger brother, elder sister,
younger sister, grand -father, grand -mother, grand -son, grand -
daughter, mother -in-law, father -in-law, daughter -in-law or son -in-
law has harbored the offender.', 2, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.21', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '96', 'Obligation to give information of commission of offence', 'Obligation to give information of commission of offence', NULL, 21, 'The National Penal (Code) Act, 2017, Chapter-3 (Obligation to give information of commission of offence)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.21.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.21', 3, 'clause', '(1)', '', NULL, 'No
person under a legal duty to give information regarding any offence
shall, knowing that such offence has been or is going to be
committed, omit to give information o f such offence or no person
who knows the commission of any offence shall intentionally give
false information about that offence.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.21.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.21', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding two years or a fine not
exceeding twenty thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.22', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '97', 'Prohibition of concealment of property or fraudulent claim to', 'Prohibition of concealment of property or fraudulent claim to', 'property: (1) No person shall fraudulently conceal, transfer or
deliver to any person, or caused to be concealed, transferred or
delivered, any property, or right in such property, wh ich is liable to
be forfeited, withheld, auctioned , sold or enforced or inventory of
which is to be taken pursuant to a decision of a court o r competent
authority, intending thereby to prevent that property or right from
being so forfeited, withheld, auctioned, sold or enforced or make a
claim to such property or right therein.', 22, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of concealment of property or fraudulent claim to)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.22.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.22', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding two years or a fine not
exceeding twenty thousand rupees or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.23', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '98', 'Prohibition of making false complaint', 'Prohibition of making false complaint', NULL, 23, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of making false complaint)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.23.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.23', 3, 'clause', '(1)', '', NULL, 'No person shall, with
intent to injure or annoy any person, make a false claim or accusation
or give false in formation against such person before or to an
authority making judicial proceeding.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.23.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.23', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable half the
maximum sentence imposable for the offence in respect of which
such false accusation has been made.
Provided that the provision of this Section shall not apply to
any case in which the Government of Nepal is plaintiff.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.23.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.23', 3, 'clause', '(3)', '', NULL, 'Where the offence referred to in sub-section (1) has
resulted in any kind of harm or loss to a person who is a victim of
such offence, compensation for such harm or loss shall be recovered
from the offender to the victim.', 2, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.24', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '99', 'Prohibition of making investigation or prosecution maliciously', 'Prohibition of making investigation or prosecution maliciously', NULL, 24, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of making investigation or prosecution maliciously)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.24.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.24', 3, 'clause', '(1)', '', NULL, 'No authority responsible by law for making investigation or
prosecution shall make investigation or prosecution maliciously,
with intent to have an innocent person bear liability or to save the
real offender.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.24.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.24', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding six months or a fine not
exceeding five thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.24.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.24', 3, 'clause', '(3)', '', NULL, 'Where any person suffers any kind of harm or loss from
the offence referred to in sub-section (1), he or she shall be entitled
to get compensation from such offender.', 2, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.25', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '100', 'Prohibition of failure to appear in violation of terms and', 'Prohibition of failure to appear in violation of terms and', 'conditions of guarantee: (1) No person wh o has been charged with
an offence and released on guarantee shall fail, without a reasonable
cause, to appear in the office or court to which guarantee is given in
accordance with the terms and conditions of such guarantee.
Explanation: For the purpose of this S ection, “guarantee ”
means cash, bank guarantee or personal guarantee.', 25, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of failure to appear in violation of terms and)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.25.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.25', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding one year or a fine not excee ding ten tho usand rupees
or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.25.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.25', 3, 'clause', '(3)', '', NULL, 'Where a person who fails to so appear under this
Section is convicted of the offence with which he or she has been
charged shall be liable to the additional sentence under this Section,
in addition to the sentence imposable on him or her for such offence.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.25.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.25', 3, 'clause', '(4)', '', NULL, 'Where a person who is released on personal guarantee
in accordance with law fails to appear in the office or court in
accordance with such guarantee, the person giving such guarantee
shall be liable to a sentence of fine not exceeding fifty thousand
rupees.', 2, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.25.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.25', 3, 'clause', '(5)', '', NULL, 'A person who has been sentenced under this Section
shall not be eligible to become a surety without security until three
years.', 3, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.26', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '101', 'Prohibition of obstructing apprehension or escaping from', 'Prohibition of obstructing apprehension or escaping from', 'custody: (1) No person for whose apprehension an arrest warrant has
been issued shall knowingly make any obstruction, by using force, in
the course of apprehension or to the apprehension of himself or
herself or to escape from apprehension if already apprehended or no
person who is lawfully detained in custody shall escape or attempt to
escape from such custody.', 26, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of obstructing apprehension or escaping from)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.26.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.26', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not excee ding three years or a fine not
exceeding thirty thousand rupees or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.27', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '102', 'Prohibition of obstructing apprehension or rescuing from', 'Prohibition of obstructing apprehension or rescuing from', 'custody: (1) No person shall intentionally make obstruction in the
course of apprehension of or to the appr ehension of any other person
for whose apprehension an arrest warrant has been issued in
accordance with law or rescue such other person from apprehension
if already apprehended or intentionally escape or aid in the escape of
a person who is lawfully detained in custody from such custody.', 27, 'The National Penal (Code) Act, 2017, Chapter-3 (Prohibition of obstructing apprehension or rescuing from)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.27.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.27', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three years or a fine not
exceeding thirty thousand rupees or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.27.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.27', 3, 'clause', '(3)', '', NULL, 'If any public servant commits or causes to be committed
the offence referred to in sub-section (1), he or she shall be liable to
double the sentence specified in sub-section (2).', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.28', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8', 2, 'rule', '103', 'Statute of limitation', 'Statute of limitation', NULL, 28, 'The National Penal (Code) Act, 2017, Chapter-3 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.28.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.28', 3, 'clause', '(1)', '', NULL, 'There shall be no statute of limitation for
making a complaint in relation to any of the offences referred to in
Section 101 or 102.', 0, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:8.28.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:8.28', 3, 'clause', '(2)', '', NULL, 'No complaint shall lie after the lapse of three months
from the date of commission of the offence under Section 100 and
from the date of knowledge of the commission of any of the other
offences under this Chapter.', 1, 'The National Penal (Code) Act, 2017, Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-5', '', NULL, 'Offences against Public Interest, Health, Safety,
Convenience and Morals', 9, 'The National Penal (Code) Act, 2017, Chapter-5', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '104', 'Prohibition of spreading infectious disease', 'Prohibition of spreading infectious disease', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of spreading infectious disease)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.0', 3, 'clause', '(1)', '', NULL, 'No person shall do
any a ct that spreads or is likely to spread any kind of infectious
disease which is dangerous to life of any one.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.0', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding ten years and a fine not
exceeding one hundred thousand rupees, if the offence has been
committed intentionally or knowingly, to a sentence of imprisonment
for a term not exceeding five years and a fine not exceeding fifty
thousand rupees, if the offence has been committed recklessly, and to
a sentence of imprisonment for a term not exceeding three years and
a fine not exceeding thirty thousand rupees, if the offence has been
committed negligently.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '105', 'Prohibition of transmitting human immuno-deficiency virus', 'Prohibition of transmitting human immuno-deficiency virus', '(HIV positive): (1) No person, knowing that his or her own body or
any other''s body contains human immuno -deficiency virus (HIV
positive) or the virus of Hepatitis B, shall with intent to transmit such
disease to another person, do nate his or her blood to such person or
cause the donation of such other person''s blood or have sexual
intercourse with any one without taking any kind of precaution or
transfuse in any way his or her or such person''s blood, semen, saliva,
sputum or human organ into other''s body.', 1, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of transmitting human immuno-deficiency virus)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.1', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding ten years and a fine not
exceeding one hundred thousand rupees.
Provided that where such disease has got transmitted with
negligence or recklessness, failing any intent to transmit it, the
offender shall be liable to a sentence of imprisonment for a term not
exceeding three years and a fine not exceeding thirty thousa nd
rupees.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.1', 3, 'clause', '(3)', '', NULL, 'Where the victim himself or herself has solicited and
established sexual intercourse with a person having the human
immuno-deficiency virus or the virus of Hepatitis B, the person
having the infection of such virus shall not be considered to have
committed the offence referred to in this Section.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '106', 'Prohibition of violating law relating to communicable disease', 'Prohibition of violating law relating to communicable disease', NULL, 2, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of violating law relating to communicable disease)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.2', 3, 'clause', '(1)', '', NULL, 'No person shall violate any rule, directive or order relating to
communicable diseases issued by the Government of Nepal , Sta te
Government or Local Level or the competent authority under law.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.2.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.2', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding six months or a fine n ot
exceeding five thousand rupees or both the sentences.
Provided that where any violation of such rule, directive or
order is likely to cause the death of a person, the offender shall be
liable to the sentence under Section 104.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '107', 'Prohibition of adul teration of food', 'Prohibition of adul teration of food', NULL, 3, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of adul teration of food)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.3', 3, 'clause', '(1)', '', NULL, 'No person shall produce
any food or drink to be consumed by the public by mixing into it any
injurious substance that is inedible, undrinkable or inconsumable or
any substance that is edible, drinkable or consumable but
substandard or any injurious chemical substance, or sell or distribute
it or sell or distribute any food of which expiry date has expired or
which is adulterated or sell, distribute, import or offer for sale or
distribution any food of standard falling short of the pres cribed
standard or inedible substance.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.3.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.3', 3, 'clause', '(2)', '', NULL, 'Any person who commits, or causes to be committed,
the offence referred to in sub-section (1) shall be liable to a sentence
of imprisonment for a term not exceeding five years and a fine not
exceeding fifty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_national_penal_code_2074_2017:9.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '108', 'Prohibition of selling, distributing food by misrepresentation', 'Prohibition of selling, distributing food by misrepresentation', NULL, 4, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of selling, distributing food by misrepresentation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.4', 3, 'clause', '(1)', '', NULL, 'No person shall sell or distribute any food, lying or misrepresenting
that it is a different food or that a food which is of low quality or
inedible is a food of high qua lity, or mixing any food substance of
low standard or inedible food substance into any food substance of
high quality', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.4.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.4', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding five years or a fine not
exceeding fifty thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '109', 'Prohibition of selling or distributing goods by misrepresentation', 'Prohibition of selling or distributing goods by misrepresentation', NULL, 5, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of selling or distributing goods by misrepresentation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.5.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.5', 3, 'clause', '(1)', '', NULL, 'No person shall sell any low quality good, except food, by
misrepresenting that such good is original one or any good by
causing to believe that it is a different good or any good so
adulterated as to degrade its quality or change a label on any good or
sell any good of which the date of expiry has expired.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.5.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.5', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three years or a fine not
exceeding thirty thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '110', 'Prohibition of hoarding consumable goods intended for sale', 'Prohibition of hoarding consumable goods intended for sale', NULL, 6, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of hoarding consumable goods intended for sale)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.6.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.6', 3, 'clause', '(1)', '', NULL, 'No person shall increase the price of any consumable goods by
creating an artificial shortage of such goods in the market or sell, or
cause to be sold, such goods at higher price or dump, store or hoard
such goods by refraining from selling such goods with the motive of
making undue profit from the sale of such goods.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.6.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.6', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding five years and a fine not
exceeding fifty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '111', 'Prohibition of fouling water', 'Prohibition of fouling water', NULL, 7, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of fouling water)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.7.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.7', 3, 'clause', '(1)', '', NULL, 'No person shall foul the water to
be consumed by the public or the water of any public spring so as to
render it unfit for drinking or fou l the water to be used for any
purpose other than drinking so as to render it unfit for that purpose.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.7.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.7', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to the sentence as
follows:
(a) Imprisonment for a term not exceeding three years or a
fine not exceeding thirty thousand rupees or both the
sentences, in the case of a person who fouls, or causes
to be fouled, drinking water or its spring,
(b) Imprisonment for a term not exceeding six months or a
fine not exceeding five thousand rupees or both the
sentences, in the case of a person who fouls, or causes
to be fouled, water to be used for other purpose.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.8', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '112', 'Prohibition of polluting environment', 'Prohibition of polluting environment', NULL, 8, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of polluting environment)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.8.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.8', 3, 'clause', '(1)', '', NULL, 'No person shall
generate, transmit, release or stockpile wastages in such a manner as
to cause significant adverse impact on the environment.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.8.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.8', 3, 'clause', '(2)', '', NULL, 'No person shall cause pollution in such a manner as to
cause injury to public health or danger to body or life of the public,
or generate, transmit, emit or stockpile, sound, heat or radioactive
wave or hazardous waste, as the case may be, from a mechanical
device.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.8.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.8', 3, 'clause', '(3)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment fo r a term not exceeding one year or a fine not
exceeding ten thousand rupees or both the sentences.', 2, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.8.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.8', 3, 'clause', '(4)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (2) shall be liable to a sentence of
imprisonment for a term not exceeding five years or a fine not
exceeding fifty thousand rupees or both the sentences.', 3, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.9', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '113', 'Prohibition of causing danger or obstruction in public way, river', 'Prohibition of causing danger or obstruction in public way, river', 'or place: (1) No person shall, by doing any act or by omitting to take
order with or maintain any property of him or her or under his or her
control or charge, cause danger, obstruction or hindrance to any one
in any public way, river or other public place.', 9, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of causing danger or obstruction in public way, river)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.9.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.9', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of a
fine not exceeding twenty-five thousand rupees.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.10', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '114', 'Prohibition of reckless conduct in using toxic or explosive', 'Prohibition of reckless conduct in using toxic or explosive', 'substance: (1) No person shall do, in the operation or with the use of
any explosive substance or fire or inflammable substance, explosive
substance or deadly weapon or machine, any act so recklessly as to
endanger or to be likely to cause injury to human body or life or
knowingly or recklessly omit to make such arrangement with such
substance of him or her or under his or her possession or charge as is
necessary to prevent any probable danger to human life.', 10, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of reckless conduct in using toxic or explosive)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.10.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.10', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding one year or a fine not
exceeding ten thousand rupees or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.11', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '115', 'Prohibition of recklessness conduct with respect to constructing,', 'Prohibition of recklessness conduct with respect to constructing,', 'demolishing or repairing buildings: (1) No person shall, in
constructing, demolishing or repair ing a building, knowingly or
recklessly omits to take such arrangement with that building as is
necessary to guard against or prevent any probable danger to cause
death of or grievous hurt to any one from such act or from the fall or
collapse of that building or any part thereof.', 11, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of recklessness conduct with respect to constructing,)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.11.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.11', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding one year or a fine not
exceeding ten thousand rupees or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.12', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '116', 'Prohibition of reckless conduct with respect to animals and', 'Prohibition of reckless conduct with respect to animals and', 'birds: (1) No person shall, in keeping or caring and cultivating any
violent or other animal or bird of him or her or under his or her
control or custody, knowingly or recklessly omits to take such
precautionary measure with that animal or bird as is necessary to
guard against or prevent any probable danger to cause death of or
grievous hurt to any one from such act or from such animal or bird.', 12, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of reckless conduct with respect to animals and)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.12.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.12', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes t o be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding one year or a fine not
exceeding ten thousand rupees or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.13', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '117', 'Prohibition of setting animal free', 'Prohibition of setting animal free', NULL, 13, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of setting animal free)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.13.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.13', 3, 'clause', '(1)', '', NULL, 'No pe rson shall set any
animal or bird of him or her or under his or her custody or control
free to other''s house or land, public road or way or public place.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.13.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.13', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding one year or a fine not
exceeding ten thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.14', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '118', 'Prohibition of indecent conduct', 'Prohibition of indecent conduct', NULL, 14, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of indecent conduct)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.14.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.14', 3, 'clause', '(1)', '', NULL, 'No person shall enter into a
public place or any place where he or she ha s no legal right to enter
into and behave any one indecently or manhandle or annoy any
woman, child or person with physical disability in any public place
or attempt to do such act.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.14.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.14', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding one year or a fine not
exceeding ten thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.15', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '119', 'Prohibition of soliciting prostitution', 'Prohibition of soliciting prostitution', NULL, 15, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of soliciting prostitution)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.15.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.15', 3, 'clause', '(1)', '', NULL, 'No person sh all solicit
prostitution.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.15.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.15', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three years and a fine not
exceeding thirty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.16', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '120', 'Prohibition of providin g house, land to be used for prostitution', 'Prohibition of providin g house, land to be used for prostitution', 'or sexual intercourse with prostitute: (1) No person shall
knowingly provide his or her house, land or means of transport for
the purpose of prostitution or having sexual intercourse with a
prostitute.', 16, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of providin g house, land to be used for prostitution)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.16.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.16', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding six months or a fine not exceeding five thousand
rupees or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.17', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '121', 'Prohibition of producing or selling obscene b ooks, pamphlets', 'Prohibition of producing or selling obscene b ooks, pamphlets', 'etc: (1) No person shall commit any of the following act s, including
producing any obscene book, pamphlet publicly:
(a) Producing, printing or publishing or circulating through
electronic media any obscene book, pamphlet, drawing,
film, pic ture, record or any other item which is
lascivious (increases physical libido) or appeals to the
prurient interest or makes characterless,
(b) Purchasing, selling, distributing or letting to hire or
publicly exhibiting such obscene item or holding such
item with intent to do so,
(c) Advertising that such obscene item is available from
any person in this way,
(d) Exporting or importing or holding such obscene item
with intent to sell, distribute it.', 17, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of producing or selling obscene b ooks, pamphlets)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.17.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.17', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding one year or a fine not exceeding ten thousand rupees
or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.17.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.17', 3, 'clause', '(3)', '', NULL, 'Notwithstanding anything contained elsewhere in this
Section, the provis ion of this Section shal l not apply to any work
which is in the interest of, or which is of importance from the
perspective of, science, education, art, literature, research or learning
or which is kept or made for a religious purpose.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.18', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '122', 'Prohibition of showing sexual organ in public place', 'Prohibition of showing sexual organ in public place', NULL, 18, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of showing sexual organ in public place)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.18.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.18', 3, 'clause', '(1)', '', NULL, 'No
person above ten years of age shall, except for the purpose of
medical sciences or treatment, do any obscene act or conduct or
show his or her sexual organ or utter or make any obscene words or
gesture to any one in a public place.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.18.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.18', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding six months or a fine not exceeding five thousand
rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.19', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '123', 'Prohibition of having sexual interco urse in public place', 'Prohibition of having sexual interco urse in public place', NULL, 19, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of having sexual interco urse in public place)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.19.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.19', 3, 'clause', '(1)', '', NULL, 'No
person shall have sexual intercourse with any one or any kind of
unnatural sexual intercourse in a public place, or in any other place
in a manner that such intercourse is visible to others.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.19.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.19', 3, 'clause', '(2)', '', NULL, 'A person who commits the offenc e referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding one year or a fine not exceeding ten thousand rupees
or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.20', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '124', 'Prohibition of committing public nuisance', 'Prohibition of committing public nuisance', NULL, 20, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of committing public nuisance)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.20.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.20', 3, 'clause', '(1)', '', NULL, 'Except as
otherwise provided in a law, no person shall do any act or omit to do
any act legally required to be done, which causes any kind of harm,
injury, danger or annoyance to the public or to the people who dwell
in the vicinity.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.20.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.20', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of fine not exceeding twenty -
five thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.21', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '125', 'Prohibition of gambling or betting', 'Prohibition of gambling or betting', NULL, 21, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of gambling or betting)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.21.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.21', 3, 'clause', '(1)', '', NULL, 'No person shall gamble or
cause gambling.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.21.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.21', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to the sentence as follows:
(a) Imprisonment for a term not exceeding three
months or a fine not exceeding thirty thousand
rupees, in the case of one who gambles or causes
any one to gamble for the first time,
(b) Imprisonment for a te rm not exceeding one year
and a fine not exceeding fifty thousand rupees, in
the case of one who gambles or causes any one to
gamble for the second time, and additional
sentence of imprisonment for a term not
exceeding three months and a fine not exceeding
ten thousand rupees for every subsequent offence.
Explanation: For the purposes of this Act,-', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.21.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.21', 3, 'clause', '(1)', '', NULL, '"gambling" means a game or process of any type
to be so played by betting as to gain, lose or win
any kind of movable or immovable property or
return, on the basis of contingency, and this term
also includes any betting or waging so made by
one who does not gamble himself or herself as to
gain or lose any movable, immovable property or
return depending on the win or loss of others.
Provided that any of the f ollowing games
or programs shall not be considered to be
gambling:
(a) A game so played, with the approval of the
Government of Nepal, for entertainment in
a public ceremony, fair, feast, festival,
exhibition or event that a small amount of
movable property is won or lost,
(b) A lottery operated with the approval of the
authorized authority.', 2, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.21.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.21', 3, 'clause', '(2)', '', NULL, '"one who causes any one to gamble " means a
person who causes gambling by knowingly
providing a house, room, space or vehicle under
his or her ownership, possession , use or custody
or by providing any kind of instrument for
gambling.', 3, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.21.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.21', 3, 'clause', '(3)', '', NULL, 'All instruments used for gambling and movable and
immovable properties earned from gambling shall be forfeited.
Provided that a house, room, place or means of transport
where gambling has taken place shall not be forfeited.', 4, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.21.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.21', 3, 'clause', '(4)', '', NULL, 'No person shall bet or cause betting.', 5, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.21.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.21', 3, 'clause', '(5)', '', NULL, 'For the purpose s of sub -section (4), a person who so
bets that he or she will receive or lose any movable, immovable
property or consideration if any particular par ty wins or loses any
game or process that can be played, or caused to be played, under
law shall be considered to have committed the offence of betting.', 6, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.21.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.21', 3, 'clause', '(6)', '', NULL, 'In the event of commission of the offence referred to in
sub-section (4), the offender shall be li able to a sentence of
imprisonment for a term not exceeding one year and a fine not
exceeding ten thousand rupees, along with the forfeiture of the
claimed amount used in the offence.', 7, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (6)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.21.8', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.21', 3, 'clause', '(7)', '', NULL, 'Convictions pronounced by a court shall be taken into
account for t he purpose of establishing recidivism in relation to the
offence referred to in this Section.', 8, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (7)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.22', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '126', 'Prohibition of soliciting alms (begging) or causing begging', 'Prohibition of soliciting alms (begging) or causing begging', NULL, 22, 'The National Penal (Code) Act, 2017, Chapter-5 (Prohibition of soliciting alms (begging) or causing begging)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.22.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.22', 3, 'clause', '(1)', '', NULL, 'No person shall solicit alms (begging) in a public place or use a child
for the purposes of begging under the pretense of singing, dancing,
playing or doing any act or use other person for purposes of begging,
in return for any kind of money or wages paid by him or her to that
other person, or abet begging.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.22.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.22', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to the sentence as follows and the claimed
amount of begging shall also be forfeited:
(a) I mprisonment for a term not exceeding one month or a
fine not exceeding one thousand rupees, in the case of
begging for the first time, and imprisonment for a term
not exceeding two months or a fine not exceeding two
thousand rupees for every instance, from the second
instance onwards,
(b) Imprisonment for a term not exceeding one year or a
fine not excee ding ten thousand rupees or both the
sentences, in the case of causing begging for the first
time, and imprisonment for a term not exceeding three
years or a fine not exceeding thirty thousand rupees or
both the sentences for every instance, from the second
instance onwards.
Explanation: For the purposes of this Section,-', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.22.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.22', 3, 'clause', '(1)', '', NULL, 'begging by a sage, saint, hermit or monk visiting
home to home as per the tradition practiced from
time immemorial or begging in any religious or
cultural work shall not be considered to be an
offence under this Section,', 2, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.22.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.22', 3, 'clause', '(2)', '', NULL, '"public place" means any road, street, park, motor
vehicle stop, government office or office
premises, and this term also includes a means of
transport in public use.', 3, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.23', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '127', 'Compensation to be paid', 'Compensation to be paid', 'Where any harm or loss is caused t o any
one or any property of any one from any of the offences referred to
in Sections 104, 105, 106, 107, 108, 109, 110, 111, 113, 114, 115,
116, 117, 118 and 124 of this Chapter, compensation shall be
ordered to be paid by the offender to the person who s o suffers such
harm or loss.', 23, 'The National Penal (Code) Act, 2017, Chapter-5 (Compensation to be paid)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.24', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9', 2, 'rule', '128', 'Statute of limitation', 'Statute of limitation', NULL, 24, 'The National Penal (Code) Act, 2017, Chapter-5 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.24.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.24', 3, 'clause', '(1)', '', NULL, 'In the case of any offence under this
Chapter which has caused the death of any one, there shall be no
statute of limitation for making a complaint in relation to such
offence.', 0, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:9.24.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:9.24', 3, 'clause', '(2)', '', NULL, 'No complaint shall lie after the expiry of three months
after the date of commission of any of the offences under Sections
113,114, 115, 116, 117, 118, 119, 120, 121 and 122 and after the
expiry of six months from the date of knowledge of commission of
any of the other offences under this Chapter.', 1, 'The National Penal (Code) Act, 2017, Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-6', '', NULL, 'Offences Relating to Arms and Ammunitions', 10, 'The National Penal (Code) Act, 2017, Chapter-6', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10', 2, 'rule', '129', 'Prohibition of manufacturing arms without obtaining license', 'Prohibition of manufacturing arms without obtaining license', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-6 (Prohibition of manufacturing arms without obtaining license)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10.0', 3, 'clause', '(1)', '', NULL, 'No person shall manufacture or repair arms and ammunition without
obtaining a license or in a mann er to be contrary to the terms and
restrictions specified in the license, even if, obtained.
Explanation: For the purposes of this Act,-
(a) "arms" means a canon, mortar, tank, machine gun, rifle,
gun, pistol, revolver or other device of similar nature to
be operated by using or not using ammunition , and this
term also includes spare parts of and machinery and
equipment for manufacturing any arms,
(b) "machine gun" means a brain gun, luis gun , stain gun,
machine, carbine, toms machine carbine, GMG, short
machine gun or automated arms of similar nature, and
this term also includes a machine, equipment for
manufacturing a machine gun, and spare parts thereof.
(c) "ammunition" means gun powder, cape, bullet , shell ,
detonator, cartoos, fuse or other substance of similar
nature to be placed in arms.', 0, 'The National Penal (Code) Act, 2017, Chapter-6, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10.0', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding ten years and a fine not
exceeding one hundred thousand rupees, according to the gravity of
the risks of arms or ammunition in question.', 1, 'The National Penal (Code) Act, 2017, Chapter-6, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10', 2, 'rule', '130', 'Prohibition of transaction of arms without obtaining license', 'Prohibition of transaction of arms without obtaining license', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-6 (Prohibition of transaction of arms without obtaining license)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10.1', 3, 'clause', '(1)', '', NULL, 'No person shall transact arms and ammunition without obtaining a
license or in a manner to be contrary to the terms and restrictions
specified in the license, even if, obtained.
Explanation: For the purposes of this Chapter, "transaction"
means procurement, sale, transport, obtaining ownership, transfer,
accumulating, stockpiling or collection, storage, export or import.', 0, 'The National Penal (Code) Act, 2017, Chapter-6, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10.1', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding seven years and a fine not
exceeding seventy thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-6, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10', 2, 'rule', '131', 'Prohibition of acquisition of specific type of arms', 'Prohibition of acquisition of specific type of arms', NULL, 2, 'The National Penal (Code) Act, 2017, Chapter-6 (Prohibition of acquisition of specific type of arms)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10.2', 3, 'clause', '(1)', '', NULL, 'No person
shall acquire the following arms, by way of procurement, sale,
donation, gift , reward, partition, succession or otherwise, retain,
stockpile or store such arms, or use, transport, export or import such
arms except with the order of the competent authority:
(a) A tank and ammunition thereof,
(b) A cannon or mortar and ammunition thereof,
(c) A machine gun and ammunition thereof,
(d) Any kind of rifle and ammunition thereof,
(e) Such other arms and ammunition thereof as specified by
the competent authority that such arms and ammunition
are prohibited from being acquired or held by the
public.', 0, 'The National Penal (Code) Act, 2017, Chapter-6, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.2.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10.2', 3, 'clause', '(2)', '', NULL, 'A person who acquires any arms set forth in sub-section', 1, 'The National Penal (Code) Act, 2017, Chapter-6, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.2.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10.2', 3, 'clause', '(1)', '', NULL, 'shall, within thirty-five days from the date of acquisition thereof,
surrender such arms to the concerned District Administration Office.', 2, 'The National Penal (Code) Act, 2017, Chapter-6, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.2.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10.2', 3, 'clause', '(3)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term n ot exceeding seven years and a fine not
exceeding seventy thousand rupees.', 3, 'The National Penal (Code) Act, 2017, Chapter-6, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.2.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10.2', 3, 'clause', '(4)', '', NULL, 'Notwithstanding anything contained elsewhere in this
Section, nothing shall be deemed to bar any officer and personnel of
the Nepal Army, Nepal Police, Armed Police Force, Nepal
concerned with security work or other security personnel who are
entitled to use arms lawfully from holding or using such arms in the
course of discharging their respective duties.', 4, 'The National Penal (Code) Act, 2017, Chapter-6, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10', 2, 'rule', '132', 'Prohibition of retaining or carrying arms without license', 'Prohibition of retaining or carrying arms without license', NULL, 3, 'The National Penal (Code) Act, 2017, Chapter-6 (Prohibition of retaining or carrying arms without license)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10.3', 3, 'clause', '(1)', '', NULL, 'No
person shall acquire, retain, stockpile, use or carry such arms as may
be allowed by law to be acquired, held, stockpiled, used or car ried,
without obtaining a license or in a manner to be contrary to the terms
and restrictions specified in the license, even if, obtained.
Provided that nothing shall bar any officer and personnel of
the Nepal Army, Nepal Police, Armed Police Force, Nepal
concerned with security work or other security personnel who are
entitled to use arms lawfully from holding, using or carry ing such
arms in the course of discharging their respective duties.', 0, 'The National Penal (Code) Act, 2017, Chapter-6, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.3.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10.3', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding five years and a fi ne not
exceeding fifty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-6, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10', 2, 'rule', '133', 'Obligation to maintain records of transaction of arms,', 'Obligation to maintain records of transaction of arms,', 'ammunition: (1) A person who carries out transaction of arms or
ammunition by obtaining a license shall maintain separate records of
the arms and ammunition transacted by him or her.', 4, 'The National Penal (Code) Act, 2017, Chapter-6 (Obligation to maintain records of transaction of arms,)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10.4', 3, 'clause', '(2)', '', NULL, 'The records maintained pursuant to sub-section (1) shall
set out, inter alia, the following matters:
(a) Type, description and quantity of the arms
procured or sold, transported, stockpiled,
exported or imported by him or her,
(b) In the case of a sale of arms to any one, the
purchaser’s name, surname, address, citizenship
or passport number, date and place of issue of
citizenship certificate or passport,', 0, 'The National Penal (Code) Act, 2017, Chapter-6, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.4.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10.4', 3, 'clause', '(3)', '', NULL, 'A person who carries out the transaction of arms or
ammunition sh all, when so asked, show the records referred to in
sub-section (2) to the authority controlling or administering arms and
ammunition, the investigating authority or a court.', 1, 'The National Penal (Code) Act, 2017, Chapter-6, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.4.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10.4', 3, 'clause', '(4)', '', NULL, 'Where any person other than one who carries out the
commercial transaction of arms or ammunition by obtaining a license
intends to carry out the transaction of arms and ammunition, he or
she shall obtain approval of the concerned District Administration
Office to that effect.', 2, 'The National Penal (Code) Act, 2017, Chapter-6, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.4.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10.4', 3, 'clause', '(5)', '', NULL, 'A person who does, or causes to be done, any act
contrary to sub-section (1), (3) or (4) shall be liable to a sentence of
imprisonment for a term not exceeding two years and a fine not
exceeding twenty thousand rupees.', 3, 'The National Penal (Code) Act, 2017, Chapter-6, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10', 2, 'rule', '134', 'Prohibition of production or transaction of nuclear, chemical,', 'Prohibition of production or transaction of nuclear, chemical,', 'biological (bacteriological) or toxin weapons: (1) No person shall
manufacture, produce, procure, sell, acquire, own, transfer, stockpile,
store, transport, export or import, invest in or manage any type of
nuclear, chemical, biological (bacteriological) or toxic weapons o r
cause any one to do so.
Explanation: For the purposes of this Section,-
(a) "chemical weapon" means any chemical weapon as
defined by the Convention on the Prohibition of the
Development, Production, Stockpiling and Use of
Chemical Weapons and their Destruct ion, done at Paris
on 13 January 1993.
(b) "biological or toxin weapon" means any biological
(bacteriological) or toxin weapon as defined by the
Convention on the Prohibition of the Development,
Production and Stockpiling of Bacteriological
(Biological) and Toxin Weapons and their Destruction,
done at London, Moscow and Washington on 10 April,
1972.', 5, 'The National Penal (Code) Act, 2017, Chapter-6 (Prohibition of production or transaction of nuclear, chemical,)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.5.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10.5', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding twenty years and a fine not exceeding two hundred
thousand rupees.', 0, 'The National Penal (Code) Act, 2017, Chapter-6, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10', 2, 'rule', '135', 'Forfeiture of movable, immovable property related to offence', 'Forfeiture of movable, immovable property related to offence', 'In
the event of the commission of any offence under this Chapter, the
arms and ammunition related to such offence, and machinery,
equipment, instrument or vehicle producing, manufacturing,
retaining or transporting such arms and proceeds of the sale and
purchase of such arms or ammunition and amount accrued or
accumulated therefrom shall be forfeited.
Provided that where the owne r of the m eans of transport or
motor vehicle proves that he or she did not know the transportation
of such arms and ammunition, such means of transport or vehicle
shall not be forfeited.', 6, 'The National Penal (Code) Act, 2017, Chapter-6 (Forfeiture of movable, immovable property related to offence)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10', 2, 'rule', '136', 'Compensation caused to be paid', 'Compensation caused to be paid', 'Where any harm or loss is
caused to any o ne''s body or property from the commission by any
person of any offence under this Chapter, a reasonable compensation
for such harm or loss shall be caused to be paid by the offender to the
victim.', 7, 'The National Penal (Code) Act, 2017, Chapter-6 (Compensation caused to be paid)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:10.8', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:10', 2, 'rule', '137', 'Statute of limitation', 'Statute of limitation', 'No complaint shall lie, in rela tion to an
offence under Section 132, after the expiry of three months of the
commission of such offence, and in relation to any of the other
offences under this Chapter, after the expiry of six months from the
date of knowledge of the commission of such offence.', 8, 'The National Penal (Code) Act, 2017, Chapter-6 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-7', '', NULL, 'Offences Relating to Explosives', 11, 'The National Penal (Code) Act, 2017, Chapter-7', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11', 2, 'rule', '138', 'Prohibition of production of explosives', 'Prohibition of production of explosives', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-7 (Prohibition of production of explosives)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11.0', 3, 'clause', '(1)', '', NULL, 'No person shall make,
prepare or produce any kind of explosives without obtaining a
license or in a manner to be contrary to the terms and restrictions
specified in the license, even if, obtained.
Explanation: For the purposes of this Act:,-
(a) "explosives” means I.E.D., T.N.C. Amatol, Barotol,
Pentolite, rapid detonative explosive (RDX), tore fex,
blastic explosives, dynamite, gun powder, nitroglyceri n,
gelignite, stemite, selsite, detonator, blastic cap,
electronic blastic cap, fuse, fireworks, cracker, gun
cotton, gun powder, ballistic powder, mercury or
fullunet made of any other metal, any other explosive
substance of similar nature, which is capa ble of
exploding and causing loss, or any substance so
specified by the Government of Nepal by a notification
in the Nepal Gazette, and this term also includes a
bomb.
(b) "bomb" means a grenade so made of any explosive or
any means, formula, process or me asure as to self -
detonate or detonate with the help of other substance, or
other object containing explosive or substance of similar
nature.', 0, 'The National Penal (Code) Act, 2017, Chapter-7, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11.0', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to the following
sentence:
(a) Imprisonment for a term not exceeding ten years
and a fine not exceeding one hundred thousand
rupees, in the case of high explosives,
(b) Imprisonment for a term not exceeding five years
and a fine not exceeding fifty thousand r upees, in
the case of low explosives,
(c) Imprisonment for a term not exceeding three
years and a fine not exceeding thirty thousand
rupees, in the case of ordinary explosives,
(d) Imprisonment for a term not exceeding two years
and a fine not exceeding tw enty thousand rupees,
in the case of a person who produces, uses,
retains or otherwise transacts any equipment,
machinery or instrument for producing or
manufacturing explosives.
Explanation: For the purposes of this Chapter,-', 1, 'The National Penal (Code) Act, 2017, Chapter-7, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11.0', 3, 'clause', '(1)', '', NULL, '"high explosives" means dynam ite, nitroglycerin,
TNC, gelignite mornqtarlab, mercury fullunet,
R.D.X. amatol, barotol, pentolite, stemite,
selsightal, blastic explosive bomb and other
explosive of similar nature.', 2, 'The National Penal (Code) Act, 2017, Chapter-7, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.0.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11.0', 3, 'clause', '(2)', '', NULL, '"low explosives" means blastic powder,
gunpowder, gun cotton, mercury or fullunet made
of any other metal and other explosive of similar
nature.', 3, 'The National Penal (Code) Act, 2017, Chapter-7, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.0.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11.0', 3, 'clause', '(3)', '', NULL, '"ordinary explosives" means detonator, blastic
cap, electronics blastic cap, fuse, firework,
cracker and other explosives of similar nature.', 4, 'The National Penal (Code) Act, 2017, Chapter-7, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11', 2, 'rule', '139', 'Prohibition of transaction of explosives', 'Prohibition of transaction of explosives', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-7 (Prohibition of transaction of explosives)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11.1', 3, 'clause', '(1)', '', NULL, 'No person shall
transact explosives without obtaining a license or in a manner to be
contrary to the terms and restrictions specified in the license, even if,
obtained.
Explanation: For the purposes of this Chapter, the term
"transaction" means procurement, sale, retention, use, stockpiling,
storage, transport, alteration, mixing, export or import.', 0, 'The National Penal (Code) Act, 2017, Chapter-7, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11.1', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to the following sentence:
(a) Imprisonment for a term n ot exceeding ten years and a
fine not exceeding one hundred thousand rupees, in the
case of high explosives,
(b) Imprisonment for a term not exceeding five years and a
fine not exceeding fifty thousand rupees, in the case of
low explosives,
(c) Imprisonment for a term not exceeding three years and a
fine not exceeding thirty thousand rupees, in the case of
ordinary explosives.', 1, 'The National Penal (Code) Act, 2017, Chapter-7, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11', 2, 'rule', '140', 'Prohibition of making or using artificial explosives', 'Prohibition of making or using artificial explosives', NULL, 2, 'The National Penal (Code) Act, 2017, Chapter-7 (Prohibition of making or using artificial explosives)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11.2', 3, 'clause', '(1)', '', NULL, 'No
person shall alter or modify any ordinary consumable goods to be
used or consumed by the public or physical or chemical characters of
such goods, through any physical or chemical process, formula,
measure or method or change the form, structure or shape thereof,
and use or caused to be used, the same as a bomb of any type or any
other explosives.', 0, 'The National Penal (Code) Act, 2017, Chapter-7, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.2.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11.2', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding three years or a fine not exceeding thirty thousand
rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-7, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11', 2, 'rule', '141', 'Prohibition of making land mines or laying explosives', 'Prohibition of making land mines or laying explosives', NULL, 3, 'The National Penal (Code) Act, 2017, Chapter-7 (Prohibition of making land mines or laying explosives)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11.3', 3, 'clause', '(1)', '', NULL, 'No
person shall lay or place any explosive, any inflammable substance
or making an electronic ambush in a public road or way, place,
building, bridge, tunnel or any other place for the public movemen t
or cause obstruction to the movement or use of any other public
utilities by placing such substance or making an ambush.', 0, 'The National Penal (Code) Act, 2017, Chapter-7, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.3.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11.3', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding ten years and a fine not
exceeding one hundred thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-7, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.3.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11.3', 3, 'clause', '(3)', '', NULL, 'Where any injury or loss is caused to the body, life or
property of any one from the commission of the offence referred to
in sub-section (1), the sentence referred to in -sub-section (2) shall be
added to the sentence which is imposable by this Act on the offender
for such injury or loss.', 2, 'The National Penal (Code) Act, 2017, Chapter-7, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11', 2, 'rule', '142', 'Obligation to maintain records of production or transaction', 'Obligation to maintain records of production or transaction', NULL, 4, 'The National Penal (Code) Act, 2017, Chapter-7 (Obligation to maintain records of production or transaction)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11.4', 3, 'clause', '(1)', '', NULL, 'A person who has obtained a licence for the p roduction or
transaction of explosives shall, in producing, manufacturing,
preparing or transacting such explosives, maintain separate records
of every production or transaction of every explosive.', 0, 'The National Penal (Code) Act, 2017, Chapter-7, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.4.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11.4', 3, 'clause', '(2)', '', NULL, 'The records referred to in sub-section (1) shall set out,
inter alia, the following matters:
(a) Type, description and quantity of the explosives
produced, prepared or manufactured,
(b) In the case of the transaction of explosives, the
purpose for which such transaction has been made,
(c) In the case of the sale and distribution of explosives,
the purchaser’s name, the purpose, and quantity of,
such sale and distribution.', 1, 'The National Penal (Code) Act, 2017, Chapter-7, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.4.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11.4', 3, 'clause', '(3)', '', NULL, 'A person who carries out the transaction of explosives
shall, when so asked, show the records referred to in sub-section (1)
to the competent authority controlling or administering explosives,
the investigating or prosecuting authority or the court.', 2, 'The National Penal (Code) Act, 2017, Chapter-7, Clause (3)', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_national_penal_code_2074_2017:11.4.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11.4', 3, 'clause', '(4)', '', NULL, 'A person who does, or causes to be done, any act
contrary to this Section shall be liable to imprisonment for a term not
exceeding three months or a fine not exceeding five thousand rupees
or both the sentences.', 3, 'The National Penal (Code) Act, 2017, Chapter-7, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11', 2, 'rule', '143', 'Obligation to take care while importing, transporting or', 'Obligation to take care while importing, transporting or', 'stockpiling explosives: (1) A person who licensed to carry out the
transaction of explosives shall, in using, carr ying, transporting or
stockpiling such explosives, so use such explosives as to ensure
adequate safety according to the nature of such explosives or carry,
transport or stockpile such explosives, having kept them in
appropriate magazines.', 5, 'The National Penal (Code) Act, 2017, Chapter-7 (Obligation to take care while importing, transporting or)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.5.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11.5', 3, 'clause', '(2)', '', NULL, 'A person wh o does, or causes to be done, any act
contrary to sub-section (1) shall be liable to a fine not exceeding fifty
thousand rupees.', 0, 'The National Penal (Code) Act, 2017, Chapter-7, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11', 2, 'rule', '144', 'Forfeiture of movable or immovable property relat ed to offence', 'Forfeiture of movable or immovable property relat ed to offence', 'In the event of the commission of any offence referred to in this
Chapter, any explosives related to such offence, goods, equipment,
instrument or raw materials used for producing, preparing or
manufacturing such explosives, motor vehicle or means of transport
used in the transportation or carriage of such explos ives and
proceeds of the production, preparation, manufacturing or transaction
of such explosives and amount accrued or accumulated therefrom
shall be forfeited.
Provided that where the owner of the motor vehicle or means
of transport proves that he or s he did not know the transportation of
the explosives, such vehicle or means of transport shall not be
forfeited.', 6, 'The National Penal (Code) Act, 2017, Chapter-7 (Forfeiture of movable or immovable property relat ed to offence)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11', 2, 'rule', '145', 'Order for compensation to be paid', 'Order for compensation to be paid', 'Where any harm or loss is
caused to the life, or any property, of any one from the commission
by a pers on of any of the offences under this Chapter, reasonable
compensation for such harm or loss shall be ordered to be paid by the
offender to the victim.', 7, 'The National Penal (Code) Act, 2017, Chapter-7 (Order for compensation to be paid)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:11.8', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:11', 2, 'rule', '146', 'Statute of limitation', 'Statute of limitation', 'No complaint shall lie after the expiry of three
months from the date of com mission of any of the offences under
Section 143 and after the expiry of six months from the date of
knowledge of commission of any of the other offences under this
Chapter.', 8, 'The National Penal (Code) Act, 2017, Chapter-7 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-8', '', NULL, 'Offences against National and Public Heritages', 12, 'The National Penal (Code) Act, 2017, Chapter-8', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12', 2, 'rule', '147', 'Prohibition of owning public building, land by individual', 'Prohibition of owning public building, land by individual', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-8 (Prohibition of owning public building, land by individual)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12.0', 3, 'clause', '(1)', '', NULL, 'No
person shall, without prior approval of the Government of Nepal or
State Government or Local Level, obtain ownership of the following
building or land, whether making its registration or not, or otherwise
occupy, cultivate or encroach, or hinder or obstruct, in any way, the
possession or use of, such building or land:
(a) Any government building or land held in the name of
the Government of Nepal, State Government or Local
Level or a public body under the full o r majority
ownership or control of the Government of Nepal, State
Government or Local Level,
(b) Any community or public house or land which has been
under community or public possession and use from
time immemorial.', 0, 'The National Penal (Code) Act, 2017, Chapter-8, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12.0', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, an
offence referred to in sub-section (1) shall be liable to imprisonment
for a term not exceeding three years or a fine not exceeding thirty
thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-8, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12.0', 3, 'clause', '(3)', '', NULL, 'Where any building, land mentioned in sub -section (1)
has already been registered in, or transmitted to, the name of any
individual, such registration or transmission also shall, ipso facto, be
void.', 2, 'The National Penal (Code) Act, 2017, Chapter-8, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12', 2, 'rule', '148', 'Prohibition of owning public heritage by individual', 'Prohibition of owning public heritage by individual', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-8 (Prohibition of owning public heritage by individual)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12.1', 3, 'clause', '(1)', '', NULL, 'No
person shall obtain the ownership of any public heritage, whether
making its registration or not, or hinder or obstruct, in any way, the
public possession or use of, or otherwise occupy, cultivate or
encroach such heritage, or cause harm, loss or damage to such
heritage in any way.
Explanation: For the purposes of this Section, the term
“public heritage” means any of the following heritages:
(a) A right of way that has been in public use from
time immemorial,
(b) A road, pasture land, water body, graveyard,
crematory, water tap, spout, well, pond, edge of
pond, spring of drinking water, canal, water
channel, meadow for animal grazing or exit for
animals, that has been in the public use,
(c) A place where market is held,
(d) A divine place, shrine, temple, Stupa, monastery,
mosque or church,
(e) A public rest house, Pauwa, Sattal, Chautaro,
(f) A historical statue, monument, cultural
monument or memorial,
(g) A place for organizing religious or cultural
functions or ceremonies,
(h) A national forest designated by the Government
of Nepal or forest, or any part thereof, under
ownership of the Government of Nepal, State
Government or Local Level.', 0, 'The National Penal (Code) Act, 2017, Chapter-8, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12.1', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding five years or a fine not
exceeding fifty thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-8, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.1.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12.1', 3, 'clause', '(3)', '', NULL, 'Where any public heritage referred to in sub -section (1)
has already been registered in, or transmitted to, the name of any
individual, such registration or transmission also shall, ipso facto, be
void.', 2, 'The National Penal (Code) Act, 2017, Chapter-8, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12', 2, 'rule', '149', 'Prohibition of encroachment of natural heritages', 'Prohibition of encroachment of natural heritages', NULL, 2, 'The National Penal (Code) Act, 2017, Chapter-8 (Prohibition of encroachment of natural heritages)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12.2', 3, 'clause', '(1)', '', NULL, 'No person
shall, except in accordance with law, encroach or possess, in any
way, any natural heritage, or sell or distribute such heritage, or cause
any harm, loss or damage to its natural structur e or beauty, in any
way.
Explanation: For the purposes of this Section, the term
“natural heritage” means any of the following heritages:
(a) A national park, wildlife or hunting reserve designated
by the Government of Nepal for the protection of the
natural environment, vegetation and wildlife,
(b) A conservation area designated by the Government of
Nepal, river, rivulet, stream, lake, wetland or natural
water-fall, snow -peak or any part thereof, higher
mountain peak,
(c) A wildlife, vegetation or landscape protected by the law
in force or the Government of Nepal, State Government
or Local Level,
(d) A habitat of wildlife protected by the Government of
Nepal, State Government or Local Level, eco-system, or
any medicinal herb which is prohibited for sale,
distribution, export or import.', 0, 'The National Penal (Code) Act, 2017, Chapter-8, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.2.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12.2', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding ten years and a fine equal to
the claimed amount if such amount is spe cified and a fine not
exceeding one million rupees if such amount is not specified or both
the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-8, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12', 2, 'rule', '150', 'Prohibition of possession or destruction of public physical', 'Prohibition of possession or destruction of public physical', 'infrastructure in unauthorized manner : (1) No person shall,
except in accordance with law, possess, in an unauthorized manner,
any public physical infrastructure or prevent any one from using
such infrastructure, or, cause any harm or loss to such infrastructure,
in any way.
Explanation: For the purposes of this Section, the term
“public physical infrastructure” means the following infrastructure to
be publicly used:
(a) A road, way, bridge, tunnel, airport,
(b) A water reservoir, canal, spring of drinking water, and
pond, power house, electricity transmission center or
line thereof,
(c) A ropeway, cab le car, telecommunication equipment,
radio station, television broadcasting center and tower
thereof,
(d) A rail and railway;
(e) A public bus station, public park, or
(f) Similar other structure.', 3, 'The National Penal (Code) Act, 2017, Chapter-8 (Prohibition of possession or destruction of public physical)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12.3', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding ten years and a fine not
exceeding one hundred thousand rupees.', 0, 'The National Penal (Code) Act, 2017, Chapter-8, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12', 2, 'rule', '151', 'Prohibition of dishonoring or destroying national anthem, flag', 'Prohibition of dishonoring or destroying national anthem, flag', 'or coat-of-arms: (1) No person shall, with intention to spread hatred
against Nepal or the Government of Nepal, dishonor the national
anthem of Nepal, burn, or knowingly dishonor, the flag of Nepal, or
use such anthem, flag or coat-of-arms of Nepal at such place, on
such object or condition as it is not appropriate for its use in view of
public morality, decency or courtesy.', 4, 'The National Penal (Code) Act, 2017, Chapter-8 (Prohibition of dishonoring or destroying national anthem, flag)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12.4', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not excee ding three years or a fine not
exceeding thirty thousand rupees or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-8, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.4.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12.4', 3, 'clause', '(3)', '', NULL, 'No person shall, with intent to spread hatred against, or
dishonor a country with which Nepal has friendly relation, burn or
knowingly misuse such country''s national flag or misuse such flag or
the coat-of-arms of such country or use such flag or coat-of-arms at
such place, on such object or condition as it is not appropriate for its
use in view of public morality, decency or courtesy.', 1, 'The National Penal (Code) Act, 2017, Chapter-8, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.4.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12.4', 3, 'clause', '(4)', '', NULL, 'No person shall, with in tent to make hatred against or dishonor the
United Nations Organization or any organization associated with, or
specialized agency of, the United Nations Organization or any
international or regional organization of which Nepal is a member,
misuse in any w ay the flag or emblem of such Organization, or use
such flag or logo, motor vehicle or other object of such Organization
without approval of such Organization.', 2, 'The National Penal (Code) Act, 2017, Chapter-8, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.4.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12.4', 3, 'clause', '(5)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (3) or (4) shall be liable to a
sentence of imprisonment for a term not exceeding one year or a fine
not exceeding ten thousand rupees or both the sentences.', 3, 'The National Penal (Code) Act, 2017, Chapter-8, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12', 2, 'rule', '152', 'Not to insult national figures/heroes', 'Not to insult national figures/heroes', NULL, 5, 'The National Penal (Code) Act, 2017, Chapter-8 (Not to insult national figures/heroes)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.5.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12.5', 3, 'clause', '(1)', '', NULL, 'No person shall
knowingly make hatred against, dishonor or defame, any national
figure/hero specified by the Government of Nepal or demolish,
cause loss or damage to the statue, monument or memorial of such
figure/hero.
Provided that any comment made in good faith in the context
of a study, research or evaluation of the life of such figure/hero shall
not be considered to be an offence referred to in this Section.', 0, 'The National Penal (Code) Act, 2017, Chapter-8, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.5.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12.5', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding six months or a fine not
exceeding five thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-8, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12', 2, 'rule', '153', 'Order for compensation to be paid', 'Order for compensation to be paid', 'Where any harm or loss is
caused from the commission of an y offence referred to in Section
150, reasonable compensation for such harm or loss shall be ordered
to be paid by the offender.', 6, 'The National Penal (Code) Act, 2017, Chapter-8 (Order for compensation to be paid)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:12.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:12', 2, 'rule', '154', 'Statute of limitation', 'Statute of limitation', 'There shall be no statute of limitation for
filing a complaint in relation to any of the offences under Sections
147, 148 and 149, and no complaint shall l ie after the expiry of six
months from the date of commission of any of the offences under the
other Sections of this Chapter.', 7, 'The National Penal (Code) Act, 2017, Chapter-8 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-9', '', NULL, 'Offences Relating to Religion', 13, 'The National Penal (Code) Act, 2017, Chapter-9', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13', 2, 'rule', '155', 'Prohibition of injuring shrines or places held sacred', 'Prohibition of injuring shrines or places held sacred', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-9 (Prohibition of injuring shrines or places held sacred)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.0', 3, 'clause', '(1)', '', NULL, 'No
person shall damage or injure or, in any way, defile, destroy or
pollute any place of religious worship, pray or function or place,
object held sacred or burial place or place of sepulture or do similar
other act with intent to outrage or insult the religion or religious
feelings of any caste, race, community or class or with the
knowledge that such outrage or insult is likely to occur.', 0, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.0', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a senten ce of
imprisonment for a term not exceeding three years and a fine not
exceeding thirty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.0', 3, 'clause', '(3)', '', NULL, 'Where a foreigner has committed, or caused to be
committed, the offence referred to in sub-section (1), he or she shall
be deported from Nepal wit hin seven days after the date of
completion of the service of imprisonment under sub-section (2).', 2, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13', 2, 'rule', '156', 'Prohibition of outraging religious feelings', 'Prohibition of outraging religious feelings', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-9 (Prohibition of outraging religious feelings)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.1', 3, 'clause', '(1)', '', NULL, 'No person shall
outrage the religious feelings of any caste, race, community or class
by words, either spoken or written, by visible representation or signs
or otherwise.', 0, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.1', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding two years and a fine n ot
exceeding twenty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13', 2, 'rule', '157', 'Prohibition of causing obstruction to religious rites and rituals', 'Prohibition of causing obstruction to religious rites and rituals', NULL, 2, 'The National Penal (Code) Act, 2017, Chapter-9 (Prohibition of causing obstruction to religious rites and rituals)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.2', 3, 'clause', '(1)', '', NULL, 'No person shall knowingly cause obstruction to other''s religious
rites and rituals that are handed down or being followed from the
time immemorial.', 0, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.2.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.2', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding one year or a fine not
exceeding ten thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13', 2, 'rule', '158', 'Prohibition of proselytizing', 'Prohibition of proselytizing', NULL, 3, 'The National Penal (Code) Act, 2017, Chapter-9 (Prohibition of proselytizing)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.3', 3, 'clause', '(1)', '', NULL, 'No person shall convert any one
from one religion to another or make attempt to or abet such conversion.', 0, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.3.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.3', 3, 'clause', '(2)', '', NULL, 'No person shall do any act or conduct which
undermines the religion, opinion or faith of any caste, race,
community or convert any one into another religion, whether by
inducement or not, in a manner to so undermine or propagate such
religion or opinion with the intention of making such conversion.', 1, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.3.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.3', 3, 'clause', '(3)', '', NULL, 'A person who commits, or cause s to be committed, the
offence referred to in sub-section (1) or (2) shall be liable to a
sentence of imprisonment for a term not exceeding five years and a
fine not exceeding fifty thousand rupees.', 2, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.3.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.3', 3, 'clause', '(4)', '', NULL, 'If a foreigner commits, or causes to be committed, the
offence referred to in sub-section (1) or (2), he or she shall be
deported from Nepal within seven days after the date of completion
of the service of imprisonment imposed under this Section.', 3, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13', 2, 'rule', '159', 'Statute of limitation', 'Statute of limitation', 'No complaint shall lie after the expiry of six
months from the date of knowledge of commission of the offence
under Section 158 and from the date of commission of any of the
other offences under this Chapter.
Chpater-10
Offences Relating to Discrimination and Other Degrading Treatment', 4, 'The National Penal (Code) Act, 2017, Chapter-9 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13', 2, 'rule', '160', 'Prohibition of making discriminator y treatment', 'Prohibition of making discriminator y treatment', NULL, 5, 'The National Penal (Code) Act, 2017, Chapter-9 (Prohibition of making discriminator y treatment)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.5.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.5', 3, 'clause', '(1)', '', NULL, 'Except as
otherwise provided by laws, no authority who exercises power under
law shall, in the exercise of such power or a general law,
intentionally make a discriminatory treatment against any citizen on
grounds of origin, religion, color, caste, race, sex, physical condition,
disability, condition of health, marital status, pregnancy, economic
condition, language or region, ideology or on similar other grounds.', 0, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.5.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.5', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three years or a fine not
exceeding thirty thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13', 2, 'rule', '161', 'Prohibition of purchasing, selling or distributing goods or', 'Prohibition of purchasing, selling or distributing goods or', 'service with discrimination: (1) No person, in purchasing, selling or
distributing any goods or services, shall purchase, sell or distribute
such goods or services from or to only any person belonging to any
particular caste, race or community or omit to provide , sell or
distribute such goods or services to any person belonging to any
particular caste, race or community.
Provided that where a person, with the approval of the
competent authority under law, provides, sells or distributes any
particular goods or services to only any person belonging to any
particular caste, race or community, for the protection of interest and
development of a class which is economically, socially or
educationally backward, such person shall not be considered to have
committed the offence under this Section.', 6, 'The National Penal (Code) Act, 2017, Chapter-9 (Prohibition of purchasing, selling or distributing goods or)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.6.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.6', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding one year or a fine not
exceeding ten thousand rupees or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13', 2, 'rule', '162', 'Prohibition of forced labour', 'Prohibition of forced labour', NULL, 7, 'The National Penal (Code) Act, 2017, Chapter-9 (Prohibition of forced labour)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.7.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.7', 3, 'clause', '(1)', '', NULL, 'No person shall force any one to
work against his or her will.
Provided that this Section shall not be deemed to bar the
engaging of any one in labor for a public work in accordance with
law.', 0, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.7.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.7', 3, 'clause', '(2)', '', NULL, 'A person who commit s, or causes to be committed, the
offence under sub -section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three months or a fine not
exceeding five thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.8', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13', 2, 'rule', '163', 'Prohibition of slavery', 'Prohibition of slavery', NULL, 8, 'The National Penal (Code) Act, 2017, Chapter-9 (Prohibition of slavery)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.8.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.8', 3, 'clause', '(1)', '', NULL, 'No pers on shall subject any one to
slavery or servitude or hold or employ him or her in such status or
subject, or cause to be subjected, him or her to any other kind of
treatment similar thereto.', 0, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.8.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.8', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term of five to ten years and a fine of fifty
thousand to one hundred thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.9', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13', 2, 'rule', '164', 'Prohibition of serfdom or debt bonded labour', 'Prohibition of serfdom or debt bonded labour', NULL, 9, 'The National Penal (Code) Act, 2017, Chapter-9 (Prohibition of serfdom or debt bonded labour)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.9.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.9', 3, 'clause', '(1)', '', NULL, 'No person shall
subject any one to, or hold any one in, serfdom or debt bonded
labour for any kind of consideration or employ any one in the status
of serfdom or bonded labour, or subject, or cause to be subjected,
him or her to any other kind of treatment similar thereto.', 0, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.9.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.9', 3, 'clause', '(2)', '', NULL, 'A person w ho commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term from three to seven years and a fine from
thirty thousand to one hundred thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.10', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13', 2, 'rule', '165', 'Prohibition of undermining social rites and rituals', 'Prohibition of undermining social rites and rituals', NULL, 10, 'The National Penal (Code) Act, 2017, Chapter-9 (Prohibition of undermining social rites and rituals)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.10.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.10', 3, 'clause', '(1)', '', NULL, 'No person
shall, by way of misrepresentation or use of force, do, or cause to be
done, any act which undermines or results in the undermining of the
social rites and rituals of any one.
Explanation: For the purposes of this Section, any r ites and
rituals constituting racial discrimination shall not be considered to be
social rites and rituals.', 0, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.10.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.10', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding one year or a fine not exceeding ten thousand rupees
or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.11', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13', 2, 'rule', '166', 'Prohibition of untouchability or discriminatory treatment on', 'Prohibition of untouchability or discriminatory treatment on', 'ground of caste: (1) No person shall subject any one to
untouchability or any other kind of discriminati on, or prevent any
one from appearing in any public place or entering into any religious
place of public nature, or deprive any one of using water or water
pond in public use or of the use of things of any other private or
public utility or convenience, on the grounds of custom, tradition,
religion, culture, rites or rituals, caste, race, community, profession,
occupation, physical condition or origin of social community.', 11, 'The National Penal (Code) Act, 2017, Chapter-9 (Prohibition of untouchability or discriminatory treatment on)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.11.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.11', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three years or a fine not
exceeding thirty thousand rupees or both the sentences, and if a
public servant commits the offence referred to in this Section, he or
she shall be l iable to an additional sentence of imprisonment for a
term not exceeding three months.', 0, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.12', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13', 2, 'rule', '167', 'Prohibition of torture', 'Prohibition of torture', NULL, 12, 'The National Penal (Code) Act, 2017, Chapter-9 (Prohibition of torture)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.12.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.12', 3, 'clause', '(1)', '', NULL, 'No authority who is competent under the
law in force to investigate or prosecute any offence, implement law,
take any one into control, or hold any one in custody or detention in
accordance with law shall subject, or cause to be subjected, any one
to physical or mental torture or to cruel, brutal, inhuman or
degrading treatment.
Explanation: For the purposes of this Section, intentional
inflicting of physical or mental pain or suffering on any person who
is arrested, taken into cont rol, held in custody, detention or
imprisonment or under preventive detention or security or any other
person interested in such person or subjecting such person to cruel,
brutal, inhuman or degrading treatment or punishment for the
following purpose shall be considered to constitute torture or cruel,
brutal, inhuman or degrading treatment or punishment against or to
such person:
(a) To get information on any matter,
(b) To extort confession of any offence,
(c) To punish for any act,
(d) To show fear, intimidation or coercion, or
(e) To do any other act contrary to law.', 0, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.12.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.12', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentenc e of imprisonment for a term
not exceeding five years or a fine not exceedi ng fifty thousand
rupees or both the sentences, according to the gravity of the offence.', 1, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.12.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.12', 3, 'clause', '(3)', '', NULL, 'A person who orders the commission of the offence
referred to in sub-section (1) or an a ccomplice who aids in the
commission of the offence referred to in this Section shall be liable
to the same sentence as is imposable on the principal offender.', 2, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.12.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.12', 3, 'clause', '(4)', '', NULL, 'No person who com mits the offence referred to in sub-
section (1) shall be allowed to plea th at he or she has committed the
offence in pursuance of an order by the authority superior to him or
her; and, on such ground, he or she shall not be exempted from the
sentence imposable on him or her for the commission of such
offence.', 3, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.13', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13', 2, 'rule', '168', 'Prohibition of degrading or inhuman treatment', 'Prohibition of degrading or inhuman treatment', NULL, 13, 'The National Penal (Code) Act, 2017, Chapter-9 (Prohibition of degrading or inhuman treatment)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.13.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.13', 3, 'clause', '(1)', '', NULL, 'No person
shall subject, or cause to be subjected, any one to degrading or
inhuman treatment.
Explanation: For the purposes of this Section, the following
act shall be deemed to constitute a degrading or inhumane treatment:
(a) To accuse one of being a witch,
(b) To expel one from his or her place of residence in
accusation of being a witch,
(c) To ex-communicate one from the society, or
(d) To make cruel, inhuman or degrading treatment by
doing any other act whatsoever.', 0, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.13.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.13', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding five years and a fine not exceeding fifty thousand
rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.13.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.13', 3, 'clause', '(3)', '', NULL, 'Banishing a woman to a shed ( Chhaupadi) during
menstruation or deliver y, or subjecting, causing to be subjected, her
to similar other discrimination, untouchability or inhuman treatment
of any kind is prohibited.', 2, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.13.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.13', 3, 'clause', '(4)', '', NULL, 'A person who commits the offence referred to in sub-
section (3) shall be liable to a sentence of imprison ment for a term
not exceeding three months or a fine not exceeding three thousand
rupees or both the sentences.', 3, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.13.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.13', 3, 'clause', '(5)', '', NULL, 'Where a public servant commits the offence referred to
in this Section, he or she shall be liable to an additional sentence of
imprisonment for a term not exceeding three months.', 4, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.14', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13', 2, 'rule', '169', 'Order for compensation to be paid', 'Order for compensation to be paid', 'A reasonable compensation
for the injury or pain caused to the victim shall be ordered to be paid
by the person who has committed the offence referred to in this
Chapter.', 14, 'The National Penal (Code) Act, 2017, Chapter-9 (Order for compensation to be paid)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.15', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13', 2, 'rule', '170', 'Statute of limitation', 'Statute of limitation', NULL, 15, 'The National Penal (Code) Act, 2017, Chapter-9 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.15.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.15', 3, 'clause', '(1)', '', NULL, 'There shall be no statute of limitation for
making a complaint in relation to any of the offences referred to in
Sections 163 and 164.', 0, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:13.15.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:13.15', 3, 'clause', '(2)', '', NULL, 'No complaint shall lie after the expiry of six months
from the date of commission of the offence referred to in Section 167
or from the date of release of the concerned person from arrest,
control, custody, detention, imprisonment or preventive detention
and from the date of knowledge of commission of any of the other
offences referred to in this Chapter.', 1, 'The National Penal (Code) Act, 2017, Chapter-9, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-11', '', NULL, 'Offences Relating to Marriage', 14, 'The National Penal (Code) Act, 2017, Chapter-11', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14', 2, 'rule', '171', 'Prohibition of concluding marriage without consent', 'Prohibition of concluding marriage without consent', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-11 (Prohibition of concluding marriage without consent)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.0', 3, 'clause', '(1)', '', NULL, 'No
marriage shall be concluded, or caused to be concluded, without the
consent of the persons getting married.', 0, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.0', 3, 'clause', '(2)', '', NULL, 'A marriage concluded without the consent referred to in
sub-section (1) shall be void.', 1, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.0', 3, 'clause', '(3)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding two years and a fine not exceeding twenty thousand
rupees.
Explanation: For the purposes of this Section, a consent given
by a person who has not attained the marriageable age under Section
173 shall not be deemed to be consent.', 2, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14', 2, 'rule', '172', 'Prohibition of concluding marriage in prohibited degree of', 'Prohibition of concluding marriage in prohibited degree of', 'relationship: (1) E xcept as otherwise customarily practiced, no
person shall conclude, or cause to be concluded, marriage with one
who is within the prohibited degree of relationship by consanguinity
or affinity.', 1, 'The National Penal (Code) Act, 2017, Chapter-11 (Prohibition of concluding marriage in prohibited degree of)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.1', 3, 'clause', '(2)', '', NULL, 'Where a marriage referred to in sub-section (1) has been
concluded in ignorance, such marriage shall be void.', 0, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.1', 3, 'clause', '(3)', '', NULL, 'Where a marriage referred to in sub-section (1) has been
concluded knowingly, the person concluding such marriage shall be
liable to the sentence imposable for the offence of incest and a
person causing the conclusion of such marriage shall be liable to a
sentence of imprisonment for a term not exceeding three months or a
fine not exceeding three thousand rupees or both the sentences, and
such marriage shall, ipso facto, be void.', 1, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14', 2, 'rule', '173', 'Prohibition of concluding child marriage', 'Prohibition of concluding child marriage', NULL, 2, 'The National Penal (Code) Act, 2017, Chapter-11 (Prohibition of concluding child marriage)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.2', 3, 'clause', '(1)', '', NULL, 'No marriage shall be
concluded or cause to be concluded unless parties to the marriage
have attained twenty years of age.', 0, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.2.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.2', 3, 'clause', '(2)', '', NULL, 'A marriage concluded in contravention of sub -section', 1, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.2.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.2', 3, 'clause', '(1)', '', NULL, 'shall, ipso facto, be void.', 2, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.2.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.2', 3, 'clause', '(3)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding three years and a fine not exceeding thirty thousand
rupees.', 3, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14', 2, 'rule', '174', 'Prohibition of transacting property in marriage', 'Prohibition of transacting property in marriage', NULL, 3, 'The National Penal (Code) Act, 2017, Chapter-11 (Prohibition of transacting property in marriage)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.3', 3, 'clause', '(1)', '', NULL, 'No marriage
shall be concluded, or caused to be concluded, upon having asked
for, or on the condition of receiving or giving of, any type of
movable or immovable property, dowry or any property from the
bridegroom or the bride side, except such ordinary gift, donatio n,
money or one set of jewelry worn on the body as has been practiced
in his or her custom.', 0, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.3.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.3', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding three years or a fine no t exceeding thirty thousand
rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.3.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.3', 3, 'clause', '(3)', '', NULL, 'No person shall, after the conclusion of marriage, ask
the bride or her relative for any movable, immovable property or
dowry referred to in sub -section (1), or make, in any way, any
annoyance, harassment or inhuman or degrading treatment to the
bride or her relative for the reason that such movable, immovable
property or dowry has not been given.', 2, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.3.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.3', 3, 'clause', '(4)', '', NULL, 'A person who commits the offence referred to in sub-
section (3) shall be liable to a sentence of imprisonment for a term
not exceeding five years or a fine not exceeding fifty thousand
rupees or both the sentences.', 3, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.3.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.3', 3, 'clause', '(5)', '', NULL, 'Where any property has been taken as mentioned in
sub-section (1) or (3), such property shall be returned to the
concerned person.', 4, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14', 2, 'rule', '175', 'Prohibition of bigamy', 'Prohibition of bigamy', NULL, 4, 'The National Penal (Code) Act, 2017, Chapter-11 (Prohibition of bigamy)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.4', 3, 'clause', '(1)', '', NULL, 'No married man shall, during the
continuation of the marital relationship, conclude another marriage.', 0, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.4.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.4', 3, 'clause', '(2)', '', NULL, 'No woman shall conclude marriage with a man
knowingly that he is already married.', 1, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.4.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.4', 3, 'clause', '(3)', '', NULL, 'Notwithstanding anything conta ined in sub -section (1)
or (2), a man or woman may marry again if the husband and wife
have got separated upon making partition in accordance with law.', 2, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.4.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.4', 3, 'clause', '(4)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) or (2) shall be liable to a
sentence of imprisonment for a term of one year to five years and a
fine of ten thousand to fifty thousand rupees.', 3, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.4.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.4', 3, 'clause', '(5)', '', NULL, 'The marriage referred to in sub -section (1) shall, ipso
facto, be void.', 4, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.4.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14.4', 3, 'clause', '(6)', '', NULL, 'Notwithstanding anything contained else where in this
Section, nothing contained in this Section shall be deemed to have
effect on any marriage concluded in accordance with the law in force
for the time being prior to the commencement of this Act.', 5, 'The National Penal (Code) Act, 2017, Chapter-11, Clause (6)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:14.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:14', 2, 'rule', '176', 'Statute of limitation', 'Statute of limitation', 'No complaint on any offence under this
Chapter shall lie after the expiry of three months from the date of
knowledge of the commission of the offence.', 5, 'The National Penal (Code) Act, 2017, Chapter-11 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-12', '', NULL, 'Offences Relating to Human Body', 15, 'The National Penal (Code) Act, 2017, Chapter-12', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15', 2, 'rule', '177', 'Prohibition of doing act with the intention of causing death', 'Prohibition of doing act with the intention of causing death', '(homicide): (1) No person shall intentionally kill, or do, or cause to
be done, any act causing the death of, another person.
Explanation: For the purposes of this S ection, even if a
person intentionally causes such serious bodily injury or hurt to
another person as is likely to cause the death of that other person but
that person does not die immediately but die subsequently in
consequence of that injury or hurt, the person shall be considered to
have killed that other person.', 0, 'The National Penal (Code) Act, 2017, Chapter-12 (Prohibition of doing act with the intention of causing death)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.0', 3, 'clause', '(2)', '', NULL, 'A person who commit s, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to the sentence of
imprisonment for life.', 0, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15', 2, 'rule', '178', 'Prohibition of doing act likely to cause death', 'Prohibition of doing act likely to cause death', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-12 (Prohibition of doing act likely to cause death)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.1', 3, 'clause', '(1)', '', NULL, 'No person shall
do any act, with the knowledge that, or having reaso n to believe that,
such act is, in an ordinary course, likely to cause the death of another
person.', 0, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.1', 3, 'clause', '(2)', '', NULL, 'If a person dies in consequence of any act referred to in
sub-section (1), t he offender shall be liable to the sentence of
imprisonment for life.', 1, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15', 2, 'rule', '179', 'Prohibition of causing death by grave provocation or in heat of', 'Prohibition of causing death by grave provocation or in heat of', 'passion: (1) Notwithstanding anything contained in Section 177 or
178, a person who causes the death of another person in any of the
following circumstances shall be liable to a sentence of
imprisonment for a term of ten to fifteen years and a fine of one
hundred thousand to one hundred fifty thousand rupees:
(a) Where the offender, while being deprived of the power
of self-control by grave and sudden provocation, causes
the death of the person who gave such provocation,
Provided that this clause shall not apply to the
following circumstance:', 2, 'The National Penal (Code) Act, 2017, Chapter-12 (Prohibition of causing death by grave provocation or in heat of)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.2', 3, 'clause', '(1)', '', NULL, 'Where the offender is provoked by
anything done in obedience to the law or in
the exercise of the right of private defense
or anything done or intended to be done by
a public servant in the exercise of his or her
official duties,', 0, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.2.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.2', 3, 'clause', '(2)', '', NULL, 'Where the offender himself or herself gives
provocation to another with intent to do
harm to any one and anything done by that
other person upon being so provoked
causes the death of any person.
(b) Where the offender in the exercise in good faith of the
right of private defence exceeds the limit of such power
and causes the death of the person against whom he or
she is exercising such right of private defence,
(c) Where dea th is caused instantly in the heat of passion
upon a sudden quarrel,
Provided that while doing any act referred to in
this clause, the offender must not have taken an undue
advantage or acted in a cruel or unusual manner.', 1, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (2)', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_national_penal_code_2074_2017:15.2.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.2', 3, 'clause', '(2)', '', NULL, 'Notwithstanding anything cont ained in clauses
(b) and (c) of sub -section (1), the provisions contained in these
clauses shall not be applicable to any case of murder committed with
premeditation or deliberate afterthought.', 2, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15', 2, 'rule', '180', 'Punishment for homicide by causing death of person other than', 'Punishment for homicide by causing death of person other than', 'person whose death was intended: Notwithstanding anything
contained in Sections 177, 178 and 179, where a person, by doing
anything which he or she intends to cause or knows to be likely to
cause or has reason to believe to be likely to cause death of any one
other than the one whose death was so intended, he or she shall be
liable to the sentence set forth in Sections 177, 178 and179, as the
case may be.', 3, 'The National Penal (Code) Act, 2017, Chapter-12 (Punishment for homicide by causing death of person other than)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15', 2, 'rule', '181', 'Prohibition of causing death by recklessness', 'Prohibition of causing death by recklessness', NULL, 4, 'The National Penal (Code) Act, 2017, Chapter-12 (Prohibition of causing death by recklessness)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.4', 3, 'clause', '(1)', '', NULL, 'No person shall
cause the death of any one by doing a reckless act.', 0, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.4.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.4', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall, except in the cases referred to in Sections 177, 178
and 179, be liable to a sentence of imprisonment for a term of three
to ten years and a fine of thirty thousand to one hundred thousand
rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15', 2, 'rule', '182', 'Prohibition of causing death by negligence', 'Prohibition of causing death by negligence', NULL, 5, 'The National Penal (Code) Act, 2017, Chapter-12 (Prohibition of causing death by negligence)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.5.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.5', 3, 'clause', '(1)', '', NULL, 'Except in the case
referred to in Section 179, no person shall cause the death of any one
by doing a negligent act.', 0, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.5.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.5', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding three years and a fine not exceeding thirty thousand
rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.5.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.5', 3, 'clause', '(3)', '', NULL, 'Except in the case referred to in sub -section (1), if any
act done by a person under such circumst ances that such act is less
likely to cause death causes the death of any one accidently, that
person shall be liable to a sentence of imprisonment for a term of six
months to two years or a fine not exceeding twenty thousand rupees
or both the sentences.', 2, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15', 2, 'rule', '183', 'Prohibition of commi tting attempt to murder', 'Prohibition of commi tting attempt to murder', NULL, 6, 'The National Penal (Code) Act, 2017, Chapter-12 (Prohibition of commi tting attempt to murder)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.6.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.6', 3, 'clause', '(1)', '', NULL, 'No person
shall, with the intention of committing murder of anyone, commit an
attempt to murder.', 0, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.6.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.6', 3, 'clause', '(2)', '', NULL, 'A person who commits , or causes to be committed, the
offence referred to in sub -section (1) shall be liable to a sentence of
imprisonment for a term not exceeding ten years and a fine not
exceeding one hundred thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15', 2, 'rule', '184', 'Prohibition of throwing or abandoning person under one''s own', 'Prohibition of throwing or abandoning person under one''s own', 'guardianship: (1) A person, being bound to care or maintain an
infant, child, disabled patient or elderly person, shall not so throw,
abandon or desert as to cause danger to the body or life of such
infant, child, patient or elderly person.', 7, 'The National Penal (Code) Act, 2017, Chapter-12 (Prohibition of throwing or abandoning person under one''s own)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.7.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.7', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three years and a fine not
exceeding thirty thousand rupees.', 0, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.7.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.7', 3, 'clause', '(3)', '', NULL, 'If the offence referred to in sub -section (1) causes the
death of such child, disabled patient or eld erly person, the offender
shall be liable to a sentence of imprisonment for a term not
exceeding seven years and a fine not exceeding seventy thousand
rupees.
Provided that if the throwing, abandonment or neglect causes
the death of an infant, the offend er shall be liable to the sentence
referred to in Section 177.', 1, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.8', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15', 2, 'rule', '185', 'Prohibition of abetment of suicide', 'Prohibition of abetment of suicide', NULL, 8, 'The National Penal (Code) Act, 2017, Chapter-12 (Prohibition of abetment of suicide)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.8.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.8', 3, 'clause', '(1)', '', NULL, 'No person shall abet the
commission of suicide by another, or create, or cause to be created,
such circumstances as likely to lead towards the commi ssion of such
act.', 0, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.8.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.8', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding five years and a fine not exceeding fifty thousand
rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.9', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15', 2, 'rule', '186', 'Order for compensation to be pai d', 'Order for compensation to be pai d', 'If any harm, injury or loss is
caused to the body, life or property of any person from the
commission of any offence referred to in this Chapter, a reasonable
compensation for such harm, injury or loss shall be ordered to be
paid by the offender to the victim and to his or her successor if the
victim is unavailable.', 9, 'The National Penal (Code) Act, 2017, Chapter-12 (Order for compensation to be pai d)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.10', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15', 2, 'rule', '187', 'Statute of limitation', 'Statute of limitation', NULL, 10, 'The National Penal (Code) Act, 2017, Chapter-12 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.10.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.10', 3, 'clause', '(1)', '', NULL, 'There shall be no statute of limitation for
making a complaint in relation to any of the offences under Sections
177, 178, 179, 180, 181, 182, and proviso to s ub-section (3) of
Section 184.', 0, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:15.10.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:15.10', 3, 'clause', '(2)', '', NULL, 'No complaint shall lie after the expiry of six months
from the date of knowledge of the commission of any of the offences
under this Chapter other than those set forth in sub-section (1).', 1, 'The National Penal (Code) Act, 2017, Chapter-12, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:16', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-13', '', NULL, 'Offences against Protection of Pregnancy', 16, 'The National Penal (Code) Act, 2017, Chapter-13', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:16.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:16', 2, 'rule', '188', 'Prohibition of abortion', 'Prohibition of abortion', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-13 (Prohibition of abortion)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:16.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:16.0', 3, 'clause', '(1)', '', NULL, 'No person shall, except in the case
referred to in Section 189, commit abortion, or do any act with intent
to cause, or with the knowledge that, or having reason to believe that,
such act is likely to cause, abortion.', 0, 'The National Penal (Code) Act, 2017, Chapter-13, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:16.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:16.0', 3, 'clause', '(2)', '', NULL, 'No person shall cause a pregnant woman to abort, by
coercing, threatening, alluring or inducing her to so abort.', 1, 'The National Penal (Code) Act, 2017, Chapter-13, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:16.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:16.0', 3, 'clause', '(3)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) or (2) shall be liable to:
(a) A sentence of imprison ment for a term not exceeding
one year and a fine not exceeding ten thousand rupees in
the case of pregnancy of up to twelve weeks,
(b) A sentence of imprisonment for a term not exceeding
three years and a fine not excee ding thirty thousand
rupees in the case of pregnancy of more tha n twelve
weeks and up to twenty-five weeks,
(c) A sentence of imprisonment for a term not exceeding
five years and a fine not exceeding fifty thousand rupees
in the case o f pregnancy of more than twenty -five
weeks.', 2, 'The National Penal (Code) Act, 2017, Chapter-13, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:16.0.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:16.0', 3, 'clause', '(4)', '', NULL, 'If the pregnancy is not terminated at once by an act of
abortion and the child born alive but the c hild dies immediately after
birth as the consequence of such act, such act shall, for the purposes
of this Section, be deemed to constitute the offence of abortion.', 3, 'The National Penal (Code) Act, 2017, Chapter-13, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:16.0.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:16.0', 3, 'clause', '(5)', '', NULL, 'If an act done by a person in making attempt to cause
the death of a pregnant woman does not cause the death of the
woman but causes the termination of her pregnancy of twenty -five
weeks or more, the offender shall be liable to a sentence of
imprisonment for a term not exceeding five years, in addition to the
sentence to be imposed under this Act or other law.', 4, 'The National Penal (Code) Act, 2017, Chapter-13, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:16.0.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:16.0', 3, 'clause', '(6)', '', NULL, 'Notwithstanding anything contained elsewhere in this
Section, if any act done by a person with premeditation against a
pregnant woman causes abortion, that person shall be liable to the
following sentence despite the fact that he or she has not done such
act with the intention of causing abortion:
(a) A sentence of imprisonment for a term not exceeding
one year in the case of pregnancy of up to twelve weeks,
(b) A sentence of imprisonment for a term not exceeding
three years in the case of pregnancy of more than twelve
weeks and up to twenty-five weeks,
(c) A sentence of imprisonment for a term not exceeding
five years in the case of pregnancy of more than twenty-
five weeks.', 5, 'The National Penal (Code) Act, 2017, Chapter-13, Clause (6)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:16.0.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:16.0', 3, 'clause', '(7)', '', NULL, 'No person shall, with the intention of causing abortion,
do, or cause to be done, any act by which the sex of the foetus is
identified, and abort or cause abortion following such sex
identification.', 6, 'The National Penal (Code) Act, 2017, Chapter-13, Clause (7)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:16.0.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:16.0', 3, 'clause', '(8)', '', NULL, 'A person who commits the offence referred to in sub-
section (7) shall be liable to:
(a) A sentence of imprisonment for a term of three months
to six months, in the case of the offence of identifying,
or causing identification of, the sex of the foetus with
the intention of causing abortion, and
(b) A sentence of imprisonment for a term not exceeding
one year, in addition to the sentence specified in sub -
section (3), in the case of the offence of aborting or
causing abortion after identifying the sex.', 7, 'The National Penal (Code) Act, 2017, Chapter-13, Clause (8)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:16.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:16', 2, 'rule', '189', 'When a bortion can be made', 'When a bortion can be made', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-13 (When a bortion can be made)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:16.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:16.1', 3, 'clause', '(1)', '', NULL, 'Notwithstanding anything
contained in Section 188, where a health worker causes abortion in
any of the following circumstances, no offence of abortion under this
Act shall be deemed to have been committed:
(a) The pregnancy of up to twelve weeks is terminated with
the consent of the pregnant woman,
(b) The pregnancy is terminated with the consent of the
pregnant woman, upon the opinion of a licensed doctor
that her life may be in danger or her physical or mental
health may deteriorate or a handicapped child will born
if pregnancy is not terminated,
(c) The pregnancy of up to eighteen weeks conceived from
rape or incest is terminated with the consen t of the
pregnant woman,
(d) The pregnancy of a woman with human immune -
deficiency virus (HIV) or other incurable disease of
similar nature is terminated with her consent.
Explanation: For the purposes of this Section, the term
"health worker" means a doctor or health worker who, upon having
the specified qualification, has obtained a license for causing
abortion.', 0, 'The National Penal (Code) Act, 2017, Chapter-13, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:16.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:16', 2, 'rule', '190', 'Sta tute of limitation', 'Sta tute of limitation', 'No complaint shall lie after the expiry of six
months from the date of knowledge of commission of the offence
under this Chapter.', 2, 'The National Penal (Code) Act, 2017, Chapter-13 (Sta tute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-14', '', NULL, 'Offences Relating to Hurt or Grievous Hurt', 17, 'The National Penal (Code) Act, 2017, Chapter-14', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17', 2, 'rule', '191', 'Prohibition of causing hurt', 'Prohibition of causing hurt', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-14 (Prohibition of causing hurt)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.0', 3, 'clause', '(1)', '', NULL, 'No person shall cause hurt to
another person.', 0, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.0', 3, 'clause', '(2)', '', NULL, 'A person who does any of the following acts to another
person shall be deemed to cause hurt:
(a) Any act by which any kind of bodily pain is caused,
(b) Any act by which a disease is transferred,
(c) Any other act by which infirmity is caused.
Explanation: For the purposes of this Section, the term
"infirmity" means the state of any part of the body being incapable of
functioning normally, and this term also includes mental infirmity.', 1, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.0', 3, 'clause', '(3)', '', NULL, 'A person who commits, or c auses to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three years or a fine not
exceeding thirty thousand rupees or both the sentences.', 2, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17', 2, 'rule', '192', 'Prohibition of causing grievous hurt', 'Prohibition of causing grievous hurt', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-14 (Prohibition of causing grievous hurt)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.1', 3, 'clause', '(1)', '', NULL, 'No person shall cause
grievous hurt to any other person.', 0, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.1', 3, 'clause', '(2)', '', NULL, 'Where any person does any act with the intention of
causing hurt to another person, which results in any of the following
consequences, that person is deemed to have committed the offen ce
of causing grievous hurt to that other person:
(a) Making blind by making privation of the sight of, or by
breaking, either eye,
(b) Privation of smelling power of the nose,
(c) Privation of hearing power of either ear,
(d) Privation of speaking power of the tongue,
(e) Cutting of woman''s breast,
(f) Emasculation of man and woman (making woman
infertile or man impotent),
(g) Privation of the backbone, …, hand, leg or joint of
such organ by breaking, fracturing, dislocating it,
(h) Any hurt which causes the sufferer to be unable to
perform his or her professional work.', 1, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.1.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.1', 3, 'clause', '(3)', '', NULL, 'Where any act of hurt, though not causing grievous hurt
immediately, results subsequently in the consequence referred to in
sub-section (2), it shall be deemed to have caused grievous hurt.', 2, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.1.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.1', 3, 'clause', '(4)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding ten years and a fine not exceeding one hundred
thousand rupees.', 3, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.1.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.1', 3, 'clause', '(5)', '', NULL, 'Notwithstanding anything contained in sub -section (4),
in the case of so ca using grievous hurt to either of the organs
performing the same function that it becomes dysfunctional, the
offender shall be liable to half the sentence specified in that sub -
section, and where the wound caused by grievous hurt gets so healed
as to restor e the organ, the offender shall be liable to a sentence of
imprisonment for a term not exceeding three years and a fine not
exceeding thirty thousand rupees.', 4, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17', 2, 'rule', '193', 'Prohibition of causing disfigurement by use of acid or other', 'Prohibition of causing disfigurement by use of acid or other', 'chemical, biological or toxin su bstance: (1) No person shall cause
bodily pain to another person by administering acid or similar kind
of other chemical, biological or toxin substance to, or throwing such
substance on, that other person, or by burning, maiming, strolling the
body with or applying to the body such substance or disfigure the
face or any part of the body of that other person.', 2, 'The National Penal (Code) Act, 2017, Chapter-14 (Prohibition of causing disfigurement by use of acid or other)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.2', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable, according to the nature of the offence, to a
sentence of imprisonment for a term of five to eight years and a fine
of one hundred thousand to five hundred thousand rupees in the case
of disfigurement of the face, and to a sentence of imprisonment for a
term of three to five years and a fine of fifty thousand to three
hundred thousand rupees in the case of disfigurement of any other
organ of the body or bodily pain.', 0, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.2.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.2', 3, 'clause', '(3)', '', NULL, 'The amount of fine collected in accordance with sub -
section (2) shall be paid in whole to the victim as compensation.', 1, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17', 2, 'rule', '194', 'Sentence for causing hurt or grievous hurt by grave provocation', 'Sentence for causing hurt or grievous hurt by grave provocation', 'or in heat of passion : (1) Notwithstanding anything contained in
Section 191 or 192, a person who causes hurt in any of the following
circumstances shall be liable to a sentence of imprisonment for a
term not exceeding tw o years or a fine not exceeding twenty
thousand rupees or both the sentences in the case of a grievous hurt,
and to a sentence of imprisonment for a term not exceeding one year
or a fine not exceeding ten thousand rupees or both the sentences in
the case of any other kind of hurt:
(a) Where the offender, while being deprived of the power
of self-control by grave and sudden provocation, causes
hurt to the person who gave such provocation or to any
other person by a mistake of fact or happens to cause
injury to another person by accident.
Provided that this clause shall not apply to the
following circumstance:', 3, 'The National Penal (Code) Act, 2017, Chapter-14 (Sentence for causing hurt or grievous hurt by grave provocation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.3', 3, 'clause', '(1)', '', NULL, 'Where the offender causes hurt upon being
provoked by anything done in obedience to
the law or in the exercise of the right of
private defence or any anything done or
intended to be done by a public servant in
the exercise of his or her official duties,', 0, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.3.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.3', 3, 'clause', '(2)', '', NULL, 'Where the offender himself or herself gives
provocation to another with intent to cause
any harm to any one and anything done by
that other pers on upon being so provoked
causes hurt to any person.
(b) Where the offender in the exercise in good faith of the
right of private defence exceeds the limi t of such power
and causes injury to any person,
(c) Where hurt is caused to any person instantly in t he heat
of passion upon a sudden quarrel,
Provided that while doing any act referred to in
this clause, the offender must not have taken an undue
advantage or acted in a cruel or unusual manner.', 1, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.3.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.3', 3, 'clause', '(2)', '', NULL, 'Notwithstanding anything contained in clauses
(b) and (c ) of sub -section (1), the provisions contained in these
clauses shall not be applicable to any case of hurt or grievous hurt
caused with premeditation or deliberate afterthought.', 2, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17', 2, 'rule', '195', 'Prohibition of causing hurt or grievous hurt by recklessness or', 'Prohibition of causing hurt or grievous hurt by recklessness or', 'negligence: (1) No person shall cause hurt or grievous hurt or other
injury to any one by doing a reckless or negligent act.', 4, 'The National Penal (Code) Act, 2017, Chapter-14 (Prohibition of causing hurt or grievous hurt by recklessness or)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.4', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to the following sentence:
(a) A sentence of imprisonme nt for a term not exceeding
two years or a fine not exceeding twenty thousand
rupees or both the sentences, in the case of a grievous
hurt caused by a reckless act, and a sentence of
imprisonment for a term not exceeding one year or a
fine not exceeding te n thousand rupees or both the
sentences, in the case of any other kind of injury caused
by a reckless act,
(b) A sentence of imprisonment for a term not exceeding
six months or a fine not exceeding five thousand rupees
or both the sentences in the case of the commission of
such offence by a negligent act.', 0, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17', 2, 'rule', '196', 'Prohibition of using criminal force', 'Prohibition of using criminal force', NULL, 5, 'The National Penal (Code) Act, 2017, Chapter-14 (Prohibition of using criminal force)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.5.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.5', 3, 'clause', '(1)', '', NULL, 'No person shall use
criminal force to another person.', 0, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.5.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.5', 3, 'clause', '(2)', '', NULL, 'A person shall be considered to use criminal force to
another person if he or she does any of the following acts:
(a) To use any kind of force to that other person with the
intention of committing an offence,
(b) To use force to that other person with the intention of
causing, or knowing it to be likely that the use of such
force will cause, injury, fear or annoyance to that other
person or his or her family or property,
(c) To terrify that other person to apprehend that force will
be used to him or her or to threat or intimidate to use
force, or attempt to use force, in any other manner, to
him or her.', 1, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.5.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.5', 3, 'clause', '(3)', '', NULL, 'Notwithstanding anything contained elsewhere in this
Section, the use of any force, with one''s consent, in the course of
imparting teaching, instruction or training on the concerned subject,
conducting acting or treatment of any kind or in a m anner to re nder
benefit or the use of force of usual nature in the course of having any
kind of game shall not be considered to be the use of criminal force.
Provided that the provision of this sub -section shall not apply
to any malicious use of force to cause injury to any one.', 2, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.5.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.5', 3, 'clause', '(4)', '', NULL, 'A person who uses, or causes to be used, criminal force
shall be liable to a sentence of imprisonment for a term not
exceeding three years or a fine not exceeding thirty thousand rupees
or both the sentences, in the case of using criminal force by carrying
a weapon, and to a sentence of imprisonment for a term not
exceeding one year or a fine not exceeding ten thousand rupees or
both the sentences, in the case of using criminal force without
carrying a weapon.', 3, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17', 2, 'rule', '197', 'Prohibition of making unc onscious with intent to commit', 'Prohibition of making unc onscious with intent to commit', 'offence: (1) No person shall, with intent to facilitate the commission
of any offence, feed or administer, in any other manner, to another
person any substance causing unconsciousness, dizziness or
unhealthiness or make that other person unconscious in any manner
whatsoever.', 6, 'The National Penal (Code) Act, 2017, Chapter-14 (Prohibition of making unc onscious with intent to commit)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.6.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.6', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offense referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding one year and a fine not
exceeding ten thousand rupees.', 0, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.6.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17.6', 3, 'clause', '(3)', '', NULL, 'Where any act referred to in sub-section (1) has resulted
in the commission of such offence, the sentence referred to in this
Section shall be added to the sentence imposable for such offence.', 1, 'The National Penal (Code) Act, 2017, Chapter-14, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17', 2, 'rule', '198', 'Compensation', 'Compensation', 'Where any harm, damag e or loss is caused to any
person''s body, life or property from the commi ssion of the offence
referred to in this Chapter, compensation shall be cause d to be paid
by the offender to the victim.', 7, 'The National Penal (Code) Act, 2017, Chapter-14 (Compensation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:17.8', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:17', 2, 'rule', '199', 'Statute of limitation', 'Statute of limitation', 'No complaint shall lie, in the ca se of the
offence referred to in Section 196, after the expiry of three months
from the date of its commission, in the case of the offence referred to
in Section 197, after the expiry of six months from the date on which
such person becomes conscious , and, in the case of any of the other
offences referred to in this Chapter, after the expiry of one year from
the date of its commission.', 8, 'The National Penal (Code) Act, 2017, Chapter-14 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:18', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-15', '', NULL, 'Offences Relating to Unlawful Detention', 18, 'The National Penal (Code) Act, 2017, Chapter-15', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:18.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:18', 2, 'rule', '200', 'Prohibition of unlawful confinement', 'Prohibition of unlawful confinement', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-15 (Prohibition of unlawful confinement)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:18.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:18.0', 3, 'clause', '(1)', '', NULL, 'No person shall
maliciously subject, or cause to be subjected, another person to
detention in any other manner except in accordance with law.', 0, 'The National Penal (Code) Act, 2017, Chapter-15, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:18.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:18.0', 3, 'clause', '(2)', '', NULL, 'A person who co mmits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding three years and a fine not exceeding thirty thousand
rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-15, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:18.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:18.0', 3, 'clause', '(3)', '', NULL, 'No one other than the competent authority shall
obstruct, or cause to be obstructed, the movement of any person.', 2, 'The National Penal (Code) Act, 2017, Chapter-15, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:18.0.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:18.0', 3, 'clause', '(4)', '', NULL, 'A person who commits the offence referred to in sub-
section (3) shall be liable to a sentence of imprisonment for a term
not exceeding six months or a fine not exceeding five thousand
rupees or both the sentences.', 3, 'The National Penal (Code) Act, 2017, Chapter-15, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:18.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:18', 2, 'rule', '201', 'Prohibition of holding in detention without providing minimum', 'Prohibition of holding in detention without providing minimum', 'humane facilities: (1) No authority who is compe tent by law to
make detention shall detain, or cause to be detained, any person by
depriving him or her of such facilities as required to be provided in
accordance with law or of such minimum humane facilities as are
available in the place of his or her detention.', 1, 'The National Penal (Code) Act, 2017, Chapter-15 (Prohibition of holding in detention without providing minimum)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:18.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:18.1', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding one and half years and a fine not exceeding fifteen
thousand rupees.', 0, 'The National Penal (Code) Act, 2017, Chapter-15, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:18.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:18', 2, 'rule', '202', 'Prohibition of detaining person for whose release order has been', 'Prohibition of detaining person for whose release order has been', 'issued: (1) No person shall keep on detaining any person held in
detention in accordance with law after receiving an order issued by a
competent authority under law for the release of such person from
detention.', 2, 'The National Penal (Code) Act, 2017, Chapter-15 (Prohibition of detaining person for whose release order has been)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:18.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:18.2', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding one year and a fine not
exceeding ten thousand rupees.', 0, 'The National Penal (Code) Act, 2017, Chapter-15, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:18.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:18', 2, 'rule', '203', 'Prohibition of detention in secret', 'Prohibition of detention in secret', NULL, 3, 'The National Penal (Code) Act, 2017, Chapter-15 (Prohibition of detention in secret)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:18.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:18.3', 3, 'clause', '(1)', '', NULL, 'No competent authority shall
hold any person in detention secretly in such a manner that the
detention of such person or the place of such detention may not be
known or discovered.', 0, 'The National Penal (Code) Act, 2017, Chapter-15, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:18.3.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:18.3', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding four years and a fine not
exceeding forty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-15, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:18.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:18', 2, 'rule', '204', 'Order for compensation to be paid', 'Order for compensation to be paid', 'A reasonable compensation
shall be ordered to be paid by the offend er who commits, or causes
to be committed, the offence referred to in this Chapter to the victim.', 4, 'The National Penal (Code) Act, 2017, Chapter-15 (Order for compensation to be paid)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:18.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:18', 2, 'rule', '205', 'Statute of limitation', 'Statute of limitation', 'No complaint shall lie, in the case of an
offence under sub-section (3) of Section 200, after the expiry of three
months from the date of commission of such offence, and in the case
of any of the other offences under this Chapter, after the expiry of
three months from the date of release of the detained person from
such detention.', 5, 'The National Penal (Code) Act, 2017, Chapter-15 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:19', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-16', '', NULL, 'Offences Relating to Enforced Disappearance', 19, 'The National Penal (Code) Act, 2017, Chapter-16', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:19.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:19', 2, 'rule', '206', 'Prohibition of enforced appearance', 'Prohibition of enforced appearance', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-16 (Prohibition of enforced appearance)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:19.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:19.0', 3, 'clause', '(1)', '', NULL, 'No person shall subject,
or cause to be subjected, any one to enforced disappearance.', 0, 'The National Penal (Code) Act, 2017, Chapter-16, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:19.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:19.0', 3, 'clause', '(2)', '', NULL, 'For the purposes of sub -section (1), the term "enforced
disappearance” means any of the following acts:
(a) The arrest, detention or any other form of control of a
person by a person or security personnel having
authority by law to make arrest, investigation or
enforcement of law, followed by a failure to produce
such person before the case trying authority within
twenty-four hours of the date of such arrest or
deprivation of liberty, excluding the time required for
journey, or a refusal to allow the concerned person to
meet such person, and/or by concealment of information
as to where, how and in what condition such pers on has
been so held,
(b) The abduction, custody, control or any other form of
deprivation of liberty of a person by any person,
organization or group, whether organized or not,
followed by concealment of information to the
concerned person as to the reason for such deprivation
and where, how and in what condition such person has
been so held,', 1, 'The National Penal (Code) Act, 2017, Chapter-16, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:19.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:19.0', 3, 'clause', '(3)', '', NULL, 'A person who orders the commission of enforced
disappearance of a person upon arrest, detention or control of such
person and a person who implements such order sh all be considered
to be the principal offender of enforced disappearance.', 2, 'The National Penal (Code) Act, 2017, Chapter-16, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:19.0.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:19.0', 3, 'clause', '(4)', '', NULL, 'Where an act of enforced disappearance is committed in
pursuance of order or direction given by a person holding public
office or by the responsible person of an organization or group,
whether organized or unorganized, the person giving such order or
direction shall be liable as the principal offender of enforced
disappearance.', 3, 'The National Penal (Code) Act, 2017, Chapter-16, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:19.0.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:19.0', 3, 'clause', '(5)', '', NULL, 'A superior who, despite knowing that his or her
subordinate official, body or group was committing o r about to
commit an act of enforced disappearance, disregards such
information or fails to take necessary measures to prevent the
commission of such act shall also be considered to have committed
the offence under this Section.', 4, 'The National Penal (Code) Act, 2017, Chapter-16, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:19.0.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:19.0', 3, 'clause', '(6)', '', NULL, 'Where a person has been subjected to enforced
disappearance by two or more persons jointly, every person involved
in such act shall be equally liable as the offender.', 5, 'The National Penal (Code) Act, 2017, Chapter-16, Clause (6)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:19.0.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:19.0', 3, 'clause', '(6)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to the following sentence:
(a) In the case of the principal offender of enforced
disappearance, a sentence of imprisonment for a
term not exceeding fifteen years and a fine not
exceeding five hundred thousand rupees, having
regard to the duration and circumstances of such
enforced disappearance,
(b) In the case of a person who is accomplice or
conspires to the commission of enforced
disappearance, the same sentence as is imposable
on the principal offender, and in the case of a
person who attempts to or facilitates the
commission of e nforced disappearance, half the
sentence imposable on the principal offender.', 6, 'The National Penal (Code) Act, 2017, Chapter-16, Clause (6)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:19.0.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:19.0', 3, 'clause', '(8)', '', NULL, 'A person who does an act constituting the offence
referred to in sub-section (1) against a woman or child shall be liable
to an additional sentence of imprisonment for a term of two years, in
addition to the sentence to be imposed pursuant to sub-section (7).', 7, 'The National Penal (Code) Act, 2017, Chapter-16, Clause (8)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:19.0.8', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:19.0', 3, 'clause', '(9)', '', NULL, 'Where a person has committed any other offence
punishable by law against any one who has been subjected to
enforced disappearance, during such disappearance, he or sh e shall
be liable to the additional sentence under this Section, in addition to
the sentence imposable by law for such offence.', 8, 'The National Penal (Code) Act, 2017, Chapter-16, Clause (9)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:19.0.9', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:19.0', 3, 'clause', '(10)', '', NULL, 'A person who subjects any one to enforced
disappearance by using any government vehicle, building, arms and
ammunition or g oods shall be liable to an additional sentence of
imprisonment for a term of one year, in addition to the sentence
imposable under this Section.', 9, 'The National Penal (Code) Act, 2017, Chapter-16, Clause (10)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:19.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:19', 2, 'rule', '207', 'Forfeiture of goods related to offence', 'Forfeiture of goods related to offence', 'Any building, land, vehicle,
arms and other goods knowingly allowe d by the owner thereof to be
used in, or used with the consent of the concerned owner in, the
commission of the offence punishable under this Chapter shall be
forfeited.
Provided that no governmental building, vehicle, arms and
goods shall be forfeited.', 1, 'The National Penal (Code) Act, 2017, Chapter-16 (Forfeiture of goods related to offence)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:19.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:19', 2, 'rule', '208', 'Entitlement to compensation', 'Entitlement to compensation', 'Where a person who is subjected to
enforced disappearance appears or is made public subsequently, he
or she shall be entitled to get a reasonable compensation from the
person who has so subjected him or her to enforced disappearance.', 2, 'The National Penal (Code) Act, 2017, Chapter-16 (Entitlement to compensation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:19.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:19.2', 3, 'clause', '(2)', '', NULL, 'Where the person subjected to enforced disappearance
is already dead, the immediate successor to him or her shall be
entitled to get the compensation referred to in sub-section (1).', 0, 'The National Penal (Code) Act, 2017, Chapter-16, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:19.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:19', 2, 'rule', '209', 'Property to be returned', 'Property to be returned', 'Where any person, in subjec ting another
person to enforced disappearance under this Chapter, has also taken
any property belonging to that other person, the person who has so
subjected to enforced disappearance shall return such property, if
available, and pay a reasonable compensat ion for such property, if
not available, to the disappeared person or his or her immediate
relative.', 3, 'The National Penal (Code) Act, 2017, Chapter-16 (Property to be returned)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:19.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:19', 2, 'rule', '210', 'Statute of limitation', 'Statute of limitation', 'No complaint shall be entertained after expiry
of six months from the date of having knowledge of commission of
the offence und er this Chapter or from the date of the disappeared
person getting or being made public.
Provided that if a complaint is filed, accompanied by the
evidence, with the leave of the court, setting out the reason for not
being in a position to file the complai nt, such complaint may lie at
any time.', 4, 'The National Penal (Code) Act, 2017, Chapter-16 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-17', '', NULL, 'Offences Relating to Kidnapping or Taking of Hostages', 20, 'The National Penal (Code) Act, 2017, Chapter-17', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20', 2, 'rule', '211', 'Prohibition of kidnapping', 'Prohibition of kidnapping', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-17 (Prohibition of kidnapping)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20.0', 3, 'clause', '(1)', '', NULL, 'No person shall kidnap, or cause to
be kidnapped, another person.', 0, 'The National Penal (Code) Act, 2017, Chapter-17, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20.0', 3, 'clause', '(2)', '', NULL, 'For the purposes of sub -section (1), a perso n shall be
considered to have committed kidnapping if he or she does any of
the following acts:
(a) To take any person to or compel him or her to go to any
place by using force or threats to use force or by
practicing fraud, deception or intimidation or by
showing or not showing arms or by misrepresenting or
by administering narcotics or alcoholic substance to him
or her or by seizing or controlling in any way a vehicle
by which he or she is travelling or exercising control in
any way over such vehicle, or
(b) To take by force any person to any place without his or
her consent or any child or any person who is under
shelter of any one due to his or her physical incapacity
or any person of unsound mind due to mental illness
without the consent of his or her f ather, mother or
guardian or by way of misrepresentation.', 1, 'The National Penal (Code) Act, 2017, Chapter-17, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20', 2, 'rule', '212', 'Prohibition of hostage -taking', 'Prohibition of hostage -taking', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-17 (Prohibition of hostage -taking)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20.1', 3, 'clause', '(1)', '', NULL, 'No person shall take another
person hostage.', 0, 'The National Penal (Code) Act, 2017, Chapter-17, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20.1', 3, 'clause', '(2)', '', NULL, 'For the purposes of sub -section (1), a person shall be
considered to have committed hostage -taking if that person seizes or
detains another person without his or her consent or a child or a
person of unsound mind without the consent of his or her father,
mother or guardian, by using force or threats to use force, or by
practicing fraud, deception, coercion or intimidation or by showing
or not showing arms or by misrepresenting or by administering
narcotics or alcoholic substance to him or her or by seizing or
controlling a vehicle or place where he or she is staying.', 1, 'The National Penal (Code) Act, 2017, Chapter-17, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.1.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20.1', 3, 'clause', '(3)', '', NULL, 'Notwithstanding anything contained in sub-section (2),
placing, in good faith, an unsound person under the surveillance or
control of any one in the course of treatment or for any other
purpose, for the benefit of the concerned person, with the consent of
his or her father, mother or guard ian shall not be deemed to
constitute hostage-taking.', 2, 'The National Penal (Code) Act, 2017, Chapter-17, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20', 2, 'rule', '213', 'Punishment for kidnapping or hostage -taking', 'Punishment for kidnapping or hostage -taking', 'A person who
does, or causes to be done, any act referred to in Section 211 or 212
shall be liable to a sentence of imprisonment for a term of seven to
ten years and a fine of seventy-five thousand to one hundred
thousand rupees if the person does , or causes to be done , such act
with the intention of causing death, causing injury by subjecting to
hurt, committing rape or unnatu ral sex, trafficking or ens laving, or
subjecting to forced labor, engaging into prostitution, subjecting to
torture, compelling to do or cause to be done any act, taking ransom
or compelling to do any other act which constitutes an y offence
under the law in force, and to a sentence of imprisonment for a term
of three to five years and a fine of thirty thousand to fifty thousand
rupees if the person does, or causes to be done, such act for any other
purpose.', 2, 'The National Penal (Code) Act, 2017, Chapter-17 (Punishment for kidnapping or hostage -taking)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20', 2, 'rule', '214', 'Additional sentence to be imposed', 'Additional sentence to be imposed', NULL, 3, 'The National Penal (Code) Act, 2017, Chapter-17 (Additional sentence to be imposed)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20.3', 3, 'clause', '(1)', '', NULL, 'A person who takes another
person hostage under Section 212 after kidnapping him or her under
Section 211 shall be liable to a sentence of imprisonment for a term
of ten to fifteen years and a fine of one hundred thousand to one
hundred fifty thousand rupees.', 0, 'The National Penal (Code) Act, 2017, Chapter-17, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.3.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20.3', 3, 'clause', '(2)', '', NULL, 'A person who does any o ther act considered to be an
offence under this Act or under the law in force by committing
kidnapping or hostage-taking shall be liable to the sentence referred
to in sub-section (1), in addition to the sentence imposable for such
offence.', 1, 'The National Penal (Code) Act, 2017, Chapter-17, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.3.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20.3', 3, 'clause', '(3)', '', NULL, 'Where the offence referred to in Sections 211 and 212 is
committed, or cause to be committed, in an organized manner, the
persons committing such offence shall be liable to an additional
sentence of imprisonment for a term of two years.', 2, 'The National Penal (Code) Act, 2017, Chapter-17, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20', 2, 'rule', '215', 'Person who abets or ord ers or attempts or conspires or is', 'Person who abets or ord ers or attempts or conspires or is', 'accomplice to be liable to sentence: (1) A person who abets or
orders the commission of any offence referred to in this Chapter shall
be liable to the same sentence as is imposable on the principal
offender.', 4, 'The National Penal (Code) Act, 2017, Chapter-17 (Person who abets or ord ers or attempts or conspires or is)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20.4', 3, 'clause', '(2)', '', NULL, 'Notwithstanding anything contained in sub -section (1),
the person who attempts or conspires to commit or is accomplice to
the commission of such act shall be liable to half the sentence
imposable for that offence.', 0, 'The National Penal (Code) Act, 2017, Chapter-17, Clause (2)', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_national_penal_code_2074_2017:20.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20', 2, 'rule', '216', 'Reduction of sentence if surrendered', 'Reduction of sentence if surrendered', 'Where a person committing
an offence under this Chapter surrenders before the security
personnel at the time of committing the offence or renders assistance
in arresting the other offenders or members of the gang committing
that offence, the court may, having reg ard to the circumstances,
reduce the sentence for that person.', 5, 'The National Penal (Code) Act, 2017, Chapter-17 (Reduction of sentence if surrendered)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20', 2, 'rule', '217', 'Compensation ordered to be paid', 'Compensation ordered to be paid', NULL, 6, 'The National Penal (Code) Act, 2017, Chapter-17 (Compensation ordered to be paid)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.6.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20.6', 3, 'clause', '(1)', '', NULL, 'A reasonable compensation
shall be ordered to be paid to the victim by the person who is held to
have committed or caused the commission of any offence under this
Chapter.', 0, 'The National Penal (Code) Act, 2017, Chapter-17, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.6.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20.6', 3, 'clause', '(2)', '', NULL, 'The compensation referred to in sub -section (1) shall be
paid to the immediate successor to the victim if the victim is already
dead.', 1, 'The National Penal (Code) Act, 2017, Chapter-17, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20', 2, 'rule', '218', 'Statute of limitation', 'Statute of limitation', NULL, 7, 'The National Penal (Code) Act, 2017, Chapter-17 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.7.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20.7', 3, 'clause', '(1)', '', NULL, 'There shall be no statute of limitation for
making a complaint i n the case of any offence under this Chapter
which has caused the death of any one.', 0, 'The National Penal (Code) Act, 2017, Chapter-17, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:20.7.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:20.7', 3, 'clause', '(2)', '', NULL, 'No complaint shall lie after the expiry of two years after
the date of commission of any offence under this Chapter other than
that set forth in sub -section (1), and a fter the expiry of six months
after the date of release of the concerned person from such offence in
the case of any of the offences under Sections 211 and 212.', 1, 'The National Penal (Code) Act, 2017, Chapter-17, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-18', '', NULL, 'Sexual Offences', 21, 'The National Penal (Code) Act, 2017, Chapter-18', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21', 2, 'rule', '219', 'Prohibition of committing rape', 'Prohibition of committing rape', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-18 (Prohibition of committing rape)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.0', 3, 'clause', '(1)', '', NULL, 'No one shall commit rape.', 0, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.0', 3, 'clause', '(2)', '', NULL, 'Where a man has sexual intercourse with a woman
without her consent or with a girl child below eighteen years of age
even with her consent, the man shall be considered to commit rape
on such woman or girl child.
Explanation: For the purposes of this Chapter,-
(a) Consent obtained by way of coercion, undue influence,
intimidation, threat, misrepresentation, or kidnapping or
taking of hostage shall not be considered to be consent,
(b) Consent obtained at the time of being of unsoundness of
mind shall not be considered to be consent,
(c) The penetration of penis into anus or mouth, penetration
of penis, to any extent, into anus, mouth or vagina,
insertion of any object other than penis into vagina shall
also be considered to be rape.', 1, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.0', 3, 'clause', '(3)', '', NULL, 'A person who commits rape shall be liable to the
sentence of imprisonment as follows, having regard to the
circumstances of such sexual intercourse and the age of woman:
(a) Imprisonment for a term of sixteen to twenty years, if
she is a girl child below ten years of age,
(b) Imprisonment for a term of fourteen to sixteen years, if
she is a girl child who is ten years or above ten years of
age but below fourteen years of age,
(c) Imprisonment for a term of twelve to fourteen years, if
she is a girl child who is fourtee n or above fourteen
years of age but below sixteen years of age,
(d) Imprisonment for a term of ten to twelve years, if the
woman is sixteen or above sixteen years of age but
below eighteen years of age,
(e) Imprisonment for a term of seven to ten years, i f the
woman is eighteen or above eighteen years of age.', 2, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.0.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.0', 3, 'clause', '(4)', '', NULL, 'Notwithstanding anything contained in sub -section (3),
if the husband commits rape on his wife during the existence of
marital relationship between them, he shall be liable to a sentence of
imprisonment for a term not exceeding five years.
Provided that the following situation shall not be considered as
the existence of marital relationship:
(a) A case of partition has been instituted upon
making separation of board and bread,
(b) The wife has lived separa te upon taking her
partition share from the husband,
(c) A case of divorce from the husband has been
instituted.', 3, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.0.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.0', 3, 'clause', '(5)', '', NULL, 'In the case of the situation referred to in sub -section (4),
the court may, if it is necessary to do so upon a petition by the
victim, order the husband to do the following:
(a) To allow the wife to reside in the same house
where she has resided, to provide her with food
and clothes, not to hurt her and to behave her
politely and decently,
(b) To get the wife to have required medical
treatment or provide reasonable amount for her
treatment,
(c) To arrange a separate residence for the husband if
it is not appropriate for them to reside in the same
place together and make necessary arrangement
for the maintenance of the wife while so residing
separately,
(d) To refraining from doing act causing suffering or
annoyance, in any manner, to the wife and do, or
cause to be done, necessary and appropriate act
for the interest and security of the wife.', 4, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.0.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.0', 3, 'clause', '(6)', '', NULL, 'Notwithstanding anything contained in sub -section (1),
a man who commits rape in spite of knowing that he has human
immune deficiency virus (HIV positive) or a sexually transmitted
disease shall be liable to the following additional sentence, in
addition to the sentence set forth in sub-section (3):
(a) The sentence referred to in Section 105 in the
event of the commission of rape in spite of
knowing that he has human immune deficiency
virus (HIV positive),
(b) A sentence of imprisonment for a term not
exceeding three years and a fine not exceeding
thirty thousand rupees in the event of the
commission of rape in spite of knowing that he
has any other sexually transmitted disease.', 5, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (6)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.0.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.0', 3, 'clause', '(7)', '', NULL, 'A man who commits rape on a woman in a gang or on a
woman having pregnancy of more than six months or on a woman
who is infirm or disabled or suffering from physical or mental
illness, or commits rape showing arms shall be liable to an additional
sentence of imprisonment for a term not exceeding five years, in
addition to the sentence set forth in sub-section (3).', 6, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (7)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.0.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.0', 3, 'clause', '(8)', '', NULL, 'A pe rson who commits rape on a woman within the
prohibited degree of relationship by consanguinity or affinity shall be
liable to the sentence referred to in this Chapter, in addition to the
sentence imposable for incest if he is liable to such sentence for
incest.', 7, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (8)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21', 2, 'rule', '220', 'Prohibition of incest', 'Prohibition of incest', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-18 (Prohibition of incest)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.1', 3, 'clause', '(1)', '', NULL, 'No person shall have sexual intercourse
with another person knowingly that such person is one falling within
the prohibited degree of relationship by consanguinity or affinity for
marriage according to the usage, custo m or tradition being practiced
in his or her caste or lineage.', 0, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.1', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) in the following relationship shall be liable to the
following sentence:
(a) A sentence of imprisonment for life in the cas e of
sexual intercourse between the natural mother
and her natural son or between the natural father
and his natural daughter,
(b) A sentence of imprisonment for a term of four
years to ten years and a fine of forty thousand
rupees to one hundred thousand rupees in the case
of sexual intercourse between the step -mother
and her step -son, between the step father and his
step daughter, between the full blood elder sister
and brother, between full blood elder brother and
sister, between father -in-law and daught er-in-law
within the same branch, between grand-father and
grand-daughter or great -grand-daughter within
the same branch, between elder brother-in-law
and sister -in-law within the same branch or
between younger brother-in-law and sister-in-law
within the same branch,
(c) A sentence of imprisonment for a term of three to
six years and a fine of thirty thousand to sixty
thousand rupees in the case of sexual intercourse
between grand -mother and her grand -son or
great-grand-son within the three generations of
the same branch, between father''s elder brother or
uncle and niece within the same branch, between
nephew and great mother (wife of own father''s
brother) or aunty within the same branch,
between father -in-law and brother''s daughter -in-
law within the same br anch, between uterine
maternal uncle and niece or nephew and maternal
aunty, between mother''s elder sister or younger
sister and nephew or between mother -in-law
(one''s wife side) and son-in-law,
(d) A sentence of imprisonment for a term of one
year to thre e years and a fine of ten thousand to
thirty thousand rupees, having regard to, inter
alia, the branch, relationship and generation, in
the case of sexual intercourse between persons in
other relationship within seven generations of
one’s own clan except t hat referred to in clause
(a), (b) or (c).', 1, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21', 2, 'rule', '221', 'Prohibition of sexual intercourse with detainee', 'Prohibition of sexual intercourse with detainee', NULL, 2, 'The National Penal (Code) Act, 2017, Chapter-18 (Prohibition of sexual intercourse with detainee)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.2', 3, 'clause', '(1)', '', NULL, 'No
government employee shall have sexual intercourse with a person
held in prison or detention or facilitate or create circumstances for
the commission by another person of sexual intercourse with such
person.', 0, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.2.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.2', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed,
sexual intercourse referred to in sub -section (1) shall be liable to a
sentence of imprisonment for a term not exceeding three years, and if
such sexual intercourse is an offence under this Act or other law also,
the sentence referred to in this Section shall be added to the sentence
under such law.', 1, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21', 2, 'rule', '222', 'Prohibition of sexual intercourse with person in one''s own', 'Prohibition of sexual intercourse with person in one''s own', 'protection or security : (1) No person shall have, or aid another
person to have, sexual intercourse with any person in his or her
protection, security or custody, and no office -bearer or employee of
any organization providing treatment or rehabilitation services to
persons of unsound mind or suffering from physical or mental illness
shall have sexual intercourse with any person held in such
organization.', 3, 'The National Penal (Code) Act, 2017, Chapter-18 (Prohibition of sexual intercourse with person in one''s own)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.3', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding thr ee years, and if such sexual intercourse is an
offence under this Act or other law also, the sentence referred to in
this Section shall be added to the sentence under such law.', 0, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21', 2, 'rule', '223', 'Prohibition of sexual intercourse with person in office or', 'Prohibition of sexual intercourse with person in office or', 'receiving profe ssional service: (1) No employee serving in a
government office or private office or person providing any
professional service or commercial work shall have, or aid another
person to have, sexual intercourse with a person serving in such
office or a person making contact or being in contact for such service
or work, while performing functions of such office or providing such
service or at the place where such service is provided.', 4, 'The National Penal (Code) Act, 2017, Chapter-18 (Prohibition of sexual intercourse with person in office or)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.4', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be l iable to a sentence of imprisonment for a term
not exceeding four years and a fine not exceeding forty thousand
rupees, and if such sexual intercourse is an offence under this Act or
other law also, the sentence referred to in this Section shall be added
to the sentence under such law.', 0, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21', 2, 'rule', '224', 'Prohibition of sexual harassment', 'Prohibition of sexual harassment', NULL, 5, 'The National Penal (Code) Act, 2017, Chapter-18 (Prohibition of sexual harassment)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.5.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.5', 3, 'clause', '(1)', '', NULL, 'No person shall commit, or
caused to be committed, sexual harassment to another person.', 0, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.5.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.5', 3, 'clause', '(2)', '', NULL, 'A person shall be considered to commit sexual
harassment if the person holds or touches or attempts to touch any
sensitive organ of, or opens or attempts to open undergarments of, or
obstructs or hinders in any way the wearing or removing of
undergarments of, or takes to any lonely place in an unusual manner,
or gets his or her sexual organ to be touched or held by, or uses
vulgar or similar other words, spoken or written or by gesture or by
way of electronic medium, or shows any pornography to, or teases or
annoys with sexual motive, or behaves in an unusual, undesirable or
indecent manner with , a person who is not his wife or her husband,
without her or his consent, with the motive of having sexual
intercourse with her or him.', 1, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.5.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.5', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding three years and a fine not exceeding thirty thousand
rupees.', 2, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21', 2, 'rule', '225', 'Prohibition of child sexual abuse', 'Prohibition of child sexual abuse', NULL, 6, 'The National Penal (Code) Act, 2017, Chapter-18 (Prohibition of child sexual abuse)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.6.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.6', 3, 'clause', '(1)', '', NULL, 'No person shall commit, or
cause to be committed, child sexual abuse.', 0, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.6.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.6', 3, 'clause', '(2)', '', NULL, 'A person shall be considered to commit child sexual
abuse if the person takes to any lonely place in an unusual manner,
or holds or touches any sexual organ of, gets his or her sexual organ
to be touched or held by, or makes any form of unusual sexual
behavior with, a child, with the motive of having sexual int ercourse
with the child.', 1, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.6.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.6', 3, 'clause', '(3)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding three years and a fine not exceeding thirty thousand
rupees.', 2, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21', 2, 'rule', '226', 'Prohibition of unnatural s exual intercourse', 'Prohibition of unnatural s exual intercourse', NULL, 7, 'The National Penal (Code) Act, 2017, Chapter-18 (Prohibition of unnatural s exual intercourse)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.7.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.7', 3, 'clause', '(1)', '', NULL, 'No person shall
have, or cause to be had, unnatural sexual intercourse with another
person without his or her consent.
Explanation: For the purposes of this sub -section, consent
given by a child shall not be considered to be consent.', 0, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.7.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.7', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding three years and a fine not exceeding thirty thousand
rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.7.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.7', 3, 'clause', '(3)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) against a child shall be liable to the sentence under
Section 219.', 2, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.8', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21', 2, 'rule', '227', 'Prohibition of bestiality', 'Prohibition of bestiality', NULL, 8, 'The National Penal (Code) Act, 2017, Chapter-18 (Prohibition of bestiality)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.8.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.8', 3, 'clause', '(1)', '', NULL, 'No person shall have, or cause to be
had, sexual intercourse with an animal.', 0, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.8.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.8', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (4) shall be liable to a sentence of imprisonment for a term
not exceeding two years and a fine not exceeding twenty thousand
rupees, if the person has committed, or caused to be committed,
sexual intercourse with a cow, and to a sentence of imprisonmen t for
a term not exceeding one year and a fine not exceeding ten thousand
rupees, in the case of sexual intercourse with any other animal.', 1, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.9', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21', 2, 'rule', '228', 'Compensation ordered to be paid', 'Compensation ordered to be paid', 'A reasonable compensation
shall be ordered to be paid to the victim of any offe nce referred to in
this Chapter other than the offences under Sections 220 and 226.', 9, 'The National Penal (Code) Act, 2017, Chapter-18 (Compensation ordered to be paid)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.10', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21', 2, 'rule', '229', 'Statute of limitation', 'Statute of limitation', NULL, 10, 'The National Penal (Code) Act, 2017, Chapter-18 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.10.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.10', 3, 'clause', '(1)', '', NULL, 'There shall be no statute of limitation for
making a complaint in relation to the case of any offence under
Section 220.', 0, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:21.10.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:21.10', 3, 'clause', '(2)', '', NULL, 'No complaint shall lie after the expiry of one year from
the date of commission of any of the offences under Sections 219,
221, 222, 223, 224 and 225 and sub -section (3) of Section 226, and
after the expiry of three months fr om the date of knowledge of
commission of any of the other offences under this Chapter.
Provided that where the offence is committed against a person
held in detention, taken into control, kidnapped or taken hostage, no
complaint shall lie after the expiry of three months from the date of
release from such detention, control, kidnapping or hostage-taking.', 1, 'The National Penal (Code) Act, 2017, Chapter-18, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-19', '', NULL, 'Offence Relating to Medical Treatment', 22, 'The National Penal (Code) Act, 2017, Chapter-19', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22', 2, 'rule', '230', 'Prohibition of conducting medical treatment by person who has', 'Prohibition of conducting medical treatment by person who has', 'not obtained licence: (1) No person, other than a person who has,
upon having acq uired the specified educational qualification in
medicines, obtained from the lawful competent authority a licence
for medical treatment, shall provide medical services to, carry out
surgery on any organ of human body of, administer or prescribe any
kind o f drug to, or otherwise conduct medical treatment of, any
person.', 0, 'The National Penal (Code) Act, 2017, Chapter-19 (Prohibition of conducting medical treatment by person who has)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.0', 3, 'clause', '(2)', '', NULL, 'Notwithstanding anything contained in sub -section (1),
nothing shall bar a person who has gained knowledge on medical
treatment from a long experience from administering, with due care,
such drug of general nature to a patient suffering from a minor
disease as not causing any specific adverse impact on any human
organ of such patient, or conducting medical treatment by
conducting operation of a minor wound, ecthyma.', 0, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.0', 3, 'clause', '(3)', '', NULL, 'A person who com mits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three years and a fine not
exceeding thirty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.0', 3, 'clause', '(4)', '', NULL, 'The offender shall be liable to the sentence of
imprisonment for life where any act of providing medical service,
conducting surgery or administering drug in contravention of sub -
section (1) causes the death of any person, and to a sentence of
imprisonment for a term not exceeding fifteen years wher e such act
causes grievous hurt.', 2, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22', 2, 'rule', '231', 'Prohibition of conducting medical treatment maliciously', 'Prohibition of conducting medical treatment maliciously', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-19 (Prohibition of conducting medical treatment maliciously)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.1', 3, 'clause', '(1)', '', NULL, 'No
person shall, with the intention of causing death of, or grievous hurt
to, another person, carry out his or her treatment, conduct one type of
medical treatment of him or her instead of another type of treatment
as required, or administer, or prescribe for administration of, any
drug to him or her knowingly or having reason to believe that the
administration or prescription of such drug may cause death of , or
grievous hurt, to him or her or conduct surgery on one organ of
human body of him or her instead of another organ as required or
make such organ dysfunctional or separate such organ from the
human body, or cause the commission of any of such acts.', 0, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.1', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to the following
sentence:
(a) The same sentence as imposable for murder, in the case
of causing the death of any person,
(a) The same sentence as imp osable for grievous hurt, in
the case of causing grievous heart to any person.', 1, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22', 2, 'rule', '232', 'Prohibition of conducting medical treatment by recklessness or', 'Prohibition of conducting medical treatment by recklessness or', 'negligence: (1) No person authorized under law to conduct medical
treatment shall, in conducting medical trea tment of any one, conduct
such treatment, administer any drug or prescribe for the
administration of drug to him or her in a reckless or negligent
manner, without taking adequate care or precaution.', 2, 'The National Penal (Code) Act, 2017, Chapter-19 (Prohibition of conducting medical treatment by recklessness or)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.2', 3, 'clause', '(2)', '', NULL, 'Where any act referred to in sub -section (1) causes
death of or grievous hurt to any one, the offender shall be liable to a
sentence of imprisonment for a term not exceeding five years and a
fine not exceeding fifty thousand rupees if the death or grievous hurt
has been caused from a reckless act and to a se ntence of
imprisonment for a term not exceeding three years and a fine not
exceeding thirty thousand rupees if the death or grievous hurt has
been caused from a negligent act.', 0, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22', 2, 'rule', '233', 'Prohibition of carrying out experiment on human body without', 'Prohibition of carrying out experiment on human body without', 'consent: (1) N o person authorized under law to conduct medical
treatment shall, in carrying out an experiment of any method relating
to medical treatment, surgery or drug on the human body, carry out
such experiment, without obtaining consent of the concerned person ,
and, in the case of a child or person of unsound mind, without
obtaining consent of his or her father, mother or guardian, and
without giving information thereof to such person, father, mother or
guardian.', 3, 'The National Penal (Code) Act, 2017, Chapter-19 (Prohibition of carrying out experiment on human body without)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.3', 3, 'clause', '(2)', '', NULL, 'Any experiment referred to in sub -section (1) shall be
carried out carefully, having regard to, inter alia, the possible effects
of such method, surgery or drug on human body.', 0, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.3.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.3', 3, 'clause', '(3)', '', NULL, 'No person shall carry out physical examination of or
alter any organ of any one, or cause the commission of such act, with
intention to get any undue economic benefit or to breach the privacy
of a woman or with any other intention.', 1, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.3.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.3', 3, 'clause', '(4)', '', NULL, 'A person who carries out, or causes to be carried out,
any experiment in contravention of sub-section (1), (2) or (3) shall be
liable to a s entence of imprisonment for a term not exceeding three
years and a fine not exceeding thirty thousand rupees.', 2, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.3.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.3', 3, 'clause', '(5)', '', NULL, 'The offender shall be liable to the same sentence as
imposable for murder if the offence referred to in sub-section (1), (2)
or (3) causes th e death of any one and to the same sentence as
imposable for grievous hurt if such offence causes grievous hurt to
any one.', 3, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22', 2, 'rule', '234', 'Prohibition of selling dangerous drug', 'Prohibition of selling dangerous drug', NULL, 4, 'The National Penal (Code) Act, 2017, Chapter-19 (Prohibition of selling dangerous drug)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.4', 3, 'clause', '(1)', '', NULL, 'No person authorized to
sell medicines as per law shall, without prescription of th e person
authorized under law to carry out treatment as per law, sell or
distribute any narcotic, toxic or dangerous drug that may cause
serious impact on human body.', 0, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.4.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.4', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed , the
offence referred to in sub -section (1) shall be liable to a sentence of
imprisonment for a term not exceeding two years or a fine not
exceeding twenty thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22', 2, 'rule', '235', 'Prohibition of adulteration of drugs or sale of adulterated drugs', 'Prohibition of adulteration of drugs or sale of adulterated drugs', NULL, 5, 'The National Penal (Code) Act, 2017, Chapter-19 (Prohibition of adulteration of drugs or sale of adulterated drugs)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.5.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.5', 3, 'clause', '(1)', '', NULL, 'No person shall knowin gly adulterate any drug in such a manner
as to void or lessen or change the efficacy of such drug or make it
noxious or sell such adulterated drug or any other thing saying that it
is a drug or issue such drug or thing to any one for treatment or
administer, or cause to be administered, such drug to any one.', 0, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.5.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.5', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to the following sentence:
(a) The same sentence as imposable for murder, in
the case of death caused from the consu mption of
such drug,
(b) The same sentence as imposable for attempted
murder, in the case of danger or likelihood of
danger to cause death caused from the
consumption of such drug,
(c) A sentence of imprisonment for a term not
exceeding ten years and a fin e not exceeding one
hundred thousand rupees, in the case of any
grievous hurt or deterioration or deprivation of
power of any organ of the body caused from the
consumption of such drug,
(d) A sentence of imprisonment for a term not
exceeding five years and a f ine not exceeding
fifty thousand rupees in cases other than that
referred to in clause (a), (b), or (c).', 1, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22', 2, 'rule', '236', 'Prohibition of selling, distributing date-expired drugs or without', 'Prohibition of selling, distributing date-expired drugs or without', 'taking precaution: (1) No person shall sell any drug required to be
used within a certain time period after the expiry of such date or sell,
distribute any drug without taking any specific precaution if such
precaution must be taken in the sale or distribution of such drug.', 6, 'The National Penal (Code) Act, 2017, Chapter-19 (Prohibition of selling, distributing date-expired drugs or without)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.6.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.6', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding one year and a fine not
exceeding ten thousand rupees.', 0, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22', 2, 'rule', '237', 'Prohibition of selling, distributing of drug as a different drug', 'Prohibition of selling, distributing of drug as a different drug', NULL, 7, 'The National Penal (Code) Act, 2017, Chapter-19 (Prohibition of selling, distributing of drug as a different drug)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.7.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.7', 3, 'clause', '(1)', '', NULL, 'No person authorize d to sell or distribute any drug under law
shall, while so selling or distributing the drug, sell or distribute a
drug of one type as a drug of another type knowingly or having
reasonable reason to know that such drug is materially a different
type of drug.', 0, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.7.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.7', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding two years or a fine not
exceeding twenty thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.8', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22', 2, 'rule', '238', 'Prohibition of giving false report', 'Prohibition of giving false report', NULL, 8, 'The National Penal (Code) Act, 2017, Chapter-19 (Prohibition of giving false report)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.8.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.8', 3, 'clause', '(1)', '', NULL, 'No person licensed under
law to conduct a pathological test of human blood, urine, sputum etc.
shall give a fake or false report while conducting such test or give a
report stating the facts different than that found from the test.', 0, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.8.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.8', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three years and a fine not
exceeding thirty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.8.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.8', 3, 'clause', '(3)', '', NULL, 'Where the consumption of any drug prescribed to,
conduction of a surgery on, or treatment of, a person on the basis of
the report referred to in sub -section (1) causes the death of or any
grievous hurt to such person, the person giving such report shall be
deemed to be the offender.', 2, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.8.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.8', 3, 'clause', '(4)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (3) shall be liable to the same
sentence as imposable for murder, in the case of causing death of,
and to the same sentence as imposable for griev ous hurt, in the case
of causing grievous heart to, any person.', 3, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.9', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22', 2, 'rule', '239', 'Compensation to be paid', 'Compensation to be paid', NULL, 9, 'The National Penal (Code) Act, 2017, Chapter-19 (Compensation to be paid)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.9.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.9', 3, 'clause', '(1)', '', NULL, 'Where the death of, or grievous hurt
to, or other harm, injury or damage to, any person is caused from the
commission of an y offence referred to in this Chapt er, reasonable
compensation shall be ordered to be paid by the offender to the
concerned victim and to his or her successor if the victim is dead.', 0, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.10', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22', 2, 'rule', '240', 'Statute of limitation', 'Statute of limitation', NULL, 10, 'The National Penal (Code) Act, 2017, Chapter-19 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.10.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.10', 3, 'clause', '(1)', '', NULL, 'There shall be no statute of limitation for
filing a complaint if death is ca used from any of the acts referred to
in sub -section (4) of Section 230, Section 231, Section 232, sub -
section (4) of Section 233, Section 235, and sub -section (4) of
Section 238.', 0, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:22.10.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:22.10', 3, 'clause', '(2)', '', NULL, 'No complaint shall lie after one year from the date of
knowledge of commission of the offence under sub -section (1) of
Section 230, and after six months from the date of commission of
any of the other offences under this Chapter.', 1, 'The National Penal (Code) Act, 2017, Chapter-19, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-20', '', NULL, 'Offences Relating to Theft and Robbery', 23, 'The National Penal (Code) Act, 2017, Chapter-20', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23', 2, 'rule', '241', 'Prohibition of theft', 'Prohibition of theft', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-20 (Prohibition of theft)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23.0', 3, 'clause', '(1)', '', NULL, 'No perso n shall commit, or cause to be
committed, theft.', 0, 'The National Penal (Code) Act, 2017, Chapter-20, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23.0', 3, 'clause', '(2)', '', NULL, 'For the purposes of sub -section (1), a person who
dishonestly takes any property under the ownership, possession,
control or custody of another person out of such ownership,
possession, control or custod y or moves such property without that
other person''s consent, with the intention of owning, using or
enjoying it, shall be considered to commit theft.
Explanation: For the purposes of this Section,-
(a) The term "c onsent" means the consent given in writing
or orally or expressed by conduct.
(b) Consent by a child who has not attained eighteen years
of age or a person of unsound mind shall not be
considered to be consent.', 1, 'The National Penal (Code) Act, 2017, Chapter-20, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23', 2, 'rule', '242', 'Punishment for theft', 'Punishment for theft', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-20 (Punishment for theft)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23.1', 3, 'clause', '(1)', '', NULL, 'A person who commits, or causes to be
committed, theft in any of the following circumstances shall be liable
to a sentence of imprisonment from a term of two to seven years and
a fine of twenty thousand to seventy thousand rupees:
(a) In the case of theft of any government or public
property or property of any religious place or temple,
(b) In the case of theft of any property, upon administering
liquor or narcotics to, or otherwise making unconscious,
any person,
(c) In the case of theft of any property, upon taking
advantage of earthquake, fire, flood, riot or similar other
situation of crisis or any accident,
(d) In the case of theft of any property of the office or
person whose service one is engaged in,
(e) In the case of theft on a vehicle used for the conveyance
of human persons or goods.', 0, 'The National Penal (Code) Act, 2017, Chapter-20, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23.1', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, theft
in any circumstance other than that referred to in sub -section (1)
shall be liable to a sentence of imprisonment for a term not
exceeding three years and a fine not exceeding thirty thousand
rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-20, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23', 2, 'rule', '243', 'Prohibition of burglary (Nakabajani)', 'Prohibition of burglary (Nakabajani)', NULL, 2, 'The National Penal (Code) Act, 2017, Chapter-20 (Prohibition of burglary (Nakabajani))', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23.2', 3, 'clause', '(1)', '', NULL, 'No person shall commit,
or cause to be committed, burglary.', 0, 'The National Penal (Code) Act, 2017, Chapter-20, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.2.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23.2', 3, 'clause', '(2)', '', NULL, 'For the purposes of sub -section (1), a person shall be
considered to commit burglary if he or she commits theft in a house
by entering into the house by bre aking its main gate or by using any
passage, place, method or means other than the main gate, or after
committing theft, he or she quits, or attempts to quit, by breaking its
main gate or by using any passage, place, method or means other
than the main gate.', 1, 'The National Penal (Code) Act, 2017, Chapter-20, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.2.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23.2', 3, 'clause', '(3)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term of
three to five years and a fine of thirty thousand to fifty thousand
rupees.', 2, 'The National Penal (Code) Act, 2017, Chapter-20, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23', 2, 'rule', '244', 'Prohibition of robbery', 'Prohibition of robbery', NULL, 3, 'The National Penal (Code) Act, 2017, Chapter-20 (Prohibition of robbery)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23.3', 3, 'clause', '(1)', '', NULL, 'No person shall commit, or cause to be
committed, robbery.', 0, 'The National Penal (Code) Act, 2017, Chapter-20, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.3.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23.3', 3, 'clause', '(2)', '', NULL, 'A person shall be deemed to commit robbery if he or
she:
(a) causes or attempts to cause to any person death or hurt
or restraint or obstruction or fear or intimidation of
instant death or of instant hurt, in order to the
committing of theft or in committing the theft or in
carrying away property obtained by the theft or to the
escaping of arrest after the commission of the theft or
commits theft carrying a deadly weapon,
(b) obtains any money or economic ben efit through
criminal extortion by putting any person in fear of
instant death or of instant or of instant restraint,
(c) commits theft by waiting near or on way, road, lonely
place or forest or show of fear or intimidation , using or
threatening to use a deadly weapon,
(d) commits theft in a group of three or more persons.', 1, 'The National Penal (Code) Act, 2017, Chapter-20, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.3.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23.3', 3, 'clause', '(3)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to the following sentence:
(a) A sentence of imprisonment for a term of seven to
fourteen years and a fine of seventy thousand to one
hundred forty thousand rupees, in the case of the
offence referred to in clause (a) or (b) of sub-section (2),
(b) A sentence of imprisonment for a term of five to ten
years and a fine of fifty thousand to one hundred
thousand rupees, in the case of the offence referred to in
clause (c) or (d) of sub-section (2).', 2, 'The National Penal (Code) Act, 2017, Chapter-20, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23', 2, 'rule', '245', 'Prohibition of movement carrying tools to be used in commission', 'Prohibition of movement carrying tools to be used in commission', 'of theft: (1) No person shall, with the intention of committing theft
or robbery, move around or enter into or attempt to enter into the
house of any person carrying instruments such as any tool, object ,
arms, duplicate key, gloves and ladder that may be used in the
commission of theft or robbery.', 4, 'The National Penal (Code) Act, 2017, Chapter-20 (Prohibition of movement carrying tools to be used in commission)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23.4', 3, 'clause', '(2)', '', NULL, 'A person who so moves, enters into or attempts to enter
into as referred to in sub -section (1) shall, unless otherwise proved,
be considered to have moved, entered into or attempted to enter into,
with the intention of committing theft.', 0, 'The National Penal (Code) Act, 2017, Chapter-20, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.4.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23.4', 3, 'clause', '(3)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding one year or a fine not
exceeding ten thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-20, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23', 2, 'rule', '246', 'Prohibition of pickpocketing', 'Prohibition of pickpocketing', '( 1) No person shall commit, or
cause to be committed, pickpocketing.', 5, 'The National Penal (Code) Act, 2017, Chapter-20 (Prohibition of pickpocketing)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.5.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23.5', 3, 'clause', '(2)', '', NULL, 'For the purposes of sub -section (1), a person who steals
cash or property from the pocket of another person who is walking
on foot, traveling on a vehicle or staying in a public place or from his
or her accompanying purse, bag or means of any other kind, with or
without notice of such other person, shall be considered to commit
pickpocketing.
Provided that where a person pick -pockets a cash amount of
more than ten thousand rupees or property valued at more than ten
thousand rupees, the person shall be considered to commit the
offence referred to in Section 241.', 0, 'The National Penal (Code) Act, 2017, Chapter-20, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.5.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23.5', 3, 'clause', '(3)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to the following sentence:
(a) A sentence of imprisonment for a term not exceedi ng
one month or a fine equal to the claimed amount or both
the sentences, in the case of the commission of
pickpocketing for the first time,
(b) A sentence of imprisonment for a term not exceeding
two months or a fine equal to the claimed amount or
both the sentences, for each instance from the second
time onwards.', 1, 'The National Penal (Code) Act, 2017, Chapter-20, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23', 2, 'rule', '247', 'Claimed a mount to be recovered', 'Claimed a mount to be recovered', 'The claimed amount, if any,
involved in the offence referred to in this Chapter shall be forfeited
from the offender of such offence and paid to the owner of that
property. If the offender has already spent the property formed of the
claimed amount, property equal to the value of claimed amount shall
be ordered to be paid to the owner.', 6, 'The National Penal (Code) Act, 2017, Chapter-20 (Claimed a mount to be recovered)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:23.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:23', 2, 'rule', '248', 'Statute of limitation', 'Statute of limitation', 'No complaint shall lie after the expiry of three
months from the date of commission of the offence in the case of any
of the offences under Sections 245 and 246 and after six months
from the date of knowledge of commission of the offence in the case
of any of the other offences under this Chapter.', 7, 'The National Penal (Code) Act, 2017, Chapter-20 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-21', '', NULL, 'Offences Relating to Cheating, Criminal Breach of Trust and
Extortion', 24, 'The National Penal (Code) Act, 2017, Chapter-21', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24', 2, 'rule', '249', 'Prohibition of cheating', 'Prohibition of cheating', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-21 (Prohibition of cheating)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24.0', 3, 'clause', '(1)', '', NULL, 'No person shall commit, or cause to be
committed, cheating.', 0, 'The National Penal (Code) Act, 2017, Chapter-21, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24.0', 3, 'clause', '(2)', '', NULL, 'For the purposes of sub -section (1), a person who
dishonestly causes any kind of loss, damage or injury to another
person whom he or she makes believe in some matter or to any other
person or obtains any benefit for him or her or any one else by
omitting to do as per such belief or by inducement, fraudulent,
dishonest or otherwise deceptive act or preventing such other person
from doing any act shall be considered to commit cheating.
Explanation: Where the victim of cheating has got a deed
executed by the cheater, the deed shall apply to that matter.', 1, 'The National Penal (Code) Act, 2017, Chapter-21, Clause (2)', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_national_penal_code_2074_2017:24.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24.0', 3, 'clause', '(3)', '', NULL, 'A person who commits the off ence referred to in sub-
section (1) shall be liable to the following sentence:
(a) A sentence of imprisonment for a term not exceeding
ten years and a fine not exceeding one hundred
thousand rupees, in the case of cheating the Government
of Nepal or any bo dy under full or majority ownership
or control of the Government of Nepal, except in cases
of corruption,
(b) A sentence of imprisonment for a term not exceeding
five years and a fine not exceeding fifty thousand
rupees, in the case of cheating by lying on e''s name,
designation, title, qualification,
(c) A sentence of imprisonment for a term not exceeding
seven years and a fine not exceeding seventy thousand
rupees in the cases of any kind of cheating other than
that referred to in clause (a) or (b).', 2, 'The National Penal (Code) Act, 2017, Chapter-21, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.0.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24.0', 3, 'clause', '(4)', '', NULL, 'A sentence of imprisonment for a term not exceeding
one year, in addition to the sentence set forth in sub-section (3), shall
be imposed in the case of cheating a child, person of unsound mind,
helpless, illiterate or person above seventy-five years of age.', 3, 'The National Penal (Code) Act, 2017, Chapter-21, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24', 2, 'rule', '250', 'Prohibition of causing difference in bid or contract', 'Prohibition of causing difference in bid or contract', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-21 (Prohibition of causing difference in bid or contract)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24.1', 3, 'clause', '(1)', '', NULL, 'No
person who has undertaken the responsibility of carrying out any
construction related work or other work or other person who acts on
his or her behalf shall, with dishonest intent, carry out, or cause to be
carried out, the construction or other work, by not using the materials
of the specified standards or quality or by altering the quantity of the
materials to be used or otherwise using materials not conforming to
the specified quality.', 0, 'The National Penal (Code) Act, 2017, Chapter-21, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24.1', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (3) shall be liable to a sentence of imprisonment for a term
not exceeding ten years and a fine not exceeding one hundred
thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-21, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.1.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24.1', 3, 'clause', '(3)', '', NULL, 'No person who has undertaken the responsibility of
supplying any materials, goods or services or other person who acts
on his or her behalf shall, with dishonest intent, supply materials,
goods or services falling short of the quality or quantity or otherwise
provide materials, goods or services not confor ming to the specified
quality.', 2, 'The National Penal (Code) Act, 2017, Chapter-21, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.1.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24.1', 3, 'clause', '(4)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (3) shall be liable to a sentence of
imprisonment for a term not exceeding five years and a fine not
exceeding fifty thousand rupees.', 3, 'The National Penal (Code) Act, 2017, Chapter-21, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24', 2, 'rule', '251', 'Prohibition of criminal misappropriation of property', 'Prohibition of criminal misappropriation of property', NULL, 2, 'The National Penal (Code) Act, 2017, Chapter-21 (Prohibition of criminal misappropriation of property)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24.2', 3, 'clause', '(1)', '', NULL, 'No
person shall make, or cause to be made, criminal misappropriation of
property.', 0, 'The National Penal (Code) Act, 2017, Chapter-21, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.2.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24.2', 3, 'clause', '(2)', '', NULL, 'For the purposes of sub -section (1), a person who does
any of the following acts shall be considered to commit criminal
misappropriation of property:
(a) To dishonestly possess and use, cause loss and damage
to or misappropriate a property belonging to another
person or rent, sell or dispose it witho ut consent of that
other person.
Provided that if the real owner of an adjoining
land uses the property belonging to another person, by
mistakenly making normal encroachment of the
boundary, he or she shall not be considered to commit
the offence referred to in this clause.
(b) To dishonestly appropriate or otherwise co nvert any
property not in the possession of any other person to his
or her own use, knowing or having the means of
discovering the owner of such property, or without
returning such property to such owner within a
reasonable time, or without giving notice to the owner to
claim the property or without waiting the owner of such
property until a reasonable time.
Provided that where the finder in good faith
appropriates a property to his or her own use when the
owner of the property is not discovered despite
reasonable efforts or the owner does not claim the
property within a reasonable time after the giving of
notice, he or she shall not be considered to commit the
offence referred to in this Section.', 1, 'The National Penal (Code) Act, 2017, Chapter-21, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.2.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24.2', 3, 'clause', '(3)', '', NULL, 'A person who commits , or causes to be committed, the
offence referred to in sub section (1) shall be liable to the following
sentence:
(a) A sentence of imprisonment for a term not exceeding
three years or a fine not exceeding thirty t housand
rupees or both the sentences, in the case of criminal
misappropriation of property which was in the
possession of a deceased person at the time of that
person''s demise and has not since been in the possession
of his or her legal successor , or criminal
misappropriation of property belonging t o a child, a
person of unsound mind due to mental or physical
illness, or a person above seventy-five years of age,
(b) A sentence of imprisonment for a term not exceeding
one year or a fine not exceeding ten t housand rupees or
both the sentences, in the case of criminal
misappropriation of property in cases other than that set
forth in clause (a).', 2, 'The National Penal (Code) Act, 2017, Chapter-21, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.2.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24.2', 3, 'clause', '(4)', '', NULL, 'If any property subjected to criminal misappropriation
under this Section is in a returnable condition, the person who so
misappropriates shall return the property to the concerned owner o r
to his or her immediate successor if the owner is dead.', 3, 'The National Penal (Code) Act, 2017, Chapter-21, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24', 2, 'rule', '252', 'Prohibition of criminal breach of trust', 'Prohibition of criminal breach of trust', NULL, 3, 'The National Penal (Code) Act, 2017, Chapter-21 (Prohibition of criminal breach of trust)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24.3', 3, 'clause', '(1)', '', NULL, 'No person shall
commit, or cause to be committed, criminal breach of trust.', 0, 'The National Penal (Code) Act, 2017, Chapter-21, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.3.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24.3', 3, 'clause', '(2)', '', NULL, 'For the purposes of sub -section (1), a person who does
any of the following acts shall be considered to commit, or cause the
commission of, criminal breach of trust:
(a) To dishonestly appropriate or otherwise convert to his
or her own use other''s property which is under his or her
custody or protection or to dishonestly a ppropriate such
property in his or her own use, or allow such property to
be used by, or dispose, or cause the disposal, of such
property to, another person, in violation of any contract,
deed of conditions or law concerning the use of such
property,
(b) To cause any loss, damage or injury by a person, who is
entrusted with responsibility or has lawful duty of doing
any work or transaction of another person or who acts as
an agent of another in relation to any work or
transaction, to that other person by do ing any act in
violation of his or her duty with the intention of causing
benefit to himself or herself or any one else.', 1, 'The National Penal (Code) Act, 2017, Chapter-21, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.3.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24.3', 3, 'clause', '(3)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to the following
sentence:
(a) A sentence of imprisonment for a term not exceeding
five years and a fine not exceeding fifty thousand
rupees, in the case of the commission of criminal breach
of trust by a person in the capacity of manager, director,
employee or agent of any or ganization or by a person
entrusted with the responsibility of carrying a property
from one place to another or keeping it safely in a
warehouse or any other place or with a legal duty to do
so,
(b) A sentence of imprisonment for a term not exceeding
three years or a fine not exceedin g thirty thousand
rupees or both the sentences, in the case of the
commission of criminal breach of trust by any person
other than that set forth in clause (a).', 2, 'The National Penal (Code) Act, 2017, Chapter-21, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24', 2, 'rule', '253', 'Prohibition of extortion', 'Prohibition of extortion', NULL, 4, 'The National Penal (Code) Act, 2017, Chapter-21 (Prohibition of extortion)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24.4', 3, 'clause', '(1)', '', NULL, 'No person shall commit, or cause to be
committed, extortion.', 0, 'The National Penal (Code) Act, 2017, Chapter-21, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.4.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24.4', 3, 'clause', '(2)', '', NULL, 'For the purposes of sub -section (1), a person who puts
any person in fear or terror of any injury to that person or to any
other person and dishonestly takes any benefit from that person for
himself or herself or any other person or induces that person to do, or
prevents that person from doing, any act with the intention of taking
such benefit shall be considered to commit extortion.', 1, 'The National Penal (Code) Act, 2017, Chapter-21, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.4.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24.4', 3, 'clause', '(3)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to the following sentence:
(a) A sentence of imprisonment for a term not exceeding
seven years and a fine not exceeding seventy thousand
rupees, in the case of putting a person in fear or terror of
death, grievous hurt or serious injury, with the intention
of committing extortion,
(b) A sentence of imprisonment for a term not exceeding
three years and a fine not exceeding thirty thousand
rupees, in the case of commission of extortion by
showing fear or terror with the intention of causing any
damage to any other person''s business or making a false
accusation in respect of such person''s character,
(c) A sentence of imprisonment for a term not exceeding
one year or a fine not exceeding ten thousand rupees or
both the sentences, in the case of the commission of
extortion in cases other than that set forth in clause (a)
or (b).', 2, 'The National Penal (Code) Act, 2017, Chapter-21, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24', 2, 'rule', '254', 'Compensation', 'Compensation', 'Where any injury or damage is caused to any
person from the commission of the offence referred to in this
Chapter, the claimed amount, if set out, and a reasonable
compensation, if the claimed amount is not set out, shall be ordered
to be paid by the offender to the victim.', 5, 'The National Penal (Code) Act, 2017, Chapter-21 (Compensation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:24.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:24', 2, 'rule', '255', 'Statute of limitation', 'Statute of limitation', 'No complaint shall lie after the expiry of one
year from the date of knowledge of commission of any offence under
this Chapter.', 6, 'The National Penal (Code) Act, 2017, Chapter-21 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-22', '', NULL, 'Offences Relating to Currency', 25, 'The National Penal (Code) Act, 2017, Chapter-22', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25', 2, 'rule', '256', 'Prohibition of counterfeiting currency', 'Prohibition of counterfeiting currency', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-22 (Prohibition of counterfeiting currency)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25.0', 3, 'clause', '(1)', '', NULL, 'No person shall
counterfeit, or attempt to counterfeit, any currency.', 0, 'The National Penal (Code) Act, 2017, Chapter-22, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25.0', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term of five to ten years and a fine of fifty
thousand to one hundred thousand rupees, having regard to the
quantity and value of the currency counterfeited.
Explanation: For the purpose of this Chapter,-
(a) “currency” means any kind of currency note, postal
order, postal note, money order, cheque, draft, traveler''s
cheque, letter of credit, letter of exchange, bond and
credit card , and this term also includes such other
similar kind of monetary instrument as specified by the
Bank, as required, by publishing and circulating a
public notice.
(b) "counterfeit currency" means a currency which is so
forged in an unauthorized manner or counterfeit as
resembling or having reason to believe it to be a
currency issued by the Government of Nepal or Nepal
Rastra Bank or foreign government or competent
foreign body.', 1, 'The National Penal (Code) Act, 2017, Chapter-22, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25', 2, 'rule', '257', 'Prohibition of using counterfeit currency', 'Prohibition of using counterfeit currency', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-22 (Prohibition of using counterfeit currency)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25.1', 3, 'clause', '(1)', '', NULL, 'No person shall,
with the intention of using as genuine, purchase, sell, export, import,
transact, or use as genuine, any counterfeit currency or attempt to do
such act or possess such currency.', 0, 'The National Penal (Code) Act, 2017, Chapter-22, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25.1', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding seven years and a fine not exceeding seventy thousand
rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-22, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25', 2, 'rule', '258', 'Prohibition of making, possessing or repairing instruments for', 'Prohibition of making, possessing or repairing instruments for', 'counterfeiting currency: (1) No person shall make, repair,
purchase, sell, give, take, export, import or possess any instrument or
other material knowing that or having a reasonable reason to believe
that it is intended to be used in or for forging or counterfeiting
currency.', 2, 'The National Penal (Code) Act, 2017, Chapter-22 (Prohibition of making, possessing or repairing instruments for)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25.2', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding seven years and a fine not
exceeding seventy thousand rupees.', 0, 'The National Penal (Code) Act, 2017, Chapter-22, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25', 2, 'rule', '259', 'Prohibition of making currency contrary to standards', 'Prohibition of making currency contrary to standards', NULL, 3, 'The National Penal (Code) Act, 2017, Chapter-22 (Prohibition of making currency contrary to standards)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25.3', 3, 'clause', '(1)', '', NULL, 'No
authority or person entrusted by the law in force to make currency
shall know ingly make currency in contravention of the standards
specified by law, make currency in violation of the terms and
restrictions applicable to the making of currency, make currency in
excess of the quantity specified or do any act with the intention of
making currency with such deviation or cause benefit to himself or
herself or any other person from such act or facilitate such act.', 0, 'The National Penal (Code) Act, 2017, Chapter-22, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.3.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25.3', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding seven years and a fine not
exceeding seventy thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-22, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25', 2, 'rule', '260', 'Prohibition of taking outside currency making instruments', 'Prohibition of taking outside currency making instruments', NULL, 4, 'The National Penal (Code) Act, 2017, Chapter-22 (Prohibition of taking outside currency making instruments)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25.4', 3, 'clause', '(1)', '', NULL, 'No person shall, except with the order of the competent authority
under law, take any currency making machinery, equipment or other
instrument out of the place where currency is made.', 0, 'The National Penal (Code) Act, 2017, Chapter-22, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.4.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25.4', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding five years and a fine not
exceeding fifty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-22, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25', 2, 'rule', '261', 'Prohibition of diminishing weight or altering form of currency', 'Prohibition of diminishing weight or altering form of currency', NULL, 5, 'The National Penal (Code) Act, 2017, Chapter-22 (Prohibition of diminishing weight or altering form of currency)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.5.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25.5', 3, 'clause', '(1)', '', NULL, 'No person shall diminish the weight of metallic currency or alter
the composition of metallic element or export, i mport or possess
currency, by causing the currency of one type to appear like the
currency of another type, with the intention of using it as genuine or
knowing that it may be used as genuine.', 0, 'The National Penal (Code) Act, 2017, Chapter-22, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.5.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25.5', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding five years and a fine not
exceeding fifty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-22, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25', 2, 'rule', '262', 'Prohibition of bringing prohibited currency into use', 'Prohibition of bringing prohibited currency into use', NULL, 6, 'The National Penal (Code) Act, 2017, Chapter-22 (Prohibition of bringing prohibited currency into use)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.6.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25.6', 3, 'clause', '(1)', '', NULL, 'No
person shall bring into use, exchange or possess a currency in use but
circulation of which has been banned by order of the competent
authority under law, in violation of such order.', 0, 'The National Penal (Code) Act, 2017, Chapter-22, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.6.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25.6', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding one year or a fine not
exceeding ten thousand rupees or both the sentences, and the
currency so brought into use, exchanged or possessed shall also be
forfeited.', 1, 'The National Penal (Code) Act, 2017, Chapter-22, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25', 2, 'rule', '263', 'Prohibition of burning , tearing, melting bank notes or coins or', 'Prohibition of burning , tearing, melting bank notes or coins or', 'writing on bank notes: (1) No person shall, except with the order of
the competent authority, burn a coin or bank note tendered as
currency or so melt or tear it that it is incapable of being used.', 7, 'The National Penal (Code) Act, 2017, Chapter-22 (Prohibition of burning , tearing, melting bank notes or coins or)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.7.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25.7', 3, 'clause', '(2)', '', NULL, 'No person shall write on or cross off bank notes.', 0, 'The National Penal (Code) Act, 2017, Chapter-22, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.7.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25.7', 3, 'clause', '(3)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) or (2) shall be liable to a
sentence of imprisonment for a term not exceeding three months and
a fine not exceeding five thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-22, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.8', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25', 2, 'rule', '264', 'Prohibition of misusing torn bank notes', 'Prohibition of misusing torn bank notes', NULL, 8, 'The National Penal (Code) Act, 2017, Chapter-22 (Prohibition of misusing torn bank notes)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.8.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25.8', 3, 'clause', '(1)', '', NULL, 'No person who is
entrusted by order of the competent authority under law with a duty
of burning or disposing off the torn notes held to be burnt or
disposed of because such bank notes tender ed as currency are worn
and torn or letters, signs or sizes are unrecognizable or such notes
cannot be brought in to use for any other reason shall bring in to use
such bank notes or refrain from burning or disposing of such notes or
give them to another person dishonestly intending to obtain any kind
of benefit therefrom.', 0, 'The National Penal (Code) Act, 2017, Chapter-22, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.8.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25.8', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three years and a fin e not
exceeding thirty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-22, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.9', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25', 2, 'rule', '265', 'Forfeiture', 'Forfeiture', 'The currency, machine, equipment or tools used in, and
materials related to, the commission of any offence under this
Chapter shall be forfeited', 9, 'The National Penal (Code) Act, 2017, Chapter-22 (Forfeiture)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:25.10', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:25', 2, 'rule', '266', 'Statute of limitation', 'Statute of limitation', 'No complaint shall lie af ter the expiry of one
year from the date of knowledge of commission of any offence under
this Chapter.', 10, 'The National Penal (Code) Act, 2017, Chapter-22 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:26', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-23', '', NULL, 'Offences Relating to Stamps', 26, 'The National Penal (Code) Act, 2017, Chapter-23', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:26.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:26', 2, 'rule', '267', 'Prohibition of counterfeiting stamps or using counterfeit stamps', 'Prohibition of counterfeiting stamps or using counterfeit stamps', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-23 (Prohibition of counterfeiting stamps or using counterfeit stamps)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:26.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:26.0', 3, 'clause', '(1)', '', NULL, 'No person shall, with the intention of using as genuine,
counterfeit, attempt to counterfeit a stamp, purchase, sell, exchange,
export or import a counterfeit stamp, or use or attempt to use as
genuine, or possess, such stamp.
Explanation: For the purposes of this Chapter,-
(a) "stamp" means a postal stamp or other revenue stamp
to be affixed to a document , and this term also includes
the sign of a stamp affixed to or printed on an envelope,
post letter or any other object or a sticker to be used for
the purpose of stamp.
(b) "counterfeit stam p" means a forged stamp made in an
unauthorized manner so that it resembles a stamp
referred to in clause (a) , and this term also includes a
stamp that has once been used.', 0, 'The National Penal (Code) Act, 2017, Chapter-23, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:26.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:26.0', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding five years and a fine not
exceeding fifty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-23, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:26.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:26', 2, 'rule', '268', 'Prohibition of purchasing, selling, repairing instruments for', 'Prohibition of purchasing, selling, repairing instruments for', 'counterfeiting stamps: (1) No person shall make , repair, purchase,
sell, exchange, possess any machinery or other instrument knowing
or having reasonable ground to believe that it is intended to be used
for the purpose of counterfeiting any stamp.', 1, 'The National Penal (Code) Act, 2017, Chapter-23 (Prohibition of purchasing, selling, repairing instruments for)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:26.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:26.1', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding five years and a fine not
exceeding fifty thousand rupees.', 0, 'The National Penal (Code) Act, 2017, Chapter-23, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:26.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:26', 2, 'rule', '269', 'Prohibition of re -using stamp used before', 'Prohibition of re -using stamp used before', NULL, 2, 'The National Penal (Code) Act, 2017, Chapter-23 (Prohibition of re -using stamp used before)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:26.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:26.2', 3, 'clause', '(1)', '', NULL, 'No person,
knowing that any stamp is a stamp already used before, shall re -use
as genuine such stamp or erase, efface or remove any seal or mark
put or impressed upon any stamp with the intention of using it as
genuine or attempt to do so.', 0, 'The National Penal (Code) Act, 2017, Chapter-23, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:26.2.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:26.2', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committ ed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding one year or a fine not
exceeding ten thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-23, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:26.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:26', 2, 'rule', '270', 'Prohibition of removing from public document stamp used f or', 'Prohibition of removing from public document stamp used f or', 'it: (1) No person shall remove, or attempt to remove, from a public
document a stamp which has been used for it.', 3, 'The National Penal (Code) Act, 2017, Chapter-23 (Prohibition of removing from public document stamp used f or)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:26.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:26.3', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding six months or a fine not
exceeding five thousand rupees or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-23, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:26.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:26', 2, 'rule', '271', 'Forfeiture', 'Forfeiture', 'Any stamp, t ool, instrument or other material related to
the commission of any offence referred to in this Chapter shall be
forfeited.', 4, 'The National Penal (Code) Act, 2017, Chapter-23 (Forfeiture)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:26.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:26', 2, 'rule', '272', 'Statute of limitation', 'Statute of limitation', 'No complaint shall lie after the expiry of one
year from the date of knowledge of commission of any offence under
this Chapter.', 5, 'The National Penal (Code) Act, 2017, Chapter-23 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:27', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-24', '', NULL, 'Offences Relating to Weights and Measures', 27, 'The National Penal (Code) Act, 2017, Chapter-24', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:27.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:27', 2, 'rule', '273', 'Prohibition of making or using fals e instrument for weighing', 'Prohibition of making or using fals e instrument for weighing', 'and measuring: (1) No person shall make, or cause to be made, any
instrument for weighing, measuring or determining quality standards
in a manner that it does not conform to the specified standards or
knowingly use as genuine any instrument so made for weighing,
measuring or determining quality standards or possess or sell such
instrument which is intended to be so used or make false seal or
mark to be affixed to such instrument or tamper the seal or mark
affixed to the instrument for weigh ing, measuring or determining
quality standards or manipulate, with the help of any other
instrument, the weighing, measuring or quality determining ability of
such instrument or affix a false seal or mark to such instrument or,
by way of any othe r means, make any weight or measure different
from the prevalent one.
Explanation: For the purposes of this Section, the term
"instrument for weigh ing, measuring or determining quality
standards" means an instrument in use under the law to measure or
determine the unit, quality or quantity of any good or service or
purity or standards of such good or service or unit of any thing.', 0, 'The National Penal (Code) Act, 2017, Chapter-24 (Prohibition of making or using fals e instrument for weighing)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:27.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:27.0', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three years and a fine not
exceeding thirty thousand rupees.', 0, 'The National Penal (Code) Act, 2017, Chapter-24, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:27.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:27.0', 3, 'clause', '(3)', '', NULL, 'Any instrument made or brought into use under sub -
section (1) and tool for maki ng or repairing such instrument shall
also be forfeited.', 1, 'The National Penal (Code) Act, 2017, Chapter-24, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:27.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:27', 2, 'rule', '274', 'Prohibition of fraudulent use of instrument for weigh ing,', 'Prohibition of fraudulent use of instrument for weigh ing,', 'measuring or determining quality standards: (1) In using the
instrument for weighing, measuring or determining quality standards
in the course of any business, transaction or trade, no person shall
fraudulently use such instrument in a manner to be different from the
weight, measure or standard specified for use or, with the help of any
other instrument or means, cause adverse effect to the weighing,
measuring or quality determination by such instrument as per t he
prevailing weights and measures.', 1, 'The National Penal (Code) Act, 2017, Chapter-24 (Prohibition of fraudulent use of instrument for weigh ing,)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:27.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:27.1', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three years and a fine not
exceeding thirty thousand rupees.', 0, 'The National Penal (Code) Act, 2017, Chapter-24, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:27.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:27', 2, 'rule', '275', 'Statute of limitation', 'Statute of limitation', 'No complaint shall lie in relation to any
offence under this Chapter after the expiry of three months from the
date of knowledge of commission of such offence.', 2, 'The National Penal (Code) Act, 2017, Chapter-24 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-25', '', NULL, 'Offences Relating to Documents', 28, 'The National Penal (Code) Act, 2017, Chapter-25', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28', 2, 'rule', '276', 'Prohibition of forgery', 'Prohibition of forgery', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-25 (Prohibition of forgery)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.0', 3, 'clause', '(1)', '', NULL, 'No person shall commit, or cause to be
committed, forgery.', 0, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.0', 3, 'clause', '(2)', '', NULL, 'For the purposes of sub-section (1), a person who makes
a false document or false electronic record or a part or portion of a
document or electronic record, with intent to caus e any harm, injury
or damage to the public or to any person or to render any benefit to
the person himself or herself or to any person shall be considered to
commit forgery.
Explanation: For the purposes of this Section,-
(a) "document" means signature, th umb impression,
seal affixed on any document and the figure,
word, date or any other content set forth in any
document.
(b) "making a false document" means any of the
following acts:', 1, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.0', 3, 'clause', '(1)', '', NULL, 'to dishonestly prepare a document or part
of a document, make or tran smit an
electronic record, archive digitals in an
electronic record, with the intention of
causing it to be believed that such
document was made, written, signed or
sealed by the person or authority who has
not actually made, written, signed or sealed
the document,', 2, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.0.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.0', 3, 'clause', '(2)', '', NULL, 'to, without lawful authority or dishonestly,
add or delete any content to or from, strike
out, change or otherwise alter or make
unclear any content of a document or
electronic record,', 3, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.0.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.0', 3, 'clause', '(3)', '', NULL, 'to cause any person to make, sign, seal, or
alter any content of, a document knowing
that such person by reason of being of
unsound mind due to mental illness or
intoxication of liquors or narcotics or by
reason of deception practiced on him or her
cannot know the meaning of any contents
set down in the document,', 4, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.0.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.0', 3, 'clause', '(4)', '', NULL, 'to prepare or use any envelope, paper
signed and delivered or any seal delivered
for a work or purpose other than that for
which such envelope, paper or seal was
signed, and delivered.', 5, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.0.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.0', 3, 'clause', '(3)', '', NULL, 'A person who commits the offence referred to in
sub-section (1) shall be liable to the following sentence:
(a) A sentence of imprisonment for a term not
exceeding ten years and a fine not exceeding one
hundred thousand rupees, in the case of forgery of
a document authenticated by the President,
(b) A sentence of imprisonment for a term not
exceeding eight years and a fine not exceeding
eighty thousand rupees, in the case of forgery of a
judgment or order of a court,
(c) A sentence of imprisonment for a term not
exceeding seven years and a fine not exceeding
seventy thousand rupees, in the case of forgery of
a government or public document other than that
referred to in clauses (a) and (b),
(d) A sentence of imprisonment for a term not
exceeding five years and a fine not exceeding
fifty thousand rupees, in the c ase of forgery of a
document other than that referred to in clauses
(a), (b) and (c).', 6, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.0.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.0', 3, 'clause', '(4)', '', NULL, 'A person who has already disposed of property which
he or she has obtained by committing forgery shall be liable to an
additional fine equal to the claimed amount, i n addition to the
sentence referred in sub-section (3).', 7, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.0.8', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.0', 3, 'clause', '(5)', '', NULL, 'Where a person obtains any property by committing
forgery, the person shall return such property to the concerned
owner; and in the event that such property has already been disposed
of, the claimed amount of such property shall be caused to be
recovered to the owner from any other property of the offender.', 8, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28', 2, 'rule', '277', 'Prohibition of possessing or using as genuine a forged document', 'Prohibition of possessing or using as genuine a forged document', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-25 (Prohibition of possessing or using as genuine a forged document)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.1', 3, 'clause', '(1)', '', NULL, 'No person shall, knowingly or having a reasonable reason to
believe that a document is a forged one, possess such document, with
intent to dishonestly use such document as genuine.', 0, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.1', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three years and a fine not
exceeding thirty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.1.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.1', 3, 'clause', '(3)', '', NULL, 'A person who uses as genuine any document which he
or she knows or has a reasonable reason to believe to be a forged
document shall be liable to the sentence in th e same manner as if he
or she had forged such document.', 2, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28', 2, 'rule', '278', 'Prohibition of making instrument for making forged document', 'Prohibition of making instrument for making forged document', NULL, 2, 'The National Penal (Code) Act, 2017, Chapter-25 (Prohibition of making instrument for making forged document)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.2', 3, 'clause', '(1)', '', NULL, 'No person shall make, repair, purchase, exchange or possess any
seal or other instrument for making a forged document, with the
intention of using it in establishing or making a forged document, or
knowingly or having a reasonable reason to believe that it may be
used in such act.', 0, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.2.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.2', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding four years and a fine not
exceeding forty thousand rupees.', 1, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28', 2, 'rule', '279', 'Prohibition of committing fraud', 'Prohibition of committing fraud', NULL, 3, 'The National Penal (Code) Act, 2017, Chapter-25 (Prohibition of committing fraud)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.3', 3, 'clause', '(1)', '', NULL, 'No person shall commit, or
cause to be committed, fraud.', 0, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.3.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.3', 3, 'clause', '(2)', '', NULL, 'For the purposes of sub -section (1), a person who, with
intent to disentitle any one, expire the statute of limitation or
appointed date for presence of, or cause, in any manner, loss,
damage, injury or benefit to, any one, knowingly does an act stating
that any thing has happened or been done which has not happened or
been done in fact or makes or signs a document containing a false
date, figure or content or causes another person to sign such
document or showing that he or she has entitlement in any thing in
which he or she has no such entitlement in fact, which does not
constitute the offence of forgery, shall be considered to commit the
offence of fraud.', 1, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.3.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.3', 3, 'clause', '(3)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub -section (1) shall be liable to a sentence of
imprisonment for a term not exceeding three years or a fine not
exceeding thirty thousand rupees or both the sentences.', 2, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.3.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.3', 3, 'clause', '(4)', '', NULL, 'A person who has already disposed of property which
he or she has obtained by committing fraud shall be liable to an
additional fine e qual to the claimed amount, in addition to the
sentence referred in sub-section (3).', 3, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.3.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.3', 3, 'clause', '(5)', '', NULL, 'Where a person obtains any property by committing
fraud, the person shall return such property to the concerned owner;
and in the event that such property has alread y been disposed of, the
claimed amount of such property shall be caused to be recovered to
the owner from any other property of the offender.', 4, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28', 2, 'rule', '280', 'Prohibition of using as genuine a fraudulent document', 'Prohibition of using as genuine a fraudulent document', NULL, 4, 'The National Penal (Code) Act, 2017, Chapter-25 (Prohibition of using as genuine a fraudulent document)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.4', 3, 'clause', '(1)', '', NULL, 'No
person shall, knowingly or having a reason to believe that a
document is a fraudulent one, use such document as genuine.', 0, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.4.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.4', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to the sentence in
the same manner as if he or she had committed fraud.', 1, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28', 2, 'rule', '281', 'Liable to punishment as accomplice', 'Liable to punishment as accomplice', 'A person who becomes a
witness to, or writes, a document knowing that the document is a
forged one shall be considered as an accomplice of the offence of
forgery.', 5, 'The National Penal (Code) Act, 2017, Chapter-25 (Liable to punishment as accomplice)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.5.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28.5', 3, 'clause', '(2)', '', NULL, 'An accomplice referred to in sub -section (1 ) shall be
liable to half the sentence set forth in sub-section (3) of Section 273.', 0, 'The National Penal (Code) Act, 2017, Chapter-25, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28', 2, 'rule', '282', 'Compensation ordered to be paid', 'Compensation ordered to be paid', 'Where any loss or damage is
caused to any person from the commission of an y offence referred to
in this Chapter, a reasonable compens ation shall be ordered to be
paid by the offender to such person who has suffered such loss or
damage.', 6, 'The National Penal (Code) Act, 2017, Chapter-25 (Compensation ordered to be paid)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:28.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:28', 2, 'rule', '283', 'Statute of limitation', 'Statute of limitation', 'No complaint shall lie , in relation to the
offence of forgery of a public document after the expiry of two years
from the dat e of knowledge of commission of such offence, and in
relation to any of the other offences under this Chapter, after the
expiry of six months from the date of knowledge of commission of
such offence.', 7, 'The National Penal (Code) Act, 2017, Chapter-25 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-26', '', NULL, 'Offences Relating to Criminal Trespass and Criminal Mischief', 29, 'The National Penal (Code) Act, 2017, Chapter-26', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29', 2, 'rule', '284', 'Prohibition of committing criminal trespass', 'Prohibition of committing criminal trespass', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-26 (Prohibition of committing criminal trespass)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29.0', 3, 'clause', '(1)', '', NULL, 'No person shall
commit, or cause to be committed, criminal trespass into the property
of another person.', 0, 'The National Penal (Code) Act, 2017, Chapter-26, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29.0', 3, 'clause', '(2)', '', NULL, 'For the purposes of sub -section (1), a person who, with
intent to do the following act, enters, in an unauthorized manner, and
whether doing manhandling or not, into a property owned or
possessed by another person without obtaining such other person’s
permission or enters into such property with such permission but
remains in, or continues to occupy or use, that property with intent
thereby to do any of such acts shall be considered to commit criminal
trespass:
(a) Committing any offence, or
(b) Intimidating, insulting or annoying the owner or
possessor of the property.', 1, 'The National Penal (Code) Act, 2017, Chapter-26, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29.0', 3, 'clause', '(3)', '', NULL, 'A person commits the offence referred to in sub-section', 2, 'The National Penal (Code) Act, 2017, Chapter-26, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.0.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29.0', 3, 'clause', '(1)', '', NULL, 'shall be liable to the following sentence:
(a) In the case of a person who commits criminal trespass
for the purpose referred to in clause (a) of sub -section', 3, 'The National Penal (Code) Act, 2017, Chapter-26, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.0.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29.0', 3, 'clause', '(2)', '', NULL, ', a sentence equal to the sente nce imposable for
attempt to such offence,
(b) In the case of criminal trespass into a government office
or human dwelling house for the purpose referred to in
clause (b) of sub -section (2), a sentence of
imprisonment for a term not exceeding six months or a
fine not exceeding five thousand rupees or both the
sentences.
Explanation: For the purposes of this Section,-', 4, 'The National Penal (Code) Act, 2017, Chapter-26, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.0.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29.0', 3, 'clause', '(1)', '', NULL, 'A place of temporary residence shall also be
considered to be a house.', 5, 'The National Penal (Code) Act, 2017, Chapter-26, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.0.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29.0', 3, 'clause', '(2)', '', NULL, 'Entry into, or use of, a way, passage, water
collection center, irrigation canal, graveyard,
temple that have been in public use for time
immemorial shall not be considered to be
criminal trespass.', 6, 'The National Penal (Code) Act, 2017, Chapter-26, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29', 2, 'rule', '285', 'Prohibition of committing criminal mischief', 'Prohibition of committing criminal mischief', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-26 (Prohibition of committing criminal mischief)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29.1', 3, 'clause', '(1)', '', NULL, 'No person shall
commit, or cause to be committed, criminal mischief.', 0, 'The National Penal (Code) Act, 2017, Chapter-26, Clause (1)', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_national_penal_code_2074_2017:29.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29.1', 3, 'clause', '(2)', '', NULL, 'For the purposes of sub -section (1), a person who does
any of the following acts shall be considered to commit criminal
mischief:
(a) Destroying, or doing such act as to diminish the value,
importance or utility of, any government, public or
private property, with the intention of causing any harm,
loss or damage to the Government of Nepal, State
Government or Local Level, any body corporate under
full or majority ownership or control of the Government
of Nepal, State Government or Local Level or publ ic or
any person, or knowing or having a reasonable reason to
believe that such damage is likely to be caused, or
causing such damage by a negligent or reckless act,
(b) Causing loss, damage or wrongful injury to, or doing
any act that causes injury to, or knowingly causing any
kind of obstruction, loss, damage or wrongful injury to
the utility of, any public or private sewerage, water
canal, drinking water pond, road, bridge or any means
of communications or transportation and the like,
(c) Destroying, removing, erasing or tampering any mark or
sign fixed for public convenience, except for any act
done in pursuance of an order of the competent
authority, by spreading rumors or using any means of
deception,
(e) Concealing, or dishonestly causing delay in the delivery
of, any correspondence, notice, parcel or other object of
another person.', 1, 'The National Penal (Code) Act, 2017, Chapter-26, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.1.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29.1', 3, 'clause', '(3)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to the following
sentence:
(a) The sentence of imprisonmen t for life and a fine equal
to the claimed amount, in the case of setting fire to, or
using explosives, in any national park or reserve or
protected zone, with the objective of destroying the
existence of species of any wildlife or flora or fauna
protected by the Government of Nepal or protected
pursuant to law, any historical or archeological
monument or statue included in the world heritage list,
any site or museum in which objects of historical or
archeological importance are kept, or any achieve where
historical documents are kept, any military or para -
military house or place in which arms and ammunition
of the army or police are stored, security press, mint,
factory, Nepal Rastra Bank''s warehouse for bank note
printing or storing,
(b) A sentence of imprisonment for a term of five to twelve
years and a fine equal to the claimed amount, in the case
of criminal mischief committed by setting fire to, or
using explosives in, any historical, archeological or
religious monument or statue other than that referre d to
in clause (a), any building containing documents of
public or governmental importance, any court
containing money ( Tahabil), any constitutional body,
any office of the Government of Nepal, State
Government or Local Level or body under full or
majority ownership or control of the Government of
Nepal, State Government, or Local Level, or any office
of foreign diplomatic mission or international or inter -
governmental organization,
(c) A sentence of imprisonment for a term not exceeding
four years and a f ine not exceeding forty thousand
rupees, in the case of criminal mischief committed by
doing any act other than that referred to in clause (a) or
(b), thereby causing injury to any public property,
(d) A sentence of imprisonment for a term of two to five
years and a fine of twenty thousand to fifty thousand
rupees, in the case of criminal mischief committed by
setting fire to or using explosives in any house, office or
property of any person,
(e) A sentence of imprisonment for a term not exceeding
three years and a fine not exceeding thirty thousand
rupees in the case of criminal mischief committed by
doing any act other than that referred to in clause (a),
(b), (c) or (d), thereby causing any loss, damage to any
person.', 2, 'The National Penal (Code) Act, 2017, Chapter-26, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.1.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29.1', 3, 'clause', '(4)', '', NULL, 'Where any loss, damage is cau sed to any person by
reason of the commission of the offence referred to in this Section, a
compensation equal to the claimed amount of such loss or damage so
caused shall be ordered to be paid by the offender to the victim of the
offence.', 3, 'The National Penal (Code) Act, 2017, Chapter-26, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29', 2, 'rule', '286', 'Prohibition of committing larceny (looting)', 'Prohibition of committing larceny (looting)', NULL, 2, 'The National Penal (Code) Act, 2017, Chapter-26 (Prohibition of committing larceny (looting))', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29.2', 3, 'clause', '(1)', '', NULL, 'No person shall
commit, or cause to be committed, larceny.', 0, 'The National Penal (Code) Act, 2017, Chapter-26, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.2.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29.2', 3, 'clause', '(2)', '', NULL, 'For the purposes of sub -section (1), a person who does
any act, other than an act that constitutes theft or cheating, by which
he or she otherwise snatches , whether forcibly or not, takes, whether
by manhandling or fighting or giving threat thereof, or causes loss,
damage to any property which he or she has no right in or which is
under ownership, custody or control of another person, with the
intention of s natching, taking, or causing loss, damage to, such
property shall be considered to commit larceny.', 1, 'The National Penal (Code) Act, 2017, Chapter-26, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.2.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29.2', 3, 'clause', '(3)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding three months or a fine not exceeding twenty -five
percent of the claimed amount subjected to larceny or both the
sentences, and the claimed amount subjected to larceny shall be
ordered to be paid by the offender to the victim.', 2, 'The National Penal (Code) Act, 2017, Chapter-26, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29', 2, 'rule', '287', 'Prohibition of acquiring property obtaine d by committing', 'Prohibition of acquiring property obtaine d by committing', 'offence: (1) No person shall acquire, hold, purchase or sell any
property knowing or having a reasonable reason to believe that such
property has been obtained by committing an offence.', 3, 'The National Penal (Code) Act, 2017, Chapter-26 (Prohibition of acquiring property obtaine d by committing)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29.3', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding five years or a fine not
exceeding fifty thousand rupees or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-26, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.3.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29.3', 3, 'clause', '(3)', '', NULL, 'The property acquired, held, purchased or sold as set
forth in sub -section (1) shall be returned to the owner of such
property.', 1, 'The National Penal (Code) Act, 2017, Chapter-26, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:29.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:29', 2, 'rule', '288', 'Statute of limitation', 'Statute of limitation', 'A complaint in relation to an offence under
Section 284 or 285 shall not be entertained after the expiry of six
months from the date of commission of such offence, in relation to
the offence under Section 286, after the expiry of three months from
the date of commission of such offence, and in relation to any of
other offences under this Chapter, after the expiry of three month s
from the date of having kn owledge of the commission of such
offence.', 4, 'The National Penal (Code) Act, 2017, Chapter-26 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:30', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-27', '', NULL, 'Offences Relating to Animals and Birds', 30, 'The National Penal (Code) Act, 2017, Chapter-27', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:30.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:30', 2, 'rule', '289', 'Prohibition of killing or beating cows or oxen', 'Prohibition of killing or beating cows or oxen', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-27 (Prohibition of killing or beating cows or oxen)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:30.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:30.0', 3, 'clause', '(1)', '', NULL, 'No person shall
do, or cause to be done, any act with the intention of killing, or
causing hurt to, any cow or ox.', 0, 'The National Penal (Code) Act, 2017, Chapter-27, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:30.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:30.0', 3, 'clause', '(2)', '', NULL, 'Where any act referred to in sub -section (1) causes the
death of any cow or ox, the offender of such offence shall be liable to
a sentence of imprisonment for a term not exceeding three years.', 1, 'The National Penal (Code) Act, 2017, Chapter-27, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:30.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:30.0', 3, 'clause', '(3)', '', NULL, 'A person shall be liable to a sentence of impris onment
for a term not exceeding six months, if he or she causes grievous hurt
to a cow or ox, and to a sentence of a fine not exceeding fifty
thousand rupees if other hurt is caused.', 2, 'The National Penal (Code) Act, 2017, Chapter-27, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:30.0.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:30.0', 3, 'clause', '(4)', '', NULL, 'Notwithstanding anything contained in sub -section (1),
if a person does any act necessary to protect from any injury likely to
be caused by any cow or ox to the body or life of the person or
another person and such act causes the death of, or any harm to, such
cow or ox, the person shall not be considered to commit any of fence
under this Section.', 3, 'The National Penal (Code) Act, 2017, Chapter-27, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:30.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:30', 2, 'rule', '290', 'Prohibition of cruel treatment to animals and birds', 'Prohibition of cruel treatment to animals and birds', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-27 (Prohibition of cruel treatment to animals and birds)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:30.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:30.1', 3, 'clause', '(1)', '', NULL, 'No
person shall subject any animal or bird to torture by beating or
hitting it, or by causing it to carry a load beyond its capacity or by
causing it to walk or run bey ond its ability or by engaging it in work
if it is unable to work because of illness, wound or Khatira, or any
other cause, or by feeding it harmful substance or in any other
manner whatsoever or leave publicly any animal or bird which he or
she has grown up because of its being ill or aged or otherwise treat it
cruelly or mercilessly.
Provided that nothing shall bar the using of minimum force in
order to make any animal or bird do any work or carry a load
according to its physical capacity or make it run , with the objective
to teach or train it to do any wok or make it efficient on its work.', 0, 'The National Penal (Code) Act, 2017, Chapter-27, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:30.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:30.1', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding three months or a fine not exceeding five thousand
rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-27, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:30.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:30', 2, 'rule', '291', 'Prohibition of killing animals or birds in public places', 'Prohibition of killing animals or birds in public places', NULL, 2, 'The National Penal (Code) Act, 2017, Chapter-27 (Prohibition of killing animals or birds in public places)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:30.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:30.2', 3, 'clause', '(1)', '', NULL, 'Except
as otherwise provided in this Act, no person shall kill any animal or
bird in any public place other than a religious place wher e there is a
tradition to offer sacrifice of an animal or bird.
Provided that nothing shall bar the killing of any animal or
bird in a fair, feast, exhibition or event or place where there is a
tradition of slaughtering animals or birds being practiced f rom time
immemorial.
Explanation: For the purposes of this Section, the term
“public place” means a way, road, bridge, meadow or place for
movement of human beings.', 0, 'The National Penal (Code) Act, 2017, Chapter-27, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:30.2.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:30.2', 3, 'clause', '(2)', '', NULL, 'In making sacrifice of an animal or bird under sub -
section (1), no sacrifice of such an imal or bird shall be executed in
any public place or religious place other than a religious place where
the sacrifice of animals or birds has been in practice from time
immemorial.', 1, 'The National Penal (Code) Act, 2017, Chapter-27, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:30.2.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:30.2', 3, 'clause', '(3)', '', NULL, 'In making sacrifice of an animal or bird under sub -
section (1), any a lternative measure, if any available, to such
sacrificing shall be adopted.', 2, 'The National Penal (Code) Act, 2017, Chapter-27, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:30.2.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:30.2', 3, 'clause', '(4)', '', NULL, 'Where it is necessary to make sacrifice of an animal or
bird being it not possible to adopt the measure under sub -section (3),
such sacrifice shall be made at such place and in accordance with
such method as determined by the manager of the concerned
religious place.', 3, 'The National Penal (Code) Act, 2017, Chapter-27, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:30.2.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:30.2', 3, 'clause', '(5)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in this Section shall be liable to a sentence of
imprisonment for a term not exceeding one month or a fine not
exceeding five thousand rupees or both the sentences.', 4, 'The National Penal (Code) Act, 2017, Chapter-27, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:30.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:30', 2, 'rule', '292', 'Statute of limitation', 'Statute of limitation', 'No complaint shall lie in relation to any of the
offences under Section 290, after the expiry of three months from the
date of commission of such off ence, and in relation to any of the
other offences under this Chapter, after the expiry of three months
from the date of knowledge of commission of such act.
Part-3
Offences against Individual Privacy and Prestige', 3, 'The National Penal (Code) Act, 2017, Chapter-27 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-1', '', NULL, 'Offences against Privacy', 31, 'The National Penal (Code) Act, 2017, Chapter-1', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31', 2, 'rule', '293', 'Prohibition of listening to or recording other''s conversation', 'Prohibition of listening to or recording other''s conversation', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition of listening to or recording other''s conversation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31.0', 3, 'clause', '(1)', '', NULL, 'No person shall, by using a mechanical device, listen to, or record,
any conversation held between two or more persons, without
permission of the competent authority or consent of such pers ons
holding conversation.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31.0', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding two years or a fine not
exceeding twenty thousand rupees or both the sentences.
Provided that this Section shall not apply to any speech or
statement made publicly.', 1, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31', 2, 'rule', '294', 'Prohibition of divulging confidential matter', 'Prohibition of divulging confidential matter', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition of divulging confidential matter)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31.1', 3, 'clause', '(1)', '', NULL, 'No person shall
divulge another person''s confidential matter, which he or she comes
to know from su ch person in the course of his or her professional
work, except where such divulgence is compelled by law or
permitted by such person.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31.1', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a t erm
not exceeding one year or a fine not exceeding ten thousand rupees
or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31', 2, 'rule', '295', 'Prohibition of taking or disfiguring photograph of any person', 'Prohibition of taking or disfiguring photograph of any person', 'without his or her consent: (1) No person shall, without consent of
another person, take a phot ograph of that other person or make
another photograph by mixing other''s photograph with the
photograph of that other person.
Provided that a person who, while taking a photograph of any
public place, happens to take also a photograph of any person
remaining in such place shal l not be considered to commit the
offence under this Section.', 2, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition of taking or disfiguring photograph of any person)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31.2', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding one year or a fine not
exceeding ten thousand rupees or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.2.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31.2', 3, 'clause', '(3)', '', NULL, 'No person shall make a disfigured photograph by
mixing some part of one''s photograph with another part of other''s
photograph or in any other manner or publish such disfigured
photograph.', 1, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.2.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31.2', 3, 'clause', '(4)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (3) shall be liable to a sentence of
imprisonment for a term not exceeding two years or a fine not
exceeding twenty thousand rupees or both the sentences.', 2, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31', 2, 'rule', '296', 'Prohibition of giving or selling one’s photograph to another', 'Prohibition of giving or selling one’s photograph to another', 'without consent: (1) No person shall give or sell one''s photograph
without his or her consent to another person, or publish, publicize,
purchase or sell such photograph, with the intention of annoying,
disturbing or troubling him or her or taking any undue benefit from
him or her or taking benefit by making commercial use of such
photograph.', 3, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition of giving or selling one’s photograph to another)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.3.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31.3', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall b e liable to a sentence of
imprisonment for a term not exceeding three years or a fine not
exceeding thirty thousand rupees or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.4', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31', 2, 'rule', '297', 'Prohibition of opening letters or tapping telephone conversation', 'Prohibition of opening letters or tapping telephone conversation', NULL, 4, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition of opening letters or tapping telephone conversation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.4.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31.4', 3, 'clause', '(1)', '', NULL, 'No person shall open a person''s let ter or tap or record a person’s
telephone conversation by using any mechanical device, without
permission of the competent authority or the concerned person.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.4.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31.4', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, an
offence under sub -section (1) shall be li able to a sentence of
imprisonment for a term not exceeding two years or a fine not
exceeding twenty thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.5', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31', 2, 'rule', '298', 'Prohibition of breaching privacy through electronic means', 'Prohibition of breaching privacy through electronic means', NULL, 5, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition of breaching privacy through electronic means)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.5.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31.5', 3, 'clause', '(1)', '', NULL, 'No person shall obtain, in an unauthorized manne r, a notice,
information and correspondence lying in or to be transmitted from
any electronic means or breach privacy thereof, or transfer, or cause
to be transferred, the same to another person in an unauthorized
manner.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.5.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31.5', 3, 'clause', '(2)', '', NULL, 'A person who commits, or cause s to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding two years or a fine not
exceeding twenty thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.6', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31', 2, 'rule', '299', 'Prohibition of deceitfully making tele phone calls or transmitting', 'Prohibition of deceitfully making tele phone calls or transmitting', 'messages: (1) No person shall deceitfully make, or cause to be made,
any telephone call or transmit any message, whether giving his or her
identity or not, with the intention of avoiding, deceiving, annoying or
troubling another person.', 6, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition of deceitfully making tele phone calls or transmitting)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.6.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31.6', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding two years or a fine not exceeding twenty thousand
rupees or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.7', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31', 2, 'rule', '300', 'Prohibition of writing letters with dishonest intention of causing', 'Prohibition of writing letters with dishonest intention of causing', 'annoyance: (1) No person shall, with the dishonest intention of
causing fear, terror or pain to, or annoying, insulting or defaming
another person, threat, annoy, tease that other person by writing or
causing to be written any letter, pamphlet or document of any other
type or through electronic means or otherwise behave such person
improperly.', 7, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition of writing letters with dishonest intention of causing)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.7.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31.7', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sente nce of
imprisonment for a term not exceeding one year or a fine not
exceeding ten thousand rupees or both the sentences.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.8', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31', 2, 'rule', '301', 'Prohibition search other''s body', 'Prohibition search other''s body', NULL, 8, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition search other''s body)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.8.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31.8', 3, 'clause', '(1)', '', NULL, 'No person, except the
competent authority, or with the order of the competent authority, or
a person deputed for security purpose, with the permission of the
competent authority, shall search, or cause to be searched, another
person''s body, vehicle or personal belongings without consent of that
other person.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.8.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31.8', 3, 'clause', '(2)', '', NULL, 'A person who commits, or causes t o be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding one year or a fine not
exceeding ten thousand rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.9', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31', 2, 'rule', '302', 'Prohibition of unauthorized entry into other'' s residence', 'Prohibition of unauthorized entry into other'' s residence', NULL, 9, 'The National Penal (Code) Act, 2017, Chapter-1 (Prohibition of unauthorized entry into other'' s residence)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.9.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31.9', 3, 'clause', '(1)', '', NULL, 'No
person, except the competent authority or with the order of such
authority under law, shall authoritatively enter into another person''s
house, breach the privacy of the house owner or his or her family or
search, or cause to be searched , such house, without the consent of
the concerned house owner.
Explanation: For the purposes of this Section, the term
"house" means a house, residence, housing, room where a person is
dwelling, and this term also includes a hotel room, camp and tent
where such person is staying to spend a night.', 0, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.9.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31.9', 3, 'clause', '(2)', '', NULL, 'A person who commits the offence referred to in sub-
section (1) shall be liable to a sentence of imprisonment for a term
not exceeding three years or a fine not exceeding thirty thousand
rupees or both the sentences.', 1, 'The National Penal (Code) Act, 2017, Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.10', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31', 2, 'rule', '303', 'Compensation to be paid', 'Compensation to be paid', 'Where a person derives any benefit or
causes any kind of damage, loss, annoyance or injury to another
person by committing the offence referred to in this Chapter, a
compensation for such damage, loss, annoyance or inj ury shall also
be ordered to be paid by the offender to the victim.', 10, 'The National Penal (Code) Act, 2017, Chapter-1 (Compensation to be paid)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:31.11', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:31', 2, 'rule', '304', 'Statute of limitation', 'Statute of limitation', 'No complaint shall lie after the expiry of three
months from the date of commission of any offence under this
Chapter.', 11, 'The National Penal (Code) Act, 2017, Chapter-1 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:32', 'doc_national_penal_code_2074_2017', NULL, 1, 'chapter', 'Chapter-2', '', NULL, 'Offence Relating to Defamation', 32, 'The National Penal (Code) Act, 2017, Chapter-2', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:32.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:32', 2, 'rule', '305', 'Prohibition of committing slander', 'Prohibition of committing slander', NULL, 0, 'The National Penal (Code) Act, 2017, Chapter-2 (Prohibition of committing slander)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:32.0.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:32.0', 3, 'clause', '(1)', '', NULL, 'No person shall slander
another person.', 0, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:32.0.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:32.0', 3, 'clause', '(2)', '', NULL, 'For the purposes of sub -section (1), a person who uses
degrading words, spoken or said, with the intention of lowering the
reputation of another person shall be deemed to commit slander.', 1, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:32.0.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:32.0', 3, 'clause', '(3)', '', NULL, 'A person who commits, or causes to be committed, the
offence referred to in sub-section (1) shall be liable to a sentence of
imprisonment for a term not exceeding one year or a fine not
exceeding ten thousand rupees or both the sentences.', 2, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:32.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:32', 2, 'rule', '306', 'Prohibition of committing libel', 'Prohibition of committing libel', NULL, 1, 'The National Penal (Code) Act, 2017, Chapter-2 (Prohibition of committing libel)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:32.1.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:32.1', 3, 'clause', '(1)', '', NULL, 'No person shall defame
another person.', 0, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:32.1.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:32.1', 3, 'clause', '(2)', '', NULL, 'For the purposes of sub -section (1), a person who
commits any of the following acts shall be deemed to commit
defamation:
(a) By words in writing, by conduct or by signs or by
visible representation or by publicity or by other means,
damaging the character of another person by making
imputation that, directly or indirectly, in the estimation
of others, lowers the personal or moral character,
conduct or reputati on of that other person, or making
imputation that causes it to be believed that the body of
that other person is in a state generally considered as
disgraceful or disseminating or publishing such
imputation, with the intention of harming, or knowing,
or h aving a reasonable reason to believe that, such
imputation will harm, the reputation of that other
person, or knowingly selling or distribution any thing
which is used as a means of libeling any one,
(b) Making any imputation against a deceased pers on if the
imputation would harm the reputation of that person if
living, and is intended to be hurtful to the feelings of his
or her family or other near relatives,
(c) Making or expressing an imputation in the form of an
alternative or ironically.', 1, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:32.1.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:32.1', 3, 'clause', '(3)', '', NULL, 'Notwithstanding anything contained elsewhere in sub -
section (2), none of the following acts shall be considered to be libel:
(a) Publishing or broadcasting any thing which is true
concerning any person, along with the evidence and
basis, for public good,
(b) Publishing in good faith and decently any thing
respecting the conduct of any public servant in the
discharge of his or her public functions or respecting his
or her character only so far as his or her character
appears in that conduct,
(c) Expressing in good fai th any opinion respecting the
conduct of public office or position of any person and
respecting his or her character only so far as his or her
character appears in that conduct,
(d) Expressing in good faith and decently any opinion
respecting the merits of any performance which its
author has submitted to the public for opinion or
respecting the character of the author only so far as his
or her character appears in such performance,
(e) Passing in good faith any censure on the conduct of a
person who has ov er another person any authority,
either conferred by law or arising out of a contract made
with that other person in matters to which such authority
relates.
(f) Investigating into any offence in accordance with law or
preferring accusation against him or her on that basis in
accordance with law,
(g) Cautioning a person against other person, for his or her
benefit or for the benefit of a person having his or her
interest or for the benefit of the public.', 2, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:32.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:32', 2, 'rule', '307', 'Punishment for libel', 'Punishment for libel', NULL, 2, 'The National Penal (Code) Act, 2017, Chapter-2 (Punishment for libel)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:32.2.0', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:32.2', 3, 'clause', '(1)', '', NULL, 'A person who commits, or causes to be
committed, libel shall be liable to a sentence of imprisonment for a
term not exceeding two years or a fine not exceeding twenty
thousand rupees or both the sentences.
Provided that if libel is committed or, caused to be committed,
by means of electronic or other means of mass communication, there
shall be imposed an additional sentence of imprisonment for a term
not exceeding one year or a fine not exceeding ten thousand rupees
in addition to such punishment.', 0, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:32.2.1', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:32.2', 3, 'clause', '(2)', '', NULL, 'If a person is convicted of libeling another person or
causing such libel, a reasonable compensation to be set having regard
to, inter alia , the gravity of the offence, effect caused to the
reputation of such person and the commission of libel by means of
electronic or other means of mass communication, shall be ordered
to be paid by the offender to th e libeled person, and litigation costs
shall also be ordered to be paid by the offender to the libeled person.', 1, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:32.2.2', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:32.2', 3, 'clause', '(3)', '', NULL, 'If a person is convicted of libeling a deceased under this
Chapter, such compensation and litigation costs shall be ordered to
be paid by the offender to the near successor to the deceased whose
feeling was hurt.', 2, 'The National Penal (Code) Act, 2017, Chapter-2, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_national_penal_code_2074_2017:32.3', 'doc_national_penal_code_2074_2017', 'doc_national_penal_code_2074_2017:32', 2, 'rule', '308', 'Statute of limitation', 'Statute of limitation', 'No complaint shall lie after the expiry of three
months from the date of knowledge of commission of any offence
under this Chapter.', 3, 'The National Penal (Code) Act, 2017, Chapter-2 (Statute of limitation)', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:0', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', NULL, 1, 'preamble', 'Preamble', 'Introductory matter', NULL, 'NEPAL CITIZENSHIP ACT 2063 (2006) 
Date of Authentication and publication   
10 Mangsir 2063 (26 Nov 2006)', 0, 'NEPAL CITIZENSHIP ACT 2063 (2006), Preamble', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', NULL, 1, 'section_group', 'Sections', 'Sections', NULL, NULL, 1, NULL, '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.0', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '1', 'Amended by some Nepalese Acts Amendment Act ,20 64  2064.5.9', 'Amended by some Nepalese Acts Amendment Act ,20 64  2064.5.9', 'Act No. 25 of the year 2063 (i.e. 2006)  
An Act Made to Amend and Consolidate Laws Relating to Citizenship : 
Preamble: Whereas the sovereignty and state authori ty is vested on the Nepalese people 
as the result of the popular  movement; 
 Whereas, as per the commitment mentioned in ''Decla ration of the  House of 
Representatives 2063 (2006) that  Nepalese citizens hip were facing difficulties in 
acquiring citizenship certificate in the past and b ased on the political understanding made 
on 22 kartik 2063 (Nov 8th 2006),  
     Whereas, it is expedient to amend and consolid ate the laws relating to citizenship 
regarding acquisition termination and other necessary provisions,    
   Now, therefore, be it enacted by the House of Re presentatives in the First Year of 
the Proclamation of the House of Representatives, 2063 (2006).', 0, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 1 (Amended by some Nepalese Acts Amendment Act ,20 64  2064.5.9)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.1', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '1', 'Short Title and Commencement:   (1) This Act may be called "Nepal', 'Short Title and Commencement', 'Citizenship Act 2063 (2006)". 
(2) This Act shall come into force immediately.', 1, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 1 (Short Title and Commencement)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.2', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '2', 'Definition:  Unless the subject or context otherwise requires, in this Act:', 'Definition', '(a) "Minor"  means a person who has not attained th e age of 16 years. 
(b)  "Person" means natural person. 
(c)  "Prescribed" or " as Prescribed" means prescri bed or as prescribed in the 
Rules made under this Act. 
3. 
Acquisition of Nepali Citizenship by descent : (1) A person born at the time 
when his/her father or mother is a citizen of Nepal , shall be a citizen of Nepal by 
descent. 
(2) Whatever may be written in Sub-section (1), a c hild born out of 
wedlock by a Nepali female citizen to a foreign nat ional shall be in accordance 
with Section 5, Sub-section  (2). 
(3) Every child found in the territory of Nepal, wh ose paternal and maternal 
addresses are undetermined, shall be considered a c itizen of Nepal by descent until 
his/her father or mother are found.', 2, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 2 (Definition)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.3', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '4', 'Acquisition of Nepali Citizenship by Birth  : (1) Any person born before', 'Acquisition of Nepali Citizenship by Birth', '2046 Chaitra 31, Bikram Sambat (i.e. 13, April, 199 0 A.D.) within the territory of 
Nepal and having domiciled permanently in Nepal sha ll be deemed a citizen of 
Nepal by birth. 
(2) A person desiring to obtain citizenship certifi cate pursuant to Sub-
section (1) shall have to apply before holding of t he election for Constituent 
Assembly and the procedure for granting of the Citi zenship Certificate shall be as 
prescribed. 
(3) In case a person, due to certain reasons, could  not submit his 
application within the period specified in Sub-sect ion (1) may apply as prescribed 
within two years from the commencement of this Act.', 3, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 4 (Acquisition of Nepali Citizenship by Birth)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.4', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '5', 'Acquisition of Citizenship by Naturalization :  (1) A foreign women', 'Acquisition of Citizenship by Naturalization', 'married to a citizen of Nepal desiring to obtain ci tizenship of Nepal shall have to 
submit an application in the prescribed form to the  designated officer. On 
submitting such application she has to produce the marriage relationship document 
with the citizen of Nepal and also evidence to show  the initiation of procedure for 
renunciation of own''s foreign citizenship. 
(2) A child born to a Nepali female citizen from ma rriage with a foreign 
citizen in Nepal and having permanent domicile in N epal may be granted 
naturalized citizenship as prescribed, provided the  child has not acquired the 
citizenship of the foreign country on the basis of the citizenship of his/her father. 
(3) A person desiring to acquire naturalized citize nship pursuant to Sub-
section (2) shall have to submit an application wit h the following documents to the 
designated authority:  
(a) Duplicate copy of the citizenship certificate o f the mother, 
(b) Recommendation by concerned Municipality or Vil lage 
Development Committee certifying the birth and perm anent 
residency in Nepal, 
(c) Evidence to show that foreign citizenship has n ot been acquired 
based on the citizenship of the father. 
(4)  The Government of Nepal may grant naturalized citizenship as 
prescribed to those foreign citizens, who have cont ributed specially for the 
upliftment of science, philosophy, art, literature,  world peace, human welfare or 
Nepalese industry, finance or social development an d have fulfilled the following 
conditions or status : 
(a)  who is able to read and write Nepali or any ot her language in 
practice in Nepal. 
(b) who is engaged in any occupation and domiciled in Nepal. 
(c) who has renounced or declared such renunciation  of the citizenship 
of the other country. 
(d) who has resided in Nepal for a minimum period o f 15 years. 
(e) who is a citizen of the country where there is provision of the law or 
practice to grant naturalized citizenship to Nepalese. 
(f) who bears good moral character 
(g) who is mentally fit and healthy. 
(5)  Whatever may have been written is Sub-section (4), from among the 
issues of the person, the child born to the person prior to that person having 
acquired citizenship by naturalization may also acq uire Nepalese citizenship by 
naturalization as prescribed form. 
(6)  Any person acquiring citizenship by naturaliza tion under this 
Section shall take an oath as mentioned in the sche dule and awarded the Nepalese 
citizen certificate in the prescribed form and such  person shall be naturalized 
citizen of Nepal from the date of receiving such certificate.', 4, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 5 (Acquisition of Citizenship by Naturalization)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.5', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '6', 'Award of Honorary Nepalese Citizenship : Notwithstanding  any thing', 'Award of Honorary Nepalese Citizenship', 'mentioned in Section 5, the Government of Nepal may  award Honorary Nepalese 
Citizenship to any internationally renowned person.', 5, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 6 (Award of Honorary Nepalese Citizenship)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.6', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '7', 'Citizenship in the case of accession of territory :  When any part of territory', 'Citizenship in the case of accession of territory', 'is integrated with Nepal, persons residing in such acceded territory shall be 
considered citizens of Nepal, from the date Governm ent of Nepal publishes a 
notification as prescribed in the Nepal Gazette.', 6, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 7 (Citizenship in the case of accession of territory)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.7', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '8', 'Filing of Application to obtain Citizenship Certifi cate  :  (1)  A person', 'Filing of Application to obtain Citizenship Certifi cate', 'attaining the age of 16 years desiring to acquire c itizenship of Nepal by descent 
pursuant to Section 3, shall have to file an applic ation in the prescribed form along 
with copies of the following documents to the designated authority: 
(a) Nepalese Citizenship Certificate of descendants  of 
relatives within three generations from paternal or  
maternal or self side. 
Provided that , this provision shall not be applica ble to 
Nepalese female citizen married to a foreigner. 
(b) Recommendation from the concerned Village Devel opment 
or Municipality certifying the place of birth and relationship. 
(2)  A person attaining the age of 16 years desirin g to acquire Nepalese 
Citizenship Certificate by virtue of birth pursuant  to Section 4 shall have to file an 
application in the prescribed form along with copies of the following documents to 
the designated authority. 
(a) Recommendation from the concerned Village Devel opment 
Committee or Municipality certifying the birth in N epal and 
residing permanently in Nepal. 
(b)  An evidence showing Land Ownership Certificate  in the 
name of self or family or Certificate of Land Tilli ng Right or 
proof of house or listing of name or the name of fa ther or 
mother in the Voters'' list prepared by the Election  
Commission. 
(3) On receipt of the applications pursuant to Sub- section (1) or (2), the 
designated authority shall award the Nepalese Citiz enship Certificate, after 
evaluating and based on evidence as produced. 
(4) In the circumstance, where a person could not s ubmit the evidences 
along with the application as prescribed in Sub-sec tion (1) and (2), the designated 
authority may award the Nepalese Citizenship Certif icate based on the spot 
investigation and on the basis of identification at  the time of spot investigation by 
at least three persons having obtained Nepalese Cit izenship Certificate and 
residing in the same Ward and are acquainted with the applicant. 
(5) While conducting the spot investigating in acco rdance with Sub-
section (iv), the applicant must have been born in Nepal and stated clearly the fact 
of having lived in a permanent manner. 
(6) On investigation and evaluation pursuant to Sub -section (3) or (4), if 
any applicant is not found have been qualified to b e awarded the Nepalese 
Citizenship Certificate, one shall be duly notified  of the decision within the 
prescribed period.', 7, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 8 (Filing of Application to obtain Citizenship Certifi cate)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.8', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '9', 'Authority to issue Citizenship Certificate  :  The authority to issue Nepalese', 'Authority to issue Citizenship Certificate', 'Citizenship Certificate by descent, on the basis of  birth or by naturalization, shall 
be vested on the designated authority.', 8, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 9 (Authority to issue Citizenship Certificate)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.9', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '10', 'Termination of Nepalese Citizenship  (1) Any citizen of Nepal who', 'Termination of Nepalese Citizenship  (1) Any citizen of Nepal who', 'voluntarily acquires the citizenship of any foreign  country shall automatically lose 
the citizenship of Nepal. 
(2) The designated authority shall register the not ice submitted by a 
citizen of Nepal, who notifies in the prescribed fo rm of renunciation of the 
Citizenship of Nepal and the citizenship of that pe rson shall be terminated from 
the date such notice has been duly registered. 
(3) Any person who has been divested of Nepalese ci tizenship pursuant 
to Section 14, shall be deemed to have lost his citizenship from that date. 
(3) If any person who is in a status of acquiring t he citizenships of Nepal 
and a foreign country concurrently, such person sha ll have to choose the 
citizenship of any one country within two years aft er attaining the age of 16 years. 
Failure to choose the citizenship in this manner sh all be deemed for that person to 
have lost his Nepalese citizenship on expiry of that specified period. 
(4) In case any question arises as to whether a Nep alese citizen has acquired a 
foreign citizenship or not, the designated authorit y shall make his 
decision pursuant to the prevailing laws.', 9, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 10 (Termination of Nepalese Citizenship  (1) Any citizen of Nepal who)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.10', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '11', 'Re-acquisition of Nepalese Citizenship  : Any Citizen of Nepal who has', 'Re-acquisition of Nepalese Citizenship', 'acquired foreign citizenship returns to reside in Nepal and submits a notification to 
the designated authority the evidence of renunciati on of foreign citizenship shall 
be reinstated the Nepalese citizenship from the date of registering such evidence.', 10, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 11 (Re-acquisition of Nepalese Citizenship)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.11', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '12', 'Revocation of Citizenship Certificate  :   The designated authority shall', 'Revocation of Citizenship Certificate', 'revoke such Citizenship Certificate of any Nepalese  citizen, if it is proven that 
such citizenship had been obtained on submission of false documentation.', 11, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 12 (Revocation of Citizenship Certificate)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.12', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '13', 'Two Citizenship Certificates not to be acquired : No person shall acquire', 'Two Citizenship Certificates not to be acquired', 'more that one citizenship certificate. 
Provided that, there shall be no objection to issue another citizenship certificate by 
the concerned office on the basis of change of resi dency, if any person so desires, 
after due withdrawal of the first issued citizenship certificate.', 12, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 13 (Two Citizenship Certificates not to be acquired)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.13', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '14', 'Deprivation from Nepalese Citizenship .  (1) The Government of Nepal may', 'Deprivation from Nepalese Citizenship .  (1) The Government of Nepal may', 'issue directives to cancel the Nepalese Citizenship  Certificate and to divest 
Nepalese citizenship of any foreign person who has been found proven to have 
fraudulently acquired Nepalese citizenship on submi ssion of false documents 
and declaration. 
(2) Any person whose Nepalese Citizenship has been divested by a 
directive issued by the Government of Nepal in acco rdance with this section may 
file an appeal to the concerned Appellate Court within thirty-five days.', 13, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 14 (Deprivation from Nepalese Citizenship .  (1) The Government of Nepal may)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.14', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '15', 'Records of Citizenship Certificates to be maintaine d : The system of', 'Records of Citizenship Certificates to be maintaine d', 'maintaining the records of Nepalese Citizenship Cer tificates shall be as  
prescribed.', 14, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 15 (Records of Citizenship Certificates to be maintaine d)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.15', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '16', 'Rights. duties and liabilities not to absolve  : No citizen of Nepal whose', 'Rights. duties and liabilities not to absolve', 'citizenship in terminated for any reason, shall not  be deemed to have been 
absolved of the rights, duties and liabilities incu rred in relation to any act done 
during the period the person was a citizen of Nepal , only by reason of termination 
of the citizenship.', 15, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 16 (Rights. duties and liabilities not to absolve)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.16', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '17', 'Correction of the Particulars  :  ∇∇ ∇∇  (1) Any person desiring to correct his/her', 'Correction of the Particulars', 'caste or age for being differently mentioned in the academic certificate to that of the 
citizenship certificate or correct the minor mistak es in the citizenship certificate 
,shall have to provide for an application with nece ssary evidence to the designated 
authority.  
Clarification 
 : For the purpose of this section ''minor'' mistake m eans the non 
substantial details the citizenship certificate to mean ''Kumari'' "Devi" "bahadur" 
                                                             
∇  Amended by some Nepalese Acts Amendment Act ,2064 
"Prasad" like words being added or not mentioned or  difference in ''Aakar or Ikar 
(speccific grammatical error in devanagari) or other minor mistake of that type. 
(2) The designated authority on receipt of the appl ication pursuant to 
Sub-section (1) shall conduct an enquiry with witne sses as necessary and together 
with evidences obtained from such person shall make  the due correction and may 
grant another citizenship certificate after withdra wing the citizenship certificate 
awarded previously. 
(3) The designated authority on receipt of the appl ication by a married 
or divorced woman for amendment of her family name,  address or other 
particulars, may after verifying the necessary fact s grant another citizenship 
certificate with amended family name, address or pa rticulars and withdraw the 
previous citizenship certificate.', 16, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 17 (Correction of the Particulars)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.17', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '18', 'Revision : (1) Notwithstanding anything provided for in this A ct, any person', 'Revision', 'who is aggrieved by a decree issued by a designated  authority in accordance 
with this Act, may file a petition within thirty fi ve days from the date such decree 
was issued with the Government of Nepal for revision of such decree. 
(2) On receipt of the petition pursuant to Sub-sect ion (1), the 
Government of Nepal may obtain a report from the de signated authority issuing 
the decree and after reviewing the report may give its verdict or issue a decree and 
such verdict or decree shall be final.', 17, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 18 (Revision)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.18', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '19', 'Publication of Name list :  Every year the names of the persons who have been', 'Publication of Name list', 'divested of Nepalese Citizenship pursuant to Sectio n 14 shall be published in the 
Nepal gazette.', 18, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 19 (Publication of Name list)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.19', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '20', 'Delegation of Authority  : (1) The Government of Nepal may delegate the', 'Delegation of Authority', 'authority vested on itself pursuant to this Act to any officer in the Government of 
Nepal. 
Provided that , the authority to divest from Nepale se Citizenship pursuant to 
Section 14 shall not be delegated. 
(2) The designated authority authorized to distribu te Citizenship 
Certificates pursuant to this Act may delegate the authority vested on him/her to 
any staff officer.', 19, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 20 (Delegation of Authority)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.20', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '21', 'punishment  : (1) Any foreign national who claims to be a Nepales e', 'punishment', 'citizen and acquires Nepalese citizenship by giving  false representation shall be 
sentenced to imprisonment from one year to five years or fined from fifty thousand 
rupees to one hundred thousand rupees or awarded bo th penalties. The citizenship 
acquired by false representation and having penaliz ed pursuant to this clause, the 
citizenship thus acquired shall be automatically cancelled. 
(2) The person who was involved in the process of v erification or 
recommendation in granting citizenship to any forei gn national on false particulars 
shall be sentenced to imprisonment from six months to three years or fined from 
twenty five thousand rupees to fifty thousand rupees or awarded both penalties. 
(3) Any person who assists and begets false or forg ed Nepalese 
Citizenship Certificate and brings it in use shall be sentenced to imprisonment 
from one year to five years or fined from twenty th ousand rupees to one hundred 
thousand rupees or awarded both penalties. 
(4) Any person who alters or makes correction and a ssists in such 
undertaking on the particulars of the original citi zenship certificate shall be 
sentenced to imprisonment up to three months or fin ed up to ten thousand rupees 
or awarded both penalties. 
(5) Any person who furnishes and acquires citizensh ip certificate on 
false representation pursuant to Section 12 or the converted particulars pursuant to 
Section 17 is proven to be false or commits and Sec tion to commit any other 
offence in violation of this Act or the rules enacted under this Act shall be fined up 
to fifteen thousand Rupees. 
(6) The issuing authority of Nepalese Citizenship C ertificate 
intentionally or with mala fide  intention in violation of this Act and the Rules 
enacted under this Act issues Citizenship Certifica te or makes changes of the 
particulars in the Citizenship Certificate, such au thority or employee shall be 
subjected to departmental action as per the prevailing laws. 
(7) The person who undertakes or assists in any off ences punishable 
under Sub-sections (1), (2) and (3) shall be awarde d half the punishment as 
mentioned in those Sub-sections.', 20, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 21 (punishment)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.21', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '22', 'Appointment of Citizenship Team :  (1) If the Government of Nepal', 'Appointment of Citizenship Team', 'deems necessary, a Citizenship Certificate Distribu tion Team may be appointed to 
distribute Citizenship Certificates. 
(2) The Team appointed pursuant to Sub-section (1) shall distribute 
citizenship certificates within the directives auth orized by the Government of 
Nepal.', 21, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 22 (Appointment of Citizenship Team)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.22', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '23', 'Power to Frame Rules : The Government of Nepal may frame necessary Rules', 'Power to Frame Rules', 'for the fulfillment of the objectives of this Act.', 22, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 23 (Power to Frame Rules)', '2026-01-15T09:00:00.000Z'),
  ('doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1.23', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf', 'doc_nepal_citizenship_act_2063_2006__2063_nepal_citizenship_act_2063_pdf:1', 2, 'section', '24', 'Repeal and Savings:   (1) Nepal Citizenship Act. 2020 (1964) is hereby', 'Repeal and Savings', 'repealed. 
(2) All acts performed or actions taken under the r epealed Act pursuant to 
sub-section (1) shall be deemed to have been perfor med or undertaken under this 
Act.', 23, 'NEPAL CITIZENSHIP ACT 2063 (2006), Section 24 (Repeal and Savings)', '2026-01-15T09:00:00.000Z')
;

