  ('doc_police_rules_2049_1992__2049_nepal_poliru_pdf:2', 'doc_police_rules_2049_1992__2049_nepal_poliru_pdf', NULL, 1, 'chapter', 'Chapter - 1', 'Chapter - 1', NULL, NULL, 2, 'Police Rules, 2049 (1992), Chapter - 1', '2026-01-15T09:00:00.000Z'),
