INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_reg_civil_service_employee_conduct_2065:0', 'doc_reg_civil_service_employee_conduct_2065', NULL, 1, 'preamble', 'Preamble', 'Introductory matter', NULL, 'The Regulation Concerning the Conduct of Employees of the  Civil Service, 2065 B.S. (2009)
Date of Publication in the Nepal Gazette
2065/11/19 B.S. (March 2, 2009)
In exercise of the power conferred by Section 44 of the Good Governance (Management and Operation) Act, 2064 B.S. (2007), the Government of Nepal has, by virtue of Clause (c) of Sub-section (2) of Section 23 of the said Act, made these Rules.', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Preamble', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:1', 'doc_reg_civil_service_employee_conduct_2065', NULL, 1, 'chapter', 'Chapter-1', 'Preliminary', NULL, NULL, 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-1', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:1.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:1', 2, 'rule', 'Rule 1', 'Short Title and Commencement', 'Short Title and Commencement', NULL, 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-1 (Short Title and Commencement)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:1.0.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:1.0', 3, 'clause', '(1)', '', NULL, 'These Rules may be called the"Regulation Concerning the Conduct of Employees of the Civil Service,
2065 B.S. (2008).', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-1, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:1.0.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:1.0', 3, 'clause', '(2)', '', NULL, 'This Regulation shall come into effect at once.', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-1, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:1.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:1', 2, 'rule', 'Rule 2', 'Definitions', 'Definitions', 'Unless the subject or context otherwise requires, in this Regulation,', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-1 (Definitions)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:1.1.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:1.1', 3, 'clause', '(a)', '', NULL, '"Employee of the Civil Service" mean and include an employee working in the Civil Service in accordance with the
Civil Service Act, 2049 B.S. (1992) and an employee working in the health service in accordance with the Health Services Act, 2053 B.S. (1996).', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-1, Clause (a)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:1.1.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:1.1', 3, 'clause', '(b)', '', NULL, '"Family" means and includes the husband, wife, son, unmarried daughter, adopted son, unmarried adopted daughter, father, mother or step mother living together with, to be looked after by, a Civil Servant and in the case of a male employee or unmarried female employee their grandfather, grandmother, and in the case of a married female employee her father-in-law and mother-in-law.', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-1, Clause (b)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:1.1.2', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:1.1', 3, 'clause', '(c)', '', NULL, '"Office" means any Ministry, Secretariat, Commission or Department of the Government of Nepal or any other government  agency or office there under wherein a Civil servant is working.', 2, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-1, Clause (c)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2', 'doc_reg_civil_service_employee_conduct_2065', NULL, 1, 'chapter', 'Chapter-2', 'Provisions Relating to Official Conduct', NULL, '', 2, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2', 2, 'rule', 'Rule 3', 'Official Status to be Maintained', 'Official Status to be Maintained', NULL, 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2 (Official Status to be Maintained)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.0.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.0', 3, 'clause', '(1)', '', NULL, 'A Civil Servant shall, in discharging his official duties, always keep in mind the larger interest of the nation and the people and subject oneself to the existing laws.', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.0.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.0', 3, 'clause', '(2)', '', NULL, 'A Civil Servant shall, while owing allegiance to the Nepal Nation and Government, always remain alert not to do or allow to do any act in such manner as to compromise the status or dignity of his or her service.', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.0.2', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.0', 3, 'clause', '(3)', '', NULL, 'A Civil Servant shall always be positive and treat others in a polite and dignified manner for the sake of making his or her position and service dignified.', 2, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.0.3', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.0', 3, 'clause', '(4)', '', NULL, 'A Civil Servant shall carry out his or her official duty in a prompt manner.', 3, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.0.4', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.0', 3, 'clause', '(5)', '', NULL, 'In cases where there are separate conduct related provisions required to be followed by a serving Civil Servant, it shall be mandatory also to follow those provisions.', 4, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2', 2, 'rule', 'Rule 4', 'Due and Uniform Treatment to be Given', 'Due and Uniform Treatment to be Given', NULL, 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2 (Due and Uniform Treatment to be Given)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.1.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.1', 3, 'clause', '(1)', '', NULL, 'A Civil Servant shall give due and uniform treatment to all without distinction as to caste, creed, religion, language, sex, age, political or social standing, geographical factors, political affinity, access or relation, physical
condition, marital status or any of these.', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.2', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2', 2, 'rule', 'Rule 5', 'Only Official Functions to be Performed During Office Hours', 'Only Official Functions to be Performed During Office Hours', 'A Civil Servant shall perform only official functions in a designated place during office hours and he or she shall not, during office hours, engage oneself in personal or any other activity that is not related to a function of his or her office:
Provided that nothing herein shall prevent from imparting trainings on a subject related to his or her profession or duty in a publicly run university or any academy or educational institution imparting trainings in the public sector if such act does not hamper the work of his or her office.', 2, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2 (Only Official Functions to be Performed During Office Hours)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.3', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2', 2, 'rule', 'Rule 6', 'Bar to misuse office Equipment and Facilities', 'Bar to misuse office Equipment and Facilities', NULL, 3, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2 (Bar to misuse office Equipment and Facilities)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.3.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.3', 3, 'clause', '(1)', '', NULL, 'No Civil Servant shall use any machinery, equipment or other sources, materials and facilities meant for the purpose of the office for personal purpose and benefit.', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.3.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.3', 3, 'clause', '(2)', '', NULL, 'No Civil Servant shall, except on the order of a competent authority, move any machinery, equipment or other materials and facilities meant for the purpose of the office or give any of these things to any other person for use.', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.3.2', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.3', 3, 'clause', '(3)', '', NULL, 'No Civil Servant shall misuse any right, power, privilege or facility acquired by him or her in his or her official capacity.', 2, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.4', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2', 2, 'rule', 'Rule 7', 'Bar to disclose or misuse Information', 'Bar to disclose or misuse Information', NULL, 4, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2 (Bar to disclose or misuse Information)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.4.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.4', 3, 'clause', '(1)', '', NULL, 'No Civil Servant shall disclose any information to anybody that is deemed to be confidential by the existing laws.', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.4.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.4', 3, 'clause', '(2)', '', NULL, 'No Civil Servant shall disclose or use, for his or her personal or family benefit or the benefit of any other person, any information or notice that has come to his or her knowledge in his or her official capacity or in the course of discharging his or her duty or by any other means, regardless of whether or not such information or notice was
made available to him or her in his or her office.', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.4.2', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.4', 3, 'clause', '(3)', '', NULL, 'No Civil Servant, other than an Office-in-Charge, Information Officer or Spokesperson, shall make public any information not yet released by his or her office:
Provided that nothing herein shall prevent from giving information that has already been made public by his or her office.', 2, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.4.3', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.4', 3, 'clause', '(4)', '', NULL, 'While giving information to the public or to a person or civil servant in connection with the function of the office by an office, it is mandatory to give full and true information.', 3, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.4.4', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.4', 3, 'clause', '(5)', '', NULL, 'No Civil Servant shall use any information acquired in the discharge of his or her official duties for any purpose other than the one for which such information was meant or made available.', 4, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.4.5', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.4', 3, 'clause', '(6)', '', NULL, 'No Civil Servant, other than an Office-in-Charge, information officer or Spokesperson, shall without authorization, deliver a statement, give an interview or give information through any means of communication on any business of the office or any subject related thereto regardless of whether or not it is done on the condition of
anonymity. In giving such information or delivering such a statement or granting such an interview upon getting authorization, one should limit oneself to the facts and no personal view or opinion may be expressed on that.', 5, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (6)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.5', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2', 2, 'rule', 'Rule 8', 'Maintenance of Fairness in Official Duties', 'Maintenance of Fairness in Official Duties', NULL, 5, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2 (Maintenance of Fairness in Official Duties)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.5.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.5', 3, 'clause', '(1)', '', NULL, 'A Civil Servant shall discharge his or her official responsibility in a free and fair manner without being influenced by any undue influence, greed, pressure, recommendation of anybody or without prejudice and biasness to  anybody and without influenced by any consideration.', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.5.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.5', 3, 'clause', '(2)', '', NULL, 'No Civil Servant shall do any business dealing with anybody or institution that has something to do with the business of his or her office or to accept or take any present, gift, donation from any person or institution in such manner as to affect his or her official duties and shall not engage oneself, directly or indirectly, in raising donation, gift or funding for whatever purpose.', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.6', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2', 2, 'rule', 'Rule 9', 'Prohibition on engaging in Trade and Commercial Activities', 'Prohibition on engaging in Trade and Commercial Activities', 'Except as permitted by the existing law, no Civil servant shall, individually or jointly in collaboration with any person or group, engage in any trade and commercial activities regardless of whether such activities are carried out
directly or indirectly.', 6, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2 (Prohibition on engaging in Trade and Commercial Activities)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.7', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2', 2, 'rule', 'Rule 10', 'Necessity to give information on matters of interest', 'Necessity to give information on matters of interest', 'In cases where a Civil Servant has any personal interest in any matter relating to his or her office, such employee shall be required to inform the higher authority about the same.', 7, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2 (Necessity to give information on matters of interest)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.8', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2', 2, 'rule', 'Rule 11', 'Necessity to wear Identification Card, Dress', 'Necessity to wear Identification Card, Dress', NULL, 8, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2 (Necessity to wear Identification Card, Dress)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.8.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.8', 3, 'clause', '(1)', '', NULL, 'A Civil Servant shall, while on duty, wear his or her identification card conspicuously.', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.8.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.8', 3, 'clause', '(2)', '', NULL, 'A Civil Servant shall wear an eloquent dress.', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.8.2', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.8', 3, 'clause', '(3)', '', NULL, 'If any uniform has been prescribed for civil servants of a particular office, they shall wear such uniform on duty when they are in office and also during when they represent their office.', 2, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.9', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2', 2, 'rule', 'Rule 12', 'Political Neutrality to be Maintained', 'Political Neutrality to be Maintained', NULL, 9, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2 (Political Neutrality to be Maintained)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.9.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.9', 3, 'clause', '(1)', '', NULL, 'No Civil Servant shall engage in any activity that may promote any personal, commercial or political will of any political officials.', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.9.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.9', 3, 'clause', '(2)', '', NULL, 'No Civil Servant shall express any opinion in favour of or against any political party, its sister organizations or its leader nor shall a Civil Servant influence any of these in order to support or oppose. In matters of Trade Unions, it shall be dealt with as set forth in the relevant Act.', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.9.2', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.9', 3, 'clause', '(3)', '', NULL, 'A Civil Servant shall, while discharging his or her official duty, maintain political neutrality to the fullest extent.', 2, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.10', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2', 2, 'rule', 'Rule 13', 'Transparency to be Maintained', 'Transparency to be Maintained', 'A Civil Servant shall make transparent any service to be provided, supply or goods to be delivered by his or her office or the proceeding and the decision making process in the case of carrying out construction works.', 10, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2 (Transparency to be Maintained)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.11', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2', 2, 'rule', 'Rule 14', 'Service Delivery', 'Service Delivery', NULL, 11, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2 (Service Delivery)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.11.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.11', 3, 'clause', '(1)', '', NULL, 'A Civil Servant shall always endeavor to carry out any responsibility entrusted to him or her in a quick, prompt, perfect and qualitative manner.', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.11.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.11', 3, 'clause', '(2)', '', NULL, 'A Civil Servant shall, while delivering service, give priority to the aged, the handicapped, the dismembered, a woman who has recently given birth to a child, or a pregnant woman, children and the helpless.', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.11.2', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.11', 3, 'clause', '(3)', '', NULL, 'A Civil Servant shall deliver service to his or her client on time if, for any reason, service cannot be delivered on time or if a service intended by a client is not possible to deliver, he or she shall inform the client the ground and reason thereof as soon as possible.', 2, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.11.3', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.11', 3, 'clause', '(4)', '', NULL, 'A Civil Service shall facilitate the public to have easy and direct access to the government or public service and shall, as far as practicable, give information and advice in a simple and plain language.', 3, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (4)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.11.4', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.11', 3, 'clause', '(5)', '', NULL, 'If any information or particular of an agency of the Government of Nepal is required in the course of delivering service to any client, the service providing employee shall arrange to ask for such information or particular through his or her office.', 4, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (5)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.12', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2', 2, 'rule', 'Rule 15', 'Grievance Handling', 'Grievance Handling', NULL, 12, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2 (Grievance Handling)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.12.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.12', 3, 'clause', '(1)', '', NULL, 'A Civil servant shall be required to be sensitive all the time towards any grievance of citizens in matters of the
services delivered by his or her office in such manner as to have less grievance as far as possible.', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:2.12.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:2.12', 3, 'clause', '(2)', '', NULL, 'A Civil Servant shall respond to any information sought or grievance made or application made by a person in respect of any activity or business of his or her office in an appropriate and effective manner and with due respect and on time, and a Civil Servant acting as the Chief of the respective office shall make arrangements in such
manner as to handle such grievance appropriately and effectively in a timely manner.', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-2, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3', 'doc_reg_civil_service_employee_conduct_2065', NULL, 1, 'chapter', 'Chapter-3', 'Provisions Relating to Professional Ethics', NULL, '', 3, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:3', 2, 'rule', 'Rule 16', 'Knowledge of Law and Compliance', 'Knowledge of Law and Compliance', NULL, 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3 (Knowledge of Law and Compliance)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3.0.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:3.0', 3, 'clause', '(1)', '', NULL, 'A Civil Servant shall have, as a minimum, the knowledge of all the laws that are pertinent to his or her
work.', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3.0.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:3.0', 3, 'clause', '(2)', '', NULL, 'A Civil Servant shall always respect and observe the existing laws, decisions or orders of courts and decisions of the constitutional bodies and the Government of Nepal.', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:3', 2, 'rule', 'Rule 17', 'Necessity to respect the Profession', 'Necessity to respect the Profession', NULL, 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3 (Necessity to respect the Profession)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3.1.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:3.1', 3, 'clause', '(1)', '', NULL, 'A Civil Servant shall always make efforts to make his or her profession reputed and dignified by paying respect to the profession.', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3.1.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:3.1', 3, 'clause', '(2)', '', NULL, 'No expression shall be made or any information be released to the clients and the general public in such manner as to develop negative attitude towards the Civil Service.', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3.2', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:3', 2, 'rule', 'Rule 18', 'Making Efforts to develop one’s capacity', 'Making Efforts to develop one’s capacity', 'A Civil Servant shall always make efforts to develop his or her professional capacity while at  the same time discharging his or her official duties.', 2, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3 (Making Efforts to develop one’s capacity)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3.3', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:3', 2, 'rule', 'Rule 19', 'Necessity to observe the conditions of professional License', 'Necessity to observe the conditions of professional License', 'In cases where a Civil Servant is required to obtain a license to discharge his or her official duties, such a civil servant shall observe the conditions of the license.', 3, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3 (Necessity to observe the conditions of professional License)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3.4', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:3', 2, 'rule', 'Rule 20', 'Necessity to perform qualitatively', 'Necessity to perform qualitatively', NULL, 4, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3 (Necessity to perform qualitatively)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3.4.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:3.4', 3, 'clause', '(1)', '', NULL, 'A civil servant shall perform an entrusted responsibility in an honest manner and to the best of his or her
ability and quality.', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3.4.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:3.4', 3, 'clause', '(2)', '', NULL, 'A Civil Servant shall take responsibility for any act performed by him or her provided that no action may be taken against him or her in respect of acts performed in accordance with the law.', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3.4.2', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:3.4', 3, 'clause', '(3)', '', NULL, 'A civil servant shall, while giving advice to the Government of Nepal or any other entity, do so on any subject where advice has been sought in such manner as to be compatible with the law in a fair and honest manner.', 2, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3.5', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:3', 2, 'rule', 'Rule 21', 'Observance of Professional Guidelines', 'Observance of Professional Guidelines', 'Ethical Guidelines existing in any particular profession or job shall also be required to be observed by a civil servant working in that profession or sector.', 5, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3 (Observance of Professional Guidelines)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3.6', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:3', 2, 'rule', 'Rule 22', 'Instructions to be followed', 'Instructions to be followed', 'A civil servant shall follow instructions of higher authorities given in connection with the official business of the
Government or the Office in a prompt manner.', 6, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3 (Instructions to be followed)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3.7', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:3', 2, 'rule', 'Rule 23', 'Financial Discipline and Maintenance of Ethics', 'Financial Discipline and Maintenance of Ethics', NULL, 7, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3 (Financial Discipline and Maintenance of Ethics)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3.7.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:3.7', 3, 'clause', '(1)', '', NULL, 'A civil Servant shall perform his function with economy.', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3.7.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:3.7', 3, 'clause', '(2)', '', NULL, 'No civil servant or a member of his or her family shall pocket or cause to pocket, abandon or misuse or cause to misuse any  government fund or government or public property.', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:3.7.2', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:3.7', 3, 'clause', '(3)', '', NULL, 'No civil servant shall allow any political party or sister organization of political party or for any programme of such party or its sister organization to use any government or public property in an unauthorized manner.', 2, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-3, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:4', 'doc_reg_civil_service_employee_conduct_2065', NULL, 1, 'chapter', 'Chapter-4', '', NULL, NULL, 4, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-4', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:4.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:4', 2, 'rule', 'Rule 24', 'Not to be deemed to have acted in breach of conduct', 'Not to be deemed to have acted in breach of conduct', 'Notwithstanding anything contained elsewhere in this Regulation, the following acts shall not be deemed a violation of any conduct of this Regulation.', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-4 (Not to be deemed to have acted in breach of conduct)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:4.0.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:4.0', 3, 'clause', '(a)', '', NULL, 'To give a written or oral speech in his or her area of expertise and do study or teaching with prior approval if such acts are done outside office hours and without prejudice to the functioning of the office,', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-4, Clause (a)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:4.0.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:4.0', 3, 'clause', '(b)', '', NULL, 'To become a member of a professional or social institution relating to literature, art, culture, sports, knowledge science and technology and to participate in such forums,', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-4, Clause (b)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:4.0.2', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:4.0', 3, 'clause', '(c)', '', NULL, 'To participate, outside office hours, in meetings or seminars organized by professional unions and associations other than those organized by political parties or their sister organizations,', 2, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-4, Clause (c)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:4.0.3', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:4.0', 3, 'clause', '(d)', '', NULL, 'To publish articles, write ups in such manner as not to make adverse effect on the policy, objectives, programmes, functioning and secrecy of the Government,', 3, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-4, Clause (d)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:4.0.4', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:4.0', 3, 'clause', '(e)', '', NULL, 'To participate in a competition opened to all and to accept a prize, medal, certificate or commendation,', 4, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-4, Clause (e)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:4.0.5', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:4.0', 3, 'clause', '(f)', '', NULL, 'To initiate necessary proceedings in offices or courts to get remedy as an aggrieved party in accordance with the laws.', 5, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-4, Clause (f)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:5', 'doc_reg_civil_service_employee_conduct_2065', NULL, 1, 'chapter', 'Chapter-5', 'Miscellaneous', NULL, '', 5, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-5', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:5.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:5', 2, 'rule', 'Rule 25', 'Personal Conduct', 'Personal Conduct', NULL, 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-5 (Personal Conduct)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:5.0.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:5.0', 3, 'clause', '(1)', '', NULL, 'A civil servant shall display due courtesy and respect towards higher authorities and behave oneself duly with
subordinate staff.', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:5.0.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:5.0', 3, 'clause', '(2)', '', NULL, 'No civil servant shall engage in gambling, playing cards and consume alcohol in public places or shall not do anything or display any behavior that may be deplorable in society.', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:5.0.2', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:5.0', 3, 'clause', '(3)', '', NULL, 'A civil servant shall always make efforts to enhance the faith of the public in the Government of Nepal and the Civil Service.', 2, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-5, Clause (3)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:5.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:5', 2, 'rule', 'Rule 26', 'Duty to notify', 'Duty to notify', NULL, 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-5 (Duty to notify)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:5.1.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:5.1', 3, 'clause', '(1)', '', NULL, 'If a civil servant comes to know or gets information to the effect that a person has committed or about to commit any act to harm or damage any government or public property, he or she, if it falls within his or her authority, shall make appropriate arrangement to protect the property in question and if the matter falls within the jurisdiction of some other entity or body, he or she shall inform the in Charge of such entity or office of the incident forthwith.', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:5.1.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:5.1', 3, 'clause', '(2)', '', NULL, 'In cases where a Civil Servant gets information to the effect that somebody is about to commit or is committing any unlawful act or criminal act, he or she shall, forthwith, inform the entity concerned or his or her Office In-Charge.', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:5.2', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:5', 2, 'rule', 'Rule 27', 'Power to make Extra code of conduct as per the nature of Work', 'Power to make Extra code of conduct as per the nature of Work', 'Ministries or Secretaries and their subordinate agencies performing different nature of functions shall have the power to make and enforce extra code of conduct in accordance with the nature of their work.', 2, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-5 (Power to make Extra code of conduct as per the nature of Work)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:5.3', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:5', 2, 'rule', 'Rule 28', 'Duty of Retired Employee to observe', 'Duty of Retired Employee to observe', NULL, 3, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-5 (Duty of Retired Employee to observe)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:5.3.0', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:5.3', 3, 'clause', '(1)', '', NULL, 'A retired Civil Servant shall as well observe the provisions contained in Rules 3,7,17, and 26 of this
Regulation.', 0, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-5, Clause (1)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:5.3.1', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:5.3', 3, 'clause', '(2)', '', NULL, 'It will not be allowed to disclose or cause to disclose, in any manner, any unpublished information that had come to his or her knowledge in the course of discharging official duties during when he or she was in service even after his or her retirement.', 1, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-5, Clause (2)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:5.4', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:5', 2, 'rule', 'Rule 29', 'Provision relating to Follow-up', 'Provision relating to Follow-up', 'Each and every Ministry, Secretariat, Commission or other central-level agency, shall on a regular basis,
follow up on whether or not an employee working in or under it, has followed the provisions of this Regulation and make arrangements to take departmental actions against violators in accordance with the
existing laws.', 4, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-5 (Provision relating to Follow-up)', '2026-01-15T09:00:00.000Z'),
  ('doc_reg_civil_service_employee_conduct_2065:5.5', 'doc_reg_civil_service_employee_conduct_2065', 'doc_reg_civil_service_employee_conduct_2065:5', 2, 'rule', 'Rule 30', 'Dissemination of the Regulation', 'Dissemination of the Regulation', 'After the commencement of this Regulation, offices shall disseminate the provisions of this Regulation among their staffs.', 5, 'The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009), Chapter-5 (Dissemination of the Regulation)', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:0', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', NULL, 1, 'preamble', 'Preamble', 'Introductory matter', NULL, 'Right to Information Act, 2064 (2007 )
Date of Authentication and publication
5 Shrawan (21 July 2007)
An act No 4 of the year 2064
AN ACT TO MAKE PROVISION FOR RIGHT TO INFORMATION
Preamble, Whereas; it is expedient to make the functions of the sate open and
transparent in accordance with the democratic system and to make responsible and
accountable to the citizen; to make the access of citizens simple and easy to the
information of public importance held in public bodies; to protect sensitive information
that could make adverse impact on the interest of the nation and citizen, and for the
necessity to have legal provisions to protect the right of the citizen to be well-informed
and to bring it into practice, the ''Legislature-Parliament'' has enacted this Act.', 0, 'Right to Information Act, 2064 (2007 ), Preamble', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:1', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', NULL, 1, 'chapter', 'Chapter- one', 'Chapter- one', NULL, NULL, 1, 'Right to Information Act, 2064 (2007 ), Chapter- one', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:1.0', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:1', 2, 'section', '1', 'Short title and commencement: (1) This Act may be called ''Right to', 'Short title and commencement', 'Information Act, 2064 B.S. (2007 A.D.).
th
(2) This Act shall come into force from the 30 (Thirty) day of certification.', 0, 'Right to Information Act, 2064 (2007 ), Chapter- one, Section 1 (Short title and commencement)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:1.1', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:1', 2, 'section', '2', 'Definition: Unless the subject or context otherwise requires, in this Act:', 'Definition', '(a) "Public Body" means the following body and institution list:
(1) A body under the constitution,
(2) A body established by an Act,
(3) A body formed by the Government of Nepal,
1
(4) Institution or foundation established by the law, public service.
(5) Political Party or organization registered under the preventing law.
(6) Body Corporate under the full or partial ownership or under control
of the Government of Nepal or such body receiving grants from the
Government of Nepal.
(7) Body Corporate formed by a Body established by the Government of
Nepal or the law upon entering into an agreement,
(8) Non-Governmental Organization/Institutions operated by obtaining
money directly or indirectly from the Government of Nepal or
Foreign Government or International Organizations/Institutions,
(9) Any other Body or Institution prescribed as Public Body by the
Government of Nepal by publishing notice in the Gazette.
(b) "Information" means any written document, material, or information related
to the functions, proceedings thereof or decision of public importance made
by a Public Body.
(c) "Public Importance" means a subject related directly or indirectly with the
interest of citizens.
(d) "Document" means any kind of scripted document and the word shall also
includes any audio visual material collected and updated through a
mechanical medium or that can be printed or retrieved.
(e) "Right to Information" means the right to ask for and obtain information of
public importance held in the Public Bodies and this term shall also include
the right to study or observation of any written document, material held in
Public Body or proceedings of such Public Body; to obtain a verified copy
of such document, to visit or observe the place where any construction of
public importance is going on and to obtain verified sample of any material
or to obtain information held in any type of machine through such machine.
(f) "Information Authority" means a person appointed in pursuant to with
Section 6.
2
(g) "Chief" means the Chief of a Public Body.
(h) "Commission" means the National Information Commission constituted in
pursuant to Section 11.
(i) "Chief Information Commissioner" means a person appointed pursuant to
Section 11.
(j) "Information Commissioner" means a person appointed pursuant Section
11.
(k) "Prescribed" or "as prescribed" means prescribed or as prescribed in Rules
framed under this Act.', 1, 'Right to Information Act, 2064 (2007 ), Chapter- one, Section 2 (Definition)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:2', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', NULL, 1, 'chapter', 'Chapter- 2', 'Chapter- 2', NULL, NULL, 2, 'Right to Information Act, 2064 (2007 ), Chapter- 2', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:2.0', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:2', 2, 'section', '3', 'Right to Information: (1) Every citizen shall, subject to this Act have the right', 'Right to Information', 'to information.
(2) Every citizen shall have access to the information held in the public
Bodies.
(3) Notwithstanding anything provided in Sections (1) and (2), the
information held by a Public Body on the following subject matters shall not be
disseminated:
(a) which seriously jeopardizes the sovereignty, integrity, national
security, public peace, stability and international relations of Nepal.
(b) which directly affects the investigation, inquiry and prosecution of a
crime.
(c) Which seriously affects on the protection of economic, trade or
monetary interest or intellectual property or banking or trade
privacy.
(d) Which directly jeopardizes the harmonious relationship subsisted
among various cast or communities.
3
(e) Which interferes on individual privacy and security of body, life,
property or health of a person.
Provided that, a public Body shall not refrain from the
responsibility of dissemination of information without appropriate
and adequate reason not to flow the information.
(4) If a Public Body has both the information in its record that can be made
public and that cannot be made public in accordance with this Act, the Information
Officer shall have to provide information to the applicant after separating the
information which can be made public.', 0, 'Right to Information Act, 2064 (2007 ), Chapter- 2, Section 3', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:2.1', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:2', 2, 'section', '4', 'Responsibility of a Public Body: (1) Each Public Body has to respect and', 'Responsibility of a Public Body', 'protect the right to information of citizen.
(2) Public Body shall have following responsibilities for the purpose of
Sub-Section (1):
(a) to classify and update information and make them public, publish
and broadcast,
(b) to make the citizens'' access to information simple and easy,
(c) to conduct its functions openly and transparently,
(d) to provide appropriate training and orientation to its staffs,
(3) Public Body may use different national languages and mass media
while publishing, broadcasting or making information public in accordance with
Section (a) of Section (2).', 1, 'Right to Information Act, 2064 (2007 ), Chapter- 2, Section 4 (Responsibility of a Public Body)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:2.2', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:2', 2, 'section', '5', 'Updating and Publication of Information: (1) A Public Body shall keep its', 'Updating and Publication of Information', 'information updated.
(2) A Public Body, as long as possible, shall update at least of twenty years
old information from the commencement of this Act related to it in pursuant to
Sub-Section (1).
(3) A Public Body shall enlist and publish its following information:
(a) structure and nature of Body,
4
(b) functions, duties, and powers of Body,
(c) number of employees and working details of Body,
(d) service to be rendered by the Body,
(e) branch and responsible officer of the service providing Body,
(f) fee and time limit required for service,
(g) decision making process and authority,
(h) authority to hear appeal against decision
(i) description of functions performed
(j) name and designation of Chief and Information Officer
(k) list of Acts, Rules, By Laws or Guidelines
(l) updated description of income, expenditures and financial
transactions.
(m) other particulars as prescribed.
(4) Public Body shall have to update and publish the information in
accordance with Sub-Section (3) within three months from the date of
commencement of this Act and in every three months thereafter.', 2, 'Right to Information Act, 2064 (2007 ), Chapter- 2, Section 5 (Updating and Publication of Information)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:2.3', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:2', 2, 'section', '6', 'Provision of Information Officer: (1) A Public Body shall arrange for an', 'Provision of Information Officer', 'Information Officer for the purpose of disseminating information held in its office.
(2) For the purpose of disseminating information in accordance with Sub-
Section (1), the Chief has to regularly provide information held in the office to the
Information Officer.
(3) Public Body shall set up an Information Section for the purpose of
disseminating information as per necessity.', 3, 'Right to Information Act, 2064 (2007 ), Chapter- 2, Section 6 (Provision of Information Officer)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:2.4', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:2', 2, 'section', '7', 'Procedures of Acquiring Information: (1) A Nepali Citizen, who is', 'Procedures of Acquiring Information', 'interested to obtain any information under this Act, shall submit an application
before concerned Information Officer by stating reason to receive such
information.
(2) If an application is received pursuant to Sub-Section (1), Information
Officer should provide the information immediately if the information by its
5
nature could be provided immediately and has to provide within fifteen days from
the date of application if the information by its nature could not be provided
immediately.
(3) If information cannot be provided immediately pursuant to Sub-Section
(2), Information Officer should instantly give a notice with reason to the applicant.
(4) Notwithstanding anything contained in Sub-Section (3), if the requested
information is related to the security of life of person, the information officer
should provide such information within Twenty Four hours of such request.
(5) Information Officer has to provide information in the format as
demanded by the applicant as much as possible.
(6) Notwithstanding anything contained in Sub-Section (5), if any
possibility subsist that the source of information may be damaged or destroyed or
spoilt if it is provided in the format as requested by the applicant, the Information
Officer shall provide such information in appropriate format with stating reason
thereof.
(7) If any individual submitted an application to study or observe the
document, material or activity pursuant to Sub-Section (1), the Information Officer
shall provide a reasonable time to the applicant for the study and observation of
such document, material or activity.
(8) While examining the application received in pursuant to Sub-Section
(1), it is found that the information demanded by the applicant is not related to
such Body, the Information Officer should give notification to the applicant
immediately.', 4, 'Right to Information Act, 2064 (2007 ), Chapter- 2, Section 7 (Procedures of Acquiring Information)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:2.5', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:2', 2, 'section', '8', 'Fee for information: (1) Applicant shall pay fee as prescribed while requesting', 'Fee for information', 'information pursuant with Section 7.
Provided that, if different fees are prescribed for any specific information in the
prevailing law, it shall be collected accordingly.
(2) The fee structure, pursuant to Sub-Section (1), shall be based on the
actual cost of providing information.
6
(3) If the fee prescribed pursuant to Sub-Section (2) is deemed more than
the actual price, the concerned person may file a petition before the Commission.
(4) While examining the petition pursuant to Sub-Section (3), the
commission may order to review the fee if it is found in contrary to Sub-Section
(2).
9 Complaint may be made: (1) If, Information Officer, does not provide
information, denies to provide information, partially provides information,
provides wrong information or does not provide information by stating that the
applicant is not a stakeholder, the concerned person shall make a complaint to the
Chief within (7) days from the date of information denied or partially information
received.
(2) While investigating the complaint received pursuant to Sub-Section (1),
the Chief shall order the Information Officer to provide information as demanded
by applicant if it is found that the information was denied or partially provided or
wrong information was provided and the Information Officer has to provide
information to the concerned applicant if such order is issued.
(3) While conducting investigation pursuant Sub-Section (2), if it is found
that the Information Officer denied to provide information or partially provided
the information knowingly or with mala fide intention or provided wrong
information, the Chief may take departmental action against such Information
Officer.
(4) While investigating pursuant to Sub-Section (2), if it is found that the
information cannot be provided; the Chief shall make a decision accordingly and
provide a notice stating the reasons to the applicant.', 5, 'Right to Information Act, 2064 (2007 ), Chapter- 2, Section 8 (Fee for information)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:2.6', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:2', 2, 'section', '10', 'Appeal can be made: (1) An individual, who is aggrieved by the decision of the', 'Appeal can be made', 'Chief made pursuant to Sub-Section (4) of Section 9, shall appeal before the
Commission within Thirty Five (35) days of the notice of decision received.
(2) Commission may summon and take statement of the concerned Chief or
Information Officer, order to submit a document, take statement of witness and
7
evidence or demand copy of the document from a Public Body while deciding the
appeal received pursuant Sub-Section (1).
(3) In the course of proceeding and deciding the appeal pursuant to Sub-
Section (2), the Commission may do as following:
(a) May order the concerned Chief to provide information, within a
given time, to the appellant without fee, if appeal is found
reasonable.
(b) May dismiss the appeal if it is found not reasonable.
(4) The Commission has to give final verdict on the appeal within sixty
days of the appeal.
(5) Other procedures to be followed by the commission during appeal
pursuant to this Section shall be as prescribed.', 6, 'Right to Information Act, 2064 (2007 ), Chapter- 2, Section 10 (Appeal can be made)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', NULL, 1, 'chapter', 'Chapter 3', 'Chapter 3', NULL, NULL, 3, 'Right to Information Act, 2064 (2007 ), Chapter 3', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3.0', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3', 2, 'section', '11', 'Provision Regarding Commission: (1) There shall be an independent National', 'Provision Regarding Commission', 'Information Commission for the protection, promotion and practice of right to
information.
(2) A Chief Information Commissioner and two other Information
Commissioners shall be in the commission.
(3) In order to appoint Chief Information Commissioner and Information
Commissioner, there shall be a committee comprised as follows:
(a) The Speaker – Chairperson
(b) Minister or State Minister for Information and Communication –
Member
(c) President, Federation of Nepalese Journalists – Member
(4) The Government of Nepal, on the recommendation of the Committee
under Sub-Section (3), shall appoint a Chief Information Commissioner and
Information Commissioners, at least one female shall be included in such
8
appointment.
(5) The Committee pursuant Sub-Section (3) shall follow the inclusive
principle as much as possible while recommending for appointment of Chief
Information Commissioner and Information Commissioners.
(6) The procedures of recommendation pursuant to Sub-Section (3) shall be
as determined by the Recommendation Committee itself.', 0, 'Right to Information Act, 2064 (2007 ), Chapter 3, Section 11 (Provision Regarding Commission)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3.1', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3', 2, 'section', '12', 'Qualifications: One shall have the following qualifications to be appointed for', 'Qualifications', 'the post of the Chief Information Commissioner and Information Commissioners:
(a) Nepali citizen,
(b) holding at least a Bachelor Degree from a recognized University,
(c) having at least fifteen years of working experience in the field of
Mass communication, law justice, public administration,
information technology or management.', 1, 'Right to Information Act, 2064 (2007 ), Chapter 3, Section 12 (Qualifications)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3.2', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3', 2, 'section', '13', 'Disqualifications: A person with any of the following disqualification shall be', 'Disqualifications', 'disqualified to be appointed in the post of Chief Information Commissioner and
Information Commissioners:
(a) not having the qualification pursuant Section 12,
(b) convicted by the court in a criminal offence with moral turpitude,
(c) incumbent employee of Government or Public institution,
(d) incumbent in any political position,
(e) Disqualified for appointment under the prevailing laws.', 2, 'Right to Information Act, 2064 (2007 ), Chapter 3, Section 13 (Disqualifications)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3.3', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3', 2, 'section', '14', 'Tenure of Office: (1) The tenure of office of the Chief Information', 'Tenure of Office', 'Commissioner and the Information Commissioner shall be for five years and s/he
shall not be re-appointed in the same Post.
(2) Notwithstanding anything contained in Sub-Section (1), the Information
Commissioner may be re-appointed in the post of Chief Information
Commissioner subject to the provision of tenure of office stated in the same Sub-
Section.
(3) The recommendation committee pursuant to Sub-Section (3) of Section
9
11, shall recommend for new appointment of Chief Information Commissioner
and Information Commissioners one month period to the expiry of the tenure of
the office .', 3, 'Right to Information Act, 2064 (2007 ), Chapter 3, Section 14 (Tenure of Office)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3.4', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3', 2, 'section', '15', 'Post to be Vacated: The post the Chief Information Commissioner and', 'Post to be Vacated', 'Information Commissioner shall be considered vacant under the following
conditions:
(a) In case of his/her death,
(b) In case, s/he completes the age of 65 years,
(c) In case, s/he tenders resignation to the Prime Minister,
(d) In case, his/her term of office is completed,
(e) In case, s/he is convicted by the court in a criminal offence with
moral turpitude ,
(f) In case of s/he is removed from the post pursuant to Section 16.', 4, 'Right to Information Act, 2064 (2007 ), Chapter 3, Section 15 (Post to be Vacated)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3.5', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3', 2, 'section', '16', 'May Remove From Office: If the meeting of the Legislature-Parliament', 'May Remove From Office', 'endorse the recommendation of the information and communication related
committee of the Legislature-Parliament, with the two third majority of meeting
presented by at least two third members out of total members, for removing Chief
Information Commissioner or Information Commissioner on the ground that s/he
is not fit to hold office for the reason of incompetence or misbehavior or not
carrying out the duties honestly, such Chief Information Commissioner or
Information Commissioner shall be removed from his/her office.
Provided that, the Chief Information Commissioner or Information Commissioner
charged with such accusation shall not be denied for reasonable opportunity of
clarification.', 5, 'Right to Information Act, 2064 (2007 ), Chapter 3, Section 16 (May Remove From Office)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3.6', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3', 2, 'section', '17', 'Provision Regarding the Conditions of Service: The remuneration,', 'Provision Regarding the Conditions of Service', 'conditions of service and facilities for Chief Information Commissioner and
Information Commissioner shall be as prescribed.
10', 6, 'Right to Information Act, 2064 (2007 ), Chapter 3, Section 17 (Provision Regarding the Conditions of Service)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3.7', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3', 2, 'section', '18', 'Oath of Office: Before taking charge of the office, the Chief Information', 'Oath of Office', 'Commissioner shall take the oath of office before the Prime Minister and the
Information Commissioner before the Chief Information Commissioner
respectively in the format as laid down in the Schedule.', 7, 'Right to Information Act, 2064 (2007 ), Chapter 3, Section 18 (Oath of Office)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3.8', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3', 2, 'section', '19', 'Functions, Duties and Powers of the Commission: In addition to the', 'Functions, Duties and Powers of the Commission', 'functions, duties and powers stated elsewhere in this Act, the functions, duties and
powers of the Commission shall be as follows:
(a) To observe and study the records and documents of public
importance held in Public Bodies,
(b) To issue order to such Body to enlist and manage the records,
documents and other materials pertaining the information
(c) To issue order to the concerned Public Body to make information
public for citizen''s notification,
(d) To prescribe timeframe and order concerned Public Body to
provide information demanded by applicant within such timeframe.
(e) To order concerned party to fulfill the liability as mentioned in this
Act.
(f) To provide necessary suggestions and recommendations to the
Government of Nepal and other bodies related to information and
communications regarding the protection and promotion of right to
information.
(g) To issue other appropriate orders regarding the protection,
promotion and exercise of right to information.', 8, 'Right to Information Act, 2064 (2007 ), Chapter 3, Section 19 (Functions, Duties and Powers of the Commission)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3.9', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3', 2, 'section', '20', 'Delegation of Power: The commission may delegate any of the functions, duties', 'Delegation of Power', 'or powers, except the power to hear and decide an appeal under Section 9, to the
Chief Information Commissioner, Information Commissioner or any other body or
official, subject to the terms and conditions prescribed for that purpose.', 9, 'Right to Information Act, 2064 (2007 ), Chapter 3, Section 20 (Delegation of Power)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3.10', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3', 2, 'section', '21', 'Office of the Commission: The central office of the Commission shall be', 'Office of the Commission', '11
located in Kathmandu Valley and the Commission may open its offices in various
places of the country as per necessity.', 10, 'Right to Information Act, 2064 (2007 ), Chapter 3, Section 21 (Office of the Commission)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3.11', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3', 2, 'section', '22', 'Staffs of the Commission: (1) Required number of staffs shall be there at the', 'Staffs of the Commission', 'Commission.
(2) The Government of Nepal shall manage the staffs required for the
Commission.', 11, 'Right to Information Act, 2064 (2007 ), Chapter 3, Section 22 (Staffs of the Commission)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3.12', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3', 2, 'section', '23', 'Expenditure of the Commission: (1) The Government of Nepal shall arrange', 'Expenditure of the Commission', 'necessary budget for the Commission.
(2) The Commission shall also receive necessary financial resources from
other sectors after getting prior permission of the Government of Nepal.', 12, 'Right to Information Act, 2064 (2007 ), Chapter 3, Section 23 (Expenditure of the Commission)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3.13', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3', 2, 'section', '24', 'Cooperate with the Commission: Public bodies shall provide necessary', 'Cooperate with the Commission', 'cooperation in the activities of the commission.', 13, 'Right to Information Act, 2064 (2007 ), Chapter 3, Section 24 (Cooperate with the Commission)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3.14', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3', 2, 'section', '25', 'Annual Report: (1) The commission shall submit annual Report of its activities', 'Annual Report', 'to the Legislature-Parliament through Prime Minister.
(2) The Commission shall publish, the Annual Report pursuant Sub-Section
(1) publicly for the purpose of public notice.', 14, 'Right to Information Act, 2064 (2007 ), Chapter 3, Section 25 (Annual Report)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3.15', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:3', 2, 'section', '26', 'Contact With the Government of Nepal: The Commission shall contact with', 'Contact With the Government of Nepal', 'the Government of Nepal through the Ministry of Information and
Communication.', 15, 'Right to Information Act, 2064 (2007 ), Chapter 3, Section 26 (Contact With the Government of Nepal)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:4', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', NULL, 1, 'chapter', 'Chapter- 4', 'Chapter- 4', NULL, NULL, 4, 'Right to Information Act, 2064 (2007 ), Chapter- 4', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:4.0', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:4', 2, 'section', '27', 'Provision Regarding Classification of Information: (1) For the protection', 'Provision Regarding Classification of Information', 'of the information related to Sub-Section (3) of Section 3, held in public Body,
there shall be a committee as following to classify the information in policy level:
(a) Chief Secretary of the Government of Nepal- Chairperson
(b) Secretary of the concerned Ministry – Member
(c) Expert of concerned subject assigned by the Chief of Office or
Chairperson – Member
12
(2) The Committee pursuant to Sub-Section (1), regarding the classification
of information under Sub-section 3 of Section (3), has to inform the Commission
by determining the number of years the information should be kept confidential
and method for the protection of information.
(3) A person, who is not satisfied with the classification made by the
committee pursuant to Sub-section (2) may file a review petition before the
commission to make the information public.
(4) The Commission, shall if it finds that any information need not be kept
confidential in the course of review of the petition pursuant to Sub-section (3),
issue an order to public such information.
(5) The information classified pursuant to the Sub-Section (2) may be kept
confidential for a maximum period of thirty years, according to the nature of the
information.
(6) Notwithstanding anything contained in Sub-Section (5), the Committee
shall review in every ten years that any information classified as confidential is
necessary to keep as confidential or not.
(7) While reviewing pursuant to Sub-Section (6), the Committee, if finds
necessary to keep such information confidential for additional period, may decide
the duration and classify as confidential for that period or may classify as non-
confidential if finds not necessary to keep confidential.', 0, 'Right to Information Act, 2064 (2007 ), Chapter- 4, Section 27 (Provision Regarding Classification of Information)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:4.1', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:4', 2, 'section', '28', 'Protection of Information: (1) Public Body shall protect the information of', 'Protection of Information', 'personal nature held in for preventing unauthorized publication and broadcasting.
(2) Personal information held in public Body, except in following
conditions, shall not be used without written consent of concerned person.
(a) In case of preventing a serious threat to life and body of a person or
public health or security.
(b) If required to be disclosed in accordance with prevailing laws.
(c) If required to control the offence of corruption.', 1, 'Right to Information Act, 2064 (2007 ), Chapter- 4, Section 28 (Protection of Information)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:4.2', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:4', 2, 'section', '29', 'Protection of Whistleblower: (1) It shall be a responsibility of an employee of', 'Protection of Whistleblower', '13
a Public Body to provide information on any ongoing or probable corruption or
irregularities or any deed taken as offence under the prevailing laws.
(2) It shall be the duty of the information receiver to make the identity of
whistleblower in accordance with Sub-Section (1) confidential.
(3) The whistleblower shall not be terminated from his/her post or punished
with any legal responsibility or caused any loss or harm for giving
information pursuant to Sub-section (1)
(4) If any punishment or harm is done to the whistleblower against Sub-Section
(3), the whistleblower may complaint, along with demand for
compensation, before the commission for revoking such decision.
(5) While investigating the complaint pursuant to Sub-Section (4), the
Commission may order to revoke the decision of removal from the office if
so removed from office and for the compensation if any damages caused to
the whistleblower.', 2, 'Right to Information Act, 2064 (2007 ), Chapter- 4, Section 29 (Protection of Whistleblower)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:4.3', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:4', 2, 'section', '30', 'Providing Personal Information: (1) Concerned Body shall provide', 'Providing Personal Information', 'information to the concerned person holding a public post, if such concerned
person demands information of during his service in the public Body.
(2) if a person demands for information related with him/her held in
Public Body that Information shall be made available to that person.
(3) The procedure for demanding and acquiring information pursuant to
Sub-Section (1) shall be as mentioned in Section 7.
(4) Fees to received the information pursuant to Sub-section (1) shall be
as prescribed in Section 8.', 3, 'Right to Information Act, 2064 (2007 ), Chapter- 4, Section 30 (Providing Personal Information)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:4.4', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:4', 2, 'section', '31', 'Information not to be Misused: (1) A person who obtains information from a', 'Information not to be Misused', 'Public Body shall not misuse the information by not using it for the same purpose
that was considered.
(2) The concerned Public Body may complain to the Commission
against a person who misuses the information against Sub-Section (1).
14', 4, 'Right to Information Act, 2064 (2007 ), Chapter- 4, Section 31 (Information not to be Misused)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:5', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', NULL, 1, 'chapter', 'Chapter- 5', 'Chapter- 5', NULL, NULL, 5, 'Right to Information Act, 2064 (2007 ), Chapter- 5', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:5.0', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:5', 2, 'section', '32', 'Punishment: (1) If the Commission finds that Chief of public Body or', 'Punishment', 'Information Officer has held back information without valid reason, refused to
information or provided partial or wrong information or destroyed information; the
Commission may impose a fine to such Chief or Information Officer from Rupees
One Thousand Rupees to Twenty Five Thousand Rupees and if such Chief or
Information Officer is in eligible for departmental action, it may write to the
concerned Body for departmental action.
(2) If the Chief of a public Body or Information Officer, delay to provide
information which has to be provided on time without reason, shall be
punished with a fine of Two Hundred Rupees per day so is delayed to
provide the information.
(3) If the Commission writes to the concerned Body for Departmental action
pursuant to Sub-Section (1), the Public Body shall take Departmental action
against that Chief or Information Officer within three months and notify the
same to the Commission.
(4) The Commission may impose a fine between Five Thousand Rupees to
Twenty Five Thousand Rupees considering that seriousness of misuse of
information if any person is found misusing the information acquired from
public Body instead of using it for purpose it was obtained for.
(5) The Commission may impose a fine up to Ten Thousand Rupees to the
concerned person in case its decision or order pursuant this Act is not
abided by.', 0, 'Right to Information Act, 2064 (2007 ), Chapter- 5, Section 32 (Punishment)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:5.1', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:5', 2, 'section', '33', 'Compensation: (1) If person incur losses and damages due to not providing', 'Compensation', 'information, denying to provide information, providing partial or wrong
information or destroying the information by the Chief or Information Officer of
Public Body, such person may file a petition before the Commission for
15
compensation within three months from the date of not acquiring information,
acquiring partial or wrong information or restriction of the information.
(2) If the application pursuant to Sub-Section (1) is found reasonable upon
the investigation, the Commission may compensate the applicant from the
concerned Body with reasonable amount upon considering the actual loses.', 1, 'Right to Information Act, 2064 (2007 ), Chapter- 5, Section 33 (Compensation)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:5.2', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:5', 2, 'section', '34', 'Appeal: A person not satisfied with the decision rendered by the Commission', 'Appeal', 'pursuant to Section 32, may appeal before the Appellate Court within thirty five
days of decision received.', 2, 'Right to Information Act, 2064 (2007 ), Chapter- 5, Section 34 (Appeal)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:6', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', NULL, 1, 'chapter', 'Chapter- 6', 'Chapter- 6', NULL, NULL, 6, 'Right to Information Act, 2064 (2007 ), Chapter- 6', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:6.0', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:6', 2, 'section', '35', 'Information may be Corrected: (1) If anyone believes that the information in', 'Information may be Corrected', 'a Public Body on a particular matter is wrong, s/he may file an application before
the concerned Chief along with necessary evidence for the correction of the
information.
(2) The Chief shall conduct necessary investigation regarding the application
pursuant to Sub-Section (1) and if the information held in such Body is found wrong
in the course of investigation, he/she should inform the applicant upon correcting
within seven days from the date of application imformation.', 0, 'Right to Information Act, 2064 (2007 ), Chapter- 6, Section 35 (Information may be Corrected)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:6.1', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:6', 2, 'section', '36', 'Save to Works done with Good Faith: Notwithstanding anything contained', 'Save to Works done with Good Faith', 'elsewhere in this Act, no case shall be filed and no punishment shall be imposed
against the Chief or Information Officer for his/her works regarding the
dissemination of in forvevtion good faith.', 1, 'Right to Information Act, 2064 (2007 ), Chapter- 6, Section 36 (Save to Works done with Good Faith)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:6.2', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:6', 2, 'section', '37', 'To be Pursuant to this Act: All the matters mentioned in this Act shall be', 'To be Pursuant to this Act', 'carried out in accordance with this Act, whereas other matters shall be dealt with
pursuant to prevalent laws.', 2, 'Right to Information Act, 2064 (2007 ), Chapter- 6, Section 37 (To be Pursuant to this Act)', '2026-01-15T09:00:00.000Z'),
  ('doc_right_to_information_act_2064_2007_2064_right_to_information_act_:6.3', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_', 'doc_right_to_information_act_2064_2007_2064_right_to_information_act_:6', 2, 'section', '38', 'Power to Frame Rules: The Government of Nepal, upon consultation with the', 'Power to Frame Rules', 'Commission shall frame necessary Rules to implement the objectives of this Act.
16
Schedule
(Related to Section 18)
Oath
I …………………….. ,hereby, faithful to the state and the people promise with truth and
trust/take the oath in the name of God that highly respecting the shall expressed by the
people through the people''s movement that Nepal''s state authority and sovereignty is to
be vested only on the people, professing allegiance to the constitution of Nepal and laws
of the land, I shall carry out my responsibilities with honesty and without any fear,
sycophancy, partiality, malice or greed, by honoring citizen''s right to information and for
the effective implementation and practice of laws pertaining to right to information.
17', 3, 'Right to Information Act, 2064 (2007 ), Chapter- 6, Section 38 (Power to Frame Rules)', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:0', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', NULL, 1, 'preamble', 'Preamble', 'Introductory matter', NULL, 'www.lawcommission.gov.np
The Act Relating to Children, 2075 (2018)
Date of authentication:
2075/06/02 (18 September 2018)
Act Number 23 of the year 2075 (2018)
An Act Made for Amendment and Consolidation of the Laws Relating to Children
Preamble:
Whereas, it is expedient to make amendment and consolidation of the laws relating
to children in order to maintain the best interests of the children, by respecting, protecting,
promoting and fulfilling the rights of the child.
Now, therefore, be it enacted by the Federal Parliament.', 0, 'The Act Relating to Children, 2075 (2018), Preamble', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:1', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', NULL, 1, 'chapter', 'Chapter -1', 'Chapter -1', NULL, NULL, 1, 'The Act Relating to Children, 2075 (2018), Chapter -1', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:1.0', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:1', 2, 'section', '1', 'Short title and commencement: (1) This Act may be cited as the "Act Relating', 'Short title and commencement', 'to Children, 2075 (2018)”.
(2) It shall come into force immediately', 0, 'The Act Relating to Children, 2075 (2018), Chapter -1, Section 1 (Short title and commencement)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:1.1', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:1', 2, 'section', '2', 'Definitions: Unless the subject or the context otherwise requires, in this Act,-', 'Definitions', '(a) "Orphan children" means orphan children as referred to in the
prevailing laws.
(b) "Investigating authority" means an official having authority under
the prevailing laws to investigate into the offence.
(c) "Offence" means a criminal offence as provided by the prevailing
laws.
(d) "Children in conflict with law" means the children accused of
committing an offence, and this term also includes the children
convicted by the Juvenile Court for committing an offence.
(e) "Prescribed" or "as prescribed" means prescribed or as prescribed in
the Rules framed under this Act.
(f) "Diversion" means the act of bringing the child accused of
committing an offence outside the ambit of the formal judicial
proceedings by adopting any of the processes mentioned in Section
29.
1
www.lawcommission.gov.np
(g) "Observation chamber" means an observation chamber established
pursuant to Section 22.
(h) "Family" means a child''s father, mother, elder brother, younger
brother, elder sister, younger sister, grand-father or grand-mother
living in an undivided family and this term also includes other
relative living in the undivided family.
(i) "Council" means the National Child Rights Council referred to in
Section 59.
(j) "Children" means persons who have not completed the age of
eighteen years.
(k) "Violence against children" means an act referred to in sub-section
(2) of Section 66.
(l) "Juvenile Court" means a juvenile court constituted in accordance
with sub-section (1) of Section 30 and this term also includes the
juvenile bench constituted pursuant to sub-section (3) of the said
Section.
(m) "Child pornography" means an act to take or make video or picture
of children showing their sex organ or making them involve in
imaginary sexual activities, to demonstrate vulgar picture through
newspaper, poster, print, movie or other medium of communication,
and this term also includes activities of production, sale, import,
export, collection or dissemination of such materials.
(n) "Child welfare authority" means an official appointed or prescribed
pursuant to Section 61.
(o) "Child home" means a child home established pursuant to Section
52.
(p) "Child sexual harassment/abuse" means an act referred to in sub-
section (3) of Section 66.
(q) "Child reform home" means a child reform home established
pursuant to Section 43.
(r) "Ministry" means the Ministry of Women, Children and Senior
Citizens of the Government of Nepal.
(s) "Children in need of special protection" means the children referred
to in Section 48.
2
www.lawcommission.gov.np
(t) "Guardian" means a person or institution appointed or having an
obligation to protect the rights and interests of the child in
accordance with this Act or the prevailing laws, and this term also
includes a curator in the absence of the guardian.
(u) "Social service provider" means a person referred to in Section 62.
(v) "Local Level" means any Rural Municipality or Municipality.', 1, 'The Act Relating to Children, 2075 (2018), Chapter -1, Section 2 (Definitions)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', NULL, 1, 'chapter', 'Chapter -2', 'Chapter -2', NULL, NULL, 2, 'The Act Relating to Children, 2075 (2018), Chapter -2', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2.0', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2', 2, 'section', '3', 'Right to live: (1) Every child shall have the right to live with dignity.', 'Right to live', '(2) The Government of Nepal, Province Government and Local Level shall
take necessary measures required for preventive and security service including
prevention of possible accidents, minimization of risks that may occur on the
children, in order to protect the rights of the child to live and development.', 0, 'The Act Relating to Children, 2075 (2018), Chapter -2, Section 3 (Right to live)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2.1', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2', 2, 'section', '4', 'Right to name, nationality and identity: (1) Every child shall have the right to', 'Right to name, nationality and identity', 'have name with own identification and birth registration.
(2) The father or mother of a child, after his or her birth, shall give a name
to him or her and register it according to the prevailing laws.
(3) The mother of a child born from rape or incest that is punishable by the
prevailing laws shall register his or her birth by mentioning only the name of the
mother if she so wishes.
(4) While giving name pursuant to sub-section (2), if the father or mother
of a child is not available immediately or there is no possibility that they can be
available, then the child may have the name given by any other family member or
guardian who looks after him or her.
(5) Every child after birth may use the surname given by mutual consent of
his or her parents or if such consent is not available he or she may use the surname
of his or her father after his or her name.
(6) Notwithstanding anything contained in sub-section (5), the child, if he
or she so wishes, may use the surname of his or her father or mother or both.
(7) A child whose paternal identity is not known may use his or her mother''s
surname after his or her name.
(8) If a dispute arises regarding the surname of any child, except as proved
otherwise, it shall be deemed that the child is using his or her father''s surname.
3
www.lawcommission.gov.np
(9) A child whose both father and mother are not identified may use the
surname given by the guardian after his or her name.
(10) The child welfare authority shall be informed about it when the
guardian gives the name and surname pursuant to sub-section (9).
(11) If the name of father, mother and grand-father, grand-mother must be
mentioned pursuant to law in any formal legal proceeding or document, in cases
where the father of the child is not known, he or she may mention his or her mother
and parents’ name and if the name of mother is also not known, mentioning that
matter will suffice the requirement.
(12) The mother, father or guardian of a child shall not change his or her
name, surname that hides the identity of the child with an intention to gain undue
benefits.', 1, 'The Act Relating to Children, 2075 (2018), Chapter -2, Section 4 (Right to name, nationality and identity)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2.2', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2', 2, 'section', '5', 'Right against discrimination: (1) No discrimination shall be made against any', 'Right against discrimination', 'child on grounds of religion, race, caste, tribe, sex, origin, language, culture,
ideological thought, physical or mental condition, physical disability, marital
status, family status, employment, health condition, economic or social condition
of him or her or his or her family or guardian, geographical area or similar other
ground.
(2) No one shall discriminate between son and daughter, son and son or
daughter and daughter or children from ex-husband or wife or present husband or
wife in maintenance, education or health care of children.
(3) No one shall make any kind of discrimination between their own son,
daughter and adopted son, daughter.
(4) No discrimination shall be made with regard to maintenance, education
and health care between children born to a man and woman before and after their
marriage.', 2, 'The Act Relating to Children, 2075 (2018), Chapter -2, Section 5 (Right against discrimination)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2.3', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2', 2, 'section', '6', 'Right to live and meet with the parents: (1) No child shall be split or separated', 'Right to live and meet with the parents', 'from his or her father or mother without his or her will.
(2) Notwithstanding anything contained in sub-section (1), the Juvenile
Court may issue an order to separate any child from his or her father or mother
and entrust him or her to any guardian''s custody for the best interests of the child,
if necessary.
Provided that the concerned party shall not be deprived of an opportunity
to submit his or her explanation before issuing such an order.
4
www.lawcommission.gov.np
(3) Except for the condition where the Juvenile Court has made a restriction
stating that it would be not in the interests of a child, the child living separately
from the father or mother or both shall have the right to make direct contact or
meet with the father or mother regularly.
(4) The person adopting a child shall allow the adopted child to meet,
contact and make correspondence with his or her biological parents.
(5) Any person or institution responsible for alternate care shall allow the
children under their care or guardianship to meet their biological parents or
families.', 3, 'The Act Relating to Children, 2075 (2018), Chapter -2, Section 6 (Right to live and meet with the parents)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2.4', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2', 2, 'section', '7', 'Right to protection: (1) Every child shall have the right to obtain proper care,', 'Right to protection', 'protection, maintenance, love and affection from his or her father, mother, other
member of family or guardian.
(2) The parents shall have equal responsibility in relation to care,
protection and maintenance of their children. In cases where the parents are
divorced or living separately due to any other reasons, financial expenses for the
maintenance of their children shall be borne by both parents according to their
capacity.
(3) No father, mother, other member of the family or guardian shall
abandon or leave the child of their own or under his or her guardianship
unattended.
(4) Children with disabilities, war victims, displaced, under vulnerable
conditions, or living on street shall have the right to special protection as
prescribed from the State for their secured future.
(5) Every child shall have the right to protection against any type of
physical or mental violence and torture, hatred, inhuman treatment, gender or
untouchability-based mistreatment, sexual harassment and exploitation that might
be caused by his or her father, mother, other family member or guardian, teacher
and other person.
(6) Every child shall have the right to protection from being exploited
economically and shall also be entitled to be protected from any activity which
may be harmful to him or her or be obstacle to his or her education or detrimental
to his or her health, physical, mental, moral, social development.
(7) No child shall be deployed in army, police and armed group and be used
for armed conflict or political purpose directly or indirectly.
5
www.lawcommission.gov.np
(8) No one shall attack, or make hindrance to the operation and
management of any school, including the place, service or facility, used for the
best interests of children, with any excuse at times of armed conflict or in any
adverse situation of whatever type.
(9) Children below fourteen years of age shall not be deployed in any risky
work or used as a house-servant or house-maid.
(10) The Government of Nepal, Provincial Government and Local Level
may follow the necessary measures and make and implement the standards for the
protection of the children.', 4, 'The Act Relating to Children, 2075 (2018), Chapter -2, Section 7 (Right to protection)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2.5', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2', 2, 'section', '8', 'Right to participate: A child who is competent to form his or her own opinion', 'Right to participate', 'shall have the right to participate in the decision-making process of family,
community, school or other public institution or organization on the matters
concerning him or her.', 5, 'The Act Relating to Children, 2075 (2018), Chapter -2, Section 8 (Right to participate)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2.6', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2', 2, 'section', '9', 'Right to freedom of expression and information: (1) Every child shall have the', 'Right to freedom of expression and information', 'freedom to express his or her opinion pursuant to the prevailing laws.
(2) Every child shall have the right to demand and receive information on
the subject of his or her right, interest and concern subject to the prevailing laws.', 6, 'The Act Relating to Children, 2075 (2018), Chapter -2, Section 9 (Right to freedom of expression and information)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2.7', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2', 2, 'section', '10', 'Right to open organization and assemble peacefully: (1) Every child shall have', 'Right to open organization and assemble peacefully', 'the right to open a child club or organization or the right to assemble peacefully
for the protection and promotion of the rights of the child.
(2) The provisions regarding the opening of a child club or organization
pursuant to sub-section (1) shall be as prescribed.', 7, 'The Act Relating to Children, 2075 (2018), Chapter -2, Section 10 (Right to open organization and assemble peacefully)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2.8', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2', 2, 'section', '11', 'Right to privacy: (1) Every child shall have the right to privacy regarding the', 'Right to privacy', 'subject of his or her body, residence, property, document, data, correspondence
and character.
(2) No one shall do, or cause to be done the act of creation of personal
information, details, photo, collection of information, publishing, printing,
demonstrating, sale and distributing or transmitting by any means that causes
negative impact on the characteristics of a child or any shame, regret or domination
to him or her.
(3) The details that provide the identity of a child along with the name,
surname, address, age, sex, family background, economic status, offence
committed by, and any details regarding action, if any taken, against a child who
is victim or accused of an offence by the Juvenile Court, police office, guardian,
6
www.lawcommission.gov.np
caretaker, or any other body shall be kept confidential. The details of a child kept
confidential shall not be used elsewhere except as provided by the law.
Provided that if such details have to be published for any study or research
work, only the age or sex of the child, without disclosing his or her name, surname,
address, other data which may reveal his or her identity and his or her family may
be published.', 8, 'The Act Relating to Children, 2075 (2018), Chapter -2, Section 11 (Right to privacy)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2.9', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2', 2, 'section', '12', 'Special rights of children with disabilities: (1) Special arrangements shall be', 'Special rights of children with disabilities', 'made, as prescribed, for the children with disabilities.
(2) Every child with disability shall have the right to determine his or her
own honour and prestige, to promote his or her own independency, to participate
actively in the society and to live a life with dignity.
(3) Every child with disability shall have the right to obtain special care
and to be assimilated in the society and to obtain the opportunity to education,
training, health care, rehabilitation service, preparation for employment and
entertainment for the development of his or her personality.
(4) Every child with disability shall have the right to equal access and
utilize the public services and facilities.', 9, 'The Act Relating to Children, 2075 (2018), Chapter -2, Section 12 (Special rights of children with disabilities)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2.10', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2', 2, 'section', '13', 'Right to nutrition and health: (1) Every child shall have the right to proper', 'Right to nutrition and health', 'nutrition, clean drinking water and the child up to two years of age shall also have
the right to breast feeding.
(2) Pregnant women and children shall have the right to get necessary
vaccination to prevent diseases and allow to utilize the physical and mental health
services according to the national standards, to get information about body,
reproduction and reproductive health according to age and maturity.
(3) Every child shall have the right to obtain free basic health service.', 10, 'The Act Relating to Children, 2075 (2018), Chapter -2, Section 13 (Right to nutrition and health)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2.11', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2', 2, 'section', '14', 'Right to sports, entertainment and culture: (1) Every child shall have the right', 'Right to sports, entertainment and culture', 'to play games and participate in sports according to his or her age and interest.
(2) Every school shall encourage the children to participate in sports at the
time other than study and for that purpose, provide for necessary playgrounds and
sports materials.
(3) Every child shall have the right to child friendly entertainment
according to his or her age, interest and requirement.
7
www.lawcommission.gov.np
(4) Every child shall have the right to take part in cultural activities
according to his or her religion, culture, custom, tradition and conscience without
causing any adverse effect on his or her interests.', 11, 'The Act Relating to Children, 2075 (2018), Chapter -2, Section 14 (Right to sports, entertainment and culture)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2.12', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:2', 2, 'section', '15', 'Right to education: (1) Children below six years of age shall have the right to', 'Right to education', 'learn in a proper way according to their age and level of development and to pre-
child development.
(2) Every child shall have the right to acquire free and compulsory
education upto the basic level and free education upto the secondary level pursuant
to the prevailing law in a child friendly environment.
(3) Every child shall have the right to acquire education through proper
study materials and teaching method according to his or her special physical and
mental condition, pursuant to the prevailing law.
(4) Dalit children shall have the right to acquire free education with
scholarship pursuant to the prevailing law.', 12, 'The Act Relating to Children, 2075 (2018), Chapter -2, Section 15 (Right to education)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:3', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', NULL, 1, 'chapter', 'Chapter -3', 'Chapter -3', NULL, NULL, 3, 'The Act Relating to Children, 2075 (2018), Chapter -3', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:3.0', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:3', 2, 'section', '16', 'Priority to be given for the best interests of children: (1) The officials of every', 'Priority to be given for the best interests of children', 'organization and institution that carries out activities related to children shall
adopt necessary child friendly process by giving priority to the best interests of
children, while doing every activity.
(2) It shall be the responsibility of everyone to instantly help children
whose life is in risk.
(3) The child welfare authority or Juvenile Court shall, while making
arrangement for a child''s alternative care, separating a child from his or her parents
or guardian, making decision on who has to take care of and maintain a child after
divorce between his or her father and mother shall adopt the process as prescribed
for the best interests of the child pursuant to this Act.
(4) Public and private social institutions where children stay or which
provide services to children shall, while constructing or refurbishing the physical
structures, make necessary arrangement that is child friendly.', 0, 'The Act Relating to Children, 2075 (2018), Chapter -3, Section 16 (Priority to be given for the best interests of children)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:3.1', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:3', 2, 'section', '17', 'Responsibility of the family or guardian: (1) Both the father and mother shall', 'Responsibility of the family or guardian', 'have equal responsibility on the child''s care, maintenance and overall
development.
8
www.lawcommission.gov.np
(2) It shall be the responsibility of every father, mother, other members of
the family or guardian to care, maintain and protect, to provide the opportunity for
education, treatment, along with personality development of, to provide
environment full of love and care and to guide properly for future certainty of the
child.
(3) Father, mother, other family member or guardian shall provide suitable
environment for acquiring education to every child of age to join school by
admitting him or her to the school.
(4) Father, mother, other member of the family or guardian shall not engage
the child on labour which may adversely affect his or her education, health and
physical or mental development.
(5) Father, mother, other member of the family or guardian shall not leave
the child below six years of age alone at home or any other place or send alone
elsewhere, without being accompanied by an adult person.', 1, 'The Act Relating to Children, 2075 (2018), Chapter -3, Section 17 (Responsibility of the family or guardian)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:3.2', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:3', 2, 'section', '18', 'Obligation of the State: The State shall make necessary arrangement for the basic', 'Obligation of the State', 'needs including maintenance, protection, health and education of children in need
of special protection, on the basis of the available means and resources.', 2, 'The Act Relating to Children, 2075 (2018), Chapter -3, Section 18 (Obligation of the State)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:3.3', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:3', 2, 'section', '19', 'Responsibility of the media sector: It shall be the responsibility of the media', 'Responsibility of the media sector', 'sector to publish and transmit information, without violating the rights of the child
and causing adverse effect on the interests of the child.', 3, 'The Act Relating to Children, 2075 (2018), Chapter -3, Section 19 (Responsibility of the media sector)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', NULL, 1, 'chapter', 'Chapter -4', 'Chapter -4', NULL, NULL, 4, 'The Act Relating to Children, 2075 (2018), Chapter -4', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.0', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '20', 'Matters to be considered while dispensing the juvenile justice: A person,', 'Matters to be considered while dispensing the juvenile justice', 'official and Juvenile Court involved in dispensing juvenile justice shall take into
account the following matters, in the course of dispensing justice, in addition to
the other matters as provided elsewhere in this Act:
(a) To take opinion of a child before making a decision that affects him
or her,
(b) To provide an opportunity to father, mother, other family member
or guardian to put their opinion before making decision on the
subject matter associated with the interests and benefits of the child,
9
www.lawcommission.gov.np
(c) To use parlance, speak and behave according to the child’s age, level
of intellectual development, conscience and cultural norms and
values,
(d) To use language preferred by the child and to take assistance of an
interpreter as required while talking to him or her.', 0, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 20 (Matters to be considered while dispensing the juvenile justice)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.1', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '21', 'To take a child under control: (1) If information on an offence is received, the', 'To take a child under control', 'investigating authority shall immediately start investigation on it. While doing
such investigation, if it appears that the investigation is not possible without taking
the child accused of the offence under control, the investigating authority may take
him or her under control.
(2) If it appears that it is no longer required to take a child under control,
who has been taken under control, pursuant to sub-section (1), he or she shall be
handed over to his or her family member or guardian or the nearest relative.
(3) If a child is taken under control pursuant to sub-section (1), the
investigating authority shall give information about it to his or her family member,
or guardian or close relative.
(4) The investigating authority shall not use force while taking a child
under control pursuant to sub-section (1).
Provided that it shall not bar the using of minimum force required to take
the child under control.
(5) The child taken under control pursuant to sub-section (1) shall, if
possible, be referred to a child psychologist or a person working in the field of
children''s welfare in order to provide the required counselling service.
(6) If the child taken under control pursuant to sub-section (1) could deviate
himself or herself pursuant to Section 27, the investigating authority may,
notwithstanding anything contained in the prevailing law, take the deposition of
him or her by himself or herself.
(7) The child taken under control pursuant to sub-section (1) may be kept
in an observation chamber with the permission of the Juvenile Court for a
maximum twenty-one days, not exceeding five days at a time.
(8) Notwithstanding anything contained in sub-section (7), if the Juvenile
Court is of the opinion that it not reasonable to keep the child accused of offence
in the observation chamber, having regard to the child''s physical condition, age,
circumstances at the time of commission of the offence or condition of the
10
www.lawcommission.gov.np
observation chamber, the Juvenile Court may make an order to investigate the case
by entrusting such a child to his or her father, mother, other family member or
guardian and in their absence to any social organization working in the field of
protection of the rights and interests of the child or child reform home on the
condition that the child shall make presence when the Juvenile Court so requires.
(9) While inquiring into the child taken under control, the investigating
authority shall make it in the presence of his or her father, mother or guardian or
children welfare authority or legal practitioner in a child friendly environment.', 1, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 21 (To take a child under control)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.2', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '22', 'Provision relating to establishment of observation chamber: (1) The', 'Provision relating to establishment of observation chamber', 'Government of Nepal may establish an observation chamber for the purpose of
keeping a child taken under control on the charge of an offence, throughout the
period of investigation.
(2) A separate room shall be arranged in every District Police Office until
the observation room referred to in sub-section (1) is established.
(3) The child taken under control for investigation shall be provided with
counselling by a child psychologist and psycho-social support as required.
(4) If any member of a child’s family wishes to stay together with the child
who is kept in the observation chamber for assistance, the investigating authority
may give permission to stay together specifying the time and conditions as
required.
(5) The provisions relating to the establishment, operation, management
and monitoring of the observation chamber shall be as prescribed.', 2, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 22 (Provision relating to establishment of observation chamber)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.3', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '23', 'Special provision relating to investigation and prosecution: (1)', 'Special provision relating to investigation and prosecution', 'Notwithstanding anything contained in the prevailing laws, the Government of
Nepal shall form a separate unit in order to investigate into the cases of offences
of which children are accused.
(2) The Government of Nepal may designate an official working at the
District Police Office, who has got training on juvenile justice, to perform that
function until the separate unit is formed pursuant to sub-section (1).', 3, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 23 (Special provision relating to investigation and prosecution)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.4', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '24', 'Provision relating to trial: (1) No child shall be detained in the course of trial', 'Provision relating to trial', 'and no bail or guarantee shall be demanded from him or her.
(2) Notwithstanding anything contained in sub-section (1), the Juvenile
Court may, for reasons to be recorded, send a child accused of an offence to the
child reform home during trial, in any of the following circumstances:
11
www.lawcommission.gov.np
(a) If there is adequate ground that the child''s life would be in
danger, someone would get hurt from him or her, such a child
would go away or any other reason that it is not appropriate
to put him or her elsewhere,
(b) If it appears from the evidence available for the time being
that a child accused of an offence punishable by
imprisonment for a term not exceeding three years or more
or there is a reasonable ground to believe that he or she is an
offender.
(3) Except in the circumstance referred to in sub-section (2), other child
accused of offence may be entrusted to his or her father, mother, other family
member or guardian, and in their absence to an institution or person working for
the welfare of the children on a condition that the child will be presented as and
when needed.
Provided that if the Juvenile Court deems that it is not appropriate to keep
the child in the reform home, taking into account the child''s physical condition,
age, circumstances at the time of commission of the offence as mentioned in sub-
section (2), it shall not bar the entrusting of such a child to his or her father,
mother, other family member or guardian, and in their absence, to an institution or
person protecting the rights and interests of the child, by specifying the conditions
pursuant to this sub-section.
(4) While entrusting a responsibility of a child pursuant to sub-section (3),
that person and the child shall be informed about the specified conditions and the
consequences that must be borne if they have not been followed.
(5) If the child who is entrusted to someone pursuant to sub-section (3)
does not follow the conditions specified by the juvenile court, the trial of the case
may be made by keeping him or her in the child reform home.', 4, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 24 (Provision relating to trial)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.5', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '25', 'Rights of child victim: A child victim shall have the right to child friendly justice', 'Rights of child victim', 'as follows in every stage of investigation, prosecution and judicial process:
(a) To get information on the language he or she understands,
(b) To participate or be involved,
(c) To keep the details of personal identification confidential,
(d) To get recovery of the reasonable compensation from the offender,
12
www.lawcommission.gov.np
Provided that this clause shall not be considered as limiting
the opportunity of the victim to receive compensation from the
State.
(e) To get free legal aid and socio-psychological counselling service as
required and to appoint a separate legal counsel if he or she so
wishes,
(f) To get free service of the translator, sign language expert or
interpreter if the victim does not understand the language used by
the investigating authority or Juvenile Court,
(g) To get, free of cost, the copy of the documents including the
decisions and orders made by the investigating authority or Juvenile
Court,
(h) To get police protection for safety against the probable threat that
may be caused from the offender or his or her party,
(i) To have his or her case heard in camera,
(j) To have the indirect presence of the defendant in the course of
hearing of the case as required.', 5, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 25 (Rights of child victim)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.6', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '26', 'Rights available to child in the course of hearing: (1) A child accused of an', 'Rights available to child in the course of hearing', 'offence shall have the following rights, in addition to the rights mentioned in the
prevailing law and elsewhere in this Act, in the course of investigation and hearing
of the case:
(a) Right to obtain information on the charge made against him or her,
its proceeding, order issued or decision made on it directly or
through his or her family or guardian,
(b) Right to receive free legal aid and other necessary support
immediately in order to defend against the charge made against him
or her,
(c) Right to have the case tried and settled by the competent judicial
authority,
(d) Right to demand the presence of family or guardian required in all
processes of juvenile justice delivery,
(e) Right to receive prompt and fair justice from the Juvenile Court,
(f) Right to have confidentiality in the process of juvenile justice
delivery
13
www.lawcommission.gov.np
(g) Right to get information on the constitutional or legal rights,
(h) Right to have investigation, prosecution and hearing in the child
friendly environment,
Explanation: For the purposes of this clause, "child friendly
environment" means the treatment done with the child that is
commensurate to the age, maturity and psychology of the child, this
term also includes the use of the language understood by the child,
creation of the fearless atmosphere, presence of his or her mother,
father or other family member or guardian, addressing the personal
needs of the child and the availability of the facilitator as required.
(i) Right to have an opportunity to participate in every stage of judicial
proceedings and to put his or her own views independently,
(j) Right to allow the participation of the parents, guardian of the child,
during the hearing of the case, if he or she so wishes,
(k) Right to stay separately from the offender, if the child so wishes
where the father, mother, parents or guardian of the victim child is
the perpetrator.
(2) The child accused of an offence shall be presumed to be innocent unless
decided otherwise by the Juvenile Court, and such child shall not be compelled to
give testimony against him or herself.', 6, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 26 (Rights available to child in the course of hearing)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.7', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '27', 'To divert: (1) Notwithstanding anything contained in the prevailing laws, the', 'To divert', 'following authorities may, in the following circumstances, take decision to divert
a child accused of an offence, if it appears reasonable to divert the child for his or
her best interests:
(a) The investigating authority, where the claimed amount is
upto five thousand rupees or the offence t is punishable by a
fine of upto two thousand rupees or imprisonment for a term
of upto two months,
(b) The government attorney, where the claimed amount is upto
ten thousand rupees or the offence is punishable by a fine of
upto five thousand rupees or imprisonment for a term of upto
three years,
(c) The Juvenile Court, irrespective of the claimed amount or the
amount of fine or term of imprisonment.
14
www.lawcommission.gov.np
(2) Notwithstanding anything contained in clause (c) of sub-section (1), a
child shall not be diverted in a case punishable by imprisonment for a term of three
years or more than three years shall not be diverted.
(3) The child or guardian may, if not satisfied with the order of diversion,
file a petition in the Juvenile Court in the case of clauses (a) and (b) of sub-section
(1) and in the High Court in the case of clause (c).', 7, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 27 (To divert)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.8', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '28', 'Matters to be considered in making diversion: The following matters shall be', 'Matters to be considered in making diversion', 'considered while making diversion:
(a) Confession of offence by the child,
(b) Consent of the concerned child, his or her father, mother and other
family member, or guardian where there are no parents,
(c) Receipt of consent of the victim ensuring the rehabilitation of the
victim party to the extent of possible,
(d) Nature of the offence and circumstances of its commission, gravity
of the event, age, maturity and intellectual level, family
environment of the child and the damage caused to the victim and
his or her rehabilitation are to be considered.', 8, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 28 (Matters to be considered in making diversion)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.9', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '29', 'Procedures to be followed while making diversion: (1) One or more of the', 'Procedures to be followed while making diversion', 'following appropriate procedures shall be followed while diverting a child, also
having regard to his or her desire:
(a) To have reconciliation or understanding between the child and the
victim,
(b) To make the child realize the mistake,
(c) To provide necessary counselling to the child and his or her family,
(d) To send the child to any community service,
(e) To send the child to any institution for his care and protection,
(f) To release the child on supervision and direction of the child welfare
authority,
(g) To entrust the child to his or her father, mother or other family
member or guardian,
(h) To make the child participate in any training or educational
program.
(2) While diverting a child by adopting any procedure referred to in clauses
(d), (e), (f), (g) and (h) of sub-section (1), the period shall also be fixed.
15
www.lawcommission.gov.np
(3) While diverting a child by adopting the procedure referred to in clauses
(d), (e), and (f) of sub-section (1), no diversion shall be made so that it exceeds
the maximum term of punishment imposable for the commission of the offence.
(4) The investigating authority or government attorney shall, before
diverting a child, obtain a report on study and analysis of physical and mental
condition of the child by the child psychologist and child expert and economic,
cultural condition and circumstances of the child by the social worker.
(5) The investigating authority, government attorney or Juvenile Court
shall give the information about the diversion of the child pursuant to sub-section
(1) to their respective higher office and Juvenile Court.
(6) If the child accused of an offence is diverted, such a dispute shall
terminate, and its formal judicial proceeding shall be deemed to be concluded.
(7) The investigating authority, government attorney or Juvenile Court that
has made diversion shall make arrangement to monitor, whether the diverted child
has been continuously participating in the diversion procedure or not, through a
probation officer.
(8) The following may be done to indemnify the damage caused to the
victim while diverting a child:
(a) To compensate the victim or to have recovery of the actual loss and
damage,
(b) To cause the property, profit or material acquired from the offence
to be returned to the concerned owner,
(9) Other provisions relating to the diversion shall be as prescribed.', 9, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 29 (Procedures to be followed while making diversion)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.10', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '30', 'Formation of the Juvenile Court: (1) The Government of Nepal may, on', 'Formation of the Juvenile Court', 'recommendation of the Judicial Council, form the required number of Juvenile
Courts to originally proceed, try and settle the offence committed by the children.
(2) The notice of formation of the Juvenile Courts pursuant to sub-section
(1) shall be published in the Nepal Gazette, and the territorial jurisdiction and
venue of such Courts shall be as mentioned in the same notice.
(3) A juvenile bench shall be formed in each District Court for the
proceeding, hearing and settlement of the offence to be dealt with the juvenile
court until the Juvenile Court is formed under sub-section (1).
(4) The juvenile bench referred to in sub-section (1) shall consist of the
following members:
16
www.lawcommission.gov.np
(a) District Judge,
(b) Social service provider,
(c) Child psychologist or child specialist.
(5) The qualification, appointment, remuneration and other conditions of
service of the social service provider, child psychologist or child specialist
referred to in clauses (b) and (c) of sub-section (4) shall be as prescribed.
(6) Notwithstanding anything contained in sub-section (1), if an adult
person is involved, along with the child, in any offence, the matter shall be
proceeded, tried and settled by the Juvenile Court in the case of the child, and the
matter shall be proceeded, tried and settled pursuant to the prevailing laws in the
case of the adult person by establishing a separate case file.', 10, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 30 (Formation of the Juvenile Court)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.11', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '31', 'Exercise of jurisdiction of the Juvenile Court: The exercise of jurisdiction of', 'Exercise of jurisdiction of the Juvenile Court', 'the Juvenile Court shall be made as prescribed.', 11, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 31 (Exercise of jurisdiction of the Juvenile Court)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.12', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '32', 'Proceeding by the Juvenile Court: Even if the child attains the age of eighteen', 'Proceeding by the Juvenile Court', 'years during the proceeding of the case, such case shall be proceeded, tried and
settled by the Juvenile Court itself.', 12, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 32 (Proceeding by the Juvenile Court)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.13', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '33', 'Cases to be transferred to the Juvenile Court: If any child has been accused of', 'Cases to be transferred to the Juvenile Court', 'offence before the commencement of this Act and the case is being originally tried
by the District Court or other body pursuant to the prevailing laws, the case shall
be transferred to the concerned Juvenile Court after the commencement of this
Act.', 13, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 33 (Cases to be transferred to the Juvenile Court)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.14', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '34', 'Provision relating to trial: (1) The Juvenile Court shall try the case in a child', 'Provision relating to trial', 'friendly environment by taking into consideration the age and maturity of the
child.
(2) The Juvenile Court shall make the child participate while trying the
case and shall provide an opportunity to freely put his or her views.', 14, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 34 (Provision relating to trial)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.15', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '35', 'Provision of in camera bench: (1) The trial and adjudication of the case against', 'Provision of in camera bench', 'a child accused of an offence shall be carried out in camera bench except as
otherwise ordered by the Juvenile Court.
(2) During the trial and adjudication of the case in-camera pursuant to sub-
section (1), only the concerned child, his or her family member or guardian,
victim, government attorney, concerned legal practitioner and the person
permitted by the Juvenile Court may enter into the in-camera bench.
(3) The procedures of the in-camera bench shall be as prescribed.
17
www.lawcommission.gov.np', 15, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 35 (Provision of in camera bench)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.16', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '36', 'Provisions relating to punishment: (1) If the child is less than ten years of age', 'Provisions relating to punishment', 'at the time of commission of the offence, no case and punishment of any kind shall
be instituted against and imposed on him or her.
(2) If a child of ten years of age or above but below fourteen years of age
commits an offence that is punishable by a fine, the child shall be released after
counseling him or her and if such a child commits an offence that is punishable by
imprisonment, the child shall be punished with imprisonment for upto six months
or be sent to the child reform home for a period not exceeding one year without
subjecting him or her to imprisonment.
(3) If a child of fourteen years of age or above but below sixteen years of
age commits an offence, the child shall be punished with half the punishment that
is imposable on the person having attained majority pursuant to the prevailing law.
(4) If a child of sixteen years of age or above but below eighteen years of
age commits an offence, the child shall be punished with two-thirds of the
punishment that is imposable on the person of legal age pursuant to the prevailing
law.
(5) The Juvenile Court shall, having regard, inter alia, to the age, sex,
maturity of the child who is held to be subject to punishment pursuant to sub-
section (2), (3) or (4), nature of the offence and also the circumstances of the
commission of the offence, postpone his or her punishment or make any of
following appropriate decisions as punishment, with or without specifying the
terms and conditions:
(a) To counsel or advise the child about good human behaviours
by any family member or guardian,
(b) To give orientation to the child through any institution or
person that provides the service,
(c) To provide single, group or family psycho-social counselling
service,
(d) To keep the child under the observation of any family
member, guardian, school, person or institution that provides
service for a fixed period subject to the observance of the
specified terms and conditions,
(e) To send the child for community service that is suitable to
his or her age, by specifying the nature and period of service,
18
www.lawcommission.gov.np
(f) To make the child stay in the child reform home for a period
not exceeding that of the punishment imposed on him or her.
(6) If any person has caused a child to commit an offence, by teaching,
giving pressure, ordering, luring or in any other manner, that person who has
taught so, given pressure, ordered, lured or made to commit it shall be punished
pursuant to law as if that person committed the offence on his or her own.
(7) Notwithstanding anything contained elsewhere in this Section, while
punishing a child who has not completed sixteen years of age, no punishment of
imprisonment shall be imposed on such a child except in cases where he or she
has committed a heinous offence, grave offence or repeated the offence.', 16, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 36 (Provisions relating to punishment)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.17', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '37', 'Period for disposing of the case: Notwithstanding anything contained in the', 'Period for disposing of the case', 'prevailing laws, the Juvenile Court shall generally dispose of a case within one
hundred twenty days from the date of filing of the case and the proceeding and
adjudication of such a case shall be made on the basis of continuous hearing.', 17, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 37 (Period for disposing of the case)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.18', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '38', 'Reform period may be reduced or remitted: (1) If there is satisfactory', 'Reform period may be reduced or remitted', 'improvement in the behaviour of a child kept in the child reform home or kept
under the protection or supervision of any institution or person pursuant to the
decision of the Juvenile Court, the child welfare authority may recommend the
Juvenile Court to reduce or remit the period of reform of such a child.
(2) The Juvenile Court may reduce or remit the remaining period of reform
of the child if it thinks it reasonable to reduce or remit the period of reform upon
examining the recommendation received pursuant to sub-section (1).', 18, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 38 (Reform period may be reduced or remitted)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.19', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '39', 'Restorative justice: (1) While dispensing the juvenile justice, it shall be made in', 'Restorative justice', 'compliance with the principle of restorative justice.
(2) Other provisions relating to restorative justice shall be as prescribed.', 19, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 39 (Restorative justice)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.20', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '40', 'Not to be considered disqualified: Notwithstanding anything contained in the', 'Not to be considered disqualified', 'prevailing laws, if any person becomes disqualified to receive any post or facility
pursuant to law by the reason of the commission by him or her of any offence, he
or she shall not be considered disqualified to receive that post or facility on the
ground of the offence that he or she committed when he or she was a child.', 20, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 40 (Not to be considered disqualified)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.21', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '41', 'Punishment not to be counted: (1) Notwithstanding anything contained in the', 'Punishment not to be counted', 'prevailing laws, the offence committed by a person during childhood shall not be
counted while counting repeated offence pursuant to this Act or the prevailing
laws, for the purposes of punishment.
19
www.lawcommission.gov.np
(2) Notwithstanding anything contained in the prevailing laws, although
any child commits an offence time and again, he or she shall not be subjected to
additional punishment on the basis of repetition of the commission of the offence.', 21, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 41 (Punishment not to be counted)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.22', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '42', 'Not to be handcuffed, shackled or kept in solitary confinement:', 'Not to be handcuffed, shackled or kept in solitary confinement', 'Notwithstanding anything contained in the prevailing laws, no child in conflict
with law shall be handcuffed, shackled or kept in solitary confinement or
detention, or prison.', 22, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 42 (Not to be handcuffed, shackled or kept in solitary confinement)', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.23', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '43', 'Provision relating to child reform home: (1) The Government of Nepal shall', 'Provision relating to child reform home', 'establish the child reform home as required for the purpose of keeping the children
in conflict with law until their reform and rehabilitation.
(2) Any institution may, with the approval of the Government of Nepal,
establish a child reform home, for the purpose of sub-section (1).
(3) The Juvenile Court may monitor and inspect the child reform homes
established within its territorial jurisdiction, issue necessary directives to such
child reform homes and order such child reform homes to submit reports on the
condition of reform of the children kept in such homes.
(4) If a child kept in a child reform home attains the age of eighteen years
before completion of the period for which he or she has to remain in the child
reform home, he or she shall be kept separately from the other children in the child
reform home for the remaining period by considering, inter alia, the improvement
seen in his or her behaviour, continuity of skills and education gained.
(5) The establishment, operation, monitoring and other arrangement of the
child reform home shall be as prescribed.', 23, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 43 (Provision relating to child reform home)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.24', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '44', 'To shift children suffering from chronic or serious disease to another place:', 'To shift children suffering from chronic or serious disease to another place', '(1) If any child kept in a child reform home needs continuous treatment because
he or she has suffered from any chronic or serious disease or if the concerned
doctor has recommended to shift any child somewhere else due to his or her
physical or mental disability or his or her addiction to narcotics, the Juvenile Court
may issue an order to shift such a child to another place for a certain period.
(2) An institution or person who keeps the child as per the order issued
pursuant to sub-section (1) shall submit a report related to the health of the child
to the concerned Juvenile Court in every six months.
20
www.lawcommission.gov.np
(3) If the child is found to be healthy or free from addiction on the basis of
the report referred to in sub-section (2), the Juvenile Court may issue an order to
return that child to his or her previous condition.', 24, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 44 (To shift children suffering from chronic or serious disease to another place)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.25', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '45', 'Psycho-sociological and psychological study report: (1) An individual psycho-', 'Psycho-sociological and psychological study report', 'sociological and psychological study report shall be prepared for the purpose of
investigation, prosecution, proceeding, hearing or adjudication of the charge made
against a child in conflict with law.
(2) The provisions regarding the preparation of the study report referred to
in sub-section (1) shall be as prescribed.', 25, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 45 (Psycho-sociological and psychological study report)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.26', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '46', 'Central Juvenile Justice Committee: (1) There shall be a Central Juvenile', 'Central Juvenile Justice Committee', 'Justice Committee, as prescribed, at the central level for carrying out the functions,
including making coordination between the various institutions working in the
field related to juvenile justice.
(2) The meetings, functions, duties and powers of the Central Juvenile
Justice Committee shall be as prescribed.', 26, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 46 (Central Juvenile Justice Committee)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4.27', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:4', 2, 'section', '47', 'District Juvenile Justice Committee: (1) There shall be a District Juvenile', 'District Juvenile Justice Committee', 'Justice Committee in every district, and the formation, functions, duties and
powers and rules of procedures of meetings of such Juvenile Justice Committee
shall be as prescribed.', 27, 'The Act Relating to Children, 2075 (2018), Chapter -4, Section 47 (District Juvenile Justice Committee)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', NULL, 1, 'chapter', 'CHAPTER 5', 'CHAPTER 5', NULL, NULL, 5, 'The Act Relating to Children, 2075 (2018), CHAPTER 5', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5.0', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5', 2, 'section', '48', 'Children in need of special protection: (1) The following children shall be', 'Children in need of special protection', 'deemed to be children in need of special protection:
(a) Orphan children,
(b) Children that have been left or found abandoned in hospitals or other
public places or separated from parents or left unclaimed, with the
identity of their parents unknown,
(c) Children that are deprived of appropriate care due to serious
physical or mental disability or incapacity of their parents,
(d) Out of the children in conflict with law, those who have been
referred for alternative care under the diversion process,
(e) Children who are staying in prison being dependent on their father
or mother who is detained or imprisoned,
21
www.lawcommission.gov.np
(f) Infants born due to rape or incestuous relationships that are
punishable by law and concerning whom application has been made
to the child welfare authority, stating inability to maintain them,
(g) Children who have been separated from their families for their best
interests due to abuse, violence or neglect by their respective father,
mother or guardian,
(h) Children who are earning their living by engaging in labour that is
forced or bonded or hazardous or worst in form or that contravenes
a prevailing law, who are addicted to smoking, drinking or other
narcotic drugs, or are infected with HIV,
(i) Children who are experiencing difficulty leading normal life or
whose lives are at risk, having been suffering from serious physical
or mental health problems or serious disability, due to the inability
of their parents or families to afford treatment,
(j) Children who are the victims of offences against children or are at
such risks,
(k) Children who have lost both or either of their parents, or whose
parents have disappeared, or have themselves got injured physically
or mentally or disability due to a disaster or armed conflict,
(l) Children belonging to deprived Dalit communities,
(m) Such other children as may be specified as children in need of
special protection by the Ministry by publishing a notice in the
Nepal Gazette.
(2) Other services and support, including rescue, temporary protection,
health treatment, psychosocial support, family reunion, rehabilitation, alternative
care, family support, social security and socialization, as required, to children
referred to in subsection (1) shall be as prescribed.', 0, 'The Act Relating to Children, 2075 (2018), CHAPTER 5, Section 48 (Children in need of special protection)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5.1', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5', 2, 'section', '49', 'Provision of alternative care: (1) The children referred to in clauses (a), (b), (c),', 'Provision of alternative care', '(d), (e), (f) and (g) shall be considered as children that require alternative care.
(2) The child welfare authority shall make arrangements for alternative care
for the children referred to in sub-section (1) on the basis of the following order
of priority:
(a) Relative from the side of the father or mother of the child,
(b) Family or person willing to provide care to the child,
22
www.lawcommission.gov.np
(c) Organization that provides foster (family-modelled) care,
(e) Children’s home.
(3) Other provisions relating to alternative care shall be as prescribed.', 1, 'The Act Relating to Children, 2075 (2018), CHAPTER 5, Section 49 (Provision of alternative care)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5.2', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5', 2, 'section', '50', 'Protection of children: (1) A person who has information about a child in need', 'Protection of children', 'of special protection at any place shall give information thereof to the child welfare
authority.
(2) If information is received pursuant to sub-section (1), the child welfare
authority shall, if he or she finds it necessary to urgently rescue the child, rescue
the child and keep him or her in a temporary protection service referred to in
Section 69.
(3) The child welfare authority may make arrangements for providing
necessary services, upon conducting inquiry on the basis of the information
received pursuant to sub-section (1).
(4) The child welfare authority may entrust a social service provider in
order to provide necessary services pursuant to sub-section (3), as prescribed.
(5) While conducting inquiry pursuant to sub-section (3), other services
needed by the children in need of special protection shall be ensured. If it is
deemed that special protection is not necessary and the child’s father, mother,
other family member or guardian has been traced, the child welfare authority may
hand over the custody of such children to them.
(6) If the child welfare authority thinks that any support is needed for
handing over the custody of the child to her or his father, mother, other family
member or guardian pursuant to sub-section (5), he or she shall make arrangements
for necessary services such as sponsorship or family support, by making
coordination with the relevant organizations.
Clarification: For the purposes of this Section:
(a) “Sponsorship” means the act of making available financial support
on the long-term or short-term basis for necessary maintenance and
education for children by any person, organization or body.
(b) “Familial support” means the support provided for creating an
environment that is conducive to safeguarding of children within the
family by identifying and addressing the economic and social
factors that lead the child’s family to disintegration, while
maintaining unity and harmony in the family.
23
www.lawcommission.gov.np
(7) If, in making examination and inquiry pursuant to sub-section (3), it
appears that alternative care is necessary, the child welfare authority shall make
arrangements for such care.
(8) In a case involving a child as a victim, the child welfare authority shall
arrange for separating a child victim from her or his parents or family and keep
him or her in a temporary protection service for a certain period of time, if the
child so desires, or the parent or guardian is the perpetrator or because of their
complicity with the perpetrator there is a possibility of greater risk to the child, or
there is likelihood of obstruction in the examination, inquiry, proceedings and
fact-finding of the incident.
(9) If, in spite of making examination and inquiry pursuant to sub-section
(3), the paternity and maternity of the child cannot be determined, the child welfare
authority shall recommend for her or his birth registration and government identity
card setting out the identity.', 2, 'The Act Relating to Children, 2075 (2018), CHAPTER 5, Section 50 (Protection of children)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5.3', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5', 2, 'section', '51', 'To appoint or designate guardian: In providing the alternative care service', 'To appoint or designate guardian', 'pursuant to Section 49, arrangement shall be made for appointing or designating a
guardian pursuant to the prevailing law.', 3, 'The Act Relating to Children, 2075 (2018), CHAPTER 5, Section 51 (To appoint or designate guardian)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5.4', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5', 2, 'section', '52', 'Establishment and operation of children’s home: (1) The Government of Nepal,', 'Establishment and operation of children’s home', 'Provincial Government and the Local Level shall establish children’s homes, as
required, for the purpose of protection of the children requiring special protection.
(2) The provisions relating to the establishment of children’s home,
qualifications of operators, operational licence, renewal, classification,
management, operation standards and monitoring shall be as prescribed.', 4, 'The Act Relating to Children, 2075 (2018), CHAPTER 5, Section 52 (Establishment and operation of children’s home)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5.5', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5', 2, 'section', '53', 'Duration of stay at children’s home: The children requiring special protection', 'Duration of stay at children’s home', 'shall be kept in children’s homes until they have been properly rehabilitated or
until they have attained the age of eighteen years.', 5, 'The Act Relating to Children, 2075 (2018), CHAPTER 5, Section 53 (Duration of stay at children’s home)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5.6', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5', 2, 'section', '54', 'Family reunion to be made: (1) Family reunion shall be made if the parents or', 'Family reunion to be made', 'guardians of the children staying in children’s homes are traced and it is in the
best interests of the children to do so.
(2) After the commencement of this Act, no child shall be kept in a
children’s home except as in accordance with Sections 49 and 69.', 6, 'The Act Relating to Children, 2075 (2018), CHAPTER 5, Section 54 (Family reunion to be made)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5.7', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5', 2, 'section', '55', 'Liability relating to rehabilitation and social reintegration: It shall be the', 'Liability relating to rehabilitation and social reintegration', 'liability of the concerned children’s home or child correction home to assist the
24
www.lawcommission.gov.np
child welfare authority in the rehabilitation and social reintegration of the children
staying at that children’s home or child correction home.', 7, 'The Act Relating to Children, 2075 (2018), CHAPTER 5, Section 55 (Liability relating to rehabilitation and social reintegration)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5.8', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5', 2, 'section', '56', 'Chief of the organization to be responsible: (1) If an organization is entrusted', 'Chief of the organization to be responsible', 'with the guardianship of a child pursuant to this Chapter, the chief of the
organization shall be deemed to have the ultimate responsibility for the care and
maintenance of the child.
Clarification: For the purposes of this Section, “chief of the organization”
means the chief executive officer or chairperson, managing director of such an
organization acting in that capacity or such other officer as designated pursuant to
the rules of that organization.
(2) If any organization that has been entrusted with the responsibility of
guardianship acts in contravention of the prescribed conditions and procedures,
the child welfare authority may prevent the organization from engaging in child
protection activities, also setting out the conditions breached by it.
(3) If it is established from the monitoring that an organization that has
been prevented pursuant to sub-section (2) has made desired improvements, the
child welfare authority may remove the prevention made on the organization from
engaging in child protection activities.', 8, 'The Act Relating to Children, 2075 (2018), CHAPTER 5, Section 56 (Chief of the organization to be responsible)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5.9', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5', 2, 'section', '57', 'Standards relating to child protection: (1) A school, every public body, private', 'Standards relating to child protection', 'sector as well as social organization directly working with children shall formulate
and enforce child protection standards at the institutional level, in order to prevent
violence against children or child sexual abuse, ensure protection of children and
immediately take action on complaints.
(2) It shall be the liability of the school, chief of every public body, private
sector and social organization to enforce the child protection standards formulated
pursuant to sub-section (1).', 9, 'The Act Relating to Children, 2075 (2018), CHAPTER 5, Section 57 (Standards relating to child protection)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5.10', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:5', 2, 'section', '58', 'Monitoring and reporting: (1) The person, guardian or organization that has', 'Monitoring and reporting', 'assumed the responsibility of care and maintenance of children pursuant to this
Act shall submit details of the children to the Local Child Rights Committee
through the Child Welfare Authority concerned, within three weeks of the
expiration of each fiscal year.
(2) Based on the details received pursuant to sub-section (1), the Local
Child Rights Committee shall prepare and submit a report to the Provincial level
25
www.lawcommission.gov.np
Child Rights Committee and Local Level Child Rights Committee on an annual
basis.
(3) The Provincial Child Rights Committee and Local Child Rights
Committee shall periodically inspect and monitor the overall status of children and
the quality and effectiveness of the available services within the Province and the
Local Level, respectively.', 10, 'The Act Relating to Children, 2075 (2018), CHAPTER 5, Section 58 (Monitoring and reporting)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:6', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', NULL, 1, 'chapter', 'Chapter- 6', 'Chapter- 6', NULL, NULL, 6, 'The Act Relating to Children, 2075 (2018), Chapter- 6', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:6.0', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:6', 2, 'section', '59', 'National Child Rights Council: (1) There shall be a National Child Rights', 'National Child Rights Council', 'Council, as prescribed, under the chairpersonship of the Government of Nepal,
Minister for Women, Children and Senior Citizens, in order to protect and promote
the rights and interests of the child.
(2) The provisions relating to the meeting, functions, duties and powers of
the Council shall be as prescribed.', 0, 'The Act Relating to Children, 2075 (2018), Chapter- 6, Section 59 (National Child Rights Council)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:6.1', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:6', 2, 'section', '60', 'Provincial and Local Level Child Rights Committee: (1) There shall be a', 'Provincial and Local Level Child Rights Committee', 'Provincial Child Rights Committee in each Province, to be chaired by the Minister
of the Province overseeing the matters relating to children.
(2) There shall be a Local Child Rights Committee in each Local Level, to
be chaired by a Member of the Rural Municipality or Municipality designated by
the Vice-Chairperson or Deputy-Mayor of such Rural Municipal Executive or
Municipal Executive respectively.
(3) The number of members of the Provincial Child Rights Committee and
Local Child Rights Committee referred to in sub-sections (1) and (2), and the
functions, duties and rights and procedures of meetings of the Committees shall
be as determined by the Province and Local Level.', 1, 'The Act Relating to Children, 2075 (2018), Chapter- 6, Section 60 (Provincial and Local Level Child Rights Committee)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:6.2', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:6', 2, 'section', '61', 'Child welfare authority: (1) There shall be a child welfare authority at the Local', 'Child welfare authority', 'Level in order to, inter alia, respect, protect and promote the rights of the child to
carry out child protection acts.
(2) Other provisions including the appointment, functions, duties and
powers and the terms of service of the child welfare authority shall be as
prescribed.
26
www.lawcommission.gov.np', 2, 'The Act Relating to Children, 2075 (2018), Chapter- 6, Section 61 (Child welfare authority)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:6.3', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:6', 2, 'section', '62', 'Social service provider and child psychologist: (1) Any persons willing to work', 'Social service provider and child psychologist', 'as social service providers and child psychologists shall get their names enlisted
themselves with the Local Child Rights Committee, as prescribed.
(2) Social service providers and child psychologists may be appointed in
required number, from among the social service providers and child psychologists
enlisted in the list referred to in sub-section (1), for carrying out child protection
related acts and delivering services at the Local Level.
(3) The social service providers and child psychologists appointed pursuant
to sub-section (2) shall act under the direct guidance and supervision of the child
welfare authority.
(4) The social service providers and child psychologists required for the
juvenile court shall be appointed from among the social service providers and child
psychologists enlisted pursuant to sub-section (1).
(5) The process of appointment, qualifications, functions, duties, powers,
terms of service and other provisions related to social service providers and child
psychologists shall be as prescribed.', 3, 'The Act Relating to Children, 2075 (2018), Chapter- 6, Section 62 (Social service provider and child psychologist)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:6.4', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:6', 2, 'section', '63', 'Child Fund: (1) There shall be a child fund, also for performing acts such as', 'Child Fund', 'immediate rescue, relief and rehabilitation and providing compensation to
children.
(2) The fund referred to in sub-section (1) shall consist of the following
amounts:
(a) Amounts received from the Government of Nepal, Provincial
Government and Local Level,
(b) Amounts received from a foreign government, international agency,
organization or individual,
(c) Amounts received from a native person, agency or organization,
(d) Amounts received in lieu of fines imposed by the juvenile court,
(e) Amounts received from any other source.
(3) The permission of the Government of Nepal, Ministry of Finance shall
be obtained prior to receiving amounts pursuant to clause (b) of sub-section (2).
(4) The amounts of the fund referred to in sub-section (1) may also be made
available to the children''s fund of the Province and Local Level in accordance with
law.
27
www.lawcommission.gov.np
(5) The provisions relating to the management, operation and use of the
fund referred to in sub-section (1) shall be as prescribed.', 4, 'The Act Relating to Children, 2075 (2018), Chapter- 6, Section 63 (Child Fund)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:7', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', NULL, 1, 'chapter', 'Chapter 7', 'Chapter 7', NULL, NULL, 7, 'The Act Relating to Children, 2075 (2018), Chapter 7', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:7.0', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:7', 2, 'section', '64', 'Local Level to enforce the rights of the child: (1) If a person violates the rights', 'Local Level to enforce the rights of the child', 'of a child referred to in Chapter 2 or does not fulfil his or her liabilities towards
the child referred to in Chapter 3, the concerned child or the stakeholder may file
an application with the judicial committee of the Local Level where the child is
residing, for the enforcement of such rights or liabilities.
(2) If an application is received pursuant to sub-section (1), the judicial
committee may require the person concerned to appear within twenty-four hours,
excluding the time required for journey, and make necessary inquiry.
(3) If, in making inquiry pursuant to sub-section (2), it appears that the
person concerned has violated the rights of the child or has not fulfilled her or his
liabilities towards the child, the judicial committee shall, within thirty days of the
receipt of the application, order the person, organization or agency concerned at
the Local Level to enforce the rights of the child or fulfil the liabilities towards
the child.
(4) If, in making inquiry pursuant to sub-section (2), it appears that the
matter of enforcing the rights of the child or fulfilment of the liabilities towards
the child does not fall under its jurisdiction, the judicial committee shall write to
the judicial committee of the other Local Level concerned to enforce the rights of
the child or fulfil the liabilities towards the child.
(5) If a correspondence is received pursuant to sub-section (4), the judicial
committee of the Local Level concerned shall make arrangements to enforce the
rights of the child and fulfilment of the liabilities towards the child pursuant to
sub-section (3).
(6) While enforcing the rights of the child or fulfilment of the liabilities
towards the child pursuant to this Section, the judicial committee may give
necessary suggestions to the child, guardian or family member or warning to the
guardian or family member.', 0, 'The Act Relating to Children, 2075 (2018), Chapter 7, Section 64 (Local Level to enforce the rights of the child)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:7.1', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:7', 2, 'section', '65', 'To enforce the rights of the child: (1) Notwithstanding anything contained in', 'To enforce the rights of the child', 'Section 64, if a person violates the rights of the child referred to in Chapter-2 or
28
www.lawcommission.gov.np
does not fulfil the liabilities towards the child referred to in Chapter-3, the
concerned child or stakeholder may file an application directly to the concerned
High Court to have the said rights enforced or the said liabilities fulfilled.
(2) If an application is received pursuant to sub-section (1), the High Court
shall make necessary inquiry into the application and make an appropriate order
to the person, organization or agency concerned to enforce the rights of the child
or fulfil the duties towards the child.
(3) If, in making inquiry into the application received pursuant to sub-
section (1), it appears that the guardian or family member has violated the rights
of the child or has not fulfilled his or her liabilities towards the child, the High
Court shall inform such a guardian or family member about the rights of the child
and have him or her make commitment to not to repeat the violation of the rights
of the child or to fulfil his or her liabilities towards the child.
(4) While making an order pursuant to sub-section (2), the High Court may
warn the person or chief of the organization or agency that has violated the rights
of the child or has not fulfilled their duties towards the child or to impose
punishment on them and order the recovery of compensation from them pursuant
to this Act.', 1, 'The Act Relating to Children, 2075 (2018), Chapter 7, Section 65 (To enforce the rights of the child)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:8', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', NULL, 1, 'chapter', 'Chapter 8', 'Chapter 8', NULL, NULL, 8, 'The Act Relating to Children, 2075 (2018), Chapter 8', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:8.0', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:8', 2, 'section', '66', 'Offences against the child: (1) If any person does any act of violence referred to', 'Offences against the child', 'in sub-section (2) or sexual abuse referred to in sub-section (3), he or she shall be
deemed to have committed the offence against the child under this Act.
(2) If any person does any of the following acts against a child, he or she
shall be deemed to have committed the act of violence against the child:
(a) To involve the child in addictions such as smoking, drinking or
gambling,
(b) To allow him or her to enter to, or use him or her in, recreational
facilities opened for the adults such as dance bars and casinos,
(c) To show him or her motion pictures or other audio-visual materials
classified as for the adults only,
29
www.lawcommission.gov.np
(d) To inflict physical or mental punishment on, or behave, in an
undignified manner, him or her whether at home, school or any other
place,
(e) To inflict physical injuries or effect to, terrorize or intimidate,
humiliate, neglect, discriminate, exclude or hate, isolate, or cause
mental torture to, him or her,
(f) To harass, cause pain to, him or her by using electronic or other
means,
(g) To organize him or her for the political purpose or use him or her in
a strike, shutdown, transportation strike, sit-ins or rally,
(h) To keep him or her in illegal confinement, detention, prison or house
arrest, handcuff him or her,
(i) To treat him or her in a cruel or inhumane manner or torture him or
her,
(j) To cause him or her to beg or disguise as an ascetic, monk or
mendicant, except for the tradition, custom or any religious or
cultural activity,
(k) To forcibly declare, or register him or her, as an orphan,
(l) To offer or dedicate him or her in the pretext of a pledge, religious
or any other purpose, or subject him or her to violence,
discrimination, neglect or exclusion or mockery in the pretext of the
custom, culture or ritual,
(m) To engage him or her in a magic or circus show,
(n) To teach or train him or her to commit any offense or involve him
or her in such offense,
(o) To fix his or her marriage, or marry, or cause to marry, him or her,
(p) To remove any organ of him or her in contravention of the prevailing
law,
(q) To use him or her for medical or any other experiment,
(r) To keep him or her in a children’s home, except in accordance with
law.
(3) If any person does any of the following acts against a child, he or she
shall be deemed to have committed child sexual abuse:
30
www.lawcommission.gov.np
(a) To show, or cause to show, him or her an obscene picture, audio-
visual recording or other material of similar kind or display, or cause
to display, such expression or gesture that reflects obscene or sexual
conduct or behaviour to him or her or display, or cause to display,
child pornography,
(b) To distribute, store or use any actual or fictitious obscene picture or
audio-visual material of him or her,
(c) To propose, lure, coerce or threaten him or her for sexual activity,
(d) To use him or her in the production of an obscene act and material,
(e) To touch, kiss, hold sensitive parts of body of him or her, embrace
him or her with sexual intent or cause him or her to touch or hold
sensitive parts of own body or body of another person or render him
or her unconscious with sexual intent or display, or cause him or her
to display sexual organs,
(f) To use, or cause to use, him or her for stimulating sexual lust or
sexual excitement,
(g) To use, or cause to use, him or her for the purpose of sexual
gratification,
(h) To engage, or cause to engage, in child sexual exploitation,
(i) To use, or cause to use, him or her with the intent of providing
sexual services,
(j) To use, or cause to use, him or her with the intent of engaging in
sexual abuse,
(k) To use him or her in prostitution or other sexual work.
(4) Notwithstanding anything contained in sub-section (3), anything that is
expressed by means of writing, speaking, gesturing or displaying any word,
picture, audio, visual means and object or material on a sex related matter without
displaying obscenity with the aim of imparting information and education or an
act done in good faith in the course of making treatment of the child or saving the
child from an accident or risk shall not be deemed to constitute an act of sexual
abuse.', 0, 'The Act Relating to Children, 2075 (2018), Chapter 8, Section 66 (Offences against the child)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:8.1', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:8', 2, 'section', '67', 'Not to be deemed eligible: (1) If it is held that a person who is serving in any', 'Not to be deemed eligible', 'public or private organization commits any offence against the child, the person
shall be dismissed in accordance with the prevailing law, and, based on the gravity
31
www.lawcommission.gov.np
and nature of the offence, such a person shall not be deemed eligible for up to ten
years to be involved in the future in any act involving direct contact with the child
or to be appointed, nominated or elected to such a private institution or
organization.
(2) A person who is convicted of child sexual abuse pursuant to this Act or
the prevailing law shall be deemed to have committed a criminal offence involving
moral turpitude.', 1, 'The Act Relating to Children, 2075 (2018), Chapter 8, Section 67 (Not to be deemed eligible)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:8.2', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:8', 2, 'section', '68', 'To give information: (1) If the father, mother, guardian, one who directly', 'To give information', 'provides services to the child such the caregiver, teacher, health-worker or any
other person comes to know that any person has committed or is committing or
going to commit act of violence or child sexual abuse against the child he or she
shall give information thereof to the nearby police office immediately.
(2) The police office concerned shall immediately give the information
referred to in sub-section (1) to the child welfare authority and seek necessary
support.
(3) While giving information with the intent of protecting the child, no legal
action shall be taken against the informant merely on the basis that he or she has
given such information.
(4) The identity of the informant who gives information pursuant to sub-
section (1) shall be kept confidential if he or she so desires.', 2, 'The Act Relating to Children, 2075 (2018), Chapter 8, Section 68 (To give information)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:8.3', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:8', 2, 'section', '69', 'Temporary protection service: The Government of Nepal shall make', 'Temporary protection service', 'arrangements for temporary protection service for safe accommodation of the
children who appear to be in need of immediate rescue and protection.', 3, 'The Act Relating to Children, 2075 (2018), Chapter 8, Section 69 (Temporary protection service)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:8.4', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:8', 2, 'section', '70', 'Rescue, protection and health check-up to be made: (1) If the police employee', 'Rescue, protection and health check-up to be made', 'receives any information, complaint or report about violence against the child or
child sexual abuse, he or she shall write, or cause to write, necessary details and
register it, and if the child needs to be rescued immediately, rescue him or her and
refer the victim child to a temporary protection service.
(2) If it appears that the child victim is in physical or mental pain, the police
employee shall send him or her to a nearby hospital or health centre and have his
or her health checked up and treated.
(3) While taking the statement of the child victim, the police employee shall
do so in the presence of his or her parents, other family member or guardian if it
32
www.lawcommission.gov.np
is possible that they can so appear, and if they cannot so appear, in the presence
of a female representative of a social organization or a social service provider.
Provided that if the parents, guardian or other family members are the
perpetrator of violence against children or child sexual abuse, their presence shall
not be allowed during the taking of such statement.', 4, 'The Act Relating to Children, 2075 (2018), Chapter 8, Section 70 (Rescue, protection and health check-up to be made)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:8.5', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:8', 2, 'section', '71', 'Rehabilitation centre: (1) The Government of Nepal shall establish rehabilitation', 'Rehabilitation centre', 'centres, as required, for physical or mental treatment or social rehabilitation of the
child victims of offences against the child.
(2) An organization may, for the purposes of sub-section (1), establish a
rehabilitation centre by obtaining permission from the Government of Nepal as
prescribed.
(3) The services and facilities to be made available at the rehabilitation
centres and other provisions including those relating to the management,
operation, monitoring of such centres shall be as prescribed.
33
www.lawcommission.gov.np', 5, 'The Act Relating to Children, 2075 (2018), Chapter 8, Section 71 (Rehabilitation centre)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:9', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', NULL, 1, 'chapter', 'Chapter-9', 'Chapter-9', NULL, NULL, 9, 'The Act Relating to Children, 2075 (2018), Chapter-9', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:9.0', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:9', 2, 'section', '72', 'Punishment: (1) If any person, organization or body violates any of the child', 'Punishment', 'rights set forth in Chapter-2 or does not fulfil any of the liabilities towards the
child set forth in Chapter-3, such a person or the chief of such organization or
body shall be liable to a fine of up to fifty thousand rupees.
(2) If the guardian or any family member does not fulfil his or her liabilities
or if the mother, father or guardian alters the name and surname of the child with
the intention of acquiring undue benefits or misappropriates the child’s property,
such a mother, father or family member or guardian shall be liable to a fine of up
to one hundred thousand rupees.
(3) A person who commits the offence against the child shall be liable to
the following punishment, according to the degree of the offence:
(a) In the case of the commission of any act referred to in clause (a),
(b), (c), (d), (e), (f) or (r) of sub-section (2) of Section 66 or sub-
section (1) or (2) of Section 78, a fine of up to fifty thousand rupees
and imprisonment for up to one year,
(b) In the case of the commission of any act referred to in clause (g),
(j), (k), (l), (m), (o) or (q) of sub-section (2) of, or clause (a), (b),
(c), (e), (f) or (i) of sub-section (3) of, Section 66, a fine of up to
seventy-five thousand rupees and imprisonment for up to three
years,
(c) In the case of the commission of any act referred to in clause (d) of
sub-section (3) of Section 66, a fine of up to eighty thousand rupees
and imprisonment for up to four years,
(d) In the case of the commission of any act referred to in clause (h) or
(i) of sub-section (2) of Section 66, a fine of up to one hundred
thousand rupees and imprisonment for up to five years,
(e) In the case of the commission of any act referred to in clause (n) of
sub-section (2) of Section 66, half the punishment that is imposable
on the liable to the offender of the offence that is taught or trained
to be committed,
34
www.lawcommission.gov.np
(f) In the case of the commission of any act referred to in clause (p) of
sub-section (2) of Section 66, a fine of up to five hundred thousand
rupees and imprisonment for up to ten years,
(g) In case of an act as per clause (g) or (h) of Sub-section (3) of Section
66, the punishment that is imposable on the offender of rape under
the prevailing law,
(h) In the case of the commission of any act referred to in clause (i) or
(k) of sub-section (3) of Section 66, a fine of up to one hundred fifty
thousand rupees and imprisonment for up to fifteen years.
(4) A person who incites another person, attempts or abets to commit any
of the acts set forth in sub-sections (1), (2) and (3) shall be liable to the punishment
of fine and imprisonment imposable on the principal offender.
(5) A person who does any act, in contravention of this Act or the rules
framed under this Act, other than that contained in this Section, shall be liable to
a fine of up to fifty thousand rupees or imprisonment for up to one year, or both
punishments, according to the degree of the offence.
(6) If a person who has been punished once under this Act repeats such act,
he or she shall be liable to an additional punishment of twenty-five per cent of the
punishment imposable pursuant to this Section.
(7) Notwithstanding anything contained elsewhere in this Section, if an act
referred to in sub-section (3) is also deemed to be an offence under any other
prevailing law, no provision of this Section shall prevent the instituting of a
separate case against, and imposing of punishment on, the offender for such
offence under that law, and, if the punishment imposable on him or her under the
prevailing law for the commission of any act in contravention of this Act exceeds
the punishment set forth in this Section, he or she liable to the punishment
accordingly.
(8) If any one establishes or operates a children’s home, child correction
home, observation chamber, rehabilitation centre or temporary protection service
centre without obtaining permission under this Act, the Ministry may shut down
such children’s home, child correction home, observation chamber, rehabilitation
centre or temporary protection service centre and impose a fine of up to one
hundred thousand rupees on the person and organization involved, and may
proceed with other additional actions in accordance with the prevailing law.
35
www.lawcommission.gov.np', 0, 'The Act Relating to Children, 2075 (2018), Chapter-9, Section 72 (Punishment)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:9.1', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:9', 2, 'section', '73', 'Compensation: (1) The juvenile court shall cause the recovery of such a', 'Compensation', 'reasonable compensation in lump sum or instalments from the offender to the
victim child that is not less than the amount of fine imposed on the offender
committing the offence against the child under this Act and the prevailing law,
having regard to, inter alia, the loss caused to the education, and physical and
mental health, development and family of the child victim.
(2) In cases where the amount of fine cannot be recovered pursuant to sub-
section (1) from the offender or if the Juvenile Court is of the opinion that such
amount of fine, even if recovered, is negligible or inadequate in comparison to the
offence against the child, the Juvenile Court shall cause the payment of a
reasonable amount of compensation to the child victim from the Child Fund
referred to in Section 63.
(3) If the child victim dies before receiving the amount of compensation
referred to in sub-section (1), such amount shall be provided to his or her father,
mother or, if they are not available, to other family member or guardian.
(4) If it is necessary to immediately carry out medical treatment of or
provide compensation or any kind of relief to the child victim of an offence against
the child under the prevailing law or offence against the child, interim
compensation shall be provided in accordance with the prevailing law.', 1, 'The Act Relating to Children, 2075 (2018), Chapter-9, Section 73 (Compensation)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:9.2', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:9', 2, 'section', '74', 'Statute of limitation: (1) In relation to any offence under Section 66, a case has', 'Statute of limitation', 'to be filed within the statute of limitation, if any, specified in the prevailing law,
and, if not so specified, within one year of the date of the commission of that
offence.
(2) In cases where no case has been filed pursuant to sub-section (1),
notwithstanding anything contained in the prevailing law, the statute of limitation
for filing the case with respect to the offence against the child shall continue to
exist until one year after such a child has attained the age of eighteen years.', 2, 'The Act Relating to Children, 2075 (2018), Chapter-9, Section 74 (Statute of limitation)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:9.3', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:9', 2, 'section', '75', 'Power to try cases: The Juvenile Court shall have the power to try and dispose of', 'Power to try cases', 'cases punishable under the sub-sections other than sub-section (8) of Section 72.', 3, 'The Act Relating to Children, 2075 (2018), Chapter-9, Section 75 (Power to try cases)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:9.4', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:9', 2, 'section', '76', 'Government of Nepal to be plaintiff: In the cases under Section 66, the', 'Government of Nepal to be plaintiff', 'Government of Nepal shall be the plaintiff, and such cases shall be deemed to be
included in Schedule 1 of the National Criminal Procedure (Code) Act 2017.', 4, 'The Act Relating to Children, 2075 (2018), Chapter-9, Section 76 (Government of Nepal to be plaintiff)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', NULL, 1, 'chapter', 'Chapter 10', 'Chapter 10', NULL, NULL, 10, 'The Act Relating to Children, 2075 (2018), Chapter 10', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10.0', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10', 2, 'section', '77', 'Duties of the child: (1) It shall be the duty of every child to respect his or her', 'Duties of the child', 'father, mother, guardian, other family members, teachers and social service
providers and obey the advice, suggestion, guidance and instruction given by
them, taking into consideration of his or her best interests.', 0, 'The Act Relating to Children, 2075 (2018), Chapter 10, Section 77 (Duties of the child)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10.1', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10', 2, 'section', '78', 'To maintain confidentiality: (1) No person shall publish or broadcast through', 'To maintain confidentiality', 'print or electronic media any details that discloses the identity of a child concerned
with a case that is sub judice in the Juvenile Court.
(2) No person shall broadcast information or news through any
communication media by disclosing the identity of a child victim of an offence
against children.
(3) The police, government attorney or Juvenile Court shall make
arrangements for maintaining records of child victims of the offences against
children, without disclosing their names and identity.
(4) The investigation authority, government attorney and Juvenile Court
shall keep the identity of children in conflict with law confidential. Copies of
documents related to such charge shall not be given to any person other than the
concerned police and government attorney’s office, Juvenile Court, the child
concerned, family members, guardian, legal practitioner of the concerned child
and Central and District Child Justice Committee.
(5) Notwithstanding anything contained elsewhere in this Section, the
details related to the child may be published or broadcast as follows, in the
following circumstance:
(a) If publishing or broadcasting the details relating to the children in
conflict with law does not adversely affect the interests of such
children, such details, with the permission of the Juvenile Court,
(b) Data on the children in conflict with law may be published with the
permission of the concerned agency, for any study or research, with
the disclosure of their age or gender, without disclosing their names,
surnames, personal details and addresses.', 1, 'The Act Relating to Children, 2075 (2018), Chapter 10, Section 78 (To maintain confidentiality)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10.2', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10', 2, 'section', '79', 'Provisions relating to probation authority: (1) The Government of Nepal shall', 'Provisions relating to probation authority', 'appoint the probation authority in each district to carry out, inter alia, investigation
into the concerned case, inspection of the observation chamber, diversion, and
37
www.lawcommission.gov.np
preparation of reports on the status of implementation of the orders by the Juvenile
Court, in close contact with the children accused of offense.
(2) Until the probation authority is appointed, the Government of Nepal
may designate any authority of the Government of Nepal to act as the probation
authority.
(3) The functions, duties, powers and terms and conditions of service of,
and other provisions relating to, the probation authority shall be as prescribed.', 2, 'The Act Relating to Children, 2075 (2018), Chapter 10, Section 79 (Provisions relating to probation authority)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10.3', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10', 2, 'section', '80', 'Case not to be tried and disposed of without legal practitioner: (1)', 'Case not to be tried and disposed of without legal practitioner', 'Notwithstanding anything contained in the prevailing law, the Juvenile Court shall
not try and dispose of a case involving a child charged with committing an offense
until a legal practitioner is appointed for defending the child.
(2) In cases where no legal practitioner has been appointed on behalf of a
child accused of an offense, the concerned Juvenile Court shall make arrangements
to make service available from a paid legal practitioner or any other interested
legal practitioner.', 3, 'The Act Relating to Children, 2075 (2018), Chapter 10, Section 80 (Case not to be tried and disposed of without legal practitioner)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10.4', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10', 2, 'section', '81', 'Appeal: (1) In the case of not being satisfied with the decision made by the', 'Appeal', 'Juvenile Court or by the Ministry pursuant to sub-section (8) of Section 72, an
appeal may be filed in the concerned High Court within thirty-five days of such a
decision.
(2) Notwithstanding anything contained in sub-section (1) and in the
prevailing law, no appeal shall be admissible against a decision of the Juvenile
Court that acquits a child, other than in the circumstances affecting justice because
of erroneous interpretation of law, wrong use of precedent or non-admission of an
admissible evidence or admission of a non-admissible evidence.', 4, 'The Act Relating to Children, 2075 (2018), Chapter 10, Section 81 (Appeal)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10.5', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10', 2, 'section', '82', 'Priority to be given in proceedings of case: Priority shall be given to the', 'Priority to be given in proceedings of case', 'proceedings, trial and disposal of cases involving children either as plaintiff or
defendant in the courts other than the Juvenile Court.', 5, 'The Act Relating to Children, 2075 (2018), Chapter 10, Section 82 (Priority to be given in proceedings of case)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10.6', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10', 2, 'section', '83', 'Basis for determining children’s age: While determining the age of a child, the', 'Basis for determining children’s age', 'following matters shall be taken as the basis:
(a) The date of birth recorded in the child’s birth registration issued by
the hospital,
(b) If the date of birth referred to in clause (a) is not available, the date
of birth recorded in the child’s birth registration certificate issued
by the Local Registrar’s Office,
38
www.lawcommission.gov.np
(c) If the certificate referred to in clause (b) is not available, the date of
birth recorded in the child’s school character certificate or the date
of birth recorded at the time of child’s admission to the school,
(d) If the certificate referred to in clause (b) or the date of birth is not
available, the date recorded in the certificate of age issued by the
hospital,
(e) If the certificate referred to in clause (d) is not available, the age
recorded in the Janmakundali (birth chart), Cheena (horoscope),
notes, or the age disclosed by the father, mother, guardian or any
other family member of the child or similar other relevant evidence.', 6, 'The Act Relating to Children, 2075 (2018), Chapter 10, Section 83 (Basis for determining children’s age)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10.7', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10', 2, 'section', '84', 'Act to prevail: The matters contained in this Act shall be governed by this Act', 'Act to prevail', 'and the other matters shall be governed by the prevailing law.', 7, 'The Act Relating to Children, 2075 (2018), Chapter 10, Section 84 (Act to prevail)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10.8', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10', 2, 'section', '85', 'Power to frame rules: The Government of Nepal may frame necessary rules in', 'Power to frame rules', 'order to implement the objectives of this Act.
Provided that the Supreme Court may frame the rules relating to procedures
on the dispensation of juvenile justice.', 8, 'The Act Relating to Children, 2075 (2018), Chapter 10, Section 85 (Power to frame rules)', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10.9', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10', 2, 'section', '86', 'Power to frame guidelines and operational procedures: (1) The Ministry may', 'Power to frame guidelines and operational procedures', 'frame guidelines and operational procedures, as necessary, subject to this Act and
the Rules framed under this Act.
(2) The Supreme Court may frame juvenile justice procedures or guidelines
subject to this Act or the Rules framed under this Act.', 9, 'The Act Relating to Children, 2075 (2018), Chapter 10, Section 86 (Power to frame guidelines and operational procedures)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10.10', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child', 'doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child:10', 2, 'section', '87', 'Amendment, repeal and saving: (1) The following clause (a) shall be substituted', 'Amendment, repeal and saving', 'for clause (a) of sub-section (1) of Section 4 of the Births, Deaths and Other
Personal Events (Registration) Act, 2033 (1976):
“(a) Information on birth and death by the father, mother, any family
member or guardian,”
(2) The Act Relating to Children, 2048 (1992) is hereby repealed.
(3) Any acts done and actions taken pursuant to the Act Relating to
Children, 2048 (1992) shall be deemed to have been done and taken under this
Act.
39', 10, 'The Act Relating to Children, 2075 (2018), Chapter 10, Section 87 (Amendment, repeal and saving)', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:0', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', NULL, 1, 'preamble', 'Preamble', 'Introductory matter', NULL, 'The Consumer Protection Act, 2075 (2018)
Date of Authentication
2075/6/2 (18 September 2018)
Act Number 10 of the year 2075 (2018)
An Act Made to Provide for Amendment and Consolidation of Laws
Relating to Consumer Protection
Preamble:
Whereas, it is expedient to make amendment to and consolidation of the legal
provisions relating to consumer protection in order to protect and promote constitutional
rights of the consumers to obtain quality goods and services, to provide judicial remedy
for the enforcement of the rights obtained by the consumers, and provide compensation
for harm and injury likely to be caused to the consumers;
Now, therefore, be it enacted by the Federal Parliament.', 0, 'The Consumer Protection Act, 2075 (2018), Preamble', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:1', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', NULL, 1, 'chapter', 'Chapter-1', 'Chapter-1', NULL, NULL, 1, 'The Consumer Protection Act, 2075 (2018), Chapter-1', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:1.0', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:1', 2, 'section', '1', 'Short Title and Commencement: (1) This Act may be cited as the “Consumer', 'Short Title and Commencement', 'Protection Act, 2075 (2018)."
(2) This Act shall commence immediately.', 0, 'The Consumer Protection Act, 2075 (2018), Chapter-1, Section 1 (Short Title and Commencement)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:1.1', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:1', 2, 'section', '2', 'Definition: Unless the subject or the context otherwise requires, in this Act,-', 'Definition', '(a) "Court" means the Consumer Court referred to in Section 41.
(b) "Unfair trade and business" means any activity referred to in Section
16.
(c) "Production" means the process of producing, preparing, refining,
changing, mixing, packaging or repackaging, assembling or
labeling, or any or all the processes to be adopted in this regard
(d) "Consumer" means a person or institution that consumes or uses any
goods or services.
(e) "Consumer association" means the institution established under the
prevailing law with the objective of protecting and promoting the
rights and welfare of the consumers.
(f) "Central Monitoring Committee" means the Central Market
Monitoring Committee referred to in Section 25.
1
(g) "Sub-standard goods" means consumer goods of any of the
following conditions:
(1) Goods the quality of which falls short of the standards
determined under Section 6 or in which the quantity of an
essential ingredient has been lowered, or any other material
has been mixed.
(2) Goods which are stale, rotten or stored or prepared in dirty
or toxic conditions or in which any chemical, colour or
flavour has been used, so that they become harmful to human
health,
(3) Goods which are fully or partly made of any diseased or
disease-generating animals or birds or harmful vegetation,
(4) Goods which are produced, transported, hoarded, stored or
sold without meeting the standard prescribed,
(5) Goods which have no quality of consumable goods if it is
prescribed, and as mentioned by the producer, if it is not
prescribed,
(6) Goods the quality of which falls short of the minimum
necessary standards or exceeds the maximum standards
prescribed, if any, in this Act or in the rules framed under
this Act.
(h) "Prescribed" or "as prescribed" means prescribed or as prescribed in
the rules framed under this Act.
(i) "Inspection Officer" means the Inspection Officer appointed or
designated pursuant to Section 32.
(j) "Council" means the Consumer Protection Council to be formed
pursuant to sub-section (1) of Section 22.
(k) "Laboratory" means the body established with the objective of
testing the purity, perfection or quality of the goods and recognized
by the Government of Nepal.
(l) "Ministry" means the Ministry of Industry, Commerce and Supply
of the Government of Nepal.
(m) "Label" means a tag, sign, picture or other descriptive thing written,
printed, lithographed, signed, embossed, included or displayed in
2
any other manner, in or on the goods or the container containing
such goods.
(m) "Goods" means the substance which the consumers consume or use
or the materials made of the mixture of goods which do not inflict
harm and injury or any kind of side effect to health, and this term
also includes the raw material, colour, fragrance or chemical to be
used in the production of such goods.
(n) "Price of goods" means the price the price labeled at the time of
production, maximum retail price (M.R.P.), the price fixed in the
import declaration form or the price fixed at the source by the
producer.
(o) "Seller" means the person, firm, company or institution that sells
and distributes goods or services.
(p) "Department" means the Commerce, Supplies and Consumer
Welfare Protection Department.
(q) "Service" means electricity, drinking water supply, telephone,
information technology, health, education and consultation,
transport, drainage, banking or other services of similar nature, and
this term also includes legal, medical or engineering services.
(r) "Defective product" means any goods or services that do not contain
such minimum safety measures due to any of the following as are
reasonably expected by the general people while using any product:
(1) defective design, construction, refinement, mixture or
installation,
(2) defective packaging, protection or storage,
(3) defective presentation,
(4) lack of sufficient measure or precaution to control the
potential risk or hazard as per the nature of the produced
goods or services,
(5) product which is different or pirated or imitated from the
product produced by the manufacturing company possessing
the intellectual property right.', 1, 'The Consumer Protection Act, 2075 (2018), Chapter-1, Section 2 (Definition)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:2', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', NULL, 1, 'chapter', 'Chapter-2', 'Chapter-2', NULL, NULL, 2, 'The Consumer Protection Act, 2075 (2018), Chapter-2', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:2.0', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:2', 2, 'section', '3', 'Rights of the consumer: (1) Every consumer shall have the right to obtain quality', 'Rights of the consumer', 'goods and services.
(2) Without prejudice to the generality of sub-section (1), for the
purpose of protecting the rights, interests and concern of the consumers, every
consumer shall have the following rights:
(a) right of easy access to goods or services,
(b) right to choose quality goods or services at the fair
competitive price,
(c) right to be informed of the price, quantity, purity, quality etc.
of the goods or services,
(d) right to obtain information from the producer, importer or
seller regarding the quantity, ingredient or percentage of the
substances contained in the goods made of or produced with
the mixture of two or more than two substances,
(e) right to be safe from the sale and distribution of the goods
and services that inflict harm to the human body, life, health
and property,
(f) right to get appropriate legal action taken against the unfair
trade and business activities,
(g) right to obtain compensation against harm and injury caused
with the use of goods or services,
(h) right to receive remedy or hearing from the competent
authority or entity on the protection of the rights and interests
of the consumers,
(i) right to get consumer education.', 0, 'The Consumer Protection Act, 2075 (2018), Chapter-2, Section 3 (Rights of the consumer)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:2.1', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:2', 2, 'section', '4', 'Regulation of goods or services: (1) The Government of Nepal shall regulate the', 'Regulation of goods or services', 'supplies, price, quality, measurement, label, advertisement of the goods and
services regularly in order to protect the rights of the consumers.
(2) The Ministry shall perform the following functions in conducting
regulation pursuant to sub-section (1):
(a) to implement the policy relating to quality, price
determination and supply system of goods or services,
(b) to prevent or control monopoly or unfair trade activities that
cause or possibly cause adverse impact upon the rights and
4
interests of the consumers, or to formulate and implement a
plan of action in this regard,
(c) to maintain fair market by continuously analyzing and
reviewing the condition of demand and supply of the goods
or services used within the country,
(d) to make necessary provisions to prevent and control the price
determined or increased in an undesired manner by the
producer, seller or distributor of the goods or services,
(e) to facilitate the supply system through the institutions or
private firms or companies having full or partial ownership
of the Government of Nepal in order to ensure the supplies
of the food and other goods for the consumers at a fair price
and easy manner,
(f) to fix the maximum quantity of the storage of the goods in
any special circumstance, or at any particular place, for the
period prescribed,
(g) to receive foods from the producers at the prescribed price
and sell them to the general people with determining certain
quantity of such foods in case there is a shortage of any foods
produced within Nepal,
(h) to make necessary provision to maintain uniformity in the
price in general, by managing wholesale or retail business,
(i) to coordinate with the concerned agencies to prevent
artificial shortage of any goods or services from occurring or
to regularly distribute the goods in all places, for protecting
the rights of the consumers and regulating the supply system,
(j) to regulate the sale and distribution system of goods, and
control the act of creating scarcity or black-marketing in an
inappropriate manner or the unfair business activities.
(3) The Government of Nepal may, in order to protect the rights of the
consumers, regulate the supply system and control the price and quality of the
goods and services, make necessary policy and institutional provisions from time
to time.
(4) The provision referred to in sub-section (3) shall have to be
implemented as prescribed.
5', 1, 'The Consumer Protection Act, 2075 (2018), Chapter-2, Section 4 (Regulation of goods or services)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:2.2', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:2', 2, 'section', '5', 'Quality of goods and services: (1) In case the quality or standards of any', 'Quality of goods and services', 'substance inherent in any goods have not been determined, the Government of
Nepal shall determine the standards or quality of such goods or services by
fulfilling the process as prescribed.
(2) The Government of Nepal shall have to publish the notice of the
matters of the standards or quality of any goods or service determined pursuant to
sub-section (1) in the Nepal Gazette.', 2, 'The Consumer Protection Act, 2075 (2018), Chapter-2, Section 5 (Quality of goods and services)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:2.3', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:2', 2, 'section', '6', 'To affix label: (1) A producer shall have to affix label on the goods produced by', 'To affix label', 'him or her.
(2) The following matters shall have to be mentioned in the label
pursuant to sub-section (1):
(a) Name, address of the producer and registration number of the
industry,
(b) Mixture, ingredient of mixture, quantity and weight of the
goods, in such goods as food, medicines and cosmetics,
(c) In the case of the goods of which quality has been
determined, the quality of such goods,
(d) Mode of using the goods and side effect likely to occur due
to the use of such goods,
(e) In the case of the goods supposed to be used within a certain
deadline, such deadline,
(f) Retail price, batch number and date of manufacture of the
goods,
(g) If it is electronic, hardware, electrical or machinery or goods
to be in use for a long time, guarantee or warranty and
guarantee or warranty date of such goods, and other
necessary things in accordance with the law related to such
goods,
(h) If any defect is seen in the condition referred to in clause (g),
provision to make reimbursement or to repair until certain
period,
(i) In the case of the goods that are inflammable, hazardous or
likely to break down easily, details relating to precaution to
be adopted for the safety of such goods,
6
(j) Maximum retail price to be incurred after including all types
of taxes applicable for the goods,
(k) If any process is supposed to be fulfilled prior to using any
goods, such process; and harm and injury likely to occur
when it is used without fulfilling such process,
(l) Use of awareness-oriented message, picture or sign on the
label of the materials of the types of causing harm upon
human health,
(m) Other matters as prescribed.
(3) The matters to be specified in the label pursuant to sub-section (2)
shall have to be written in the Nepali or English language by the producer in the
case of the goods produced within Nepal and by the importer in the case of the
goods imported, in the way which can be understood by common people.
(4) The goods on which label is not affixed pursuant to sub-section (3)
shall not be allowed to be imported, sold and distributed in Nepal.
(5) Notwithstanding anything contained elsewhere in this Section, it
shall not be necessary to specify the matters set forth in this Section, while selling
consumable goods such as vegetables, fruits to be sold openly.
Provided that the label shall have to be affixed on the imported vegetables
and fruits.', 3, 'The Consumer Protection Act, 2075 (2018), Chapter-2, Section 6 (To affix label)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', NULL, 1, 'chapter', 'Chapter-3', 'Chapter-3', NULL, NULL, 3, 'The Consumer Protection Act, 2075 (2018), Chapter-3', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3.0', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3', 2, 'section', '7', 'Liability of producer: (1) While producing goods or services, the producer shall', 'Liability of producer', 'have to fulfill the following liabilities, in addition to the liabilities to be fulfilled
under the prevailing laws:
(a) to produce quality goods or services,
(b) to determine the label of the goods,
(c) to specify the matters referred to in Section 6 on the label,
(d) not to produce defective product,
(e) to collect and destroy the goods produced by him or her if it
is informed that such goods remain in the market upon
having been defectively produced,
7
(f) to provide reasonable compensation if any kind of damage is
caused to the consumer due to the manufacture of goods and
service,
(g) not to make wrong or misleading advertisement or publicity
of the goods or services,
(h) to provide the consumer with information as to the quantity,
ingredients or percentage of the substances contained in the
goods made of or produced with the mixture of two or more
than two substances.
(i) to fulfill such other conditions as prescribed by the law.
(2) If the liability pursuant to sub-section (1) is not fulfilled or any
fault, deficiency and defect occurs in the process of production, construction,
refinement, design, formula, preparation, import, packing, labeling, and harm and
injury is caused to anyone’s body, life, property after using such goods or services,
the producer of such goods or services shall be responsible for such harm and
injury and shall have the liability to provide compensation for the same.
Provided that,
(a) it must be the actual producer of the goods or services, the
use of which causes harm and injury,
(b) direct cause must be established that harm and injury is
caused with the consumption or use of the goods or services
as claimed for causing such harm and injury.', 0, 'The Consumer Protection Act, 2075 (2018), Chapter-3, Section 7 (Liability of producer)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3.1', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3', 2, 'section', '8', 'Liability of importer: (1) While importing goods, the importer shall have to', 'Liability of importer', 'fulfill the following liabilities, in addition to the liabilities to be fulfilled under
law:
(a) to import without exceeding or making different from the
cost price,
(b) to provide details of the goods relating to the imported goods
when so demanded by the concerned agency or official,
(c) not to import the goods prohibited to be imported under the
prevailing law,
(d) to fulfill such other liabilities as prescribed.
(2) Notwithstanding anything contained in sub-section (1), except for
the provision made otherwise as per the quality or nature of any goods, the goods
shall be forbidden to be imported which are not supposed to or cannot be used
8
after six months from the date of being imported or which cannot be used after the
expiry of such period.
(3) If anyone imports the goods without specifying the matters to be
specified on the label, and if harm and injury is caused to anybody due to the use
of such goods, the importer shall be responsible for such harm and injury and be
liable to provide compensation for the same.', 1, 'The Consumer Protection Act, 2075 (2018), Chapter-3, Section 8 (Liability of importer)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3.2', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3', 2, 'section', '9', 'Liability of carrier: The carrier shall have to fulfill the following liabilities, in', 'Liability of carrier', 'addition to the liabilities to be fulfilled under law:
(a) to transport within the determined time period as per the
nature of the goods to be imported,
(b) to prevent degradation in the quality of goods while
transporting,
(c) to completely abide by the safety arrangement and the
conditions to be abided by as prescribed, while transporting,
(d) to provide the details of the goods when the concerned
agency or official so demands,
(e) to fulfill such other liabilities as prescribed.', 2, 'The Consumer Protection Act, 2075 (2018), Chapter-3, Section 9 (Liability of carrier)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3.3', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3', 2, 'section', '10', 'Liability of hoarder: The hoarder who hoards the goods shall have to fulfill the', 'Liability of hoarder', 'following liabilities in addition to the liabilities to be fulfilled under the prevailing
law:
(a) to exercise care as per the nature of the goods while hoarding
such goods,
(b) to hoard upon adopting safety measures as prescribed so as
to prevent degradation in the quality as per the type or nature
of the goods, and not to do any act that may cause
degradation in the quality of goods,
(c) not to change or replace the label or details specified by the
producer,
(d) to provide the details of the goods related to the hoarding of
the goods when the concerned agency or the official so
demands,
(e) to adopt safety measures as prescribed,
(f) to fulfill other liabilities as prescribed.', 3, 'The Consumer Protection Act, 2075 (2018), Chapter-3, Section 10 (Liability of hoarder)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3.4', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3', 2, 'section', '11', 'Liability of seller: The seller who sells the goods shall have to fulfill the following', 'Liability of seller', 'liabilities, in addition to the liabilities to be fulfilled under the law:
9
(a) to sell the goods to the consumers without discrimination,
(b) to safely keep and safely sell the goods as per the type or
nature by preventing degradation,
(c) to keep price list of the goods so that it is clearly seen and
understood by general people,
(d) to provide storage or details of the goods remained with him
or her when the concerned agency or official so demands,
(e) to abide by the provision of guarantee or warranty, if any, in
the goods,
(f) to sell the goods to the customers on a first-come-first-served
basis,
(g) to give the bill or receipt on selling the goods,
(h) to fulfill other liabilities as prescribed.', 4, 'The Consumer Protection Act, 2075 (2018), Chapter-3, Section 11 (Liability of seller)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3.5', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3', 2, 'section', '12', 'Liability of service provider: The service provider providing service to the', 'Liability of service provider', 'consumer shall have to fulfill the following liabilities, in addition to the liabilities
to be fulfilled under the law:
(a) to provide the consumer with the service without
discrimination,
(b) to keep nature of the service to be provided and the list of the
price to be paid by the consumers for such service received,
at the place visible to everyone, so that it is clearly
understood by the general people,
(c) to provide the details and documents related to the service to
be provided when the concerned agency or official so
demands,
(d) to provide the service to the customer on a first-come-first-
served basis,
(e) to give the bill or receipt after receiving the amount for the
service provided to the consumer,
(f) to fulfill such other liabilities as prescribed.', 5, 'The Consumer Protection Act, 2075 (2018), Chapter-3, Section 12 (Liability of service provider)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3.6', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3', 2, 'section', '13', 'To determine level of market: For the purpose of protecting the rights of', 'To determine level of market', 'consumers, managing the market in accordance with the market rule and making
market fair and transparent, the levels of market involved in taking the prescribed
goods or services from the producer or importer to the final consumer shall be as
prescribed.
10', 6, 'The Consumer Protection Act, 2075 (2018), Chapter-3, Section 13 (To determine level of market)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3.7', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3', 2, 'section', '14', 'To return goods: (1) If anyone wishes to return, being dissatisfied with, any goods', 'To return goods', 'purchased from the seller, he or she may return it to the seller within seven days
or take other similar goods equal to that price or the payment of the amount which
was paid while purchasing such goods.
(2) While returning the goods pursuant to sub-section (1), the seller shall
not be allowed to make deduction in the price or take any kind of additional charge.
(3) While returning the goods pursuant to sub-section (1), the bill or receipt
given by the seller at the time of purchasing such goods shall have to be produced.
(4) Notwithstanding anything contained in sub-section (1), no goods may
be returned or taken as replacement in the following circumstances:
(a) if the quality or quantity of such goods is altered by the
purchaser after the purchase,
(b) in the case of the goods of such nature that they must be used
within the certain deadline, such deadline has already
expired,
(c) in the case of the goods of such nature as being rotten,
overripe, such as milk, fruits, fish, meat, in case they are not
consumed instantly,
(d) if the purchased goods are already used,
(e) if the seal is broken off in the case of sealed goods.
(5) Notwithstanding anything contained elsewhere in this Section, in the
case of sealed goods, such goods may be returned within fifteen days, in the
unbroken condition of the seal, or other similar goods equal to the same price may
be taken instead of such goods.', 7, 'The Consumer Protection Act, 2075 (2018), Chapter-3, Section 14 (To return goods)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3.8', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:3', 2, 'section', '15', 'To keep bill or invoice: (1) The importer, carrier, hoarder and seller shall have to', 'To keep bill or invoice', 'keep with them the producer or purchase bill or invoice of the goods or services
purchased for the purpose of sale.
(2) The bill or invoice shall have to be shown at the time when the
concerned official so demands.', 8, 'The Consumer Protection Act, 2075 (2018), Chapter-3, Section 15 (To keep bill or invoice)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:4', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', NULL, 1, 'chapter', 'Chapter-4', 'Chapter-4', NULL, NULL, 4, 'The Consumer Protection Act, 2075 (2018), Chapter-4', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:4.0', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:4', 2, 'section', '16', 'Not to conduct unfair trade and business activities: (1) No one shall conduct or', 'Not to conduct unfair trade and business activities', 'cause to conduct unfair trade and business activities.
11
(2) For the purpose of sub-section (1), if any of the following activities is
conducted, an unfair trade and business activity shall be deemed to have been
taken place:
(a) selling or providing the goods or services by lying,
concealing, hiding or misleading the actual quality, quantity,
price, measurement, format or composition etc. of such
goods or services,
(b) releasing false or misleading advertisement, or selling the
goods by making misleading advertisement,
(c) doing any of the following acts through oral, written or visual
means in the case of goods or services:
(1) selling sub-standard goods by showing standard,
quality, quantity, class, composition, design as if
having specialty or quality,
(2) selling re-produced or old goods showing or
misrepresenting that they are new one,
(3) advertising or notifying and disseminating, in false
and misleading manner, while selling the goods or
services even when no benefit is obtained as declared,
(4) claiming, guaranteeing or selling any goods through
consumption or use of such goods without factual
ground.
(d) determining price in a manner to shift burden upon the
consumer price on the ground different than the ground of
actual cost of any goods or services, or fixing the price by
including the cost of any contest, lottery, occasion, or selling
at such price,
(e) determining price by including the price or cost of other
goods to be obtained as donation, gift or without charge upon
the price of any goods or service, or selling such goods or
service at such price,
(f) producing, mixing up or supplying or transporting or
hoarding or selling the goods so as to become less or more
than the quality or standard in any goods or service, or to
12
inflict harm and injury upon the consumer from the use of
such goods or service,
(g) creating artificial shortage of, hoarding or selling, any goods,
(h) selling the goods by including the price of goods destroyed
by defective product or the price of goods contracted in the
course of business transaction in the cost price of other
goods,
(i) producing or importing fake goods or selling such goods to
displace any goods,
(j) refusing to issue bill or invoice of the sold goods or service,
or not issuing bill or invoice, or demanding additional
amount while issuing bill, invoice,
(k) using poison or any chemical so as to inflict harm and injury
upon the consumer while using any goods, or selling the
goods so used,
(l) selling the already expired goods by affixing new label on
such goods which is not consumable or is not supposed to be
used,
(m) importing, producing or selling sub-standard goods which
cannot be used,
(n) providing service without specifying the price, quality of
service, venue and time to provide service by a professional
service provider,
(o) selling so as to become contrary to sub-section (1) of Section
17 in collusion with the producer, importer, carrier, hoarder
or seller or such person and other person, organization and
institution,
(p) selling or providing by setting up levels or series more than
the business level prescribed while selling or providing any
goods or services,
(q) selling without fulfilling the structure, measurement or
standard if any, prescribed for selling or providing any goods
or service.', 0, 'The Consumer Protection Act, 2075 (2018), Chapter-4, Section 16 (Not to conduct unfair trade and business activities)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:4.1', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:4', 2, 'section', '17', 'Not to cause adverse impact on demand, supply or price: (1) No one shall sell,', 'Not to cause adverse impact on demand, supply or price', 'distribute or transport or hinder the sale and distribution of any goods by taking
13
profit higher than that prescribed and over the cost invested in the production,
import, transport, hoarding or sale and distribution of that goods.
(2) No one shall cause adverse impact on the demand, supply or price
of any goods or service by doing any of the following acts, in association with any
person, institution or anyone else:
(a) determining quota of the raw materials required for the
manufacture of any goods, or reducing the production of any
goods or doing any other such work,
(b) creating artificial shortage by hoarding any goods or service
or by any other manner,
(c) selling the goods or service at the determined time or place
only or doing other acts of similar nature.', 1, 'The Consumer Protection Act, 2075 (2018), Chapter-4, Section 17 (Not to cause adverse impact on demand, supply or price)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:4.2', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:4', 2, 'section', '18', 'Other act not to be done regarding goods or service: No one shall do or cause', 'Other act not to be done regarding goods or service', 'to be done any of the following acts, regarding any goods or services:
(a) producing, selling or importing sub-standard goods
knowingly,
(b) selling any goods or services by lying or deceiving that the
goods or services are other goods or services and stating high
standard goods for low standard goods or services,
(c) producing or selling the goods or service that cause adverse
impact upon the health of consumer,
(d) affecting the price and supply system by creating shortage of
the goods by accompanying with businesspersons or business
groups in order to manufacture, import or sell various goods
of the same nature,
(e) operating service by adopting a circle system, quota system,
rotational system, trip system or token system, in cooperation
with more than one business persons or business groups that
provide any service of the same nature,
(f) making a provision requiring to purchase other goods too,
while purchasing any goods.', 2, 'The Consumer Protection Act, 2075 (2018), Chapter-4, Section 18 (Other act not to be done regarding goods or service)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:5', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', NULL, 1, 'chapter', 'Chapter-5', 'Chapter-5', NULL, NULL, 5, 'The Consumer Protection Act, 2075 (2018), Chapter-5', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:5.0', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:5', 2, 'section', '19', 'List of essential food and other goods and service: (1) The Government of Nepal', 'List of essential food and other goods and service', 'shall determine the list of essential food and other goods or services by a
notification in the Nepal Gazette from time to time.
(2) The maximum price of essential food and other goods or services
shall also have to be fixed in the list pursuant to sub-section (1).
(3) While selling the goods or service pursuant to sub-section (1), the
seller shall not sell, or cause to be sold, the same in a price higher than that referred
to in sub-section (2).', 0, 'The Consumer Protection Act, 2075 (2018), Chapter-5, Section 19 (List of essential food and other goods and service)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:5.1', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:5', 2, 'section', '20', 'To keep price list and registration certificate: (1) Price list shall have to be kept', 'To keep price list and registration certificate', 'by clearly specifying the factory price of each of the goods by the producer,
wholesale or retail price of goods to be sold and distributed by the seller, and price
of the service to be provided by the service provider.
(2) If it is an industry to produce the goods, the industry registration
certificate, and in the case of business, business registration, license shall have to
be displayed at the place of sale in a way visible to the general people.
(3) The Government of Nepal may, by a notification in the Nepal
Gazette, establish a price information center as prescribed.
(4) The producer and wholesaler or retailer located in the district
concerned shall have to provide the factory price and the wholesale or retail price
respectively to the price information center established pursuant to sub-section
(3).', 1, 'The Consumer Protection Act, 2075 (2018), Chapter-5, Section 20 (To keep price list and registration certificate)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:5.2', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:5', 2, 'section', '21', 'Provision to determine standard of price of goods or service: (1) The agency', 'Provision to determine standard of price of goods or service', 'as prescribed shall prepare the standards relating to determination of price of
goods or services as prescribed.
(2) While preparing standards relating to price determination pursuant
to sub-section (1), profit amount to be taken by the seller also shall have to be
accepted as basis in such a way that production cost of the goods, transport
expenses, custom, tax, charge paid by the importer pursuant to law shall not be
more than the percentage fixed while selling.
(3) While preparing standards relating to the determination of price of
any service, if the agency prescribed pursuant to sub-section (1) has assigned
anybody or authority in accordance with the law regulating or managing the
conduct and functions of the person who provides such a service, the standards
shall have to be prepared as per the standards determined by such a body or
authority.
15
(4) While preparing standards, in case the standards are not determined
even after the body or authority is assigned pursuant to sub-section (3), such a
body or authority shall have to be consulted with.
(5) While preparing standards relating to the determination of price
pursuant to sub-section (1) or (3), the standards may be determined differently to
make the maximum price, be taken for such goods or services provided, on the
basis of the geographical region, nature of the services and particular place.', 2, 'The Consumer Protection Act, 2075 (2018), Chapter-5, Section 21 (Provision to determine standard of price of goods or service)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:6', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', NULL, 1, 'chapter', 'Chapter-6', 'Chapter-6', NULL, NULL, 6, 'The Consumer Protection Act, 2075 (2018), Chapter-6', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:6.0', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:6', 2, 'section', '22', 'Formation of Consumers Protection Council: (1) There shall be formed a', 'Formation of Consumers Protection Council', 'Consumer Protection Council in order to make policy on the matters of protecting
and implementing the rights of consumers and performing other functions under
this Act.
(2) The Council referred to in sub-section (1) shall consist of the
following Chairperson and Members:
(a) Minister for Industry, Commerce and Supplies - Chairperson
(b) Secretary, Ministry of Industry, Commerce
and Supplies -Member
(c) Secretary, Ministry of Agriculture and
Livestock Development -Member
(d) Secretary, Ministry of Land Management,
Cooperative and Poverty Alleviation -Member
(e) Secretary, Ministry of Finance -Member
(f) Secretary, Ministry of Home Affairs -Member
(g) Secretary, Ministry of Law, Justice and
Parliamentary Affairs -Member
(h) Secretary, Ministry of Health and Population -Member
(i) Chairperson, Federation of Nepalese Chambers
of Commerce and Industry -Member
(j) Chairperson, Nepal Chamber of Commerce -Member
(k) Chairperson, Confederation of Nepal Industries -Member
16
(l) Chairperson, Federation of Nepal National
Industries and Entrepreneurs -Member
(m) Two persons including one woman
nominated by the Ministry from among
the persons having experience of at least
five years in the body or institution related
to the rights and welfare of the consumers -Member
(n) Director General, the Department -Member-Secretary
(3) The term of the Members nominated pursuant to clause (m) of sub-
section (2) shall be of two years, and they may be nominated again for another
term.
(4) Notwithstanding anything contained in sub-section (3), the Ministry
may remove such a Member from the post at any time if any act is done contrary
to the rights and interests of the consumers or act is done in such a way that it
becomes contrary to the functions, duties and powers of the Council.
(5) Before removing from the post pursuant to sub-section (4), he or she
shall have to be given a reasonable opportunity to submit clarification.
(6) The Chairperson and Members of the Council shall be entitled to the
meeting allowance facility as prescribed by the Government of Nepal.', 0, 'The Consumer Protection Act, 2075 (2018), Chapter-6, Section 22 (Formation of Consumers Protection Council)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:6.1', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:6', 2, 'section', '23', 'Meeting of Council: (1) The meeting of the Council shall be convened at the date,', 'Meeting of Council', 'time and place fixed by the Chairperson.
(2) The meeting of the Council shall be convened at least twice a year,
and the interval between the two meetings shall not be more than six months.
(3) If more than fifty percent members of the total members of the
Council are present, it shall be deemed to constitute a quorum for the meeting of
the Council.
(4) The Chairperson of the Council shall preside over the meeting, and
in his or her absence, the Member selected from among the Members shall preside
over the meeting.
(5) Experts and scientists of different sectors, communities may be
invited to the meeting as necessary.
(6) The decision of the Council shall be authenticated by the Member-
Secretary of the Council.
(7) Other procedures relating to the meeting of the Council shall be as
determined by the Council itself.
17
(8) The Department shall perform the functions as the Secretariat of the
Council.', 1, 'The Consumer Protection Act, 2075 (2018), Chapter-6, Section 23 (Meeting of Council)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:6.2', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:6', 2, 'section', '24', 'Functions, duties and powers of the Council: The functions, duties and powers', 'Functions, duties and powers of the Council', 'of the Council shall be as follows:
(a) to submit to the Government of Nepal by determining
policies on the matters regarding the protection and
enforcement of the rights of the consumers, supply system
and the determination of price and quality of goods and
services,
(b) to provide necessary recommendation to the Government of
Nepal regarding the amendment, improvement in the existing
policies or new policies which are to be made regarding the
protection of the rights of consumers,
(c) to disseminate and cause to be disseminated information
relating to the rights and welfare of the consumers to get the
consumers informed regarding the goods and services,
(d) to inform or get the consumers informed regarding the price,
quality, quantity, purity and unfair trade activities of the
goods or services,
(e) to make necessary policy arrangements for including the
consumer education in the curriculum from secondary level
up to the university level,
(f) to draft necessary policies to cooperate with national and
international organizations or institutions related to the
rights of consumers,
(g) to give directive to the Provincial Government or Local
Level to protect and promote the rights of the consumers as
necessary,
(h) to perform such other functions as prescribed.', 2, 'The Consumer Protection Act, 2075 (2018), Chapter-6, Section 24 (Functions, duties and powers of the Council)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', NULL, 1, 'chapter', 'Chapter-7', 'Chapter-7', NULL, NULL, 7, 'The Consumer Protection Act, 2075 (2018), Chapter-7', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7.0', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7', 2, 'section', '25', 'Central Market Monitoring Committee: (1) A Central Market Monitoring', 'Central Market Monitoring Committee', 'Committee shall be formed for the protection of the rights and interests of the
consumers or for making coordination among the bodies involved in the
18
monitoring or inspection of the supply system, price, quality and purity of the
goods or services.
(2) The Central Market Monitoring Committee referred to in sub-section
(1) shall consist of the following Members:
(a) Secretary, Ministry of Industry, Commerce
and Supplies -Coordinator
(b) Joint-secretary, Ministry of Industry,
Commerce and Supplies (responsible
the supplies) -Member
(c) Joint-secretary, Ministry of Home Affairs -Member
(d) Secretary, Ministry of Agriculture and
Livestock Development -Member
(e) Secretary, Ministry of Land Management,
Cooperative and Poverty Alleviation -Member
(f) Director General, Department of Food
Technology and Quality Control -Member
(g) Director General, Nepal Bureau of Standards -Member
(h) Director General, Department of Drug
Management -Member
(i) Director General, Department -Member-Secretary
(3) The procedures relating to the meeting of the Central Market
Monitoring Committee shall be as prescribed.', 0, 'The Consumer Protection Act, 2075 (2018), Chapter-7, Section 25 (Central Market Monitoring Committee)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7.1', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7', 2, 'section', '26', 'Function, duties and powers of Central Market Monitoring Committee: The', 'Function, duties and powers of Central Market Monitoring Committee', 'functions, duties and powers of the Central Market Monitoring Committee shall
be as follows:
(a) to take necessary initiative to make the goods or services
easily available, by identifying their shortage seen in the
market,
(b) to monitor and supervise regarding the supply system, price,
weight, quality, purity etc. of the goods or services in the
market,
(c) to make recommendation of the procedures of operation of
market monitoring, monitoring team and consumers
organizations and institutions,
19
(d) to maintain coordination in the functions of the Market
Monitoring Team and Local Monitoring Committee,
(e) to give necessary directives to the bodies that protect the
rights and interests of the consumers and law enforcement
bodies in order to make market monitoring effective,
(f) to set up the Consumers Information Center,
(g) to form committees or sub-committees as necessary,
(h) to perform such other functions as prescribed.', 1, 'The Consumer Protection Act, 2075 (2018), Chapter-7, Section 26 (Function, duties and powers of Central Market Monitoring Committee)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7.2', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7', 2, 'section', '27', 'Provincial Market Monitoring Committee: (1) The Provincial Government', 'Provincial Market Monitoring Committee', 'may, in order to make necessary arrangements for protection of the rights and
welfare of the consumers, form a Provincial Market Monitoring Committee by a
notification in the Provincial Gazette, for carrying out inspection and monitoring
on the matters relating to the supply system, price, quality, purity of the goods or
services.
(2) The Provincial Market Monitoring Committee referred to in sub-
section (1) may form monitoring teams or sub-committees as necessary.
(3) The functions, duties and powers of the Provincial Market
Monitoring Committee referred to in sub-section (1) shall be as prescribed.
(4) Other provisions relating to the functions of the Provincial Market
Monitoring Committee referred to in sub-section (1) shall be in accordance with
the rules framed by the Provincial Government.', 2, 'The Consumer Protection Act, 2075 (2018), Chapter-7, Section 27 (Provincial Market Monitoring Committee)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7.3', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7', 2, 'section', '28', 'Local Market Monitoring Committee: (1) The Rural Municipality or', 'Local Market Monitoring Committee', 'Municipality may, for the protection of the rights of consumers under this Act,
form a Local Market Monitoring Committee for carrying out field inspection and
monitoring of the market on the matters relating to the supply system, price,
quality, purity of the goods or services.
(2) The Committee referred to in sub-section (1) shall also consist of
the bodies and consumers under the Local Level in necessary numbers.
(3) The functions, duties, powers, work procedures and other necessary
matters of Local Market Monitoring Committee to be formed pursuant to sub-
section (1) shall be as prescribed.
(4) The Local Market Monitoring Committee to be formed pursuant to
sub-section (1) may form market monitoring teams or sub-committees as
necessary.
20', 3, 'The Consumer Protection Act, 2075 (2018), Chapter-7, Section 28 (Local Market Monitoring Committee)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7.4', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7', 2, 'section', '29', 'To form Market Monitoring Team: (1) In order to monitor and supervise', 'To form Market Monitoring Team', 'regularly as to whether any unfair business activity has taken place pursuant to
Section 16, price list is kept or not pursuant to Section 20, and regarding the
quality, quantity or price of goods or services, Market Monitoring Team or
Subject-wise Monitoring Team or Joint Monitoring Team consisting of the expert
of the related sector as well as Inspection Officer may be formed as prescribed.
(2) The Market Monitoring Team referred to in sub-section (1) may get
information about or enquire into the quality, quantity, price determination of any
goods or services.
(3) The Market Monitoring Team referred to in sub-section (1) may,
while getting information or making inquiry pursuant to sub-section (2), demand
necessary document and evidence, and it shall be the duty of the producer or seller
concerned to submit such document or evidence.
(4) The Market Monitoring Team referred to in sub-section (1) may
exercise all the powers conferred to the Inspection Officer under this Act.
(5) The Market Monitoring Team referred to in sub-section (1) shall,
while making monitoring and inspection of the market, use the market monitoring
and inspection form as prescribed.', 4, 'The Consumer Protection Act, 2075 (2018), Chapter-7, Section 29 (To form Market Monitoring Team)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7.5', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7', 2, 'section', '30', 'To make inquiry or inspection: (1) If there is reasonable ground to believe that', 'To make inquiry or inspection', 'any person is doing unfair trade or business activity, doing the act of affecting the
price or supply system by maintaining monopoly or any other manner in the
market, or producing or selling and distributing sub-standard goods, or doing any
act contrary to this Act or the rule framed under this Act, or if information is
received regarding such matters through any means of communication or any
complaint or through anyone that carries out surveillance, the Ministry or
Department may immediately inquire into or inspect that matter or cause such
inquiry or inspection to be made.
(2) Inspection or monitoring shall be carried out accordingly if the
prevailing law provides for monitoring and inspection, with respect to the
inspection or inquiry pursuant to sub-section (1), and in other circumstances, the
Ministry may form immediately an inspection or inquiry committee or designate
any committee formed under this Act or the Inspection Officer to that effect.
(3) Any producer, dealer, agent, seller, person or institution found
guilty from the inquiry or inspection pursuant to sub-section (1) shall be liable to
action under this Act or the prevailing law.
21
(4) If upon inspection or inquiry, the committee or the Inspection Officer
designated pursuant to sub-section (2) does not find that such an act falls under
this Act, the committee or the officer shall send the matter, along with the inquiry
or inspection file, to the concerned body for necessary action; and such a body
shall also give information about the action taken in that respect to such a
committee or officer.', 5, 'The Consumer Protection Act, 2075 (2018), Chapter-7, Section 30 (To make inquiry or inspection)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7.6', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7', 2, 'section', '31', 'Power to carry out casual inspection: (1) The Department may carry out casual', 'Power to carry out casual inspection', 'inspection for the protection of the rights, interests of the consumers.
(2) Other provisions relating to casual inspection shall be as prescribed.', 6, 'The Consumer Protection Act, 2075 (2018), Chapter-7, Section 31 (Power to carry out casual inspection)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7.7', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7', 2, 'section', '32', 'Power to appoint or designate Inspection Officer: (1) The Department may, in', 'Power to appoint or designate Inspection Officer', 'order to carry out monitoring of availability of the quality goods or services at
appropriate price for consumers by making market and supply system effective,
appoint Inspection Officer or designate any officer employee of the Government
of Nepal, Provincial Government or Local Level to act as Inspection Officer as
prescribed.
(2) The qualification of the Inspection Officer appointed or designated
pursuant to sub-section (1) shall be as prescribed.', 7, 'The Consumer Protection Act, 2075 (2018), Chapter-7, Section 32 (Power to appoint or designate Inspection Officer)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7.8', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7', 2, 'section', '33', 'Functions, duties and powers of Inspection Officer: (1) If there is reasonable', 'Functions, duties and powers of Inspection Officer', 'ground to believe that the unsafe goods having adverse effect or sub-standard
goods are being produced or sold, or services have been provided, or any acts are
being done contrary to this Act and the rules framed under this Act, the Inspection
Officer may, by entering into such a place at any time as necessary, inspect, inquire
or search, arrest the person who commits such act and hold such a person in
detention for seven days with the permission of the case trying authority.
(2) In the course of inspection, inquiry or search pursuant to sub-section
(1), necessary description, information or statement may be taken from the
producer, importer, carrier, hoarder, seller, service provider or other related
person.
(3) While carrying out inspection, investigation or search pursuant to sub-
section (2), if it seems unsafe, affected goods or goods having no quality are being
produced or sold and distributed, or service provided or activities are contrary to
this Act and the rules framed under this Act, the Inspection Officer may impose
restriction on producing or selling and distribution of such goods or providing
services for prescribed period by taking samples of such goods as prescribed.
22
(4) A testing list of the goods or services shall have to be prepared as
prescribed for the purpose of carrying out market inspection or inquiry pursuant
to sub-section (1).
(5) If it is not found to be in accordance with the testing list pursuant to
sub-section (4), the Inspection Officer may immediately impose the fine referred
to in Section 39 with restriction on the sale and distribution of such goods.
(6) The report relating to the functions carried out by the Inspection
Officer pursuant to sub-section (2) shall have to be submitted to the Department
within seven days.
(7) If a fine is imposed pursuant to sub-section (5) in the report pursuant
to Sub-section (6), report shall have to be prepared by specifying such details as
well.
(8) If it seems appropriate to give any order immediately to the producer
or seller in course of inspection or inquiry, the Inspection Officer may give such
an order or do such other act as appropriate.
(9) The procedures to be adopted by the Inspection Officer while
carrying out inspection, inquiry or search shall be as prescribed.
(10) The Inspection Officer may, while carrying out inspection, inquiry
or search, if it seems that any legal action is required to be taken against any
producer, seller, send it to the Department by mentioning such details in the report
as well, or to other bodies concerned with the reason if needed.
(11) The provisions relating to other functions, duties and powers of the
Inspection Officer and the implementation of the report furnished by the
Inspection Officer shall be as prescribed.', 8, 'The Consumer Protection Act, 2075 (2018), Chapter-7, Section 33 (Functions, duties and powers of Inspection Officer)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7.9', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7', 2, 'section', '34', 'Testing of goods: (1) The Inspection Officer shall forward, immediately the', 'Testing of goods', 'samples of goods taken for testing pursuant to sub-section (3) of Section 33 to the
laboratory of the Government of Nepal or the laboratory accredited by the
Government of Nepal, as prescribed if the goods are of the nature of being instantly
rotten, overripe, and within twenty-four hours from the date of samples taken if
they are other goods.
(2) The Inspection Officer shall, while forwarding samples to the
laboratory pursuant to sub-section (1), have to forward them by giving symbol
numbers to them.
23
(3) If a false result is given or negligence is found to have been made
while testing the goods in the laboratory pursuant to sub-section (1), departmental
action shall be taken against such an employee.', 9, 'The Consumer Protection Act, 2075 (2018), Chapter-7, Section 34 (Testing of goods)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7.10', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7', 2, 'section', '35', 'To confiscate or destroy sub-standard goods: (1) If the goods are not found to', 'To confiscate or destroy sub-standard goods', 'have the quality as prescribed while testing the samples of such goods forwarded
to the laboratory for testing pursuant to Section 34, such goods shall be confiscated
and shall, as required, be destroyed as prescribed.
(2) When the goods are confiscated and destroyed pursuant to sub-
section (1), the producer, importer or seller shall have to bear the expenses for
confiscating or destroying such goods.', 10, 'The Consumer Protection Act, 2075 (2018), Chapter-7, Section 35 (To confiscate or destroy sub-standard goods)', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7.11', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7', 2, 'section', '36', 'To make complaint: (1) If any goods or service provider performs any act against', 'To make complaint', 'the consumer interest or contrary to this Act or any rule framed under this Act,
any person who gets information of such matters may make a complaint in writing
or orally or even through electronic means to the Central Market Monitoring
Committee, Department or Inspection Officer, along with the information or proof
and evidence under his or her custody.
(2) If the person who makes a complaint pursuant to sub-section (1)
wishes to keep his or her name confidential, the name of such a person shall have
to be kept confidential.
(3) Other provisions relating to the complaint shall be as prescribed.', 11, 'The Consumer Protection Act, 2075 (2018), Chapter-7, Section 36 (To make complaint)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7.12', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:7', 2, 'section', '37', 'Action against person leaking information: (1) Departmental action shall be', 'Action against person leaking information', 'taken against a public servant, who leaks the information of casual inspection or
the monitoring to be carried out regularly pursuant to Section 31, before such
inspection or monitoring takes place.
(2) If information is leaked by a consumers’ organization or institution
of consumers or other person involved in the act referred to in sub-section (1), the
Director General of the Department shall impose a fine on such person,
representative or institution in accordance with the claimed amount as revealed
and from fifty thousand rupees up to one hundred thousand rupees if the claimed
amount in not set out, and such an organization or institution shall be included in
the black list for a period not exceeding three years.
24', 12, 'The Consumer Protection Act, 2075 (2018), Chapter-7, Section 37 (Action against person leaking information)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:8', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', NULL, 1, 'chapter', 'Chapter-8', 'Chapter-8', NULL, NULL, 8, 'The Consumer Protection Act, 2075 (2018), Chapter-8', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:8.0', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:8', 2, 'section', '38', 'Offences deemed to have been committed: If anyone does, or causes to be done,', 'Offences deemed to have been committed', 'any of the following acts, he or she shall be deemed to have committed the offence:
(a) failure to make the labeling pursuant to Section 6 or
mentioning false matters in the label,
(b) failure of the producer, importer, carrier, hoarder, seller or
service provider to fulfill his or her liabilities or doing any
act to breach such liabilities under Sections 7, 8, 9, 10, 11
and 12 respectively,
(c) failure of the seller to withdraw the goods within the deadline
prescribed or failure to give the goods equal to such price as
replacement pursuant to Section 14,
(d) failure to keep the bills, invoices pursuant to Section 15,
(e) doing, or causing to be done, the unfair trade activity
pursuant to clause (a), (g), (j) or (l) of sub-section (2) of
Section 16,
(f) doing, or causing to be done, the unfair trade activity
pursuant to clauses (b), (c), (d), (e), (f), (h), (i), (k), (m), (o)
and (p) of sub-section (2) of Section 16,
(g) inflicting, or causing to be inflicted, adverse impact on
demand, supplies or price pursuant to clause (a) of sub-
section (1) or sub-section (2) of Section 17,
(h) doing, or causing to be done, any act referred to in clause (b)
or (c) of sub-section (2) of Section 17,
(i) doing, or causing to be done, any act contrary to Section 18,
(j) selling, or causing to be sold, at the price higher than that
fixed by the Government of Nepal, contrary to sub-section
(3) of Section 19,
(k) failure to do, or causing not to be done, any act referred to
in sub-section (1) or (2) of Section 20,
(l) to sell or distribute goods or services contrary to the
standards determined under sub-section (1) of Section 21,
25
(m) not to render assistance in the course of investigation,
inspection or monitoring under this Act pursuant to sub-
section (2) of Section 54.', 0, 'The Consumer Protection Act, 2075 (2018), Chapter-8, Section 38 (Offences deemed to have been committed)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:8.1', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:8', 2, 'section', '39', 'To impose fine instantly: (1) Notwithstanding anything contained in Section 38,', 'To impose fine instantly', 'if from the instantly received evidence, the producer, carrier, hoarder, importer,
seller of goods or service provider is found to have committed any offence, in the
course of market monitoring, inspection, inquiry, the Inspection Officer may
impose the fine as follows:
(a) From five thousand to twenty thousand rupees if the offence
referred to in clause (d) of Section 38 is committed, or caused
to be committed,
(b) From two hundred thousand to three hundred thousand
rupees if the offence referred to in clause (e) of Section 38 is
committed, or caused to be committed,
(c) From fifty thousand rupees to one hundred thousand rupees
if the offence referred to in clause (h) of Section 38 is
committed or caused to be committed,
(d) From fifty thousand to one hundred thousand rupees if the
offence referred to in clause (k) of Section 38 is committed,
or caused to be committed,
(e) Up to twenty thousand rupees if the offence referred to in
clause (m) of Section 38 is committed, or caused to be
committed.
(2) If the offence referred to in sub-section (1) is committed frequently,
double fine shall be imposed for commission of the offence each time.
(3) The Inspection Officer shall have to inform the Department within three
days by revealing all the details including the cause to impose the fine instantly
and the amount charged thereof.
(4) The Inspection Officer may take the following actions against the
producer, carrier, hoarder, importer or seller of such goods who does not pay or
submit such fine within seven days from the date of the decision made to fine
instantly pursuant to sub-section (1):
(a) keeping such goods sealed until the fine is paid,
(b) withholding such other goods as well as to be produced,
transported, hoarded, imported or sold by the producer,
26
carrier, hoarder, importer or seller of such goods until the
fine is paid.
(5) If one is not satisfied with any act of the Inspection Officer under this
Section, an application may be made to the Director General of the Department
within seven days for the review of the matter.
(6) The Director General of the Department shall have to make a decision
in this regard within twenty-one days after examining whatever or whoever is to
be examined upon the application made against the decision by the Inspection
Officer pursuant to sub-section (5).
(7) While making an application for the review, fifty percent of the fine
imposed by the Inspection Officer shall have to be submitted as a cash deposit.
(8) The decision made by the Director General upon the application made
for the review shall be final.
(9) Other procedures to be adopted regarding the instant imposition of fine
by the Inspection Officer shall be as prescribed.', 1, 'The Consumer Protection Act, 2075 (2018), Chapter-8, Section 39 (To impose fine instantly)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:8.2', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:8', 2, 'section', '40', 'Punishment: (1) If any one commits, or causes to be committed, any of the', 'Punishment', 'following acts which is deemed to be an offence under this Act, the Director
General of the Department may, according to the gravity of the offence, punish as
follows:
(a) with imprisonment from three months to six months or fine
up to fifty thousand rupees or both penalties if the offence
referred to in clauses (a) and (c) of Section 38 is committed,
or caused to be committed,
(b) with imprisonment from three months to one year or fine
from one hundred thousand rupees to three hundred thousand
rupees or both penalties if the offence referred to in clause
(i) of Section 38 is committed,
(c) with imprisonment from three months to six months or fine
from fifty thousand rupees to one hundred thousand rupees
or both penalties if the offence referred to in clauses (j) and
(l) of Section 38 is committed.
(2) A party who is not satisfied with the decision made by the Director
General of the Department under sub-section (1) may appeal to the concerned
District Court within thirty-five days.
(3) For the following offences, punishment shall be as follows:
27
(a) with imprisonment from two years to three years or fine from
three hundred thousand to five hundred thousand rupees or
both penalties for one who commits, or causes to be
committed, the offence referred to in clause (b) of Section
38,
(b) with imprisonment from two years to five years or fine from
four hundred thousand to six hundred thousand rupees or
both penalties for one who commits, or causes to be
committed, the offence referred to in clause (f) of Section 38,
(c) with imprisonment from two years to three years or fine from
three hundred thousand to five hundred thousand rupees or
both penalties for one who commits, or causes to be
committed, the offence referred to in clause (g) of Section
38.
(4) A person who commits, or causes to be committed, any other act
contrary to this Act or the rules framed under this Act, Except for the acts under
sub-section (1), shall be punished with imprisonment for a term not exceeding two
years or fine up to three hundred thousand rupees or both.', 2, 'The Consumer Protection Act, 2075 (2018), Chapter-8, Section 40 (Punishment)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', NULL, 1, 'chapter', 'Chapter-9', 'Chapter-9', NULL, NULL, 9, 'The Consumer Protection Act, 2075 (2018), Chapter-9', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9.0', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9', 2, 'section', '41', 'Constitution of Consumer Court: (1) The Government of Nepal may, in order to', 'Constitution of Consumer Court', 'try and settle the cases other than the cases to be prosecuted pursuant to sub-
section (1) of Section 40 under this Act, constitute a Consumer Court as per
necessity, by a notification in the Nepal Gazette.
(2) The venue and jurisdiction of the Consumer Court to be formed
pursuant to sub-section (1) shall be as prescribed in the same notice.
(3) The Consumer Court shall consist of the Chairperson and Members as
follows:
(a) District Judge of the concerned district
designated by the Government of Nepal -Chairperson
(b) Gazetted second class officer of Nepal Judicial
Service designated by the Government of Nepal -Member
(c) Gazetted second class officer of the Government
of Nepal designated by the Government of Nepal -Member
28
(4) The Government of Nepal shall notify the designation of the
Chairperson or Members pursuant to sub-section (3) in the Nepal Gazette.
(5) The Government of Nepal shall consult the Judicial Council before the
District Judge is designated as the Chairperson of the Court, and of the Judicial
Service Commission before the officer of the Nepal Judicial Service is designated
as a Member pursuant to sub-section (3).', 0, 'The Consumer Protection Act, 2075 (2018), Chapter-9, Section 41 (Constitution of Consumer Court)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9.1', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9', 2, 'section', '42', 'Application of jurisdiction of Court: (1) All the members shall collectively', 'Application of jurisdiction of Court', 'exercise the jurisdiction of the Court.
Provided that the Bench in which at least one Member is present may carry
out procedural matters other than detention, and the Bench in which two Members
are present may take all other matters including detention.
(2) If unanimity is not reached while trying and settling a case in presence
of two Members, the case shall be settled as per the opinion of the Chairperson if
it is the Bench including the Chairperson in case it is the procedural matter of the
case.
(3) If it is the Bench in which the Chairperson is not present, it shall be as
per the opinion of the senior member based on the appointment. If it is the decision
or final order of the case, it shall be submitted to the Chairperson, and the opinion
supported by him or her shall be deemed to be the decision of the Court.
(4) The three Members shall collectively exercise the jurisdiction of the
Bench and majority opinion including that of the Chairperson shall be deemed to
be the decision of the Court.
(5) If all three Members have divergent opinion, the opinion of the
Chairperson prevails on the procedural matters and if it is on decision or final
order it shall be forwarded to the concerned High Court for the decision, by
specifying the reasons for not being able to issue a decision or final order.
(6) Hearing of the case pursuant to sub-section (5) shall be held in the single
Bench of the High Court and the decision or final order made by such a Bench
shall be deemed to be the decision or final order of the Court.', 1, 'The Consumer Protection Act, 2075 (2018), Chapter-9, Section 42 (Application of jurisdiction of Court)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9.2', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9', 2, 'section', '43', 'Contempt of Court: (1) The Court may initiate proceedings against the contempt', 'Contempt of Court', 'of court and if the act of contempt of court is found to be proved, the Court may
punish the offender with a fine not exceeding ten thousand rupees or an
imprisonment for a term not exceeding one year or with both.
(2) Notwithstanding anything contained in sub-section (1), if the person
accused of contempt of court apologizes to the satisfaction of the Court, the Court
29
may not initiate the proceedings or excuse, reduce or change in punishment if the
punishment has already been determined or issue an order with effect of non-
execution of the sentence, if the conditions are complied with by the accused.', 2, 'The Consumer Protection Act, 2075 (2018), Chapter-9, Section 43 (Contempt of Court)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9.3', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9', 2, 'section', '44', 'To make files or documents available: (1) If the Court or the Director General', 'To make files or documents available', 'of the Department orders any person, institution or office to submit or forward any
file, deed, document or any other proof as evidence in the course of the
proceedings of the case, such a person, institution or office shall have to submit or
forward such a file, deed, document or evidence, within the deadline determined
by the Court or the Director General of the Department.
(2) If it is obstructed to try, hear or settle the case, or if harassment or harm
or injury is caused to any party due to the reason that any person, institution or
office has not complied with the order pursuant to sub-section (1), the Court or
Director General of the Department may impose upon such a person or institution
or chief of office a fine not exceeding one thousand rupees each time.
(3) Notwithstanding anything contained in sub-section (2), if such a person
or institution or chief of office makes an application to the Court or the Director
General of the Department, within the time-limit determined by the Court or the
Director General, specifying the reason for not being able to abide by such order,
stating that fine should not be imposed, and if the statement of such application is
found to be reasonable, the Court or the Director General of the Department may
revoke such an order for imposition of the fine.', 3, 'The Consumer Protection Act, 2075 (2018), Chapter-9, Section 44 (To make files or documents available)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9.4', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9', 2, 'section', '45', 'Appeal: An appeal may be made to the concerned High Court within thirty days', 'Appeal', 'against the decision made by the Court under this Act.', 4, 'The Consumer Protection Act, 2075 (2018), Chapter-9, Section 45 (Appeal)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9.5', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9', 2, 'section', '46', 'Execution of decisions: If it is specified in the decision or order that the decision', 'Execution of decisions', 'or order is to be executed by any particular agency or official, the same agency or
official shall execute the decision or final order made by the Court under this Act,
and if it is not specified as such, it shall be executed by the concerned District
Court.', 5, 'The Consumer Protection Act, 2075 (2018), Chapter-9, Section 46 (Execution of decisions)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9.6', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9', 2, 'section', '47', 'Dissolution of the Court: (1) The Government of Nepal may dissolve the Court', 'Dissolution of the Court', 'at any time by a notification in the Nepal Gazette.
(2) If the Court is dissolved pursuant to sub-section (1), the cases,
complaints or petitions remained pending at the time of dissolution after being
filed in such Court shall be ipso facto transferred to the concerned District Court
having territorial jurisdiction.
30', 6, 'The Consumer Protection Act, 2075 (2018), Chapter-9, Section 47 (Dissolution of the Court)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9.7', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9', 2, 'section', '48', 'Special provision relating to action and finalization of case: Notwithstanding', 'Special provision relating to action and finalization of case', 'anything contained in Section 41, the concerned District Court shall have the
authority to take action, hear or try the case under this Act until the Court is
constituted pursuant to this Section.', 7, 'The Consumer Protection Act, 2075 (2018), Chapter-9, Section 48 (Special provision relating to action and finalization of case)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9.8', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:9', 2, 'section', '49', 'To table notice: The Government of Nepal shall have to table the notice published', 'To table notice', 'pursuant to sub-section (1) of Section 41 or sub-section (1) of Section 47 in the
House of Representatives.', 8, 'The Consumer Protection Act, 2075 (2018), Chapter-9, Section 49 (To table notice)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:10', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', NULL, 1, 'chapter', 'Chapter-10', 'Chapter-10', NULL, NULL, 10, 'The Consumer Protection Act, 2075 (2018), Chapter-10', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:10.0', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:10', 2, 'section', '50', 'Compensation may be claimed: If bodily, mental, financial, physical or other', 'Compensation may be claimed', 'kind of harm and injury is caused to any consumer by use of the goods or services
sold or distributed contrary to this Act, or damage is occurred as a result of
defective production of goods, the consumer himself or herself, or any consumer
association on his or her behalf, or the heir of the consumer if the consumer is
incompetent or has already died, may make a complaint to the Court for
compensation from the person who has produced, imported, hoarded, transported,
sold and distributed or provided such goods or services within six months from
the date of harm and injury caused.', 0, 'The Consumer Protection Act, 2075 (2018), Chapter-10, Section 50 (Compensation may be claimed)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:10.1', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:10', 2, 'section', '51', 'To provide compensation: If the consumer is wounded by the use of the goods', 'To provide compensation', 'or services sold, distributed or provided contrary to this Act, treatment expenses,
interim relief amount for the daily subsistence as per the family circumstances
throughout the treatment period and, if it is proved, in course of the investigation,
that the consumer has suffered, the consumer, or the heir as per law, if he or she
has died, shall entitled to get the amount of compensation from the concerned
producer, importer, hoarder, carrier, distributor or seller concerned on the basis of
such harm and injury.', 1, 'The Consumer Protection Act, 2075 (2018), Chapter-10, Section 51 (To provide compensation)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:10.2', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:10', 2, 'section', '52', 'To determine the standards of compensation: (1) The Court shall, while', 'To determine the standards of compensation', 'determining the amount to be received by the consumer for compensation pursuant
to Section 51, have to determine it by taking following matters into consideration:
(a) physical or mental suffering or pain caused to the victim, and
its severity,
(b) estimated expenses to be made for treatment if curable
damage is caused,
31
(c) depreciation caused in the capacity of the victim to generate
income due to the physical or mental damage,
(d) victim’s age and his or her family responsibility, if incurable
type of physical or mental damage is caused,
(e) number of victim’s family members who are dependent upon
him or her and minimum expenses required for the
maintenance of their livelihood if the victim has died,
(f) such other matters, out of the matters claimed by the victims,
as found to be proper and appropriate,
(g) financial and business condition of the producer, importer,
hoarder, seller and service provider.
(2) Other provisions relating to the determination of compensation pursuant
to sub-section (1) shall be as prescribed.', 2, 'The Consumer Protection Act, 2075 (2018), Chapter-10, Section 52 (To determine the standards of compensation)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', NULL, 1, 'chapter', 'Chapter-11', 'Chapter-11', NULL, NULL, 11, 'The Consumer Protection Act, 2075 (2018), Chapter-11', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11.0', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11', 2, 'section', '53', 'To provide essential goods or services at fair price: The Government of Nepal', 'To provide essential goods or services at fair price', 'may make provision to provide the essential foods or other goods or services
determined pursuant to Section 19 at a fair price as prescribed.', 0, 'The Consumer Protection Act, 2075 (2018), Chapter-11, Section 53 (To provide essential goods or services at fair price)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11.1', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11', 2, 'section', '54', 'To extend support: (1) If the Department seeks support of local administration', 'To extend support', 'and police in the course of implementing this Act, it shall be the duty of the local
administration and the police to extend such support.
(2) In the course of carrying out inquiry, monitoring or inspection under
this Act, it shall be the duty of all the concerned to extend necessary support to
the official carrying out such inquiry, monitoring or inspection or to the person,
team or Inspection Officer deputed under this Act.', 1, 'The Consumer Protection Act, 2075 (2018), Chapter-11, Section 54 (To extend support)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11.2', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11', 2, 'section', '55', 'Liability of institution: (1) If any business institution commits any act considered', 'Liability of institution', 'as offence under this Act, the official who works in the capacity of the chief
administrative official of such an institution shall have the responsibility and
liability of such act.
(2) Notwithstanding anything contained in sub-section (1), such a person
shall not have to bear the liability regarding the offence occurred before he or she
became the chief administrative official.', 2, 'The Consumer Protection Act, 2075 (2018), Chapter-11, Section 55 (Liability of institution)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11.3', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11', 2, 'section', '56', 'Reward to informant: (1) After eventually settling the case filed upon being', 'Reward to informant', 'investigated as per the information provided by the person who provides
32
information that the offence has been or is going to be committed, such a person
shall be rewarded with the ten percent of the claimed amount recovered or one
million rupees, whichever is the lesser.
(2) Notwithstanding anything contained in sub-section (1), no employee of
the Government of Nepal or corporate institution or the family member or
representative of the consumers’ organization or institution or employee deputed
for monitoring or their family member shall be entitled to the reward referred to
in this Section.
(3) The name, address of the informant pursuant to this Section and the
details of the information received from him or her shall be kept confidential.', 3, 'The Consumer Protection Act, 2075 (2018), Chapter-11, Section 56 (Reward to informant)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11.4', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11', 2, 'section', '57', 'No to bar to prosecute case under prevailing law: If any act which is deemed', 'No to bar to prosecute case under prevailing law', 'as an offence under this Act is also deemed as an offence under other prevailing
law, this Act shall not bar to prosecute the case under such law.', 4, 'The Consumer Protection Act, 2075 (2018), Chapter-11, Section 57 (No to bar to prosecute case under prevailing law)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11.5', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11', 2, 'section', '58', 'Government of Nepal to be plaintiff: The Government of Nepal shall be the', 'Government of Nepal to be plaintiff', 'plaintiff in the cases under this Act.', 5, 'The Consumer Protection Act, 2075 (2018), Chapter-11, Section 58 (Government of Nepal to be plaintiff)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11.6', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11', 2, 'section', '59', 'Investigation and filing of case: (1) The Inspection Officer shall carry out', 'Investigation and filing of case', 'investigation of the case relating to the offence under this Act.
(2) The Inspection Officer shall, after completing the investigation, have to
forward the matter to the concerned government attorney for the decision on
whether or not to institute the case, and if decision is made by the government
attorney to institute the case, the Inspection Officer shall file the case.
(3) While filing the case pursuant to sub-section (1), the Inspection Officer
shall file the case before the Director General of the Department in connection
with the case relating to the offence carrying the punishment referred to in sub-
section (1) of Section 40, and before the Court if the Court has been constituted
and before the District Court concerned if the Court has not been constituted in
connection with the case carrying punishment referred to in sub-section (3) of
Section 40.', 6, 'The Consumer Protection Act, 2075 (2018), Chapter-11, Section 59 (Investigation and filing of case)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11.7', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11', 2, 'section', '60', 'To follow summary procedures: (1) While trying and settling the cases filed', 'To follow summary procedures', 'under this Act, procedures shall have to be followed pursuant to the Summary
Procedures Act, 2028 (1972).
(2) Notwithstanding anything contained in sub-section (1), general
procedures shall have to be followed in the cases carrying the sentence of
imprisonment for more than three years.
33', 7, 'The Consumer Protection Act, 2075 (2018), Chapter-11, Section 60 (To follow summary procedures)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11.8', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11', 2, 'section', '61', 'Saving of act done in good faith: The Consumer Protection Council, Central', 'Saving of act done in good faith', 'Monitoring Committee, Local Market Monitoring Committee, Inspection Officer
or any employee of the Government of Nepal, Provincial Government or Local
Level shall not be personally responsible for any act done by him or her in good
faith while performing his or her duties under this Act or the rules framed under
this Act.', 8, 'The Consumer Protection Act, 2075 (2018), Chapter-11, Section 61 (Saving of act done in good faith)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11.9', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11', 2, 'section', '62', 'To be in accordance with this Act: The matters contained in this Act shall be in', 'To be in accordance with this Act', 'accordance with this Act and other matters shall be in accordance with the
prevailing law.', 9, 'The Consumer Protection Act, 2075 (2018), Chapter-11, Section 62 (To be in accordance with this Act)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11.10', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11', 2, 'section', '63', 'Power to frame rules: (1) The Government of Nepal may frame necessary rules', 'Power to frame rules', 'in order to implement this Act.
(2) The Provincial Government may frame necessary rules in order to make
the activities relating to market monitoring systematic and effective pursuant to
Section 27.', 10, 'The Consumer Protection Act, 2075 (2018), Chapter-11, Section 63 (Power to frame rules)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11.11', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11', 2, 'section', '64', 'Power to frame and enforce directives, procedures or standards: (1) The', 'Power to frame and enforce directives, procedures or standards', 'Ministry may, in order to implement this Act and the rules framed by the
Government of Nepal under this Act, frame and enforce directives, procedures or
standards as necessary.
(2) The concerned Rural Municipality or Municipality may, in order to
make the activities relating to market monitoring systematic and effective pursuant
to Section 28, frame and enforce necessary directives and procedures.', 11, 'The Consumer Protection Act, 2075 (2018), Chapter-11, Section 64 (Power to frame and enforce directives, procedures or standards)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11.12', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac', 'doc_the_consumer_protection_act_2075_2018_2075_consumer_protection_ac:11', 2, 'section', '65', 'Repeal and Saving: (1) The Consumer Protection Act, 2054 (1998) is hereby', 'Repeal and Saving', 'repealed.
(2) The acts and actions performed under the Act pursuant to sub-section
(1) shall be deemed to have been performed under this Act.
34', 12, 'The Consumer Protection Act, 2075 (2018), Chapter-11, Section 65 (Repeal and Saving)', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:0', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', NULL, 1, 'preamble', 'Preamble', 'Introductory matter', NULL, '1
The Copyright Act, 2059 (2002) 
Date of Authentication and Publication  
30 shrawan 2059 (15 August 2002)', 0, 'The Copyright Act, 2059 (2002), Preamble', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:1', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', NULL, 1, 'section_group', 'Sections', 'Sections', NULL, NULL, 1, NULL, '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:1.0', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:1', 2, 'section', '1', 'Amendment  by Some Nepal Acts relating to Export and Import and Intellectual Property Act, 2063      2 063.8.8', 'Amendment  by Some Nepal Acts relating to Export and Import and Intellectual Property Act, 2063      2 063.8.8', 'Act number 8 of the year 2059 (2002)  
An Act Made to Provide for Copyright  
Preamble : Whereas, it is expedient to update the legal provis ions relating to copyright; 
Now, therefore, be it enacted by Parliament in the first year of reign of His Majesty the 
King Gyanendra Bir Bikram Shah Dev.', 0, 'The Copyright Act, 2059 (2002), Section 1 (Amendment  by Some Nepal Acts relating to Export and Import and Intellectual Property Act, 2063      2 063.8.8)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:2', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', NULL, 1, 'chapter', 'Chapter - 1', 'Chapter - 1', NULL, NULL, 2, 'The Copyright Act, 2059 (2002), Chapter - 1', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:2.0', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:2', 2, 'section', '1', 'Short title and commencement : (1) This Act may be called as the', 'Short title and commencement', '"Copyright Act, 2059 (2002). 
  (2) This act shall come into forceimmediately. 
2. 
Definitions:  Unless the subject or the context otherwise require, in this Act,- 
(a) "Work" means any work presented originally and intellectually in the 
field of literature, art and science and in any oth er field, and this term 
also includes the following work: 
(1) Book, pamphlet, article, thesis, 
(2) Drama, dramatic-music, dumb show and a work prepare d to 
perform in such manner, 
(3) Musical notation with or without words, 
(4) Audio visual works, 
(5) Architectural design, 
(6) Fine Arts, painting, work of sculpture, work of woo dcarving, 
lithography, and other work relating to architecture, 
(7) Photographic work, 
 2
(8) Work of applied art, 
(9) Illustration, map, plan, three-dimensional work rel ating to 
geography, and scientific article and work, 
(10) Computer program. 
(b) "Author" means a person who creates a work as referred to in clause (a) 
above. 
(c) "Audio-visual work" means a cinematographic work that can be viewed 
in screen, with or without sound. 
(d) "Photographic work" means a work produced by using light or any other 
radiation recorded in the surface in such a manner that the image 
(picture) of any thing can be set in the surface or  that the image (picture) 
can be created from such surface with the help of c hemical, electrical or 
any other technology. 
Provided, however, that a still photography taken f rom any audio-visual 
work shall not be considered as a photographic work  but as a part of the 
concerned audio-visual work. 
(e) "Sound recording" means the act of recording of sou nd of any 
performance recorded in any manner and with any met hod whatsoever 
for the purpose of hearing, except the act of recor ding sound and image 
at the same time. 
(f) "Performance" means,- 
(1) In the case of work other than the audio-visual wor k, performance 
made through recitation, playing music, dancing, ac ting or any 
other manner, directly or with the help of any othe r device or 
method, 
(2) In the case of the audio-visual work, sequential vi deo clipping of 
the scene contained in such a work, along with soun d for hearing 
purpose, 
 3
(3) In the case of the sound recording, act of performa nce made 
outside the family circle, neighbors, friends or re latives or made 
in such manner that it can be heard publicly despit e the presence 
of such persons. 
(g) "Economic right" means the rights conferred on the copyright owner 
pursuant to Section 7. 
(h) "Copyright owner" means the author of a work in cas es where the 
economic right of that work is vested in that autho r, a person or 
organization in cases where the economic right of t he work is primarily 
vested in the person or organization other than the  author, and a person 
or organization, in cases where the economic right of the work is 
transferred to that person or organization. 
(i) "Broadcasting" means communication or exhibition of a work for public 
information or broadcasting of audio or audio-visua l work through 
wireless equipment or satellite. 
(j) "Communication to the public" means the act of broad casting and audio 
or visual broadcasting or both either by wire or wi reless equipment in 
such a manner that it can be heard or viewed stayin g near or far from the 
place of broadcasting. 
(k) "Moral right" means the right to be conferred to th e author or his 
successor or any person authorized by the author pursuant to Section 8. 
(l) "Performer" means any actor, singer, musician, danc er and other person 
who performs a literary or artistic work or folklor e expression to the 
general public through acting, singing, music and dancing. 
(m) "Publication" means: 
(1) In the case of a work of drama, motion picture, or work 
performed in any other manner, the shows, sale or r ental of such a 
work publicly with or without translating or altering it, 
(2) In the case of any other work, the work which has b een publicly 
sold, distributed or utilized or so brought out as to be sold and 
 4
distributed or utilized publicly, with or without t ranslating or 
altering it; and, in the case of a work that can be exhibited through 
acting, this term includes its exhibition in a publi c manner with or 
without translating or altering it. 
(n) "Registrar" means the person specified pursuant to Sub-section (1) of 
Section 30. 
(o) "Royalty collecting body" means the body formed pur suant to Section 
39. 
(p) "Prescribed" or "as prescribed" means prescribed or  as prescribed in the 
Rules framed under this Act.', 0, 'The Copyright Act, 2059 (2002), Chapter - 1, Section 1 (Short title and commencement)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', NULL, 1, 'chapter', 'Chapter-2', 'Chapter-2', NULL, NULL, 3, 'The Copyright Act, 2059 (2002), Chapter-2', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3.0', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3', 2, 'section', '3', 'Protection of copyright : (1) Copyright protection shall be extended to any', 'Protection of copyright', 'work. 
  (2) Any translation, arrangement, sequential arra ngement of work or 
collection of works presented as original from view point of presentation, 
collection or expression, data or database readable  with or without support of 
machine, any proverb, folktale, folk song falling u nder folk expression or any 
other derivate works based on folk expression shall  be protected as original 
work, without prejudice to the copyright of the original work.', 0, 'The Copyright Act, 2059 (2002), Chapter-2, Section 3 (Protection of copyright)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3.1', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3', 2, 'section', '4', 'Non-availability of copyright protection : Notwithstanding anything', 'Non-availability of copyright protection', 'contained in Section 3, copyright protection under this Act shall not be 
extended to any thought, religion, news, method of operation, concept, 
principle, court judgment, administrative decision,  folksong, folktale, proverb 
and general data despite the fact that such matters  are expressed or explained or 
interpreted or included in any work.', 1, 'The Copyright Act, 2059 (2002), Chapter-2, Section 4 (Non-availability of copyright protection)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3.2', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3', 2, 'section', '5', 'Registration not compulsory : (1) Registration of a work, sound recording,', 'Registration not compulsory', 'performance or broadcasting shall not be required t o acquire the right under this 
Act. 
 5
  (2) Notwithstanding anything contained in sub-sec tion (1), in cases 
where any person intends to get any work, sound rec ording, performance or 
broadcasting registered voluntarily, that person ma y make an application to the 
Registrar and get the same registered; and the proc edures on registration shall 
be as prescribed.', 2, 'The Copyright Act, 2059 (2002), Chapter-2, Section 5 (Registration not compulsory)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3.3', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3', 2, 'section', '6', 'Owner of economic right of work : (1) The author of a work shall be the', 'Owner of economic right of work', 'first owner of the economic right of that work. 
  (2) Notwithstanding anything contained in Sub-sec tion (1), the economic 
right of a work shall vest in the following person or organization in the 
following circumstances:- 
(a)  Co-author in the case of a joint work; 
Provided, however, that where such a joint work is divided in 
different parts and each part can be identified as of different 
authors and  the work can be used separately, the e conomic right 
shall vest in  the concerned author in respect of e ach part created 
by that author. 
(b)  In cases where a joint work is prepared at the ini tiation or 
 direction of any person or organization, that pers on or 
 organization at whose direction or initiation such  a work has been 
 so prepared, 
(c)  In case where a work is prepared on payment of rem uneration by 
 any person or organization, that person or organiz ation who has 
 paid such remuneration, 
(d)  In the case of an anonymous work, the publisher of  that work, 
 until the authorship of such a work is proved. 
  Provided, however, that in cases where the real a uthor of such a 
  work presents his/her identity subsequently, the economic right of 
  that work shall vest in that author from the date of presentation of 
  his/her identity. 
 6
(e)  In the case of an audio-visual work, the producer of such a work 
 except as otherwise provided for in the contract. 
  Provided, however, that in case where the work of  the co-author 
  of an audio-visual work or a pre-existing work is  incorporated or 
  adapted in making the audio-visual work, their ec onomic right 
  shall be according to their respective contributi on.', 3, 'The Copyright Act, 2059 (2002), Chapter-2, Section 6 (Owner of economic right of work)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3.4', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3', 2, 'section', '7', 'Economic Right : Subject to provisions of Chapter-4, only the autho r or the', 'Economic Right', 'owner of copyright shall have the exclusive right t o carry out the following acts 
in respect of the work: 
(a) To reproduce the work, 
(b) To translate the work, 
(c) To revise or amend the work, 
(d) To make arrangement and other transformation in the work, 
(e) To sell, distribute or rent the original and copy o f the work for the 
  general public, 
(f) To transfer or rent the right of audiovisual work, work embodied 
  in sound recording, computer program or musical wo rk in graphic 
  form conferred to that author or owner, 
(g) To import copies of the work, 
(h) To have public exhibition of the original or copy of the work, 
(i) To perform the work in public, 
(j) To broadcast the work, 
(k) To communicate the work to the general public.', 4, 'The Copyright Act, 2059 (2002), Chapter-2, Section 7 (Economic Right)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3.5', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3', 2, 'section', '8', 'Moral right : (1) The author of a work shall have the following moral rights,', 'Moral right', 'irrespective of whether that author has the economic right to that work: 
(a) To get his/her name mentioned in copies of the work or in his/her  
work  where it is used publicly, 
 7
(b)  In cases where, instead of his/her real name, a ps eudonym is 
 mentioned in his work, then to get that pseudonym mentioned 
 while using such a work publicly, 
(c)  To prevent such acts as undermining the reputation  or goodwill 
 earned by him/her, by mutilating his/her work or p resenting it in a 
 distorting manner, 
(d)  To make necessary amendment or revision in the work . 
(2) The right referred to in sub-section (1) shall not be transferable 
during the life of the author. 
Provided, however, that where the author has nomina ted any one whom 
such right is to be transferred after the death of the author, such right shall 
devolve on the person or organization so nominated,  and on the nearest heir, 
failing such nomination.', 5, 'The Copyright Act, 2059 (2002), Chapter-2, Section 8 (Moral right)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3.6', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3', 2, 'section', '9', 'Rights of performer : (1) The performer shall have the right to perform the', 'Rights of performer', 'following acts:- 
(a) To take one''s performance to the general public thr ough 
 broadcasting or communication, 
(b) To determine modality or medium of making one''s per formance 
 and reproduce it, 
(c) To take one''s performance to the general public for  the first time 
 by making performance or selling or transferring c opies thereof or 
 changing ownership, 
(d) To rent copies of one''s performance, 
(e) To take the performance produced through the determ ined 
 modality or medium to the general public in an easi ly available 
 manner, through wire or wireless equipment, 
(f) To amend or revise one''s performance. 
 8
(2) The performer shall not be allowed to re-exerci se the rights 
mentioned in Sub-section (1) once he/she has author ized his/her performance to 
be incorporated in audio-visual medium. 
(3) Notwithstanding anything contained in Sub-section (2), the performer 
shall have the right to have his/her identity maint ained as the performer of 
direct audio performance as well as of the performa nce incorporated in the 
sound recording and to make a claim for the same, a nd, where any person has 
so mutilated or distorted his/her performance or ot herwise deformed his 
performance by mutilating the meaning as to prejudi ce his/her reputation or 
goodwill, to prevent such acts. 
(4) Nothing mentioned in this Section shall be deem ed to have any effect 
on the right of a performer to enter into, or to be  agreed on, an agreement with 
such terms as may yield much more benefits or facil ities to him/her from the  
performance. 
(5) The right conferred to the performer pursuant t o this Section shall be 
protected for a period of fifty years from the year of incorporation of 
performance in sound recording device, and for a pe riod of fifty years from the 
year of such performance where such incorporation has not been made.', 6, 'The Copyright Act, 2059 (2002), Chapter-2, Section 9 (Rights of performer)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3.7', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3', 2, 'section', '10', 'Right of sound recording producer : (1) The sound recording producer', 'Right of sound recording producer', 'shall have the following rights:- 
(a) To reproduce the sound recording, directly or indir ectly, in 
any manner or in any form, 
(b) To import copies of the sound recording, 
(c) To make the sound recording easily available by way  of sale 
or ownership transfer or otherwise of the original or copies of 
the sound recording, 
(d) To rent or lease the sound recording publicly, 
(e) To make the sound recording capable of being heard with 
wire or wireless equipment from any specific place or from 
the place of one''s own choice or by the general public. 
 9
(2) The term of the right referred to in sub-sectio n (1) shall be of fifty 
years from the year of publication of such a sound recording.', 7, 'The Copyright Act, 2059 (2002), Chapter-2, Section 10 (Right of sound recording producer)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3.8', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3', 2, 'section', '11', 'Reasonable remuneration for the use of sound record ing : (1) In cases', 'Reasonable remuneration for the use of sound record ing', 'where a sound recording published for commercial pu rpose or a reproduced 
copy of such sound recording is directly used for b roadcasting or other 
communications and is so performed to the people pub licly, the producer shall 
get a reasonable remuneration from the user of the same. 
 (2) The performer shall get the remuneration as pe r the agreement, in 
any, made between the performer and the producer on the remuneration referred 
to in Sub-section (1), and half the amount received  by the producer where no 
such agreement is made. 
 (3) The term of the right to receive reasonable rem uneration under Sub-
section (1) shall be for fifty years from the year of publication of such a sound 
recording or from the year of adjustment of such a sound recording. 
12. 
Right of broadcasting organization : (1) The broadcasting organization 
shall have the right to carry out the following act:- 
(a) To re-broadcast the subject it has broadcast, 
(b) To so communicate its broadcast as to make it easily  available to the 
general public, 
(c) To make adjustment of its own broadcast, 
(d) To reproduce the adjustment of its broadcast. 
(2) The term of the right referred to in sub-sectio n (1) shall be for fifty 
years from the year of commencement of such broadcast. 
*13.  Protection of work, performer, sound recording prod ucer or 
broadcasting organization  : (1) A work of the following author shall enjoy 
protection under this Act: 
                                                   
*  Amendment by the  Act Made to Amend Some Nepal Acts relating to Export and Import and Intellectual Property  
 10 
(a) A work created by the author residing in Nepal or in a member country of 
the World Trade Organization and published in the N epal or in that 
country, 
(b) An audio-visual work produced by a producer res iding in Nepal or in a 
member country of the World Trade Organization, 
(c) An architectural design of a building made in t he Nepal or in a member 
country of the World Trade Organization or other ki nd of artistic work 
used in a building or any other structure, 
(d) A work published in Nepal by an author residing  in a country other than 
Nepal or a member country of the World Trade Organi zation or an audio-
visual work produced in the Nepal by a producer of such other country. 
  (2) The following performer shall be entitled to the rights relating to 
performer as referred to in this Act: 
(a) A performer of Nepal or a member country of the  World Trade 
Organization, 
(b) A performer of the performance made in Nepal or  in a member 
country of the World Trade Organization or of the p erformance 
contained in the sound recording protected under th is Act or of the 
performance contained in a broadcast even though it  is not 
contained in the sound recording. 
  (3) The following sound recording producer shall be entitled to the 
rights relating to sound recording producer as referred to in this Act: 
(a) A sound recording produced by a person in Nepal  or a member 
country of the World Trade Organization, 
(b) A sound recording published in Nepal or in a mem ber country of 
the World Trade Organization. 
   (4) The following broadcasting organization shal l be entitled 
to the rights relating to broadcasting organization as referred to in this Act: 
 11 
(a)  A broadcast by a broadcasting organization wit h its office in 
Nepal or in a member country of the World Trade 
 Organization, 
(b)  A Broadcast by a broadcasting station situated  in Nepal or in a 
member country of the World Trade Organization. 
Chapter: 3  
Term of protection of Copyright', 8, 'The Copyright Act, 2059 (2002), Chapter-2, Section 11 (Reasonable remuneration for the use of sound record ing)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3.9', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:3', 2, 'section', '14', 'Term of protection of copyright : (1) The economic and moral rights', 'Term of protection of copyright', 'available to the author under this Act shall be pro tected throughout the life of 
the author and in the case of his/her death until f ifty years computed from the 
year of his death. 
 (2) The economic and moral rights over the work pr epared jointly shall 
be protected for fifty years computed from the year  of death of the last 
surviving author. 
 (3) The economic and moral right of the work prepa red pursuant to 
Clauses (b) and (c) or Sub-section (2) of Section 6  shall be protected until fifty 
years from the date of first publication of such wo rk or the date on which the 
work is made public, whichever is earlier. 
 (4) The economic and moral right of the work publi shed anonymously or 
with pseudonym name shall be protected until fifty years from the date of first 
publication of such work or the date on which the w ork is made public, 
whichever is earlier. 
 Provided, however, that in cases where the name of  author is published 
within that period of time, the protection referred  to in Sub-section (1) or (5) 
shall be available depending on the case. 
 (5) The economic and moral right of a work relatin g to applied art and 
photographic work shall be protected until twenty-f ive years from the year of 
preparation of such work. 
15. 
Term of protection of work published after the deat h of author : 
Notwithstanding anything contained in Section 14, t he work published after the 
 12 
death of the author where there is only one author of such work and after the 
death of one of the authors where there are two or more authors shall be 
protected until fifty years from the year of publication of that work.', 9, 'The Copyright Act, 2059 (2002), Chapter-2, Section 14 (Term of protection of copyright)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:4', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', NULL, 1, 'chapter', 'Chapter-4', 'Chapter-4', NULL, NULL, 4, 'The Copyright Act, 2059 (2002), Chapter-4', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:4.0', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:4', 2, 'section', '16', 'Reproduction allowed for personal purpose : (1) Notwithstanding', 'Reproduction allowed for personal purpose', 'anything contained in Clause (a) of Section 7, no a uthorization shall be required 
from the author or the copyright owner to reproduce  some portions of any 
published work for personal use. 
 (2) Notwithstanding anything contained in Sub-sect ion (1), no 
reproduction of an architectural design erected as a building and other 
construction related design or a significant portio n of any book or of a musical 
work as notation of all or significant portion of a  database through digital 
transmission shall be allowed in a manner to be pre judicial to the economic 
right of the author or the copyright owner. 
17. 
Citation allowed : Notwithstanding anything contained in Clause (a) o f 
Section 7, some portions of a published work can be  cited for fair use without 
authorization of the author or the copyright owner in a manner not to be 
prejudicial to the economic right of such author or  owner. In making such 
citation, its source and the author'' name, in cases  where it appears, shall also be 
mentioned.', 0, 'The Copyright Act, 2059 (2002), Chapter-4, Section 16 (Reproduction allowed for personal purpose)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:4.1', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:4', 2, 'section', '18', 'Reproduction allowed for teaching and learning : (1) Notwithstanding', 'Reproduction allowed for teaching and learning', 'anything contained in Clause (a) of Section 7, the following acts may be done 
for teaching and learning activities without author ization of the author or the 
copyright owner in a manner not to be prejudicial to  the economic right of such 
author or owner:- 
(a) To reproduce a small portion of any published work by way of 
citation, writing or audio-visual aid, 
 13 
(b) To reproduce, broadcast and exhibit some portions o f the work for 
purposes of educational activities to be performed in the classroom. 
(2) All copies reproduced pursuant to Sub-section ( 1) have to indicate 
the source and the author''s name.', 1, 'The Copyright Act, 2059 (2002), Chapter-4, Section 18 (Reproduction allowed for teaching and learning)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:4.2', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:4', 2, 'section', '19', 'Reproduction by library and archives : Notwithstanding anything', 'Reproduction by library and archives', 'contained in Clause (a) of Section 7, in cases wher e a public library or archives, 
which makes available the work stored in it at the request of a person doing 
research or study without deriving economic profits  directly or indirectly, 
looses any work with it or such work is destroyed o r is old or is incapable of 
being obtained, it may reproduce one copy of such a  work without authorization 
of the author or the copyright owner of such work.', 2, 'The Copyright Act, 2059 (2002), Chapter-4, Section 19 (Reproduction by library and archives)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:4.3', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:4', 2, 'section', '20', 'Reproduction, broadcast and other communication all owed for', 'Reproduction, broadcast and other communication all owed for', 'purposes of information to the general public : (1) Notwithstanding 
anything contained in clauses (a), (i) and (j) of S ection 7, the following acts can 
be done, by mentioning the sources and name of the author of any work, 
without authorization of the author or the copyright owner of such work. 
(a) To print in any newspaper or journal or to make bro adcast or other 
communication to public of any article, article unde r political or 
religious topics or similar other broadcasts publish ed in any 
newspaper or journal. 
 Provided, however, that such act shall not be prej udicial to the 
economic right of the author or the copyright owner. 
(b) To reproduce, broadcast or otherwise communicate or justify any 
event with a view to informing the general public ab out any 
current event. 
(c) To reproduce, broadcast or to make communication to public some 
portions of any regular newspaper or journal regula rly publishing 
information for communication to the general public or pleadings 
made on court proceedings with a view to disseminati ng current 
information. 
 14 
(2) Notwithstanding anything contained in Sub-secti on (1), in cases 
where the author himself/herself has indicated that his/her work is prohibited 
from being reproduced, broadcast and other kinds of  communications, no 
reproduction, broadcasting and other communication shall be allowed.', 3, 'The Copyright Act, 2059 (2002), Chapter-4, Section 20 (Reproduction, broadcast and other communication all owed for)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:4.4', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:4', 2, 'section', '21', 'Reproduction of computer program : Notwithstanding anything contained', 'Reproduction of computer program', 'in Clauses (a) and (c) of Section 7, in cases where  the objectives for which a 
computer program was acquired could not be achieved  or with a view to 
maintaining records or where the computer program a cquired legally is lost or 
destroyed or is incapable of being used, one copy o f the computer program can 
be reproduced without authorization of its author or copyright owner.', 4, 'The Copyright Act, 2059 (2002), Chapter-4, Section 21 (Reproduction of computer program)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:4.5', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:4', 2, 'section', '22', 'Importation allowed for personal purposes : Notwithstanding anything', 'Importation allowed for personal purposes', 'contained in Clauses (g) of Section 7, one copy of any work can be imported for 
personal purpose, without authorization of its author or copyright owner.', 5, 'The Copyright Act, 2059 (2002), Chapter-4, Section 22 (Importation allowed for personal purposes)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:4.6', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:4', 2, 'section', '23', 'Public exhibition allowed : Notwithstanding anything contained in clauses', 'Public exhibition allowed', '(h) of Section 7, in cases where any person intends  to have public display of 
any work or copy of the work, he may do so without authorization of its author 
or copyright owner. 
  Provided, however, that such public display has t o be made without the 
help of film, slide, television image or otherwise using the screen or device of 
other kind.', 6, 'The Copyright Act, 2059 (2002), Chapter-4, Section 23 (Public exhibition allowed)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:5', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', NULL, 1, 'chapter', 'Chapter-5', 'Chapter-5', NULL, NULL, 5, 'The Copyright Act, 2059 (2002), Chapter-5', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:5.0', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:5', 2, 'section', '24', 'Transfer of Copyright : (1) The copyright owner may transfer all or any of', 'Transfer of Copyright', 'the economic rights conferred on him/her to any one  by making a written 
agreement or authorize any one to use the same with  or without specifying any 
terms. 
 (2) The person entitled to moral rights may, for t he protection of moral 
rights, transfer his moral rights to any one, with effect after his/her death, by 
making a written agreement, with the terms and cond itions that his/her name 
shall not be removed from the work. 
 15 
 (3) The person to whom the rights are transferred by the copyright owner 
pursuant to this Section shall not carry out any ot her activities except the rights 
so transferred.', 0, 'The Copyright Act, 2059 (2002), Chapter-5, Section 24 (Transfer of Copyright)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:6', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', NULL, 1, 'chapter', 'Chapter-6', 'Chapter-6', NULL, NULL, 6, 'The Copyright Act, 2059 (2002), Chapter-6', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:6.0', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:6', 2, 'section', '25', 'Infringement of protected right : (1) Any one who carries out the following', 'Infringement of protected right', 'act shall be considered to have infringed the right protected under this Act:- 
(a) To reproduce copies of a work or sound recording an d sell and 
distribute them or publicly communicate or rent the m with 
commercial or any other motive with or without deriving economic 
benefits without authorization of the author or the  copyright owner 
or by infringing the terms contained in the agreeme nt or license 
notwithstanding that such authorization has been obtained, 
(b) To do advertisement or publicize by copying a work belonging to 
another person with a motive of taking advantage of  the reputation 
gained by that work, 
(c) To make work of another subject or nature by changi ng the form 
and language of a work belonging to another person with a motive 
of deriving economic benefit, 
(d) To make an attempt to take benefit by adapting any work directly 
or indirectly with intention of making the viewer, listener or reader 
believe it to be another work through advertisement  or by any 
other means, 
(e) To import, produce or rent any equipment or device prepared with 
intention of circumventing any device designed to di scourage the 
unauthorized reproduction,  
(f) To produce or import, with intent to sell, any equi pment 
facilitating unauthorized reception of a program bro adcast by 
encrypting it in a code language, 
 16 
(g) To import, sell, distribute and use a mechanical de vice prepared 
with a sole object of infringing the copyright, exc ept those 
mentioned in Clauses (e) and (f). 
(2) No one shall, with knowledge of publication of any work or sound 
recording or where there is adequate ground to beli eve it, sell and distribute and 
rent copies of work or sound recording so published , in contravention of sub-
section (1).', 0, 'The Copyright Act, 2059 (2002), Chapter-6, Section 25 (Infringement of protected right)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:6.1', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:6', 2, 'section', '26', 'Restriction on the importation of unauthorized copi es : Importation of', 'Restriction on the importation of unauthorized copi es', 'copies of work or sound recording, either made in a  foreign country or sourced 
otherwise, into Nepal for business purpose shall no t be permitted if preparation 
of such copies would be considered illegal if they were prepared in Nepal.', 1, 'The Copyright Act, 2059 (2002), Chapter-6, Section 26 (Restriction on the importation of unauthorized copi es)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:6.2', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:6', 2, 'section', '27', 'Punishment on infringement of protected right : (1) In cases where any', 'Punishment on infringement of protected right', 'person infringes Section 25, such a person shall be  punished with a fine of a 
sum from ten thousand to one hundred thousand rupees or with imprisonment 
for a term not exceeding six months or both and wit h a fine of a sum from 
twenty thousand to two hundred thousand rupees or w ith imprisonment for a 
term not exceeding one year or with both for each i nstance from the second 
time. The materials so published or reproduced or d istributed or devices used to 
reproduce such materials shall be seized. 
  (2) Compensation for the loss caused to the copyr ight owner by the 
infringer of the protected right shall also be real ized and provided to the 
copyright owner.', 2, 'The Copyright Act, 2059 (2002), Chapter-6, Section 27 (Punishment on infringement of protected right)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:6.3', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:6', 2, 'section', '28', 'Punishment for importation of unauthorized copy : In cases where any', 'Punishment for importation of unauthorized copy', 'person imports unauthorized copies of any work in violation of Section 26, such 
a person shall be punished with a fine of a sum fro m ten thousand to one 
hundred thousand rupees according to the gravity of  the offense, and such 
copies shall be seized; and compensation for the lo ss caused to the copyright 
owner from such importation shall also be realized from the importer and 
provided to the copyright owner. 
 17', 3, 'The Copyright Act, 2059 (2002), Chapter-6, Section 28 (Punishment for importation of unauthorized copy)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:6.4', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:6', 2, 'section', '29', 'Other punishment : In cases where any person infringes any other matt er', 'Other punishment', 'contained in this Act or the Rules framed under this  Act, such a person shall be 
punished with a fine of a sum from five thousand to fifty thousand rupees 
according to the gravity of the offense.', 4, 'The Copyright Act, 2059 (2002), Chapter-6, Section 29 (Other punishment)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', NULL, 1, 'chapter', 'Chapter-7', 'Chapter-7', NULL, NULL, 7, 'The Copyright Act, 2059 (2002), Chapter-7', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7.0', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7', 2, 'section', '30', 'Registrar and his functions, duties and powers : (1) Government of Nepal', 'Registrar and his functions, duties and powers', 'may, by a notification in the Nepal Gazette, design ate any officer of at least 
Gazetted second class to act as the Registrar pursuant to this Act. 
  (2) In addition to those mentioned elsewhere in t his Act, the functions, 
duties and powers of the Registrar shall be as follows: 
(a) To monitor and control the royalty collecting body, 
(b) To hear complain as prescribed made by any party wh o is not 
 satisfied with the royalty fixed by the royalty co llecting body, 
(c) To perform, or cause to be performed such other fun ctions as 
 prescribed for the accomplishment of the objective  of this Act.', 0, 'The Copyright Act, 2059 (2002), Chapter-7, Section 30 (Registrar and his functions, duties and powers)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7.1', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7', 2, 'section', '31', 'Appeal against order and decision of Registrar : An party who is not', 'Appeal against order and decision of Registrar', 'satisfied with any order or decision made by the Re gistrar may make an appeal 
in the Appellate Court in the area where the Office  of the Registrar is situated, 
within thirty-five days.', 1, 'The Copyright Act, 2059 (2002), Chapter-7, Section 31 (Appeal against order and decision of Registrar)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7.2', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7', 2, 'section', '32', 'Power to seize copies of work, sound recording or o ther materials : (1)', 'Power to seize copies of work, sound recording or o ther materials', 'In cases where any person doubt that any one has pu blished or reproduced or is 
about to publish or reproduce any work or sound rec ording contrary to Section 
25 and makes a complaint before the police who has a duty of investigating the 
offense under this Act, the police shall make neces sary arrangements for 
preventing the copies of such work or sound recordi ng from being sold and 
distributed and may, in cases where required, searc h the copies of such work or 
sound recording and seize the same pursuant to the law in force. 
 18 
 (2) In conducting search and seizure pursuant to S ub-section (1), the 
machine including materials used to publish and rep roduce the copies of such 
work or sound recording may also be seized.', 2, 'The Copyright Act, 2059 (2002), Chapter-7, Section 32 (Power to seize copies of work, sound recording or o ther materials)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7.3', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7', 2, 'section', '33', 'To destroy copies of work, sound recording or other  materials : In', 'To destroy copies of work, sound recording or other  materials', 'cases where the copies of the work or sound recordi ng seized pursuant to 
Section 32 are held by the court liable to be seize d, they shall be destroyed in 
presence of the representatives of the District Adm inistration Office and the 
Local body.', 3, 'The Copyright Act, 2059 (2002), Chapter-7, Section 33 (To destroy copies of work, sound recording or other  materials)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7.4', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7', 2, 'section', '34', 'Power of Customs Officer to stop importation of una uthorized copies :', 'Power of Customs Officer to stop importation of una uthorized copies', '(1) In cases where any person suspects that any oth er person is importing 
copyrighted materials into Nepal in an unauthorized  manner, such a person may 
make an application, accompanied by the evidence, t o the Custom Officer to 
prevent the importation of such material. 
 (2) In cases where, in conducting necessary invest igation upon receipt of 
an application pursuant to Sub-section (1), the dem and of the applicant appears 
reasonable, the Customs Officer may prevent the mat erials to be imported for a 
maximum of twenty working days at the rate of ten working days at a time. 
 (3) Notwithstanding anything contained in Sub-sect ions (1) and (2), in 
cases where the Customs Officer learns or suspects that any one is importing 
copyright reserved materials into in an unauthorize d manner, he/she may 
prevent such materials for a maximum of twenty work ing days at the rate of ten 
working days at a time. 
(4) Other procedures on the prevention of importati on of unauthorized 
copies shall be as prescribed. 
35. 
To try and settle cases : (1) The concerned District Court shall have the 
powers to try and settle cases punishable under this Act. 
 (2) In trying and settling cases under this Act, t he procedures referred to 
in the Summary Procedures Act, 2028 (1971) shall be followed.', 4, 'The Copyright Act, 2059 (2002), Chapter-7, Section 34 (Power of Customs Officer to stop importation of una uthorized copies)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7.5', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7', 2, 'section', '36', 'Power to order for withholding : In cases where, in the course of trying and', 'Power to order for withholding', 'settling a compliant pursuant to this Act, the Dist rict Court, at the request of the 
 19 
concerned party, thinks it reasonable to stop any a ctivity contrary to this Act, it 
may order the concerned person or body to stop such activity.', 5, 'The Copyright Act, 2059 (2002), Chapter-7, Section 36 (Power to order for withholding)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7.6', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7', 2, 'section', '37', 'To be state cases : (1) The cases punishable under Sections 27 and 28  shall be', 'To be state cases', 'state cases and those cases shall be considered to be included in Schedule-1 of 
the State Cases Act, 2049 (1992). 
 (2) A police officer of at least the rank of polic e inspector shall 
investigate and inquire into the cases under this Act. 
38. 
Limitation:  In cases where any right under this Act is infring ed, a case has to 
be filed within three months of the knowledge of such infringement.', 6, 'The Copyright Act, 2059 (2002), Chapter-7, Section 37 (To be state cases)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7.7', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7', 2, 'section', '39', 'Provisions relating to royalty collecting body : (1) Generally, one royalty', 'Provisions relating to royalty collecting body', 'collecting body shall be formed as prescribed in on e discipline for the purposes 
of fixing, collecting and distributing royalty of the works relating to copyright. 
 (2) The royalty collecting body formed pursuant to  Sub-section (1) has to 
be registered with the Registrar in the manner as prescribed. 
 (3) The royalty collecting body shall be an autono mous body corporate 
with perpetual succession. 
 (4) The royalty collecting body shall have a seal of its own for all of its 
activities. 
 (5) The royalty collecting body may, like an indiv idual, acquire, use, sell 
and dispose of or otherwise manage movable and immovable property and may, 
like an individual, sue and be sued by its name. 
 (6) Government of Nepal may specify the terms to b e followed by the 
royalty collecting body; and it shall be the duty o f the royalty collecting body to 
abide by such terms. 
40. 
Copyright Government of Nepal : (1) Government of Nepal shall have the 
copyright over the work prepared by Government of Nepal. 
 (2) Government of Nepal may rent or sell the right  accrued to it pursuant 
to sub-section (1) to any person or organization or  give authorization to use the 
same in any other manner. 
 20', 7, 'The Copyright Act, 2059 (2002), Chapter-7, Section 39 (Provisions relating to royalty collecting body)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7.8', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7', 2, 'section', '41', 'Calculation of year:  In calculating a year pursuant to this Act, it sha ll be', 'Calculation of year', 'calculated from the New year as per Bikram Sambat  that starts from the end of 
the year on which the work was published or communi cated publicly or sound 
recording was produced.', 8, 'The Copyright Act, 2059 (2002), Chapter-7, Section 41 (Calculation of year)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7.9', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7', 2, 'section', '42', 'Powers to frame rules : Government of Nepal may frame necessary Rules in', 'Powers to frame rules', 'order to carry out the objectives of this Act.', 9, 'The Copyright Act, 2059 (2002), Chapter-7, Section 42 (Powers to frame rules)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7.10', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf', 'doc_the_copyright_act_2059_2002__2059_copyright_act_2059_pdf:7', 2, 'section', '43', 'Repeal and saving : (1) The Copyright Act, 2022 (1965) is hereby repea led.', 'Repeal and saving', '(2) The remaining term of protection of the copyrig ht of a work 
published publicly prior to the commencement of this  Act shall be deemed to 
have been protected pursuant to this Act. 
 (3) The acts and actions done and taken under the Copyright Act, 2022 
(1965) shall be deemed to have been done and taken under this Act.', 10, 'The Copyright Act, 2059 (2002), Chapter-7, Section 43 (Repeal and saving)', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:0', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', NULL, 1, 'preamble', 'Preamble', 'Introductory matter', NULL, 'The Electronic Transactions Act, 2063 (2008)
Date of Authentication and Publication
22 Mansir 2063 ( december 8, 2006)
Act number 27 of the year 2063
An Act promulgated for Electronic Transactions
Preamble:
WHEREAS, it is expedient to make, legal provisions for authentication and
regularization of the recognition, validity, integrity and reliability of generation,
production, processing, storage, communication and transmission system of electronic
records by making the transactions to be carried out by means of electronic data
exchange or by any other means of electronic communications, reliable and secured;
And where as, for controlling the acts of unauthorized use of electronic records or of
making alteration in such records through the illegal manner,
Now, therefore, be it enacted by the House of Representatives in the First Year of the
issuance of the Proclamation of the House of Representatives, 2063(2007) .', 0, 'The Electronic Transactions Act, 2063 (2008), Preamble', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:1', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', NULL, 1, 'chapter', 'Chapter - 1', 'Chapter - 1', NULL, NULL, 1, 'The Electronic Transactions Act, 2063 (2008), Chapter - 1', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:1.0', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:1', 2, 'section', '1', 'Short Title, Extension and Commencement: (1) This Act may be', 'Short Title, Extension and Commencement', 'called "The Electronic Transactions act,2063 (2008)".
(2) This Act shall be deemed to have been commenced from 24 Bhadra
2063 ( sep.2, 2006).
(3) This Act shall extend throughout Nepal and shall also apply to
any person residing anywhere by committing an offence in contravention to
this Act.', 0, 'The Electronic Transactions Act, 2063 (2008), Chapter - 1, Section 1 (Short Title, Extension and Commencement)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:1.1', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:1', 2, 'section', '2', 'Definitions: Unless the subject or context otherwise requires, in this Act,-', 'Definitions', '1
(a) "Asymmetric Crypto System" means a system that creates a secured
key-pair consisting of a private key creating a digital signature and a
public key to verify the digital signature.
(b) "License" means a license obtained pursuant to Sub-section (3) of
Section 18.
(c) "Originator" means a person who generates, stores or transmits
electronic records, and this term also includes a person who causes any
other person to carry out such functions:
Provided that it shall not include an intermediary.
(d) "Computer" means an electro-magnetic, optical or other high-speed data
processing device or system, which performs logical, arithmetic and
memory functions by manipulating electro-magnetic or optical impulses,
and also includes all acts of input, output, processing, storage and
computer software or communication facilities which are connected or
related to the computer in any computer system or computer network.
(e) "Computer Database" means an information, knowledge and concept or
presentation of instructions, which are being prepared or have already
been prepared in word, image, voice or audio visual form in a
formalized manner or which have been produced by a computer,
computer system or computer network, with a view to use in a
computer, computer system or computer network.
(f) "Computer Network" means an interrelationship between two or more
than two computers having interconnection with each other or in contact
of communication.
(g) "Computer System" means a device or a group of devices, containing all
computer programmes including input and output support devices,
electronic instructions, input and output data that performs logical,
arithmetic, data storage and retrieval, communication including
controlling functions.
2
(h) "Computer Resource" means a computer, computer system, computer
network, data, computer database or software.
(i) "Subscriber" means a person who has obtained a certificate under Sub-
section (3) of Section 31.
(j) "Key Pair" means a private key in an asymmetric crypto system and of
pair of public key, interconnected in a mathematics form with the
private key which has a code to verify digital signature by the public key
to be created from the private key.
(k) "Data" means the presentation of information, knowledge, fact and
concept or instructions in any form, which are kept in a formalized
manner in a computer system or computer network and is intended for
processing the same, or processed or stored in a computer memory.
(l) "Tribunal" means the Information Technology Tribunal formed pursuant
to section 60.
(m) "Private Key" means a key of any key pair used to create a digital
signature.
(n) "Controller" means the Controller appointed or designated pursuant to
section 13.
(o) "Digital Signature" means a signature made in any electronic form to be
included in the transformation of electronic record by a person having a
non- transformed initial electronic record and the public key of signatory
by using a type of asymmetric crypto system that may clearly ascertain
the following matters:
(1) Whether or not transformation of electronic record was
created by using a type of private key keeping a logical consistency with
the public key of signatory; and
(2) Whether or not the initial electronic record has been
changed after the transformation of electronic record.
3
(p) "Access" means an opportunity of gaining entry into, logical,
arithmetical or resources of memory function of any computer,
computer system or computer network, giving instructions to such
resources or making communication contact with such resources.
(q) "Appellate Tribunal" means the Information Technology Appellate
Tribunal formed pursuant to section 66.
(r) "Certificate" means a Digital Signature Certificate issued by the
Certifying Authority under Section 30.
(s) "Certification Practice Statement" means any statement issued by a
Certifying Authority to specify the practices to be applied by the
Certifying Authority while issuing a Digital Signature Certificate.
(t) "Certifying Authority" means a certifying authority which has obtained
a license to issue a Digital Signature Certificate under Sub-section (3) of
Section 18.
(u) "Addressee" means a person receiving the processed electronic record as
intended by the originator.
Provided that it shall not include an intermediary.
(v) "Electronic Record" means the data, record, image or sound transmitted,
received or stored in an electronic form by generating the same through
any means.
(w) "Electronic Form" means a form of information transmitted, received or
stored by generating the same through the means of magnetic, optical,
computer memory or similar other devices.
(x) "Public Key" means a key of any key pair used to verify digital
signature.
(y) "Information" means the data details of the scripted texts, images,
sounds, codes, computer programmes, software and computer databases.
4
(z) "Information system" means a system to generate, produce, transmit,
receive, store and display information or to process the same by other
method.
(aa) Software" means any specific part of computer system such as system
software and application software having the capacity for operating
computer hardware.
(ab) "Computer Accessory" means a technology such as computer resource,
the information used by any institution in its business, a software-like
item produced or purchased by such an institution, hardware and
computer network.
(ac) "Government Authority" means a Ministry, Secretariat, Department of
Government of Nepal or the Offices thereunder, Constitutional Body or
the Offices thereunder, Court or Tribunal or Office of the Nepal Army
and it shall also includes other Offices of the similar nature.
(ad) "Public Institution" means the following institutions:-
(1) A company, bank or board whether fully or partially owned or
controlled by Government of Nepal , or a Commission agency,
authority, corporation, enterprise board, centre, council and other
corporate body of the similar nature established by Government
of Nepal pursuant to the laws prevailing.
(2) A university, school, research centre, and other similar academic
or educational institutions operated by Government of Nepal or
which have been receiving a full or partial grant from
Government of Nepal,
(3) The Local Bodies formed under the Local Self-Governance Act,
1998 (2055 B.S);
(4) The Institutions run on the loan, grant or guarantee of
Government of Nepal;
5
(5) The Institution which is fully or partially owned or controlled by
the institution referred to in sub-Clauses (1), (2), (3) or (4) or
which receiving grant from such institution;
(6) Any other Institutions prescribed by Government of Nepal as a
public institution by a notification published in the Nepal
Gazette.
(ae) “Prescribed” or “As prescribed” means prescribed or as prescribed in
Rules framed under this Act.', 1, 'The Electronic Transactions Act, 2063 (2008), Chapter - 1, Section 2 (Definitions)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:2', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', NULL, 1, 'chapter', 'Chapter - 2', 'Chapter - 2', NULL, NULL, 2, 'The Electronic Transactions Act, 2063 (2008), Chapter - 2', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:2.0', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:2', 2, 'section', '3', 'Authencity of Electronic Record: (1) Any subscriber may, subject to the', 'Authencity of Electronic Record', 'provisions of this section, authenticate to any electronic record by his/her
personal digital signature.
(2) While authenticating the electronic record pursuant to Sub-
section (1), an act of transforming such electronic record to other electronic
record shall be effected by the use of asymmetric crypto system and hash
function.
Explanation: For the purpose of this section, "hash function" means the acts of
mapping of algorithm or translating of a sequence of bits into another,
generally smaller, set yielding the same hash result from any record in the same
form while executing the algorithm each and every time by using the same
record as an input, infeasible to derive or reconstruct any record from the hash
result produced by the algorithm from the computation point of view, and
making the two records, which produce the same hash result by using the
algorithm, computationally infeasible to derive.
(3) Any person may verify the electronic record by using the public
key of the subscriber.
6', 0, 'The Electronic Transactions Act, 2063 (2008), Chapter - 2, Section 3 (Authencity of Electronic Record)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:2.1', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:2', 2, 'section', '4', 'Legal Recognition of Electronic Record: Where the prevailing law', 'Legal Recognition of Electronic Record', 'requires any information, documents, records or any other matters to be kept in
written or printed typewritten form, then, if such information, document, record
or the matter is maintained in an electronic form by fulfilling the procedures as
stipulated in this Act or the Rules made hereunder, such electronic record shall
also have legal validity.', 1, 'The Electronic Transactions Act, 2063 (2008), Chapter - 2, Section 4 (Legal Recognition of Electronic Record)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:2.2', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:2', 2, 'section', '5', 'Legal Recognition of Digital Signature: Where the prevailing law requires', 'Legal Recognition of Digital Signature', 'any information, document, record or any other matters to be certified by
affixing signature or any document to be signed by any person; then, if such
information, documents, records or matters are certified by the digital signature
after fulfilling the procedures as stipulated in this Act or the Rules made
hereunder, such digital signature shall also have legal validity.', 2, 'The Electronic Transactions Act, 2063 (2008), Chapter - 2, Section 5 (Legal Recognition of Digital Signature)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:2.3', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:2', 2, 'section', '6', 'Electronic Records to be Kept Safely: Where the prevailing law requires', 'Electronic Records to be Kept Safely', 'any information, document or record to be kept safely for any specific period of
time and if such information, document or record are kept safely in an
electronic form, by fulfilling the following condition,, such information,
document or record shall have legal validity if that is,-
(a) kept in an accessible condition making available for a subsequent
reference,
(b) kept safely in the format that can be demonstrated subject to presenting
again exactly in the same format in which they were originally generated
and transmitted or received or stored,
(c) kept making the details available by which the origin, destination and
transmission or date and time of receipt can be identified,
Provided that the provision of this Clause shall not be applied in regard to any
information to be generated automatically for the purpose of transmitting or
receiving any record.', 3, 'The Electronic Transactions Act, 2063 (2008), Chapter - 2, Section 6 (Electronic Records to be Kept Safely)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:2.4', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:2', 2, 'section', '7', 'Electronic Record May Fulfill the Requirement of Submission of any', 'Electronic Record May Fulfill the Requirement of Submission of any', 'Original Document: Where the prevailing law requires that any record shall
7
have to be submitted or retained in its main or original form or kept safely,
then, such requirement shall, if the following terms are fulfilled, be deemed to
have been satisfied by the electronic records:
(a) If there exits a ground as prescribed that can be believed that any type of
change is not made in such record by any means from the fist time of its
generation in electronics form,
(b) If such record is of the nature where there is a compulsion of submitting
such document to any person it could be clearly shown to such a person
to whom it requires to do so.', 4, 'The Electronic Transactions Act, 2063 (2008), Chapter - 2, Section 7 (Electronic Record May Fulfill the Requirement of Submission of any)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:2.5', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:2', 2, 'section', '8', 'Secured Electronic Records: If the verification has been made as prescribed', 'Secured Electronic Records', 'in connection with the matter as to whether or not any type of changes are
made into the electronic records generated with the application of security
procedures as prescribed, such electronic records shall be deemed to be a
secured electronic records.', 5, 'The Electronic Transactions Act, 2063 (2008), Chapter - 2, Section 8 (Secured Electronic Records)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:2.6', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:2', 2, 'section', '9', 'Secured Digital Signature: Where any digital signature made in electronic', 'Secured Digital Signature', 'record has been examined in a manner as prescribed with the application of
such security procedure as prescribed, then, such digital signature shall be
deemed to be a secured digital signature.', 6, 'The Electronic Transactions Act, 2063 (2008), Chapter - 2, Section 9 (Secured Digital Signature)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:3', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', NULL, 1, 'chapter', 'Chapter - 3', 'Chapter - 3', NULL, NULL, 3, 'The Electronic Transactions Act, 2063 (2008), Chapter - 3', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:3.0', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:3', 2, 'section', '10', 'Electronic Record to be Attributed to Originator: (1) Any specific', 'Electronic Record to be Attributed to Originator', 'electronic record shall, in case of any of the following conditions, be attributed
to the originator:
(a) If such an electronic record was transmitted by the originator
him/herself,
8
(b) If such an electronic record was transmitted by a person who had
the authority to act on behalf of the originator in respect of such
an electronic record,
(c) Such an electronic record was transmitted through any
information system that was programmed by the originator or on
behalf of the originator to operate automatically.
(2) If any condition exists as prescribed in respect of electronic
record transmitted pursuant to Sub-section (1), the addressee shall assume that
such an electronic record is attributed to any particular originator and shall
have the authority to act thereon accordingly.', 0, 'The Electronic Transactions Act, 2063 (2008), Chapter - 3, Section 10 (Electronic Record to be Attributed to Originator)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:3.1', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:3', 2, 'section', '11', 'Procedure of Receipt and Acknowledgement of Electronic Record:', 'Procedure of Receipt and Acknowledgement of Electronic Record', '(1) Where the originator requests the addressee to transmit the
acknowledgement or receipt of electronic record at the time of or before the
dispatch of such electronic record or where there is an agreement between the
originator and addressee to transmit the acknowledgement or receipt of such an
electronic record, then, the provisions of Sub-sections (2), (3) and (4) shall be
applied in relation to the receipt and acknowledgement of such an electronic
record.
(2) Where there is no agreement between the originator and
addressee that information or acknowledgement of receipt of electronic record
is to be given in a particular format or by a particular manner, such an
information or receipt may be given as the following:-
(a) by automated or any other means of communication by the
addressee,
(b) by any conduct of the addressee sufficient to indicate that the
originator has received electronic record.
(3) Where the originator has stipulated in relation to any electronic
record that such an electronic record shall be binding on him/her only after the
receipt of information or acknowledgement of receipt of such electronic record
9
from the addressee, then, unless the information or acknowledgement of receipt
of such an electronic record has been so received from addressee, the electronic
record shall not be deemed to have been transmitted by the originator.
(4) Where the originator has not stipulated that the electronic record
shall be binding only on receipt of such acknowledgement, and where the
originator and addressee have not agreed upon or have not specified any time
for acknowledgement of such receipt of electronic record, then, the originator
shall have to receive such acknowledgement of receipt of such an electronic
record from addressee within a specified time as prescribed. If such
acknowledgement of receipt is not received from addressee, then, such an
electronic record shall be deemed to have not been transmitted by the
originator.
(5) Other procedures of receipt of acknowledgement of electronic
record shall be as prescribed.', 1, 'The Electronic Transactions Act, 2063 (2008), Chapter - 3, Section 11 (Procedure of Receipt and Acknowledgement of Electronic Record)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:3.2', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:3', 2, 'section', '12', 'Time and Place of Dispatch and Receipt of Electronic Record: (1)', 'Time and Place of Dispatch and Receipt of Electronic Record', 'Save as otherwise agreed between the originator and the addressee, the dispatch
of an electronic record occurs when it enters into an information system outside
the control of the originator.
(2) Save as otherwise agreed between the originator and the
addressee, the time of receipt of an electronic record shall be determined as
prescribed.
(3) Save as otherwise agreed between the originator and the
addressee, an electronic record shall be deemed to have been dispatched from
the place where the originator has his/her place of business and shall be
deemed to have been received at the place where the addressee has his/her
place of business.
Explanation: For the purpose of this Sub-section "the place of business"
means:
10
(a) In case the originator or the addressee has more than one place of
business, the place of business means the place where the concerned
business shall be operated
(b) If the originator or the addressee does not have a place of business, their
place of residence shall be considered their place of business.', 2, 'The Electronic Transactions Act, 2063 (2008), Chapter - 3, Section 12 (Time and Place of Dispatch and Receipt of Electronic Record)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', NULL, 1, 'chapter', 'Chapter 4', 'Chapter 4', NULL, NULL, 4, 'The Electronic Transactions Act, 2063 (2008), Chapter 4', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4.0', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4', 2, 'section', '13', 'Appointment of the Controller and other Employees: (1)', 'Appointment of the Controller and other Employees', 'Government of Nepal may, by notification in the Nepal Gazette, designate any
Government officer or appoint any person who has qualifications as
prescribed in the office of the Controller.
(2) Government of Nepal may, in order to assist the Controller
to perform his/her functions to be performed under this Act, appoint or assign a
Deputy Controller and other employees as required. The employees so
appointed or assigned shall perform their functions under the general direction
and control of the Controller.', 0, 'The Electronic Transactions Act, 2063 (2008), Chapter 4, Section 13 (Appointment of the Controller and other Employees)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4.1', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4', 2, 'section', '14', 'Functions, Duties and Powers of the Controller:', 'Functions, Duties and Powers of the Controller', 'The functions, duties and powers of the controller shall be as follows:-
(a) To issue a license to the certifying Authority,
(b) To exercise the supervision and monitoring over the activities of
Certifying Authority,
(c) To fix the standards to be maintained by certifying authority in respect
to the verification of digital signature,
(d) To specify the conditions to be complied with by the certifying authority
in operating his/her business,
(e) To specify the format of the certificate and contents to be included
therein,
11
(f) To specify the procedures to be followed by the certifying authority
while conducting his/her dealings with the subscribers,
(g) To maintain a record of information disclosed by the certifying authority
under this act and to make provision of computer database accessible to
public and to update such database,
(h) To perform such other functions as prescribed.', 1, 'The Electronic Transactions Act, 2063 (2008), Chapter 4, Section 14 (Functions, Duties and Powers of the Controller)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4.2', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4', 2, 'section', '15', 'License to be obtained: No person shall perform or cause to be performed', 'License to be obtained', 'the functions of a certifying authority without obtaining a license under this
Act.', 2, 'The Electronic Transactions Act, 2063 (2008), Chapter 4, Section 15 (License to be obtained)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4.3', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4', 2, 'section', '16', 'Application to be submitted for a License: (1) Any person willing to', 'Application to be submitted for a License', 'work as Certifying Authority by issuing a certificate under this Act and who
has the qualifications as prescribed shall have to submit an application to the
controller in a format as prescribed accompanied by a fee as prescribed for
obtaining a license for the certification.
(2) The applicant applying under Sub-section (1) shall also attach the
following documents:
(a) Details regarding certification,
(b) Documents to prove the identification and verification of the
applicant,
(c) Statements specifying the financial resources, human resources and
other necessary facilities,
(d) Such other documents as prescribed.
(3) The controller may, if he/she thinks necessary, ask the applicant
to serve additional documents and details in connection to examine the
appropriation of the applicant as to perform the function of Certifying
Authority. If the necessary additional documents and details are so asked, no
actions shall be taken upon the application of the applicant unless he/she
submits such documents and details.
12', 3, 'The Electronic Transactions Act, 2063 (2008), Chapter 4, Section 16 (Application to be submitted for a License)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4.4', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4', 2, 'section', '17', 'Other Functions and Duties of the Certifying Authority:', 'Other Functions and Duties of the Certifying Authority', 'Other functions and duties of the certifying authority, other than those to
issue a certificate, to suspend or revoke it, shall be as prescribed.', 4, 'The Electronic Transactions Act, 2063 (2008), Chapter 4, Section 17 (Other Functions and Duties of the Certifying Authority)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4.5', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4', 2, 'section', '18', 'Procedure for granting of a license: (1) The Controller may, on receipt of', 'Procedure for granting of a license', 'an application under section 16, after considering the qualification of applicant
and also the documents and statements decide upon within a period of two
months of receipt of such application whether or not such a person possesses
the financial, physical and human resources, and other facilities as prescribed
and whether or not a license should be issued to such an applicant and a notice
to that effect shall be given to him.
(2) While deciding upon the issuance of a license under Sub-section
(1), the Controller may inspect the facilities, financial and physical resources of
the applicant.
(3) If the Controller decides to issue a license under Sub-section (1),
a license in the prescribed format shall be issued to the applicant specifying the
period of validity of the license and also the terms and conditions to be
followed by him.
(4) Other procedures relating to the issuance of a license shall be as
prescribed.', 5, 'The Electronic Transactions Act, 2063 (2008), Chapter 4, Section 18 (Procedure for granting of a license)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4.6', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4', 2, 'section', '19', 'Renewal of License: (1) A license obtained by Certifying Authority shall', 'Renewal of License', 'have to renew in each year,
(2) A Certifying Authority desirous to renew the license under Sub-
section (1), shall have to submit and application in the prescribed format to the
Controller at least two months prior to the expiry of the period of validity of
such a license along with such renewal fee as prescribed,
(3) If an application is submitted for renewal, under Sub-section (2),
the Controller shall have to decide whether to renew the license or not, after
completing the procedures as prescribed one month prior to the expiry date of
validity of such a license,
13
(4) While deciding to reject to renew a license, the applicant shall be
given a reasonable opportunity to present his/her statement in this regard.', 6, 'The Electronic Transactions Act, 2063 (2008), Chapter 4, Section 19 (Renewal of License)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4.7', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4', 2, 'section', '20', 'License may be suspended: (1) If the documents or statement and statement', 'License may be suspended', 'of financial and physical resources submitted by the certifying authority before
the Controller in order to obtain a license are found incorrect or false or the
conditions to be complied with in course of operation of business is not
complied with or this Act of the Rules framed hereunder are found to be
violated, the Controller may suspend the license of the certifying authority till
the inquiry in this regard is completed.
Provided that, Certifying Authority shall be given the reasonable
opportunity to present his/her defense prior to such suspension of a license.
(2) Other procedures concerning suspension of license and other
provisions related thereto be as prescribed.', 7, 'The Electronic Transactions Act, 2063 (2008), Chapter 4, Section 20 (License may be suspended)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4.8', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4', 2, 'section', '21', 'License may be revoked: (1) If the controller believes, after completion of', 'License may be revoked', 'an inquiry in connection to any activity of Certifying Authority, made duly, as
prescribed, that any of the following circumstances have been occurred, the
Controller may revoke a license issued under this Act, at any time, as he deems
to be appropriate:
(a) If the Certifying Authority fails to comply with the liabilities under this
act and the rules made thereunder.
(b) If it is found that the Certifying Authority has submitted false or
incorrect document or statement at the time of submitting an application
for obtaining a license or for its renewal, as the case may be.
(c) If the Certifying Authority operates business in such a manner so that it
shall make adverse effect to the public interest or to the national
economy,
(d) If the Certifying Authority commits any act that is defined as an offence
under this Act or the Rules framed hereunder.
14
(2) The Controller shall, prior to revocation of a license under Sub-
section (1), provide a reasonable opportunity to the Certifying Authority to
present his/her defense.
(3) Other procedures concerning revocation of a license shall be as
prescribed.', 8, 'The Electronic Transactions Act, 2063 (2008), Chapter 4, Section 21 (License may be revoked)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4.9', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4', 2, 'section', '22', 'Notice of Suspension or revocation of a License: (1) Where a license of', 'Notice of Suspension or revocation of a License', 'any Certifying Authority is suspended or revoked under Section 20 or 21, as
the case may be the Controller shall give a written notice to the Certifying
Authority of such suspension or revocation, as the case may be, to such a
certifying Authority and shall keep such a notice in his computer database and
also publish in the electronic form.
(2) The Controller shall publish the notice of suspension or
revocation of a license at least in two daily newspapers in Nepali and English
languages for two times.
Provided that, there shall be no effect to any decision of suspension or
revocation, as the case may be, made by the Controller under Section 20 or 21,
merely on the ground of non-publication of such a notice.', 9, 'The Electronic Transactions Act, 2063 (2008), Chapter 4, Section 22 (Notice of Suspension or revocation of a License)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4.10', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4', 2, 'section', '23', 'Recognition to Foreign Certifying Authority may be given: (1) The', 'Recognition to Foreign Certifying Authority may be given', 'Controller may with the prior approval of Government of Nepal, and subject to
such conditions and restrictions as may be prescribed, by notification in the
Nepal Gazette, recognize any Certifying Authority who has obtained a license
to certify under any foreign law. Any foreign Certifying Authority so
recognized may issue the certificates under this Act or the Rules made
thereunder throughout the Nepal.
(2) The procedures to be adopted in providing the recognition to a
foreign Certifying Authority as referred to in Sub-section (1), shall be as
prescribed.', 10, 'The Electronic Transactions Act, 2063 (2008), Chapter 4, Section 23 (Recognition to Foreign Certifying Authority may be given)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4.11', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4', 2, 'section', '24', 'The Controller may issue Orders: (1) The Controller may, in order to', 'The Controller may issue Orders', 'cause to fulfill the responsibilities in regard to issuance of a certificate by the
15
Certifying Authorities, issue directives, from time to time. It shall be a duty of
the Certifying Authority to comply with such directives.', 11, 'The Electronic Transactions Act, 2063 (2008), Chapter 4, Section 24 (The Controller may issue Orders)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4.12', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4', 2, 'section', '25', 'The Controller may delegate power: The Controller may, in order to', 'The Controller may delegate power', 'perform the function to be performed by him/her delegate to any officer
subordinate to him/her to exercise all or any of his/her powers under this Act or
the Rules framed thereunder.', 12, 'The Electronic Transactions Act, 2063 (2008), Chapter 4, Section 25 (The Controller may delegate power)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4.13', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4', 2, 'section', '26', 'The Controller may investigate: (1) The Controller may, if he/she', 'The Controller may investigate', 'believes that this Act or the Rules framed hereunder are not complied with by
the Certifying Authority or by other concerned person, conduct him/herself or
cause any officer to conduct necessary investigation in that regard.
(2) It shall be a duty of Certifying Authority to assist the
investigations, referred to in Sub-section (1).
(3) The procedure to be followed by the Controller or any other
officer in respect to investigation referred to in Sub-section (1) shall be as
prescribed.', 13, 'The Electronic Transactions Act, 2063 (2008), Chapter 4, Section 26 (The Controller may investigate)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4.14', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4', 2, 'section', '27', 'Performance Audit of Certifying Authority: (1) The Controller may', 'Performance Audit of Certifying Authority', 'conduct or cause to be conducted performance audit of the Certifying Authority
in each year.
(2) The Controller may, for the purpose of the performance audit
referred to in Sub-section (1), appoint any recognized auditor, who has
expertise in computer security or any computer expert.
(3) The Controller shall publish the report of the performance audit
in the electronic form made under Sub-section (1) by maintaining in his/her
computer database.
(4) The qualification of the performance auditor or remuneration and
the procedures of such audit shall be as prescribed.
16
(5) The Controller shall fix the standard of the service of Certifying
Authority and publish a notice thereof publicly for the information to the
public-in-general.', 14, 'The Electronic Transactions Act, 2063 (2008), Chapter 4, Section 27 (Performance Audit of Certifying Authority)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4.15', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4', 2, 'section', '28', 'The Controller to have the Access to Computers and data: (1) The', 'The Controller to have the Access to Computers and data', 'Controller shall, if there is a reasonable ground to suspect that provision of this
Act and Rules framed hereunder has been violated, have the power to have the
access to any computer system, apparatus, devices, data, information system or
any other materials connected with such system.
(2) The Controller may, for the purpose of Sub-section (1), issue
necessary directives to the owner of any computer system, apparatus, device,
data, information system or any material connected with such system or to any
other responsible person to provide technical or other cooperation as he/she
deems necessary.
(3) It shall be the duty of the concerned person to comply with such
directive issued under Sub-section (2).', 15, 'The Electronic Transactions Act, 2063 (2008), Chapter 4, Section 28 (The Controller to have the Access to Computers and data)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4.16', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:4', 2, 'section', '29', 'Record to be maintained: (1) The Controller shall maintain records of all', 'Record to be maintained', 'Certificates issued under this Act.
(2) The Controller shall, in order to ensure the privacy and security
of the digital signatures, perform following functions:
(a) To use Computer Security System,
(b) To apply security procedures to ensure the privacy and
integrity of digital signature,
(c) To comply with the standard as prescribed,
(3) The Controller shall maintain and update computerized data base
of all public keys in a computer system.
(4) For the purpose of verification of Digital Signature, the
Controller shall make available a public key to any person requesting for such a
key.
17', 16, 'The Electronic Transactions Act, 2063 (2008), Chapter 4, Section 29 (Record to be maintained)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:5', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', NULL, 1, 'chapter', 'Chapter-5', 'Chapter-5', NULL, NULL, 5, 'The Electronic Transactions Act, 2063 (2008), Chapter-5', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:5.0', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:5', 2, 'section', '30', 'Certifying Authority may issue a Certificate: Only a licensed or', 'Certifying Authority may issue a Certificate', 'recognized Certifying Authority under this Act may issue a Digital Signature
Certificate.', 0, 'The Electronic Transactions Act, 2063 (2008), Chapter-5, Section 30 (Certifying Authority may issue a Certificate)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:5.1', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:5', 2, 'section', '31', 'Apply to obtain a Certificate: (1) Any person desirous to obtain Digital', 'Apply to obtain a Certificate', 'Signature Certificate may apply to the Certifying Authority in such a format
along with such fee and other statements as prescribed.
(2) On receipt of an application under Sub-section (1), the Certifying
Authority shall have to decide whether to issue or not a certificate to the
applicant within one month of such application so received.
(3) The Certifying Authority shall, if it decides to issue a certificate
under Sub-section (2), issue a Digital Signature Certificate within seven days
affixing his signature in a prescribed format with the inclusion of such
statements as prescribe and if it decides to reject to issue such certificate, the
applicant shall be notified the reasons for rejection within seven days.', 1, 'The Electronic Transactions Act, 2063 (2008), Chapter-5, Section 31 (Apply to obtain a Certificate)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:5.2', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:5', 2, 'section', '32', 'Certificate may be suspended: (1) Certifying Authority may suspend the', 'Certificate may be suspended', 'Certificate in following circumstances:
(d) If the subscriber obtaining the certificate or any person
authorized to act on behalf of such a subscriber, requests to
suspend the certificate.
(e) If it is found necessary to suspend the certificate that
contravenes public interest as prescribed.
(f) If it is found that significant loss might be caused to those
persons who depend on the certificate by the reason that
provisions of this Act or the Rules framed hereunder were
not followed at the time of issuance of the certificate, and if
18
the controller instructs to suspend the certificate having
specified the above ground.
(2) Grounds and procedures for suspension and release of the
suspended certificates shall be as prescribed.', 2, 'The Electronic Transactions Act, 2063 (2008), Chapter-5, Section 32 (Certificate may be suspended)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:5.3', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:5', 2, 'section', '33', 'Certificate may be revoked: (1) The Controller or the Certifying Authority', 'Certificate may be revoked', 'may revoke a Certificate in following conditions:
(g) Where the subscriber or any other person authorized by him
requests to revoke a certificate,
(h) If it is necessary to revoke in a certificate that contravenes
the public interest as prescribed,
(i) Upon the death of the subscriber,
(j) Upon the insolvency, winding up or dissolution of the
company or corporate body under the prevailing laws,
where the subscriber is a company or a corporate body.
(k) If it is proved that a requirement for issuance of the
Certificate was not satisfied.
(l) If a material fact represented in the certificate is proved to
be false.
(m) If a key used to generate key pair or security system was
compromised in a manner that affects materially the
Certificate''s reliability.
(2) The procedures to be followed by the Controller or Certifying
Authority with respect to revocation of a Certificate shall be as prescribed.', 3, 'The Electronic Transactions Act, 2063 (2008), Chapter-5, Section 33 (Certificate may be revoked)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:5.4', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:5', 2, 'section', '34', 'Notice of Suspension or Revocation: (1) Where a Certificate is suspended', 'Notice of Suspension or Revocation', 'or revoked under sections 32 or 33, the Certifying Authority or the Controller,
as the case may be, shall publish a public notice thereof maintaining its record
in their repository.
19
(2) It shall be the responsibility of the Certifying Authority or the
Controller, as the case may be, to communicate the subscribers as soon as
possible on suspension or revocation Certificates.', 4, 'The Electronic Transactions Act, 2063 (2008), Chapter-5, Section 34 (Notice of Suspension or Revocation)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:6', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', NULL, 1, 'chapter', 'Chapter-6', 'Chapter-6', NULL, NULL, 6, 'The Electronic Transactions Act, 2063 (2008), Chapter-6', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:6.0', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:6', 2, 'section', '35', 'To Generate Key pair: (1) Where any Certificate issued by the Certifying', 'To Generate Key pair', 'Authority and accepted by subscriber, consisting of a public key which
corresponds to the key pair and to be listed in such Certificate and if such key
pair is supposed to be generated by the subscriber only, then the subscriber
shall generate such key pair by applying the secured asymmetric crypto system.
(2) Notwithstanding anything contained in Sub-section (1), if a
Certifying Authority and the subscriber have concluded an agreement or the
Certifying Authority has accepted any specific system regarding the security
system to be used to generate the key pair, then, it shall be the duty of
subscriber to apply the security system as specified in agreement or accepted
by the Certifying Authority.', 0, 'The Electronic Transactions Act, 2063 (2008), Chapter-6, Section 35 (To Generate Key pair)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:6.1', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:6', 2, 'section', '36', 'To Accept a Certificate: (1) The certificate shall be deemed to have been', 'To Accept a Certificate', 'accepted by the subscriber in the following conditions:
(n) If he publishes such a certificate or authorizes to publish to
one or more persons, or
(o) If there exists any ground of his acceptance to such
certificate which may cause to believe it.
(2) If the certificate is accepted it shall be deemed that the subscriber,
by that reason, has guaranteed to all who reasonably rely on the information
contained in the certificate that-
(a) The subscriber holds the private key corresponding to the public
key and is entitled to hold the same,
20
(b) All representations and information made by the subscriber to the
Certifying Authority in course of issuance of the certificate are
true and correct and all facts relevant to the information
contained in the certificate are true, and
(c) All information mentioned in the certificate is, to the best
knowledge of subscriber, is true and correct.', 1, 'The Electronic Transactions Act, 2063 (2008), Chapter-6, Section 36 (To Accept a Certificate)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:6.2', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:6', 2, 'section', '37', 'To retain the private key in a secured manner: (1) Every subscriber shall', 'To retain the private key in a secured manner', 'exercise reasonable care to retain control of the private key corresponding to
the public key listed in the Certificate and adopt all measures to prevent its
disclosure to a person not authorized to affix the digital signature of subscriber.
(2) If the private key has been disclosed or compromised by any
reason whatsoever, then, the subscriber shall communicate the same without
any delay to the Certifying Authority and on receipt of such information the
Certifying Authority shall immediately suspend such a Certificate.
(3) If a certificate is suspended under this Act, it shall be a duty of
the subscriber to retain the private key under this section in a safe manner
throughout the duration of such suspension of Certificate.', 2, 'The Electronic Transactions Act, 2063 (2008), Chapter-6, Section 37 (To retain the private key in a secured manner)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:6.3', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:6', 2, 'section', '38', 'To Deposit the Private Key to the Controller: (1) If the Controller', 'To Deposit the Private Key to the Controller', 'thinks, in order to protect the sovereignty or integrity of Nepal, to maintain the
friendly relations with friendly countries, to maintain the law and order, to
prevent from committing of any offence under the laws prevailing, and or in
other conditions as prescribed, necessary to issue an order to any subscriber to
deposit the private key to him/her specifying reason there for, such a subscriber
shall immediately deposit the private key to the Controller.
(2) The controller shall not inform any unauthorized person about the
private key deposited as per sub section (1).
21', 3, 'The Electronic Transactions Act, 2063 (2008), Chapter-6, Section 38 (To Deposit the Private Key to the Controller)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:7', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', NULL, 1, 'chapter', 'Chapter-7', 'Chapter-7', NULL, NULL, 7, 'The Electronic Transactions Act, 2063 (2008), Chapter-7', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:7.0', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:7', 2, 'section', '39', 'Government Documents may be published in electronic form: (1)', 'Government Documents may be published in electronic form', 'Government of Nepal may also publish ordinance, Act, Rules Bye-laws,
Formation Orders or notifications or any other matters in the electronic form
which are published in the Nepal Gazette under the prevailing laws.
(2) Where the prevailing law provides for the filing of any form,
application or any other document or any record to be generated or retained or
secured and or any license or permit or approval or certificate to be issued or
provided or any payment to be made in any Government agency, or public
entity or in any bank or financial institution operating business within the
Nepal, it may be filed, generated, retained or secured or issued or granted in
electronic form or payment may be made in electronic mode of
communication, and, it shall not be denied to provide the legal validity to such
form, application, document record, license, permit or approval, certificate or
payment on the ground of the use of electronic form or electronic
communication mode.', 0, 'The Electronic Transactions Act, 2063 (2008), Chapter-7, Section 39 (Government Documents may be published in electronic form)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:7.1', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:7', 2, 'section', '40', 'To Accept the Document in Electronic Form: (1) Government agency', 'To Accept the Document in Electronic Form', 'or public entity or bank or financial institutions operating business within the
Nepal may also accept any document and payment to be submitted or paid to
them under the prevailing law in electronic form or through any electronic
mode and if such documents and submitted or payment is made, as the case
may be, it shall not be denied to grant legal recognition merely on the ground
that it was accepted electronic form or through any electronic mode.
(2) Notwithstanding anything contained in Sub-section (1) no
Government agency or public entity or bank of financial institution operating
business within the Nepal shall, except in the conditions as prescribed and
government agencies as prescribed, be compelled to accept any document or
22
payment in electronic form, and such an agency or institution shall, except in
the conditions and agency as prescribed, not compel to any other persons to
accept any document in electronic form or the payment through any electronic
form.
(3) For the purpose of Sub-section (1), the provision relating to the
procedure, process and format to be followed shall as prescribed.', 1, 'The Electronic Transactions Act, 2063 (2008), Chapter-7, Section 40 (To Accept the Document in Electronic Form)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:7.2', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:7', 2, 'section', '41', 'Use of Digital Signature in Government Offices: (1) Where it is', 'Use of Digital Signature in Government Offices', 'required that the concerned person shall have to affix his/her signature in any
document or record for verification of such document or record to be
transmitted or issued by any Government agency or public entity or bank or
financial institution operating business within the Nepal or to be accepted by
such agency or institution then, Government of Nepal may, if it thinks
appropriate, make a provision to use digital signature instead of such a
signature.
(2) Notwithstanding anything contained elsewhere in this Act,
Government of Nepal may, for the purpose of the provision made in Sub-
section (1), prescribe additional security procedure for the verification and
authentication of such digital signature.
(3) Provisions regarding the Certifying Authority and Digital
Signature Certificate to be used by the government agency or entity referred to
in Sub-section (1), shall be as prescribed.', 2, 'The Electronic Transactions Act, 2063 (2008), Chapter-7, Section 41 (Use of Digital Signature in Government Offices)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:8', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', NULL, 1, 'chapter', 'Chapter –8', 'Chapter –8', NULL, NULL, 8, 'The Electronic Transactions Act, 2063 (2008), Chapter –8', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:8.0', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:8', 2, 'section', '42', 'Liability of Network Service Providers: Intermediaries providing their', 'Liability of Network Service Providers', 'services as network service providers shall undertake the following liabilities in
regard to such service provided by them:
(a) Liabilities referred to in the agreement made with the subscriber in
regard to service provision,.
23
(b) Liabilities referred to in the license of network service providers, and,
(c) Any such other liability as prescribed.', 0, 'The Electronic Transactions Act, 2063 (2008), Chapter –8, Section 42 (Liability of Network Service Providers)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:8.1', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:8', 2, 'section', '43', 'Network Service Provider not to be Liable: Notwithstanding anything', 'Network Service Provider not to be Liable', 'contained in Section 42, no network service provider shall be liable to bear any
criminal or civil liability arising from any fact or statement mentioned or
included in the information or data of the third party made available in
electronic form by him/her merely on the ground that he/she has made
available the access to such information or data.
Provided that, such a person or institution providing network service
shall not be relieved from such liability, if he/she has made available access to
such information or data with the knowledge that any fact or statement
mentioned or included in such information or data contravene this Act or Rules
framed hereunder.
Explanation: For the purpose of this section" Third Party" means a net work
service provider who provides service as intermediary and any person over
whom there is no control of the network service provider.', 1, 'The Electronic Transactions Act, 2063 (2008), Chapter –8, Section 43 (Network Service Provider not to be Liable)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', NULL, 1, 'chapter', 'Chapter -9', 'Chapter -9', NULL, NULL, 9, 'The Electronic Transactions Act, 2063 (2008), Chapter -9', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9.0', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9', 2, 'section', '44', 'To Pirate, Destroy or Alter computer source code: When computer', 'To Pirate, Destroy or Alter computer source code', 'source code is required to be kept as it is position for the time being the
prevailing law, if any person, knowingly or with malafide intention, pirates,
destroys, alters computer sources code to be used for any computer, computer
programme, computer system or computer network or cause, other to do so,
he/she shall be liable to the punishment with imprisonment not exceeding three
years or with a fine not exceeding two hundred thousand Rupees or with both.
Explanation: For the purpose of this section "computer source code" means
the listing of programmes, computer command, computer design and layout
and programme analysis of the computer resource in any form.
24', 0, 'The Electronic Transactions Act, 2063 (2008), Chapter -9, Section 44 (To Pirate, Destroy or Alter computer source code)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9.1', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9', 2, 'section', '45', 'Unauthorized Access in Computer Materials: If any person with an', 'Unauthorized Access in Computer Materials', 'intention to have access in any programme, information or data of any
computer, uses such a computer without authorization of the owner of or the
person responsible for such a computer or even in the case of authorization,
performs any act with an intention to have access in any programme,
information or data contrary to from such authorization, such a person shall be
liable to the punishment with the fine not exceeding Two Hundred Thousand
Rupees or with imprisonment not exceeding three years or with both depending
on the seriousness of the offence.', 1, 'The Electronic Transactions Act, 2063 (2008), Chapter -9, Section 45 (Unauthorized Access in Computer Materials)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9.2', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9', 2, 'section', '46', 'Damage to any Computer and Information System: If any person', 'Damage to any Computer and Information System', 'knowingly and with a mala fide intention to cause wrongful loss or damage to
any institution destroys, damages, deletes, alters, disrupts any information of
any computer source by any means or diminishes value and utility of such
information or affects it injuriously or causes any person to carryout such an
act, such a person shall be liable to the punishment with the fine not exceeding
two thousand Rupees and with imprisonment not exceeding three years or with
both.', 2, 'The Electronic Transactions Act, 2063 (2008), Chapter -9, Section 46 (Damage to any Computer and Information System)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9.3', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9', 2, 'section', '47', 'Publication of illegal materials in electronic form: (1) If any person', 'Publication of illegal materials in electronic form', 'publishes or displays any material in the electronic media including computer,
internet which are prohibited to publish or display by the prevailing law or
which may be contrary to the public morality or decent behavior or any types
of materials which may spread hate or jealousy against anyone or which may
jeopardize the harmonious relations subsisting among the peoples of various
castes, tribes and communities shall be liable to the punishment with the fine
not exceeding One Hundred Thousand Rupees or with the imprisonment not
exceeding five years or with both.
(2) If any person commit an offence referred to in Sub-section (1)
time to time he/she shall be liable to the punishment for each time with one and
one half percent of the punishment of the previous punishment.
25', 3, 'The Electronic Transactions Act, 2063 (2008), Chapter -9, Section 47 (Publication of illegal materials in electronic form)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9.4', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9', 2, 'section', '48', 'Confidentiality to Divulge: Save otherwise provided for in this Act or Rules', 'Confidentiality to Divulge', 'framed hereunder or for in the prevailing law, if any person who has an access
in any record, book, register, correspondence, information, documents or any
other material under the authority conferred under this Act or Rules framed
hereunder divulges or causes to divulge confidentiality of such record, books,
registers, correspondence, information, documents or materials to any
unauthorized person, he/she shall be liable to the punishment with a fine not
exceeding Ten Thousands Rupees or with imprisonment not exceeding two
years or with both, depending on the degree of the offence.', 4, 'The Electronic Transactions Act, 2063 (2008), Chapter -9, Section 48 (Confidentiality to Divulge)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9.5', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9', 2, 'section', '49', 'To inform False statement: If any person with an intention to obtain a', 'To inform False statement', 'license from Certifying Authority under this Act or with any other intention
either to Controller or with an intention to obtain Digital Signature Certificate
or with any other intention conceals statement knowingly or lies any statement
to be submitted to the Certifying Authority any false statements shall be liable
to the punishment with a fine not exceeding One Hundred Thousands rupees
or with an imprisonment not exceeding two years or with both.', 5, 'The Electronic Transactions Act, 2063 (2008), Chapter -9, Section 49 (To inform False statement)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9.6', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9', 2, 'section', '50', 'Submission or Display of False License or Certificates: (1) If any', 'Submission or Display of False License or Certificates', 'person who works as a Certifying Authority without a license issued by the
Controller under this Act, shall be liable to the punishment with a fine not
exceeding one hundred thousands Rupees or with an imprisonment not
exceeding two years or with both, depending on seriousness of the offence.
(2) Any person without obtaining a license from the Certifying
Authority publishes a fake license or false statement in regard to license or
provides to any person by any other means, shall be liable to the punishment
not exceeding one hundred thousand Rupees in the case where the act referred
to in Sub-section (1) has not been accomplished by such a person.
(3) If any person publishes or otherwise makes available a certificate
to any other person by any means knowingly that a certificate is not issued by
the Certifying Authority referred to in such a certificate or the subscriber listed
in such certificate has not accepted the certificate or such a certificate is already
26
suspended or revoked, shall be liable to the punishment with a fine not
exceeding one hundred thousands Rupees or with an imprisonment not
exceeding two years or with both.
Provided that, if such a certificate suspended or revoked is published or
provided for the purpose of verification of the Digital Signature before it was
suspended or revoked, it shall not be deemed to have been committed an
offence under this Sub-section.', 6, 'The Electronic Transactions Act, 2063 (2008), Chapter -9, Section 50 (Submission or Display of False License or Certificates)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9.7', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9', 2, 'section', '51', 'Non-submission of Prescribed Statements or Documents: (1) If any', 'Non-submission of Prescribed Statements or Documents', 'person responsible to submit any statement, document or report to the
Controller or Certifying Authority under this Act or Rules framed hereunder,
fails to submit such statement, document, or report within the specified time
limit, such a person shall be liable to the punishment with a fine not exceeding
fifty thousands Rupees.
(2) Any person who fails to maintain duly any book, register, records
or account and in a secured manner to be maintained duly and in a secured
manner under this Act or Rules framed hereunder shall be liable to the
punishment with a fine not exceeding fifty thousands Rupees.', 7, 'The Electronic Transactions Act, 2063 (2008), Chapter -9, Section 51 (Non-submission of Prescribed Statements or Documents)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9.8', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9', 2, 'section', '52', 'To commit computer fraud: If any person, with an intention to commit any', 'To commit computer fraud', 'fraud or any other illegal act, creates, publishes or otherwise provides digital
signature certificate or acquires benefit from the payment of any bill, balance
amount of any one''s account, any inventory or ATM card in connivance of or
otherwise by committing any fraud, amount of the financial benefit so acquired
shall be recovered from the offender and be given to the person concerned and
such an offender shall be liable to the punishment with a fine not exceeding one
hundred thousand Rupees or with an imprisonment not exceeding two years or
with both.', 8, 'The Electronic Transactions Act, 2063 (2008), Chapter -9, Section 52 (To commit computer fraud)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9.9', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9', 2, 'section', '53', 'Abetment to commit computer related offence: A person who abets', 'Abetment to commit computer related offence', 'other to commit an offence relating to computer under this Act or who attempts
or is involved in the conspiracy to commit such an offence shall be liable to the
27
punishment with a fine not exceeding fifty thousand Rupees or with
imprisonment not exceeding six months or with both, depending on the degree
of the offence.', 9, 'The Electronic Transactions Act, 2063 (2008), Chapter -9, Section 53 (Abetment to commit computer related offence)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9.10', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9', 2, 'section', '54', 'Punishment to the Accomplice: A person who assists others to commit', 'Punishment to the Accomplice', 'any offence under this Act or acts as accomplice, by any means shall be liable
to one half of the punishment for which the principal is liable.', 10, 'The Electronic Transactions Act, 2063 (2008), Chapter -9, Section 54 (Punishment to the Accomplice)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9.11', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9', 2, 'section', '55', 'Punishment in an offence committed outside Nepal: Notwithstanding', 'Punishment in an offence committed outside Nepal', 'anything contained in the prevailing laws, if any person commits any act which
constitutes an offence under this Act and which involves the computer,
computer system or computer network system located in Nepal, even though
such an act is committed while residing outside Nepal, a case may be filed
against such a person and shall be punished accordingly.', 11, 'The Electronic Transactions Act, 2063 (2008), Chapter -9, Section 55 (Punishment in an offence committed outside Nepal)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9.12', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9', 2, 'section', '56', 'Confiscation: Any computer, computer system, floppy, compact disks, tape', 'Confiscation', 'drivers, softwares or any other accessory devices used to commit any act
deemed to be an offence relating to computer under this Act shall be liable to
confiscation.', 12, 'The Electronic Transactions Act, 2063 (2008), Chapter -9, Section 56 (Confiscation)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9.13', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9', 2, 'section', '57', 'Offences Committed by a corporate body: (1) If any act is done by a', 'Offences Committed by a corporate body', 'corporate body which deems an offence under this Act, such an offence shall
be deemed to have been committed by a person who was responsible as chief
for the operation of the corporate body at the time of committing such an
offence.
Provided that, if the person who was responsible as a chief for the
operation of such a corporate body proves that such an offence was committed
without his/her knowledge or that he/she exercised all reasonable efforts to
prevent such an offence, he/she shall not be liable to the guilty.
(2) Notwithstanding anything contained in Sub-section (1), if it is
proved that any offence under this Act committed by a corporate body with the
consent or in knowledge or by the reason of negligence of a director, manager,
secretary or any other responsible person of such corporate body, such an
28
offence shall be deemed to have been committed by such a corporate body and
by a director, manager, secretary or other responsible person of such a
corporate body.', 13, 'The Electronic Transactions Act, 2063 (2008), Chapter -9, Section 57 (Offences Committed by a corporate body)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9.14', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9', 2, 'section', '58', 'Other Punishment: If any violation of this Act or Rules framed hereunder', 'Other Punishment', 'has been committed, for which no penalty has been separately provided, such a
violator shall be liable to the punishment with a fine not exceeding fifty
thousand Rupees, or with an imprisonment not exceeding six months or with
both.', 14, 'The Electronic Transactions Act, 2063 (2008), Chapter -9, Section 58 (Other Punishment)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9.15', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:9', 2, 'section', '59', 'No Hindrance to Punish Under the Laws prevailing: If any act deemed to be', 'No Hindrance to Punish Under the Laws prevailing', 'an offence under this Act shall also be deemed to be another offence under the
laws prevailing, it shall not be deemed to have been hindered by this Act to file
a separate case and punish accordingly.', 15, 'The Electronic Transactions Act, 2063 (2008), Chapter -9, Section 59 (No Hindrance to Punish Under the Laws prevailing)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:10', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', NULL, 1, 'chapter', 'Chapter-10', 'Chapter-10', NULL, NULL, 10, 'The Electronic Transactions Act, 2063 (2008), Chapter-10', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:10.0', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:10', 2, 'section', '60', 'Constitution of a Tribunal: (1) Government of Nepal shall, in order to', 'Constitution of a Tribunal', 'initiate the proceedings and adjudicate the offences concerning computer as
referred to in Chapter -9, constitute a three member Information Technology
Tribunal consisting of one member each of law, Information Technology and
Commerce by notification in the Nepal Gazette from amongst the persons who
are qualified under section 60.
(2) The Law Member shall be the chairperson of the Tribunal.
(3) The Tribunal shall exercise its jurisdiction as prescribed.
(4) Any person aggrieved by an order or a decision made by Tribunal
may appeal to the Appellate Tribunal within thirty five days from the date of
such order or decision, as the case may be.', 0, 'The Electronic Transactions Act, 2063 (2008), Chapter-10, Section 60 (Constitution of a Tribunal)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:10.1', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:10', 2, 'section', '61', 'Qualification of the Member of the Tribunal: (1) Any person who has', 'Qualification of the Member of the Tribunal', 'the knowledge in information technology and, who is or who has been or who
29
is qualified to be a judge in the District Court, shall be eligible to be a law
member of the Tribunal.
(2) A Nepalese citizen who holds at least master degree in computer
science or information technology and who has at least three years experience
in the field of electronic transactions, information technology or electronic
communication, shall be eligible to be a information technology member of the
Tribunal.
(3) A Nepali citizen who holds at least master degree in management
or commerce and who has specialization in the field of electronic transaction
and who has at least three years experience in the related field shall be eligible
to be a commerce member of the Tribunal.', 1, 'The Electronic Transactions Act, 2063 (2008), Chapter-10, Section 61 (Qualification of the Member of the Tribunal)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:10.2', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:10', 2, 'section', '62', 'Terms of office, remuneration and conditions of service of the', 'Terms of office, remuneration and conditions of service of the', 'Member of Tribunal: (1) The term of office of a member of the Tribunal
shall be of five years and he/she shall be eligible for reappointment.
(2) Remuneration and the terms and conditions of the service of a
Member of the Tribunal shall as prescribed.
(3) Every Member of the Tribunal shall, before assuming his/her
office, take the oath of his/her office and secrecy before the Chief Judge of
Appellate Court in a format and in a manner as prescribed.', 2, 'The Electronic Transactions Act, 2063 (2008), Chapter-10, Section 62 (Terms of office, remuneration and conditions of service of the)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:10.3', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:10', 2, 'section', '63', 'Circumstances under which office shall be fallen vacant and filling', 'Circumstances under which office shall be fallen vacant and filling', 'up of vacancy: (1) Office of a Member of the Tribunal shall be fallen
vacant in the following circumstances:
a) On expiry of terms of office,
b) On attainment of sixty three years of age.
c) On death,
d) If one tenders resignation,
e) If one is convicted by a court on any criminal offence involving
moral turpitude, or
30
f) If it is proved that one has misbehavior or has become
incompetent to perform one''s duty while making an inquiry by
Government of Nepal on the charge that one has misbehavior
against one''s office or has become incompetent to perform one''s
duty.
Provided that, a Member of the Tribunal charged under this
Clause shall given a reasonable opportunity to defense his/her case.
(2) Notwithstanding anything contained in Clause (f), if the
law member of the Tribunal is a sitting judge, while making such an
inquiry, it shall be done in accordance with the prevailing law
concerning his/her terms of service.
(3) The procedure of inquiry, for the purpose of Clause (f) of
Sub-section Sub-section (1), shall be as prescribed.
(4) Government of Nepal shall, in case of vacancy of the
office of any member of Tribunal under Sub-section (1), fulfill such
vacancy from among the persons who are qualified under section 61 for
remaining term of office of such a member.', 3, 'The Electronic Transactions Act, 2063 (2008), Chapter-10, Section 63 (Circumstances under which office shall be fallen vacant and filling)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:10.4', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:10', 2, 'section', '64', 'Staff of the Tribunal: (1) Government of Nepal shall make available', 'Staff of the Tribunal', 'necessary staff to the Tribunal to perform its functions.
(2) Other provisions regarding the staff of the Tribunal shall be as
prescribed.', 4, 'The Electronic Transactions Act, 2063 (2008), Chapter-10, Section 64 (Staff of the Tribunal)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:10.5', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:10', 2, 'section', '65', 'Procedures to be followed by the Tribunal: The Tribunal shall, while', 'Procedures to be followed by the Tribunal', 'initiating proceedings and adjudicating the case under section 60, shall follow
the procedures as prescribed.', 5, 'The Electronic Transactions Act, 2063 (2008), Chapter-10, Section 65 (Procedures to be followed by the Tribunal)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:11', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', NULL, 1, 'chapter', 'Chapter-11', 'Chapter-11', NULL, NULL, 11, 'The Electronic Transactions Act, 2063 (2008), Chapter-11', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:11.0', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:11', 2, 'section', '66', 'Establishment and formation of the Appellate Tribunal: (1)', 'Establishment and formation of the Appellate Tribunal', 'Government of Nepal shall, in order to hear the appeal against the order or the
31
decision made by the Tribunal and to hear the appeal against the decision or
order made by the Controller or by the Certifying Authority, as the case may
be, under this Act, by notification in the Nepal Gazette, establish a three
member Information Technology Appellate Tribunal consisting of one member
each of law, information technology and commerce from among the persons
who are qualified under section 67,
(2) Law Member shall be the chairperson of the Appellate Tribunal.
(3) Exercise of the jurisdiction of Appellate Tribunal shall be as
prescribed.', 0, 'The Electronic Transactions Act, 2063 (2008), Chapter-11, Section 66 (Establishment and formation of the Appellate Tribunal)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:11.1', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:11', 2, 'section', '67', 'Qualification of the Member of Appellate Tribunal: (1) A person who', 'Qualification of the Member of Appellate Tribunal', 'has the knowledge in information technology and who is or who has already
been or who is qualified to be a judge in the Appellate Court shall be eligible to
be a law member of the Appellate Tribunal.
(2) A Nepali citizen who holds at least master degree in computer
science or information technology and who has at least five years experience in
the electronic transaction, information technology or electronic communication
shall be eligible to be an information technology member of the Tribunal.
(3) A Nepali citizen who holds at least master degree in management
or commerce and who has specialization in the field of electronic transactions
and who has at least five years experience in the relevant field, shall be eligible
to be a commerce member.', 1, 'The Electronic Transactions Act, 2063 (2008), Chapter-11, Section 67 (Qualification of the Member of Appellate Tribunal)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:11.2', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:11', 2, 'section', '68', 'Terms of Office, Remuneration and Terms & Conditions of the', 'Terms of Office, Remuneration and Terms & Conditions of the', 'service of the Member of Appellate Tribunal: (1) The term of office of
the member of the Appellate Tribunal shall be of five years and he/she shall be
eligible for reappointment.
(2) Remuneration and other terms and conditions of the services of
the members of the Appellate Tribunal shall as prescribed.
32
(3) A member of the Appellate Tribunal shall, before assuming
his/her office after appointment, take the oath of his/her office and secrecy
before the Chief Justice of the Supreme Court.', 2, 'The Electronic Transactions Act, 2063 (2008), Chapter-11, Section 68 (Terms of Office, Remuneration and Terms & Conditions of the)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:11.3', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:11', 2, 'section', '69', 'Conditions of Vacancy of Office and filling up of such Vacancy: (1)', 'Conditions of Vacancy of Office and filling up of such Vacancy', 'Office of a Member of Appellate Tribunal shall be fallen vacant in the
following circumstances:
(a) On expiry of terms of office,
(b) On attainment of sixty three years age,
(c) On death,
(d) If one tenders resignation
(e) If one is convicted by a court on any criminal offence involving
moral turpitude, and,
(f) If it is proved that one has misbehavior or has become
incompetent to perform one''s duty, while making an inquiry by
Government of Nepal on the charge that one has misbehavior
against one''s office or has become incompetent to perform one''s
duty.
Provided that, a member of the Appellate Tribunal charged under this
Clause shall be given a reasonable opportunity to defense his/her case.
(2) Notwithstanding anything contained in Clause (f), if the law
member of the Tribunal is a sitting judge, while making such an inquiry, it shall
be done in accordance with the prevailing law concerning his/her terms of
service.
(3) The procedure of inquiry, for the purpose of Clause (f) of Sub-
section (1), shall as prescribed.
(4) Government of Nepal shall, in case of vacancy of the office of
any member of Tribunal under Sub-section (1), fulfill such vacancy from
33
amongst the persons who are qualified under section 67 for remaining term of
office of such a member.', 3, 'The Electronic Transactions Act, 2063 (2008), Chapter-11, Section 69 (Conditions of Vacancy of Office and filling up of such Vacancy)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:11.4', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:11', 2, 'section', '70', 'Staff of the Appellate Tribunal: (1) Government of Nepal shall make', 'Staff of the Appellate Tribunal', 'available necessary staff to Appellate Tribunal to perform its functions.
(2) Other provisions regarding the staff of the Appellate Tribunal
shall be as prescribed.', 4, 'The Electronic Transactions Act, 2063 (2008), Chapter-11, Section 70 (Staff of the Appellate Tribunal)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:11.5', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:11', 2, 'section', '71', 'Procedures to be followed by the Appellate Tribunal: The Tribunal', 'Procedures to be followed by the Appellate Tribunal', 'shall, while initiating proceedings and adjudicating the appeal filed before it,
shall follow the procedures as prescribed.', 5, 'The Electronic Transactions Act, 2063 (2008), Chapter-11, Section 71 (Procedures to be followed by the Appellate Tribunal)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', NULL, 1, 'chapter', 'Chapter-12', 'Chapter-12', NULL, NULL, 12, 'The Electronic Transactions Act, 2063 (2008), Chapter-12', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12.0', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12', 2, 'section', '72', 'Provision may be made by an Agreement: The parties involved to the', 'Provision may be made by an Agreement', 'work for creating, transmitting, receiving, storage or for processing through
any other means, of any electronic record may make the provision by an
agreement, not to apply any or all provisions of the Chapter 3 or to alter some
of the provisions referred to in the said Chapter in course of their business and
may make the provisions to regulate their activities accordingly.', 0, 'The Electronic Transactions Act, 2063 (2008), Chapter-12, Section 72 (Provision may be made by an Agreement)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12.1', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12', 2, 'section', '73', 'Government of Nepal may issue Directives: Government of Nepal may, in', 'Government of Nepal may issue Directives', 'regard to the implementation of this Act, issue necessary directives to the
Controller or Certifying Authority, and in such a case, it shall be a duty of the
Controller or Certifying Authority, as the case may be, to comply with such
directives.', 1, 'The Electronic Transactions Act, 2063 (2008), Chapter-12, Section 73 (Government of Nepal may issue Directives)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12.2', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12', 2, 'section', '74', 'Time Limitation to file a Complaint: If a violation of this Act or Rules', 'Time Limitation to file a Complaint', 'framed hereunder has been occurred or if any act deemed to be an offence
under this Act has been committed, first information report in regard to such a
violation or an offence shall have to file within thirty five days of the
information on which such a violation has been occurred or an offence has
been committed.
34', 2, 'The Electronic Transactions Act, 2063 (2008), Chapter-12, Section 74 (Time Limitation to file a Complaint)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12.3', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12', 2, 'section', '75', 'Government of Nepal to be a Plaintiff: (1) Any case deemed to be an', 'Government of Nepal to be a Plaintiff', 'offence under this Act shall be initiated by Government of Nepal as plaintiff
and such a case shall be deemed have been included in Schedule 1 of the
Government Cases Act, 1992 (2049).
(2) While conducting investigation of a case under Sub-section (1),
the police has to take assistance of the Controller or other concerned expert, as
the case may be.', 3, 'The Electronic Transactions Act, 2063 (2008), Chapter-12, Section 75 (Government of Nepal to be a Plaintiff)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12.4', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12', 2, 'section', '76', 'Compensation to be Recovered: If any loss or damage has been caused to', 'Compensation to be Recovered', 'any person by the reason of offence committed under this Act, the
compensation of such loss or damage shall also be recovered from the offender.', 4, 'The Electronic Transactions Act, 2063 (2008), Chapter-12, Section 76 (Compensation to be Recovered)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12.5', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12', 2, 'section', '77', 'This Act shall not Apply: (1) Notwithstanding anything contained elsewhere', 'This Act shall not Apply', 'in this Act, this Act shall not be applied in the following matters:
(a) Negotiable Instruments as referred to in the Negotiable
Instruments Act, 2034 (1977).
(b) Deed of will, deed of mortgage, bond, deed of conveyance,
partition or any such deed related with transfer of the title in any
immovable property,
(c) Any other document which demonstrates title or ownership in
any immovable property,
(d) Power of Attorney, statement of claim, statement of defense or
any such other documents as may be used in courts proceedings,
(e) Statement of claim, counter-claim, statement of defense or any
such other document as may be submitted in writing in the
proceedings of any Arbitration,
(f) Documents as prescribed by the prevailing law that requires not
to retain in electronic form.
35
(2) Notwithstanding anything contained in Sub-section (1)
Government of Nepal may, by notification in the Nepal Gazette, alter the
documents referred to in Sub-section (1).', 5, 'The Electronic Transactions Act, 2063 (2008), Chapter-12, Section 77 (This Act shall not Apply)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12.6', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12', 2, 'section', '78', 'Power to Frame Rules: Government of Nepal may in order to fulfill the', 'Power to Frame Rules', 'objective of this Act, frame necessary Rules.', 6, 'The Electronic Transactions Act, 2063 (2008), Chapter-12, Section 78 (Power to Frame Rules)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12.7', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12', 2, 'section', '79', 'To Frame and Enforce the Directives: Government of Nepal may, in', 'To Frame and Enforce the Directives', 'order to achieve the objective of this Act, frame and enforce necessary
directives, subject to this Act and Rules framed hereunder.', 7, 'The Electronic Transactions Act, 2063 (2008), Chapter-12, Section 79 (To Frame and Enforce the Directives)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12.8', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac', 'doc_the_electronic_transactions_act_2063_2008_2063_electronic_transac:12', 2, 'section', '80', 'Effect of inoperativeness of The Electronic Transactions Ordinance,', 'Effect of inoperativeness of The Electronic Transactions Ordinance,', '2063 (2008): With the Electronic Transactions Ordinance, 2063 (2008) being
inoperative, unless a different intention appears, the inoperativeness shall not,
(a) Revive anything not prevailing or existing at the time, at which
the Ordinance became inoperative,
(b) Affect the matter in operation as per the Ordinance or anything
duly done or any punishment suffered there under,
(c) Affect any right, privilege, obligation or liability acquired,
accrued or incurred under the Ordinance,
(d) Affect any penalty, punishment or forfeiture incurred under the
Ordinance,
(e) Affect any action or remedy made or taken in respect of any such
right, privilege, obligation, liability, penalty or punishment as
aforesaid; and any such legal proceeding or remedy may be
instituted, continued or enforced as if the Ordinance were in
force.
36', 8, 'The Electronic Transactions Act, 2063 (2008), Chapter-12, Section 80 (Effect of inoperativeness of The Electronic Transactions Ordinance,)', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:0', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', NULL, 1, 'preamble', 'Preamble', 'Introductory matter', NULL, 'www.lawcommission.gov.np 
1 
 
The Environment Protection Act, 2019 (2076)  
Date of Authentication  
2076.06.24 ( 11th October , 2019 ) 
Act No. 9 of the year 2019 (2076)  
An Act Made to Amend and Consolidate Law Relating to  Environment  
Preamble:  
Whereas, it is expedient to amend and consolidate the prevailing law on 
environmental protection in order to protect the fundamental right of each citizen to  live 
in a clean and healthy environment , provide the victim with compensat ion by the polluter 
for any damage resulting from environmental pollution or degradation, maintain a proper 
balance between environment and development, mitigate adverse environmental impacts 
on environment and biodiversity and face the challenges posed by  climate change;  
Now, therefore, the Federal Parliament has made this Act .', 0, 'The Environment Protection Act, 2019 (2076), Preamble', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:1', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', NULL, 1, 'chapter', 'Chapter -1', 'Chapter -1', NULL, NULL, 1, 'The Environment Protection Act, 2019 (2076), Chapter -1', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:1.0', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:1', 2, 'section', '1', 'Short title and commencement: (1) This Act  may be cited as the  "Environment', 'Short title and commencement', 'Protection Act,  2019 (2076).  
(2) This Act shall commence on the eighth day of the date on which it 
is authenticated.', 0, 'The Environment Protection Act, 2019 (2076), Chapter -1, Section 1 (Short title and commencement)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:1.1', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:1', 2, 'section', '2', 'Definitions:  Unless the subject or the context otherwise requires, in this Act:', 'Definitions', '(a) “Adaptation” means the prevention or mitigation of further loss and 
damage upon projecting potential impacts and risks of climat e 
change.  
(b) “Emission” means emission of greenhouse gas or any other gas, 
smoke or dust on the environment from any certain area in a certain 
period.  
(c) “Fund” means the environment protection fund referred to in 
Section 31.  
(d) “Climate change”  means a gradual change of climate of the earth 
which is attributed directly or indirectly to human activity that alters 
the composition of the global atmosphere and which is in addition 
www.lawcommission.gov.np 
2 
 
to natural climate variability observed over comparable time 
periods.  
(e) “Climate change management” means the mitigation or adaptation 
of problems arising as a result of climate change, and this term also 
includes a totality of acts including policies, strategies, making 
institutional mechanisms, provision of finance, cap acity building.  
(f) “Hazardous substance” means any substance enlisted in the Basel 
Convention on the Control of Transboundary Movement  of 
Hazardous Wastes and  Their Disposal, and  explosives, 
inflammable, perpetual and substances with corrosive 
properties and substances that are intended to be in use for the 
first time upon be processed from raw materials not re -used 
which cause adverse impact on the environment.  
(g) "Biological diversity" means eco -system diversity, species diversity 
and genetic diversity.  
(h) “Prescribed” or “as prescribed” means prescribed or as prescribed 
in the rules framed under this Act.  
(i) “Mitigation” means reduction or prevention of emission of 
greenhouse gas as a result of human activity.  
(J) "Pollution" means the activities that  significantly degrade, damage 
the environment or harm the beneficial or useful purpose of the 
environment, by changing the environment directly or indirectly as 
a result of wastes, chemical, heat, noise, electrical, electro -magnetic 
wave or radioactive ra y. 
(k) "Proposal" means a proposal prepared in regard to the carrying out 
of such development work, physical activity that may bring about 
change in the existing environmental conditions or any plan, project 
or programme which changes the land use.  
(l) "Proponent" means a person or governmental, semi -governmental 
or non -governmental agency or institution that makes application 
for the approval of a proposal or that has go t approval for the 
implementation of the proposal.   
(m) "Initial environmental examination" means an analytical study or 
evaluation to be conducted to ascertain as to whether, in 
www.lawcommission.gov.np 
3 
 
implementing a proposal, the proposal does have significant adverse 
impacts on the environment or not, and with respect to the measur es 
to be adopted for avoiding or mitigating such impacts by any means.  
(n) “Supplementary environmental impact assessment” means an 
environmental impact assessment to be made again vis -à-vis a 
proposal submitted in order to make revision partly in physica l 
infrastructure, design or form, transfer or alter a structure, add a 
forest area or increase the project capacity on the environmental 
impact assessment proposal which has been already accepted.  
(o) “Council” means the national council on environment pro tection 
and climate change management referred to in Section 32.  
(p) “Provincial Ministry” means the Ministry of a Provincial 
Government responsible for environment related matter.  
(q) "Wastes" means the liquid, solid, gas, slurry, smoke, dust, radiated 
element or substance or similar other materials disposed in a manner 
to degrade the environment.  
(r) "Ministry" means the Ministry of Forest and Environment of the 
Government of Nepal.  
(s) "National heritage" means any such object, physical structure, site, 
plant or animal related with the environment available within Nepal 
as is likely to be important to the human being from natural, cultural, 
historical, archaeological, scientific, spiritu al, aesthetic or social 
point of view.  
(t) "Environment"  means the interaction and inter -relationship among 
the components of natural, cultural and social systems, economic 
and human activities and their components . 
(u) “Environmental study report” means a report prepared with respect 
to the brief environmental study, initial environmental examination 
or environmental impact assessment.  
(v) "Environmental impact assessment" means detailed study and 
evaluation to be made to ascertain as to whether, in imple menting a 
proposal, the proposal does have significant adverse impacts on the 
environment or not, and as to the measures to be adopted for 
avoiding or mitigating such impacts.  
www.lawcommission.gov.np 
4 
 
(w) “Department” means the Department of Environment under the 
Ministry.  
(x) “Concerned body” means the body referred to in sub -section (2) of 
Section 3  which is responsible for taking action and decision on the 
environmental study report.  
(y) “Brief environmental study” means a study to be made briefly as to 
the measures to be adopte d for avoiding or mitigating the adverse 
effects on the environment as a result of implementation of any 
proposal.  
(z) “Local Level” means a Rural Municipality or Municipality.', 1, 'The Environment Protection Act, 2019 (2076), Chapter -1, Section 2 (Definitions)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', NULL, 1, 'chapter', 'Chapter -2', 'Chapter -2', NULL, NULL, 2, 'The Environment Protection Act, 2019 (2076), Chapter -2', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2.0', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2', 2, 'section', '3', 'Environmental study report to be prepared: (1) A proponent shall prepare such', 'Environmental study report to be prepared', 'an environmental study report of such a proposal as may be prescribed.  
  (2) The environmental study report prepared pursuant to sub -section 
(1) shall, in fulfillment of the process as prescribed, be submitted to the 
follow ing body for approval:  
(a) To the prescribed body , in the case of a brief environmental study 
report or initial environmental examination of a development 
project with national priority, a project to be implemented upon its 
investment being approved by the  Investment Board, a project of 
national pride, a development or construction work or project falling 
under the jurisdiction of the Federation in accordance with the 
prevailing, a project requiring construction work to be done in more 
than one Provinces or  a project specified by the Government of 
Nepal , and to the Ministry in the case of the environmental impact 
assessment,  
(b) To the body prescribed by the concerned Provincial law in the case 
of a proposal relating to development, construction work or proj ect 
pertaining to a matter f alling under the jurisdiction of the Provincial 
Government,  
(c) To the body designated by the concerned local law in the case of a 
brief environmental study report or initial environmental 
www.lawcommission.gov.np 
5 
 
examination report on a proposal relati ng to development, 
construction work or project pertaining to a matter falling under the 
jurisdiction of the Local Level, and  to such body of the Provincial 
Government as prescribed by the Provincial Government in the case 
of an environmental impact assessment report.  
(3) Notwithstanding anything contained in sub -section (1) or (2), 
nothing shall bar the approving of environmental study reports submitted for 
approval at the time of commencement of this Act in accordance with t he legal 
provisions in force at the time of submission of such reports.  
(4) Notwithstanding anything contained elsewhere in this Section, there 
shall not be required an environmental study report for reconstructing as such a 
heritage considered an ancient  monument , in accordance with the law relating to 
ancient monuments.  
(5) In preparing an environmental study report, the proponent shall 
hold, as prescribed, a public hearing as to the proposal.  
(6) Other provisions relating to the submission of an environ mental 
study report shall be as prescribed.', 0, 'The Environment Protection Act, 2019 (2076), Chapter -2, Section 3 (Environmental study report to be prepared)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2.1', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2', 2, 'section', '4', 'Detailed analysis of alternative to be made: (1) The proponent shall make', 'Detailed analysis of alternative to be made', 'detailed analysis  of possible adverse effects on the environment from the 
implementation of such a proposal and various alternatives th at can be adopted for 
mitigation such effects, and recommend the alternative that is appropriate for the 
implementation of the proposal and the grounds and reasons why that alternative 
is implementable.  
  (2) In preparing the environmental study report pur suant to sub -section 
(1), the proponent shall set out, inter alia, the possible short -term, mid -term and 
long-term adverse effects on the environment from the implementation of the 
project and the method and process to be adopted for mitigation thereof.', 1, 'The Environment Protection Act, 2019 (2076), Chapter -2, Section 4 (Detailed analysis of alternative to be made)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2.2', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2', 2, 'section', '5', 'Scoping and work schedule : (1) Prior to preparing the environmental study report', 'Scoping and work schedule', 'of any proposal pursuant to this Act, the scope  of such a proposal,  in the case of a 
brief environmental study and initial environmental examination, and scope and 
work schedule, in the case of an environmental impact assessment shall be 
approved by the concerned body.  
  (2) Other provisions on the scoping and preparation of the work 
schedule referred to sub -section (1) and approval thereof shall be as prescribed.  
www.lawcommission.gov.np 
6', 2, 'The Environment Protection Act, 2019 (2076), Chapter -2, Section 5 (Scoping and work schedule)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2.3', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2', 2, 'section', '6', 'Standards and quality to be maintained: (1) In preparing an environmental', 'Standards and quality to be maintained', 'study report pursuant to this Act, the proponent shall so prepare it in the form as 
prescribed that the standards and quality determined by the Government of Nepal 
are maintained.  
  (2) If the report is submitted contrary to the standards or qualify 
referred to in sub -section (1) or without complying with such standards, the 
consultant w ho has prepared such a report shall not be allowed to prepare an 
environmental study report for a perio d not exceeding five years.', 3, 'The Environment Protection Act, 2019 (2076), Chapter -2, Section 6 (Standards and quality to be maintained)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2.4', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2', 2, 'section', '7', 'Environmental study report to be approved:  (1) If an environmental study', 'Environmental study report to be approved', 'report prepared in the context of the implementation of any proposal pursuant to 
Section 3 is received, the concerned body shall make necessary inquiry into the 
report.  
  (2) The concerned body may form a committee comprising a 
representative of that body, representatives of the relevant bodies concerned with 
the proposal and subject expert as required, to inquire into the environmental study 
report recei ved pursuant to sub -section (1) and furnish advice and suggestions.  
  (3) If, in inquiring into the environmental study report received 
pursuant to sub -section (1), it appears that further environmental study has to be 
made in relation to such a proposal, the concerned body shall give order to the 
proponent to make, or cause to be made, the initial environmental examination in 
the case of the brief environmental study or the environmental impact assessment 
in the case of the brief environmental study.  
  (4) The proponent shall make further study in pursuance of the order 
given pursuant to sub -section (3) and submit a report thereof to the concerned 
body.  
  (5) If, in making inquiry pursuant to this Section, it does not appear that 
the implementation of such a proposal causes significant adverse impacts on the 
environment, the concerned body shall approve such environmental study report, 
upon specifying the terms and conditions to be observed by the proponent, as 
required.  
  (6) Other provisions relating to th e approval of the environmental study 
report shall be as prescribed.  
www.lawcommission.gov.np 
7', 4, 'The Environment Protection Act, 2019 (2076), Chapter -2, Section 7 (Environmental study report to be approved)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2.5', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2', 2, 'section', '8', 'Proposal not to be implemented: No person shall implement, or cause to be', 'Proposal not to be implemented', 'implemented, any proposal without having the environmental study report 
approved pursuant to this Act.', 5, 'The Environment Protection Act, 2019 (2076), Chapter -2, Section 8 (Proposal not to be implemented)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2.6', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2', 2, 'section', '9', 'Strategic environmental analysis:  (1) Prior to the implementation of such policy,', 'Strategic environmental analysis', 'program or project as may be specified by the Government of Nepal by a 
notification in the Nepal Gazette, the strategic environmental analysis shall be 
carried out in relation to  such a policy, program or project.  
  (2) Other provisions relating to the strategic environmental analysis 
shall be as prescribed.', 6, 'The Environment Protection Act, 2019 (2076), Chapter -2, Section 9 (Strategic environmental analysis)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2.7', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2', 2, 'section', '10', 'Environmental management plan:  (1) Prior to the implementation of a proposal,', 'Environmental management plan', 'the proponent shall prepare an environment al management plan as prescribed.  
  (2) In preparing the environmental management plan pursuant to sub -
section (1),  the proponent shall set out, inter alia, which of the measures to mitigate 
environmental adverse impacts will be adopted in the course of bu ilding the 
project and which of such measures will be adopted after the completion, or in the 
course of implementation, of the project.  
  (3) If it does not appear that the measures to mitigate environmental 
adverse impacts set out by the proponent in the environmental management plan  
pursuant to sub -section ( 2) are effective, the concerned body may give necessary 
direction to adopt other effective measures, and the concerned proponent shall bear 
the expenses incurred in the implementation of the direction so given by the 
concerned body.  
  (4) The proponent shall  make a clear action plan for the implementation 
of e nvironmental management plan prepared pursuant to sub -section (1)  and 
implement it accordingly, and submit its progress report to the concerned body in 
every six months after the commencement of the proj ect implementation.  
  (5) In adopting the measures to mitigate environmental adverse impacts 
in the course of implementation of the e nvironmental management plan referred 
to in sub-section (1) , priority shall be given to the operation of the program throug h 
the local community which affected from the implementation of the proposal.', 7, 'The Environment Protection Act, 2019 (2076), Chapter -2, Section 10 (Environmental management plan)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2.8', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2', 2, 'section', '11', 'Supplementary environmental impact assessment to be made:  (1) If it is', 'Supplementary environmental impact assessment to be made', 'required to make some revision in the physical infrastructure, design or form, 
transfer or alter the structure  of any project of which the environmental impact 
assessment report has been approved pursuant to Section 7 , add the forest area or 
www.lawcommission.gov.np 
8 
 
increase the capacity  of the project, the proponent shall make a supplementary 
environmental impact assessment in ord er to ascertain whether the operation of 
such work causes adverse impacts on the environment or not, and whether such 
impacts can be done away with or mitigated by any means or not.  
  (2) The proponent shall, i n order to make the supplementary 
environmental impact assessment pursuant to sub -section (1),  make an application 
to the concerned body, along with an analysis of the reasons for making changes 
in various components of the project and possible adverse impacts on the 
environment from such changes, a comparative table according to environmental 
indicators and other necessary justifications.  
  Provided that where the concerned body has given order to the proponent 
to submit a supplementary environmental impact assessment  report, the proponent 
need not make an application.  
  (3) If the content is found reasonable upon inquiring into the application 
received pursuant to sub -section (2), the concerned body may give permission for 
a supplementary environmental impact assessme nt study as prescribed.  
  (4) Other provisions relating to the supplementary environmental 
impact assessment  shall be as prescribed.', 8, 'The Environment Protection Act, 2019 (2076), Chapter -2, Section 11 (Supplementary environmental impact assessment to be made)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2.9', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2', 2, 'section', '12', 'To make environmental examination after commencement of service: (1) The', 'To make environmental examination after commencement of service', 'Ministry or prescribed body shall, not later t han six months of the date of 
completion of two years of the commencement of production or distribution of the 
service or goods  or of the  implementation of a proposal requiring the 
environmental impact assessment pursuant to this Act , make analysis of the 
adverse impacts  on the environment as a result of the implementation of such a 
proposal, measures adopted to mitigate such impacts, effectiveness of such 
measures, adverse impacts that could not be mitigated or occurrence of any 
unprojected /unforeseen  adverse impacts and maintain  undated records of  the 
environmental examination report.  
  (2) If the Ministry or prescribed body does not see , upon making 
necessary study, in coordination with the concerned body with respect to the 
environmental examination repo rt referred to in sub -section (1), that the measures  
adopted to mitigate the adverse impacts on the environment are not adequate, it 
may give appropriate order to the proponent to do away with or mitigate such 
adverse impacts.  
www.lawcommission.gov.np 
9 
 
  (3) It shall be the duty of  the proponent to implement the order given 
by the Ministry or prescribed body pursuant to sub -section (2).', 9, 'The Environment Protection Act, 2019 (2076), Chapter -2, Section 12 (To make environmental examination after commencement of service)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2.10', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2', 2, 'section', '13', 'Power to prevent : (1) If any person executes a project without having the', 'Power to prevent', 'environmental study report approved pursuant to this Act or contrary to the 
approved environmental study report, the concerned body may immediately 
prevent the project from being executed.  
  (2) Where a project is prevented from being executed pursuant to sub -
section (1) and such prevention results in any harm to the propon ent, the proponent 
shall not be allowed to make a claim of compensation for such harm.  
  (3) Notwithstanding anything contained in sub -section (1), if the 
proponent of the project prevented from being executed gets the environmental 
study report to be app roved pursuant to this Act or makes improvement in the 
project execution in accordance with the approved environmental study report, the 
concerned body may release the prevention made pursuant to sub -section (1).', 10, 'The Environment Protection Act, 2019 (2076), Chapter -2, Section 13 (Power to prevent)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2.11', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:2', 2, 'section', '14', 'Power of the Government of Nepal or Pro vincial Government to make', 'Power of the Government of Nepal or Pro vincial Government to make', 'environmental study:  (1) The Government of Nepal or Provincial Government 
may, on its own, map out  any area or place and make the environmental study of 
that area.  
  (2) The concerned body shall, on the basis of the descriptions  obtained 
from the study referred to in sub -section (1)  shall prepare descriptions as to such 
development, construction works or projects that can be executed in such area in 
the future and work that is not appropriate for execution in such area.  
  (3) The concerned body shall maintain records of the descriptions 
obtained from the study referred to in sub -section (1)  and the descriptions referred 
to in sub -section ( 2). 
  (4) The concerned body shall make public the descriptions referred to 
in this Section, a nd the concerned proponent, body and party concerned shall act 
in consistent therewith.', 11, 'The Environment Protection Act, 2019 (2076), Chapter -2, Section 14 (Power of the Government of Nepal or Pro vincial Government to make)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:3', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', NULL, 1, 'chapter', 'Chapter -3', 'Chapter -3', NULL, NULL, 3, 'The Environment Protection Act, 2019 (2076), Chapter -3', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:3.0', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:3', 2, 'section', '15', 'Control of pollution:  (1) The Government of Nepal may, by a notification in the', 'Control of pollution', 'Nepal Gazette, determine necessary standards for the mitigation or doing away 
with the impacts  of pollution from any motor vehicle, device, equipment, 
www.lawcommission.gov.np 
10 
 
industrial enterprise , hotel, restaurant or ot her place or goods or activity or effects 
from the disposal or emission of any hazardous substance.  
  (2) No person shall create pollution in such a manner as to cause 
significant adverse impacts on the public life, public health and environment or 
do, or cause to be done, any act contrary to the standards determined by the 
Government of Nepal pursuant to sub -section (1).  
(3) No person or group that visits a mountain or high hill area  for 
expedition, trekking, sightseeing or any other purpose shall do, or c ause to be 
done, any such act that may cause adverse impacts on the environment by making 
pollution contrary to the standards determined by the Government of Nepal.  
(4) If it appears that any one has caused adverse impacts on the 
environment by doing  any a ct contrary to sub -section (1) or (2), the Department 
may give direction to the relevant person, group or institution to take measures for 
mitigation of or doing away with  pollution, prescribe necessary terms or prohibit 
the carrying out of any act in a ma nner to cause adverse impacts on the 
environment .   
  (5) If it appears that the use of any substance, fuel, tool, machine or 
equipment has caused or is likely to cause significant adverse impacts on the 
environment, the Department may request the Ministry  for necessary action.  
  (6) If a request is received from the Department pursuant to sub -section 
(5), the Ministry may, in necessary consultation with the concerned body or other 
stakeholders, prevent  the use of such substance, fuel, tool , device  or equip ment or 
the production, import, sale, distribution or storage of such materials, and a notice 
on such prevention shall be published in the Nepal Gazette.  
  (7) The Department shall, from time to time, carry out monitoring and 
evaluation as to compliance with the standards determined pursuant to sub -section 
(1). 
  (8) Other provisions relating to the control of pollution shall be as 
prescribed.', 0, 'The Environment Protection Act, 2019 (2076), Chapter -3, Section 15 (Control of pollution)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:3.1', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:3', 2, 'section', '16', 'Export and import of hazardous substance : (1) No hazardous substance of any', 'Export and import of hazardous substance', 'kind shall be imported into Nepal.  
  (2) Notwithstanding anything contained in sub-section (1) , any such 
specific kind of hazardous substance that does not cause significant adverse 
www.lawcommission.gov.np 
11 
 
impacts on the human health and environment as specified by the Government of 
Nepal by a notification in the Nepal Gazette may be impor ted. 
  (3) A producer of a hazardous substance or person or body established 
under prevailing law may export hazardous substance by obtaining permission 
from the Ministry.  
  (4) Grounds, criteria for issuance of, and other provisions relating to, 
permission to export a hazardous substance pursuant to sub -section (3) shall be as 
prescribed.  
  (5) A hazardous substance imported contrary to this Act shall be sent to 
the same country from which it has been imported.', 1, 'The Environment Protection Act, 2019 (2076), Chapter -3, Section 16 (Export and import of hazardous substance)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:3.2', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:3', 2, 'section', '17', 'Manageme nt of a hazardous substance: (1) The person or body that produces a', 'Manageme nt of a hazardous substance', 'hazardous substance shall be responsible for managing such a hazardous 
substance.  
  (2) In collecting, storing, processing, selling, distributing, disposing or 
transporting a hazardous sub stance, the concerned person or body shall make its 
proper management in a manner not to cause adverse impacts on the environment.  
  (3) The concerned person or body shall manage the hazardous substance 
pursuant to sub -section (1) at his or her own cost.', 2, 'The Environment Protection Act, 2019 (2076), Chapter -3, Section 17 (Manageme nt of a hazardous substance)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:3.3', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:3', 2, 'section', '18', 'Power to establish laborator ies: (1) The Government of Nepal or Provincial', 'Power to establish laborator ies', 'Government may establish laboratories , as required , to carry out test or 
examination relative to environment protection and pollution control or prescribe 
any laboratory  recogniz ed by the Government of Nepal  to carry out test or 
examination  relative to environment protection and pollution control.   
(2) Provisions relating to  the operation and management of the 
laboratory established pursuant to sub -section (1) shall be as prescri bed.', 3, 'The Environment Protection Act, 2019 (2076), Chapter -3, Section 18 (Power to establish laborator ies)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:3.4', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:3', 2, 'section', '19', 'To allow collection of samples: (1) If the concerned body intends to study, test,', 'To allow collection of samples', 'examine or analyze the pollution or wastes to be or likely to be generated from 
any industry, factory, mechanical equipment like a machine and motor vehicle, the 
concerned owner or relevant person shall allow to collect samples of the pollution 
or wastes generated from  such industry, factory, mechanical equipment like a 
machine and motor vehicle.  
  (2) Other provisions relating to the collection, study, examination , test 
or analysis of samples pursuant to sub -section (1) shall be as prescribed.  
www.lawcommission.gov.np 
12', 4, 'The Environment Protection Act, 2019 (2076), Chapter -3, Section 19 (To allow collection of samples)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:3.5', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:3', 2, 'section', '20', 'Power to issue pollution control certificate:  (1) The Ministry or Provincial', 'Power to issue pollution control certificate', 'Ministry may  provide  a pollution control certificate, as prescribed, to any industry 
that mak es a significant contribution to the control of pollution.  
  (2) Other provisions relating to the pollution control certificate shall be 
as prescribed.', 5, 'The Environment Protection Act, 2019 (2076), Chapter -3, Section 20 (Power to issue pollution control certificate)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:3.6', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:3', 2, 'section', '21', 'Environmental inspector:  (1) The environmental inspector shall  carry out', 'Environmental inspector', 'monitoring and inspection a s to whe ther or not  acts to be  performed  in accordance 
with the environmental study report  approved pursuant to Section 7 have been 
performed effectively  and standards relating to pollution control and 
environmental protection have been complied with.  
  (2) Notwithstanding anything contained in sub -section (1), in cases 
where the environmental inspector is not available, the following body may 
designate the following officer or employee as the environmental inspector and 
depute such officer or employee fo r monitoring and inspection:  
(a) The Ministry may designate any officer employee of the 
Government of Nepal or Provincial Government, as to whether or 
not acts to be performed in accordance with the environmental study 
report referred to in clause (a) of s ub-section (2) of Section 7 have 
been performed effectively and standards relating to pollution 
control and environmental protection have been complied with , 
(b) The Provincial Ministry may designate any officer employee of the 
Provincial Government, as to  whether or not acts to be performed in 
accordance with the environmental study report referred to in clause 
(b) of sub -section (2) of Section 3 approved pursuant to Section 7 
or the environmental impact assessment report referred to in clause 
(c) of sub -section (2) of Section 3 have been performed effectively 
and standards relating to pollution control and environmental 
protection have been complied with within its Province,  
(c) The Local Level may designate any employee of the Local Level, as 
to whether o r not acts to be performed in accordance with the 
environmental study report referred to in clause (c) of sub -section 
(2) of Section 3 approved pursuant to Section 7 have been performed 
effectively and standards relating to pollution control and 
www.lawcommission.gov.np 
13 
 
environmen tal protection have been complied with within its Local 
Level.  
(3) Other provisions relating to the environmental inspector shall be as 
prescribed.', 6, 'The Environment Protection Act, 2019 (2076), Chapter -3, Section 21 (Environmental inspector)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:3.7', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:3', 2, 'section', '22', 'Functions, duties and powers of the environmental inspector:  (1) The', 'Functions, duties and powers of the environmental inspector', 'functions, duties and powers of the  environmental inspector shall be as follows:  
(a) To inspect as to whether or not disposal of hazardous 
substances  has been made  or pollution has been caused 
contrary to this Act or the rules framed under this Act,  
(b) To inspect as to whether or not the acts of mitigation, 
avoidance or control of pollution have been carried out in 
accordance with this Act or the rules framed under this Act,  
  (c) To inspect on site as to whether or not work has been 
performed consistent  with the terms prescribed in the 
approved environmental study report while executing the 
proposal,  
(d) To inspect as to where the matters prevented pursuant to 
Section 13 or 15 have been complied with.  
(2) In the course of making inspection pursuant to su b-section ( 1), the 
environmental inspector may, by giving a prior notice to the concerned person, 
body or proponent, inspect, examine or investigate any house, land, building, 
factory, industry, motor vehicle, industrial device, tools, machinery, animal, 
object, records, document or other goods  or object .   
(3) It shall be the duty of the  concerned person, body or proponent to 
render assistance to the environmental inspector in the course of inspection 
pursuant to this Section, by providing such descriptions or information as 
demanded by him or her.  
 (4) If the concerned person or body does not allow  the environmental 
inspector to  make inspect ion, while moving on to make inspectio n pursuant to this 
Section , does not provide such descriptions or information as demanded by him or 
her, gives false descriptions, creates let and hinderance or does not assist in the 
course of inspection, the environmental inspector may immediately impose the 
fine as follows on such a person or body:  
www.lawcommission.gov.np 
14 
 
(a) A fine of up to twenty thousand rupees  in case of disallowing him 
or her to make inspection or creation of let and hindrance in 
inspection,  
(b) A fine of up to fifteen thousand rupees in case of failure to provide 
such descriptions or information as demanded or of giving f alse 
description in the course of inspection or failure to assist in 
inspection.  
(5) A party  who is not satisfied with a punishment imposed  by the 
environmental inspector pursuant to sub -section ( 4) may make a complaint to the Director 
General not later th an fifteen days of the date of receipt of information of that punishment.  
(6) The environmental inspector shall submit a report of inquiry and inspection 
carried out pursuant to this Section to the concerned body and the Department.  
(7) Other functions, du ties and powers of the environmental inspector shall be 
as prescribed.', 7, 'The Environment Protection Act, 2019 (2076), Chapter -3, Section 22 (Functions, duties and powers of the environmental inspector)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:4', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', NULL, 1, 'chapter', 'Chapter -4', 'Chapter -4', NULL, NULL, 4, 'The Environment Protection Act, 2019 (2076), Chapter -4', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:4.0', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:4', 2, 'section', '23', 'To provide information: (1) The Ministry shall carry out study as prescribed, on', 'To provide information', 'a periodic basis, as to the adverse impacts caused by climate change on the local 
communities, eco -system and bio -diversity and make public descriptions thereof.  
  (2) The Ministry shall,  on the basis o f the study carried out pursuant to 
sub-section (1), and  from time to time, make public necessary information on such 
measures as to be adopted for the mitigation of adverse impacts or risks  from 
climate change while formulating development projects to be executed by the 
Government of Nepal, Provincial Government and Local Level.  
  (3) The Government of Nepal, Provincial Government and Local Level 
may, on the basis of the information made public pursuant to sub -section (2), set 
the priorities of formulation  of development projects.', 0, 'The Environment Protection Act, 2019 (2076), Chapter -4, Section 23 (To provide information)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:4.1', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:4', 2, 'section', '24', 'Adaptation plan may be made:  (1) In order to avoid adverse impacts and risks', 'Adaptation plan may be made', 'of climate change, the Ministry, Provincial Ministry and Local Level may make 
and implement an adaptation plan at the national, Provincial and Local levels, 
respectively.  
  (2) In making the adaptation plac e referred to in sub -section (1), special 
priority shall be accorded to the women, persons with disabilities, children, senior 
www.lawcommission.gov.np 
15 
 
citizens and economically indigent communities who are more vulnerable to 
effects of climate change and the inhabitants of those geographical areas that have 
become more vulnerable to climate change.  
  (3) Local communities may make and implement an adaptation plan at 
the local level, and the concerned body shall make necessary assistance and 
facilitation in the implementation of su ch a plan.', 1, 'The Environment Protection Act, 2019 (2076), Chapter -4, Section 24 (Adaptation plan may be made)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:4.2', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:4', 2, 'section', '25', 'Power to carry out acts of mitigation: (1) The Government of Nepal may  identify', 'Power to carry out acts of mitigation', 'areas emitting green -house gas and determine  their national reference level.  
  (2)  The Ministry shall make periodic monitoring as to the national 
reference leve l determined pursuant to sub -section (1) and make public the 
updated information.  
  (3) The Ministry, Provincial Government and Local Level may launch 
necessary programs.  
  (4) The Ministry may make, or cause to be made, measurement of 
green -house gas emis sion.  
  (5) Other provisions relating to mitigation shall be as prescribed.', 2, 'The Environment Protection Act, 2019 (2076), Chapter -4, Section 25 (Power to carry out acts of mitigation)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:4.3', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:4', 2, 'section', '26', 'Impacts from climate change and risk management:  (1) The Government of', 'Impacts from climate change and risk management', 'Nepal may, for the purpose of managing adverse impacts and risks of climate 
change, issue necessary order s, by a notification in the Nepal Gazette, as to such 
measures as to be adopted for the mitigation of adverse impacts and risks of 
climate change, in the sectoral policies, strategies and action plans  to be executed 
by the Government of Nepal, Provincial G overnment, Local Level  and other public 
bodies as well as the private sector.  
  (2) The Government of Nepal may prescribe priority while issuing any 
order pursuant to sub -section (1).', 3, 'The Environment Protection Act, 2019 (2076), Chapter -4, Section 26 (Impacts from climate change and risk management)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:4.4', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:4', 2, 'section', '27', 'Power to determine technical standards: (1) The Government of Nepal may', 'Power to determine technical standards', 'determine and enforce necessary standards for the setting of priority of matters to 
be implemented in urban and rural areas as to the mitigation of adverse impacts 
and risks of climate change.  
  (2) The Government of Nepal may determine necessary polic y and 
technical standards for the development of such technology as may be necessary 
in the prescribed subject areas for the mitigation of adverse impacts and risks of 
climate change.  
www.lawcommission.gov.np 
16', 4, 'The Environment Protection Act, 2019 (2076), Chapter -4, Section 27 (Power to determine technical standards)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:4.5', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:4', 2, 'section', '28', 'Power to participate in carbon trade:  (1) The Government of Nepal ma y', 'Power to participate in carbon trade', 'participate in carbon trade with the mechanisms established by the international 
treaty, any foreign government or organization, business entity or private sector 
for the mitigation and conservation  of carbon emission.  
  (2) Other provisions relating to participation in carbon trade pursuant 
to sub -section (1) and allocation of benefits resulted therefrom shall be as 
prescribed.', 5, 'The Environment Protection Act, 2019 (2076), Chapter -4, Section 28 (Power to participate in carbon trade)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:5', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', NULL, 1, 'chapter', 'Chapter -5', 'Chapter -5', NULL, NULL, 5, 'The Environment Protection Act, 2019 (2076), Chapter -5', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:5.0', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:5', 2, 'section', '29', 'Protection of national h eritages:  (1) It shall be the duty of all the concerned', 'Protection of national h eritages', 'agency to protect national heritages.  
(2) For the purpose of the protection of national heritages, the 
concerned body shall to prepare and maintain an inventory, and such an inventory 
shall also inclu de the objects or places within Nepal which are listed in the World 
Heritage List.  
(3) The objects, places, plants, animals, environment etc., included in 
the inventory referred to in sub -section (2) shall be protected as prescribed.', 0, 'The Environment Protection Act, 2019 (2076), Chapter -5, Section 29 (Protection of national h eritages)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:5.1', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:5', 2, 'section', '30', 'Special provision relating to environment protection areas:  (1) The', 'Special provision relating to environment protection areas', 'Government of Nepal may, in consultation with the Provincial Government and 
concerned Local Level and by a notification in the Nepal Gazette, maintain as an 
environment protection area any place c ontaining a natural heritage or aesthetic 
place which is considered extremely  significant from the point of view of 
environmental protection or any place of historical  or cultural importance . 
  (2) In making any road, building, river management or other ph ysical 
infrastructures, the Government of Nepal may, in coordination with the concerned 
body and by a notification in the Nepal Gazette, specify any specific area as an 
open or green area with a view to protecting the environment of such area.  
  (3) Prohib ition may be imposed on any such act as prescribed within 
the environment protection area maintained pursuant to sub -section (1) or open or 
green area specified pursuant to sub -section (2) . 
  (4) In cases where it appears that adverse impacts have been cau sed, are 
likely to be caused, on public health or environment of any specific area or place 
www.lawcommission.gov.np 
17 
 
as a result of excessive environmental pollution, soil erosion, excessive 
exploitation of natural heritages or occurrence of a natural calamity in such area 
or plac e, the Government of Nepal may, in consultation with the concerned Local 
Level, issue any appropriate order for the balance, management or restoration of 
the environment, upon specifying such an area or place as a sensitive area from 
the environmental view point.  
  (5) The Government of Nepal may specify any place in which any 
injurious or hazardous substance or wastes are stored or disposed or there is 
excessive pollution for other reason as a  polluted area and prevent the movement 
of public there.  
  (6) In cases where there is improvement from the environmental 
viewpoint in the place referred to in sub -section (4) or (5), such area may be 
removed from the list of sensitive area or polluted area.  
  (7) Participation of the local community maybe forged in t he 
management of any area maintained or specified pursuant to this Section for the 
protection of environment.  
  Explanation: For the purposes of this Section and Section 36, “local 
community” means the community residing within or in neighborhood of such a n 
area.   
  (8)  There shall be participation of the local community as prescribed 
in the benefits resulted from the management of the area managed pursuant to sub -
section (7).', 1, 'The Environment Protection Act, 2019 (2076), Chapter -5, Section 30 (Special provision relating to environment protection areas)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:5.2', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:5', 2, 'section', '31', 'Establishment and operation of fund : (1) There shall be established a fund', 'Establishment and operation of fund', 'entitled the environment protection fund, for the protection of environment, 
prevention and control of pollution, management of climate change and protection 
of the national heritages.  
(2) The following amounts shall be credited to the fund referred to in 
sub-section (1):   
(a) Amount received from the Government of Nepal, Provincial 
Government or Local Level,  
(b)  Amount received from any native person or organization,  
(c) Amount received from any foreign government or international 
organization.  
www.lawcommission.gov.np 
18 
 
(3) Prior  to obtaining the amount referred to in clause (c) of sub -section 
(2), approval of the Government of Nepal, Ministry of Finance shall be obtained.  
(4) The fund shall be audited by the Auditor General.  
(5) The operation of the fund shall be as prescribed.', 2, 'The Environment Protection Act, 2019 (2076), Chapter -5, Section 31 (Establishment and operation of fund)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:5.3', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:5', 2, 'section', '32', 'Power to constitute council : (1) There shall be an environmental protection and', 'Power to constitute council', 'climate change management national council  chaired by the Prime Minister,  for 
the carrying out of acts relating to environmental protection and climate change  at 
the national level in an effective manner.  
  (2) The council referred to in sub -section (1) shall consist of the 
following chairperson and members:  
  (a) Prime Minister      -Chairperson  
 (b) Minster for Forest and Environment,  
Government of Nepal     -Member  
(c) Three Minsters of the Government of Nepal  
designated by the Prime Minister    -Member  
(d) Chief Ministers of all Provinces    -Minister  
(e) Member of the National Planning Commission  
who looks af ter the matter of environment   -Member  
(f) Two pe rsons including one woman nominated by  
the Chairperson from  among the professors  
in fore st and environmental science   -Member  
(g) Three persons including two women nominated by the  
Chairperson from among the persons with expertise  
in the fi eld of forest and environment   -Member  
(h) Secretary, Ministry     -Member -Secretary  
(3) The chairperson may designate one Minister out of the members as 
the vice -chairperson.  
(4) The tenure of the members nominated pursuant to clauses (f) and (g) 
shall be three years.  
(5) Notwithstanding anything contained in sub -section (4), if a 
nominated member fails perform the duties of his or her office, the chairperson 
may remove him or her from the office of member.  
Provided that, prior to such removal, he or she sh all be provided with a 
reasonable opportunity to submit clarification.  
www.lawcommission.gov.np 
19', 3, 'The Environment Protection Act, 2019 (2076), Chapter -5, Section 32 (Power to constitute council)', '2026-01-15T09:00:00.000Z')
;

INSERT INTO document_nodes (id, document_id, parent_id, depth, node_type, identifier, title, heading, content, position, citation, created_at) VALUES
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:5.4', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:5', 2, 'section', '33', 'Meetings and of the Council:  (1) The Council shall meet  at least once a year  at', 'Meetings and of the Council', 'such date, time and place as prescribed by the chairperson.  
  (2) The member -secretary of the Counci l shall, in consultation with the 
chairperson send a notice setting out the date, time and place of the meeting of the 
Council, along with the agenda to be deliberated thereat, so that all the members 
can receive it in advance of at least forty -eight hours  of the time of the meeting.  
  Provided that in the event of a need for calling a meeting of the Council 
immediately, the chairperson of the Council may call the meeting in advance of 
seventy -two hours, if the meeting is so called, the member -secretary of the 
Council shall as soon as possible send the notice thereof so that all the members 
can receive it.  
  (3) The presence of a majority of the total number of members shall be 
deemed to constitute a quorum for the meeting of the Council.  
  (4) The chairperson of the Council  shall preside over the meeting of the  
Council,  and in the absence of the chairperson, the vice-chairperson of the Council 
shall preside over the meeting.  
(5) Any decision of the Council shall be taken by a majority, and in the 
case of a tie , the chairperson shall exercise the casting vote.  
(6)  Any office -bearer, representative of concerned body or 
organization or environmental expert may, as required, be invited to the meeting 
of the Council.  
(7) The member -secretary of the Counc il shall authenticate the decision 
of the Council .  
(8) Other procedures relating  to the meeting of the Council shall be as 
determined by the Council  itself.', 4, 'The Environment Protection Act, 2019 (2076), Chapter -5, Section 33 (Meetings and of the Council)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:5.5', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:5', 2, 'section', '34', 'Functions, duties and powers of the Council: (1) The functions, duties and', 'Functions, duties and powers of the Council', 'powers of the Counc il shall be as follows:  
(a) To give direction, as required, to the Ministry and other bodies to 
keep on integrating the matters relating to the environment and 
climate change into the long -term policies, plans and programs,  
(b) To set policy for the develo pment of a national system for the 
control of pollution, management of wastes and protection of 
national heritages , 
www.lawcommission.gov.np 
20 
 
(c) To give necessary policy guidance to the Provincial and Local levels 
with regard to environment al protection  and climate change,  
(d) To manage economic resources for environmental protection and 
climate change and facilitate for the same,  
(e) To give guidance to the Ministry for utilization, management, 
development and protection of natural, cultural and physical 
resources and heritages,  
(f) To make evaluation of acts pertaining to environmental protection 
and climate change.', 5, 'The Environment Protection Act, 2019 (2076), Chapter -5, Section 34 (Functions, duties and powers of the Council)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:6', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', NULL, 1, 'chapter', 'Chapter -6', 'Chapter -6', NULL, NULL, 6, 'The Environment Protection Act, 2019 (2076), Chapter -6', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:6.0', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:6', 2, 'section', '35', 'Fine:  (1) If any person does the following act, the concerned body may punish', 'Fine', 'that person as follows:  
(a) A fine not exceeding five hundred thousand rupees if, in the case of 
a proposal of which the brief environmental study report has to be 
approved,  the proposal is executed without having it approved or if 
any proposal is executed in a manner inconsistent with the approved 
repor t, 
(b) A fine not exceeding one million rupees if any proposal is executed 
without having the initial environmental examination approved or 
in a manner inconsistent with the approved report,  
(c) A fine not exceeding five million rupees if, in the case of a  proposal 
of which the environmental impact assessment report has to be 
approved, the proposal is executed without having it approved or if 
any proposal is executed in a manner inconsistent with the approved 
report.  
(2) If any person does any act referred to in sub -section (1), the 
concerned body may give order to stop such act immediately and have the 
environmental study report approved pursuant to this Act where such report has 
not been got approved, and to improve the act if acted inconsistent with such a 
report, and it shall be the duty of the concerned person or body to do as per the 
order so given. The concerned body may impose a fine that is three -fold of the 
fine imposed pursuant to sub -section (1) if the order so given is not complied with.  
www.lawcommission.gov.np 
21 
 
 (3) If any person does any act inconsistent with this Act or the rules, 
guidelines, procedures or norms framed under this Act, other than that set forth in 
sub-section (1), the concerned body may restrict the doing of such act and punish 
that person with a fin e not exceeding three hundred thousand rupees and give order 
to do the act referred to in this Act or the rules, guidelines, procedures or norms 
framed under this Act. A fine that is three -fold of the fine imposed pursuant to this 
sub-section if the order so given is not complied with.  
(4) If the act referred to in the order given pursuant to sub -section (2) 
or (3) is not done, such act shall be restricted and the concerned body shall send a 
request, accompanied by the recommendation, to take necessary acti on for 
blacklisting such a person or body.  
(5) If so recommended pursuant to sub -section (4), the Department 
shall, if it finds the content reasonable, blacklist such a person or body for a period 
of one year to five years.  
(6) Notwithstanding anything con tained in sub -sections (4) and (5), the 
Department shall make necessary inquiry into non -compliance with the order 
given by it and take action referred to in sub -section (5).  
(7) If a body is blacklisted pursuant to sub -section (5), such a person  or 
body m ay not submit any proposal in that body’s name or in any name whatever 
associated with such a person or body for the period of blacklisting.  
(8) Prior to imposing the fine referred to in this Section, a reasonable 
opportunity shall be given to the person o r body or project which is to be 
blacklisted.', 0, 'The Environment Protection Act, 2019 (2076), Chapter -6, Section 35 (Fine)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:6.1', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:6', 2, 'section', '36', 'Application may be made:  (1) If a person execute s, in contravention of this Act,', 'Application may be made', 'a proposal w ithout having the initial environmental examination, brief 
environmental study or environmental impact assessment  report approved or  in a 
manner inconsistent with the approved report or does or proceeds to do any act 
contrary to this Act, application may be made to the concerned body or authority.  
  (2) If any person, body or local community suffers any loss or damage 
as a result of the pollution or disposal of a hazardous waste by another person 
inconsistent with this Act or the rules, guidelines or standards framed under this 
Act, the person, body or local community victimized from such an act may make 
an appli cation to the concerned body for getting compensation for the injury 
caused to such person , body or community.  
www.lawcommission.gov.np 
22 
 
(3)  If, in examining and inquiring into the  application made pursuant 
to sub -section (1)  or (2) , it is proved that the applicant has sustained l oss or 
damage, the concerned body shall  ascertain the injury and require a reasonable 
compensation to be paid by the person, body or proponent who has caused such 
loss or damage to the victim person, body or local community.  
(4) There shall be formed a com mittee comprising three experts 
nominated by the Government of Nepal to make inquiry into any application made 
as to the injury caused from pollution made by any body of the Government of 
Nepal or body owned and controlled by the Government of Nepal, and 
compensation shall be paid pursuant to sub -section (3) on the basis of 
recommendation by that committee.  
(5) There shall be formed a committee comprising three experts 
nominated by the Provincial Government to make inquiry into any application 
made as to th e injury caused from pollution made by any body of the Provincial 
Government or Local Level or body owned and controlled by the Provincial 
Government or Local Level, and compensation shall be paid pursuant to sub -
section (3) on the basis of recommendation by that committee.  
(6) The basis for determining compensation pursuant to this Section and 
other provisions shall be as prescribed.', 1, 'The Environment Protection Act, 2019 (2076), Chapter -6, Section 36 (Application may be made)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:6.2', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:6', 2, 'section', '37', 'Appeal:  (1) A party who is not satisfied with the fine imposed pursuant to Section', 'Appeal', '35 may make an appeal within thirty -five days to the concerned District Court if 
such fine is imposed by the Local Level and to the concerned High Court if it is 
imposed by other b ody or authority of the Government of Nepal or Provincial 
Government.  
  (2) A party who is not satisfied with the decision made as to the 
determination of compensation pursuant to Section 36 may make an appeal to the 
concerned High Court within thirty -five days.', 2, 'The Environment Protection Act, 2019 (2076), Chapter -6, Section 37 (Appeal)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:7', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', NULL, 1, 'chapter', 'Chapter -7', 'Chapter -7', NULL, NULL, 7, 'The Environment Protection Act, 2019 (2076), Chapter -7', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:7.0', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:7', 2, 'section', '38', 'Environment protection plan to be formulated:  (1) The Government of Nepal', 'Environment protection plan to be formulated', 'may formulate and implement an environment protection plan with a view to 
maintaining a clean and healthy environment, and conserving and promoting the 
same.  
www.lawcommission.gov.np 
23 
 
  (2) The Provincial Government and Local Level may, subject to the 
plan referred to in sub -section ( 1), make and implement necessary plans for 
environmental protection.  
  (3) In formulating the plans referred to in sub -sections (1) and (2), 
traditional and local practices on the protection, conservation, sustainable use of 
the environment and equitable d istribution of fruits received from the use of 
environmental resources shall be included in the plans.  
  (4) The plan referred to in sub -section (1) shall include such other 
matters as prescribed.', 0, 'The Environment Protection Act, 2019 (2076), Chapter -7, Section 38 (Environment protection plan to be formulated)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:7.1', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:7', 2, 'section', '39', 'Monitoring and inspection to be carried out:  (1) The Ministry or Department', 'Monitoring and inspection to be carried out', 'may carry out monitoring and inspection as to whether or not this Act or the rules, 
guidelines, procedures or standards framed under this Act have been implemented.  
  (2) The Provincial Government or Local Level may, with a view to 
protecting and conserving the environment within its area, carry out monitoring 
and inspection as to whether or not this Act or the rules, guidelines, procedures or 
standards framed under this Act have been implemented.  
(3) Other provisions relating to monit oring and inspection to be carried 
out pursuant to s ub-section (1)  or (2)  shall  be as prescribe d.', 1, 'The Environment Protection Act, 2019 (2076), Chapter -7, Section 39 (Monitoring and inspection to be carried out)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:7.2', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:7', 2, 'section', '40', 'Annual report to be prepared: (1) The Ministry shall  each year prepare an annual', 'Annual report to be prepared', 'report including the following matters:  
(a) Description obtained from the  monitoring and inspection carried out 
pursuant to Section 39,  
(b) Description relating to national and international activities on 
climate change,  
(c) Other necessary description.  
(2) The Ministry shall submit the annual report referred to in sub -
section (1) to the Council within two months of the date of expiry of each fiscal 
year.', 2, 'The Environment Protection Act, 2019 (2076), Chapter -7, Section 40 (Annual report to be prepared)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:7.3', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:7', 2, 'section', '41', 'Power to issue order: (1) The Government of Nepal may, by a notification in the', 'Power to issue order', 'Nepal Gazette, issue necessary order as to the matters requiring precautions from 
the point of view of environmental protection.  
  (2) The Director General may impose a fine not exceeding one hundred 
thousand rupees on a person or body that violates the order issued pursuant to sub -
section (1).  
www.lawcommission.gov.np 
24', 3, 'The Environment Protection Act, 2019 (2076), Chapter -7, Section 41 (Power to issue order)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:7.4', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:7', 2, 'section', '42', 'Delegation of power:  The Ministry may, as per necessity, delegate any of the', 'Delegation of power', 'powers conferred on it pursuant to this Act to the Department, environmental 
inspector or any office employee or any body .', 4, 'The Environment Protection Act, 2019 (2076), Chapter -7, Section 42 (Delegation of power)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:7.5', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:7', 2, 'section', '43', 'Prevail ing law to govern :  The matters set forth in this Act shall be g overned by', 'Prevail ing law to govern', 'this Act, and other matters shall be governed by the prevailing law.', 5, 'The Environment Protection Act, 2019 (2076), Chapter -7, Section 43 (Prevail ing law to govern)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:7.6', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd', 'doc_the_environment_protection_act_2019_2076__2019_the-environment-protection-act-2019-2076_2021-12-03_06-38-31_pd:7', 2, 'section', '44', 'Power to frame rules:  The Government of Nepal may frame necessary rules for', 'Power to frame rules', 'implementing this Act.', 6, 'The Environment Protection Act, 2019 (2076), Chapter -7, Section 44 (Power to frame rules)', '2026-01-15T09:00:00.000Z'),
