  ('doc_the_foreign_investment_and_technology_transfer_act_2019_2075__2019_fitta-2075_pdf:7.17', 'doc_the_foreign_investment_and_technology_transfer_act_2019_2075__2019_fitta-2075_pdf', 'doc_the_foreign_investment_and_technology_transfer_act_2019_2075__2019_fitta-2075_pdf:7', 2, 'section', '2', 'Cottage and small industries,', 'Cottage and small industries,', NULL, 17, 'The Foreign Investment and Technology Transfer Act, 2019 (2075), Chapter 7, Section 2 (Cottage and small industries,)', '2026-01-15T09:00:00.000Z'),
  ('doc_the_foreign_investment_and_technology_transfer_act_2019_2075__2019_fitta-2075_pdf:7.18', 'doc_the_foreign_investment_and_technology_transfer_act_2019_2075__2019_fitta-2075_pdf', 'doc_the_foreign_investment_and_technology_transfer_act_2019_2075__2019_fitta-2075_pdf:7', 2, 'section', '3', 'Personal service business ( hair cutting, tailoring, driving etc.) ,', 'Personal service business ( hair cutting, tailoring, driving etc.) ,', NULL, 18, 'The Foreign Investment and Technology Transfer Act, 2019 (2075), Chapter 7, Section 3 (Personal service business ( hair cutting, tailoring, driving etc.) ,)', '2026-01-15T09:00:00.000Z'),
